/// TrustIr dialect namespace used when canonical TrustIr has no first-class Formula node.
pub const SYMBOLIC_FORMULA_DIALECT: &str = "trust_symbolic";
/// Dialect op emitted for `trust_types::Operand::Symbolic`.
pub const SYMBOLIC_FORMULA_OP: &str = "formula";
/// Dialect op emitted for a lifted SMT memory-array state update.
pub const SYMBOLIC_MEMORY_STATE_OP: &str = "memory_state";
/// Dialect op emitted when aggregate construction must preserve symbolic fields.
pub const SYMBOLIC_AGGREGATE_OP: &str = "aggregate";
/// Attribute carrying the stable SMT-LIB2 representation of the formula.
pub const SYMBOLIC_FORMULA_ATTR_SMTLIB: &str = "formula.smtlib2";
/// Attribute carrying the inferred SMT sort as SMT-LIB2 text.
pub const SYMBOLIC_FORMULA_ATTR_SORT: &str = "formula.sort";
/// Attribute carrying a Rust-debug AST rendering for diagnostics.
pub const SYMBOLIC_FORMULA_ATTR_DEBUG: &str = "formula.debug";
/// Attribute carrying the stable serialized trust-types Formula schema id.
pub const SYMBOLIC_FORMULA_ATTR_SCHEMA: &str = "schema";
/// Attribute carrying a round-trippable trust-types Formula JSON payload.
pub const SYMBOLIC_FORMULA_ATTR_JSON: &str = "formula_json";
/// Attribute describing the non-scalar carrier context for a preserved formula.
pub const SYMBOLIC_FORMULA_ATTR_CONTEXT: &str = "formula.context";
/// Attribute describing which aggregate construction pattern was preserved.
pub const SYMBOLIC_AGGREGATE_ATTR_KIND: &str = "aggregate.kind";
/// Attribute carrying the number of aggregate field operands.
pub const SYMBOLIC_AGGREGATE_ATTR_FIELD_COUNT: &str = "aggregate.field_count";
/// ProofFormula schema used to carry source/assertion metadata through TrustIr.
pub const TRUST_OBLIGATION_SOURCE_SCHEMA: &str = "trust.trust_ir.obligation-source.v1";

const THREAD_LOCAL_REF_DETAIL_PREFIX: &str = "thread-local reference to ";

fn thread_local_ref_symbol(detail: &str) -> Option<&str> {
    detail.strip_prefix(THREAD_LOCAL_REF_DETAIL_PREFIX).filter(|symbol| !symbol.is_empty())
}

fn thread_local_ref_thin_address_ty(ty: &Ty) -> bool {
    let pointee = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        _ => return false,
    };

    !matches!(
        pointee,
        Ty::Slice { .. }
            | Ty::Str
            | Ty::SymArray { .. }
            | Ty::Dynamic { .. }
            | Ty::Unsupported { .. }
    )
}

/// ProofFormula schema used when the obligation's `payload` carries the parsed
/// contract predicate in machine-readable form (a `trust_types::Formula`
/// serialized as JSON), alongside its SMT-LIB rendering (`smtlib`) and sort.
///
/// This is exactly the schema `trust_ir::ProofFormula::trust_types_json` names
/// for a producer-emitted trust-types formula payload, so a router/backend can
/// index on it and consume the predicate without re-parsing the description
/// string. It is emitted ONLY when the predicate parses; on a parse failure the
/// lowering FAILS CLOSED back to [`TRUST_OBLIGATION_SOURCE_SCHEMA`] with
/// `smtlib`/`sort` left `None` (see `ObligationSourceMetadata::into_formula`).
pub const TRUST_CONTRACT_PREDICATE_SCHEMA: &str = "trust-types.Formula@1";

/// The SMT sort a contract predicate always has: `Bool`. A `#[requires]` /
/// `#[ensures]` / invariant / refinement predicate is a boolean assertion, and
/// `parse_spec_expr` always yields a Bool-sorted `Formula` at the top level
/// (comparisons, boolean connectives, predicate applications). We populate
/// `ProofFormula.sort` with this so a router can dispatch without inferring it.
const TRUST_CONTRACT_PREDICATE_SORT: &str = "Bool";

type ClosureEnvTypes = FxIndexMap<String, Ty>;

fn is_type_only_projection(projection: &Projection) -> bool {
    matches!(projection, Projection::OpaqueCast(_) | Projection::UnwrapUnsafeBinder(_))
}

fn place_is_direct_local(place: &Place) -> bool {
    place.projections.iter().all(is_type_only_projection)
}

fn validate_aggregate_kind_for_trust_ir(kind: &AggregateKind) -> Result<(), BridgeError> {
    match kind {
        AggregateKind::Tuple | AggregateKind::Array | AggregateKind::Closure { .. } => Ok(()),
        AggregateKind::Adt { active_field: Some(active_field), .. } => {
            Err(BridgeError::UnsupportedOp(format!(
                "ADT aggregate active_field {active_field} requires union layout semantics in TrustIr"
            )))
        }
        AggregateKind::Adt { active_field: None, .. } => Ok(()),
        // Trust: piece #13 step-2 (safe-async native lowering) — the OUTER async
        // fn body constructs the coroutine frame with `Rvalue::Aggregate(Coroutine)`
        // to return the `impl Future`. Accept it here; the frame is lowered to an
        // opaque, obligation-free value (see the `Rvalue::Aggregate` handler),
        // exactly mirroring the vcgen/default lane (generate.rs). A coroutine frame
        // has NO modeled data fields (`map_type_ctx` registers it as a zero-field
        // opaque struct), so constructing it carries no safety obligation and every
        // later frame-field / discriminant read is havoc'd — the sound over-
        // approximation for "anything the executor left across a suspend". A
        // `CoroutineClosure` (`async ||`) still fails closed — a later increment.
        AggregateKind::Coroutine { .. } => Ok(()),
        AggregateKind::CoroutineClosure { name } => Err(BridgeError::UnsupportedOp(format!(
            "coroutine closure aggregate `{name}` requires async closure state-machine semantics in TrustIr"
        ))),
        other => Err(BridgeError::UnsupportedOp(format!(
            "unsupported aggregate semantics in TrustIr bridge: {other:?}"
        ))),
    }
}

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

/// Errors during trust-types to TrustIr conversion.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum BridgeError {
    #[error("unsupported type: {0}")]
    UnsupportedType(String),

    #[error("unsupported operation: {0}")]
    UnsupportedOp(String),

    #[error(
        "symbolic formula {context} lowering would require aggregate Undef; preserve formula metadata and reject proof-grade instead"
    )]
    SymbolicFormulaPreservationBlocked { context: String },

    #[error("missing block: bb{0}")]
    MissingBlock(usize),

    #[error("missing local: _{0}")]
    MissingLocal(usize),

    #[error(
        "duplicate compiler-certified paired-condvar authority for `{function_def_path}` bb{block} `{callee}`"
    )]
    DuplicatePairedCondvarAuthority {
        function_def_path: String,
        block: usize,
        callee: String,
    },

    #[error("failed to digest paired-condvar body `{function_def_path}`: {reason}")]
    PairedCondvarBodyDigest { function_def_path: String, reason: String },

    #[error(
        "invalid compiler-certified paired-condvar authority for `{function_def_path}` bb{block} `{callee}`: {reason}"
    )]
    InvalidPairedCondvarAuthority {
        function_def_path: String,
        block: usize,
        callee: String,
        reason: String,
    },
}

// ---------------------------------------------------------------------------
// Type mapping: trust-types Ty -> trust_ir Ty
// ---------------------------------------------------------------------------

/// Convert a trust-types `Ty` to a TrustIr `Ty`.
///
/// ## Mapping gaps
///
/// - thin `Ty::Ref` and `Ty::RawPtr` -> `TrustIrTy::Ptr`
/// - slice fat pointers (`[T]`, `&[T]`, `*const [T]`) require context-aware
///   lowering to register `FatPtr(Slice(element TyId))`
/// - `Ty::Tuple` -> `TrustIrTy::Tuple`
/// - `Ty::Adt` -> unsupported in this stateless mapper; use `LoweringCtx`
/// - `Ty::Datatype` -> unsupported in this stateless mapper; use `LoweringCtx`
///   (registers an opaque zero-field module struct — a fact-free sort marker)
/// - `Ty::Closure` -> unsupported in this stateless mapper; use `LoweringCtx`
///   so captured environment slots can be registered as module types
/// - `Ty::Bv(w)` -> closest integer type by width
/// - `Ty::Never` -> `TrustIrTy::Never`
pub fn map_type(ty: &Ty) -> Result<TrustIrTy, BridgeError> {
    match ty {
        Ty::Bool => Ok(TrustIrTy::Bool),
        Ty::Int { width: 8, signed: true } => Ok(TrustIrTy::I8),
        Ty::Int { width: 16, signed: true } => Ok(TrustIrTy::I16),
        Ty::Int { width: 32, signed: true } => Ok(TrustIrTy::I32),
        Ty::Int { width: 64, signed: true } => Ok(TrustIrTy::I64),
        Ty::Int { width: 128, signed: true } => Ok(TrustIrTy::I128),
        Ty::Int { width: 8, signed: false } => Ok(TrustIrTy::U8),
        Ty::Int { width: 16, signed: false } => Ok(TrustIrTy::U16),
        Ty::Int { width: 32, signed: false } => Ok(TrustIrTy::U32),
        Ty::Int { width: 64, signed: false } => Ok(TrustIrTy::U64),
        Ty::Int { width: 128, signed: false } => Ok(TrustIrTy::U128),
        // Trust (v25 B1): the faithful-scalar spellings from
        // `extract_function_faithful` — the differential lane's identity
        // carriers. Map onto trust-ir's first-class variants so producer and
        // oracle signatures agree by leaf equality.
        Ty::PtrSizedInt { signed: true } => Ok(TrustIrTy::Isize),
        Ty::PtrSizedInt { signed: false } => Ok(TrustIrTy::Usize),
        Ty::Char => Ok(TrustIrTy::Char),
        Ty::Float { width: 32 } => Ok(TrustIrTy::F32),
        Ty::Float { width: 64 } => Ok(TrustIrTy::F64),
        Ty::Unit => Ok(TrustIrTy::Unit),
        Ty::Never => Ok(TrustIrTy::Never),
        // Trust (B2-2): `str` is ID-LESS (FatPtrKind::Str carries no table reference),
        // so the STATELESS mapper can spell it directly — the faithful lane's
        // `Ref{inner: Str}` becomes the format's first-class fat pointer here.
        Ty::Str => Ok(TrustIrTy::FatPtr(trust_ir::FatPtrKind::Str)),
        Ty::Ref { inner, .. } if matches!(inner.as_ref(), Ty::Str) => {
            Ok(TrustIrTy::FatPtr(trust_ir::FatPtrKind::Str))
        }
        Ty::RawPtr { pointee, .. } if matches!(pointee.as_ref(), Ty::Str) => {
            Ok(TrustIrTy::FatPtr(trust_ir::FatPtrKind::Str))
        }
        // Trust (B2-1b): first-class slice fat pointers carry their ELEMENT type
        // through the module `types` table (`FatPtrKind::Slice(TyId)`); the STATELESS
        // mapper has no module to intern into, so these arms fail closed — use the
        // context-aware mapper (the Closure precedent).
        Ty::Slice { .. } => Err(BridgeError::UnsupportedType(
            "slice fat pointer requires module type registration; use context-aware lowering"
                .to_string(),
        )),
        // Trust: piece #7a — a const-generic array `[T; N]` (symbolic length) maps
        // to a SLICE fat pointer on the native path (opaque handle; see
        // `slice_element_type`). This lets native lowering COMPLETE; the bounds
        // safety comes from the trust-vcgen VC discharged via the ay bridge, not
        // from any native array model (which cannot exist without a concrete len).
        Ty::SymArray { .. } => Err(BridgeError::UnsupportedType(
            "sym-array fat pointer requires module type registration; use context-aware lowering"
                .to_string(),
        )),
        Ty::Ref { inner, .. } if is_slice_pointee(inner) => Err(BridgeError::UnsupportedType(
            "slice-ref fat pointer requires module type registration; use context-aware lowering"
                .to_string(),
        )),
        Ty::RawPtr { pointee, .. } if is_slice_pointee(pointee) => {
            Err(BridgeError::UnsupportedType(
                "slice-raw-ptr fat pointer requires module type registration; use context-aware \
                 lowering"
                    .to_string(),
            ))
        }
        // Trust (B2-3): `&dyn Trait` — TraitObject is ID-LESS (`trait_id` is the CONTENT
        // hash of the principal's def path via `trust_ir::stable_trait_object_id`, the
        // ONE shared mint with the THIR producer), so the STATELESS mapper spells it
        // directly, the Str precedent. Gated to SHARED refs with a REAL principal: the
        // oracle's principal-less sentinel (`trait_name == "dyn"`, e.g. `&dyn Send`)
        // keeps the thin catch-all below (status-quo spelling; the producer fail-closes
        // those bodies, so the pair is never compared), as do `&mut dyn` (producer-thin
        // on both sides this slice) and raw `*dyn` (producer fail-closed).
        Ty::Ref { mutable: false, inner } if matches!(inner.as_ref(), Ty::Dynamic { trait_name } if trait_name != "dyn") =>
        {
            let Ty::Dynamic { trait_name } = inner.as_ref() else { unreachable!() };
            Ok(TrustIrTy::FatPtr(trust_ir::FatPtrKind::TraitObject {
                trait_id: trust_ir::stable_trait_object_id(trait_name),
            }))
        }
        Ty::Ref { .. } | Ty::RawPtr { .. } => Ok(TrustIrTy::Ptr),
        // A function pointer in the STATELESS mapper is an opaque code address — `Ptr`:
        // storing/moving/comparing it cannot panic, and a CALL through it fails closed at
        // `resolve_call_target`, so it is never falsely proved. The CONTEXT-AWARE mapper
        // (`map_type_ctx`) upgrades representable sigs to `Ty::Func(FuncTyId)` matching the
        // producer's model (it can register the `FuncTy` in the module; this mapper cannot).
        Ty::FnPtr { .. } => Ok(TrustIrTy::Ptr),
        Ty::Array { .. } => Err(BridgeError::UnsupportedType(
            "Array requires module type registration; use context-aware lowering".to_string(),
        )),
        Ty::Tuple(elems) if elems.is_empty() => Ok(TrustIrTy::Unit),
        Ty::Tuple(elems) => {
            elems.iter().map(map_type).collect::<Result<Vec<_>, _>>().map(TrustIrTy::Tuple)
        }
        Ty::Adt { .. } => Err(BridgeError::UnsupportedType(
            "ADT requires module struct registration; use context-aware lowering".to_string(),
        )),
        Ty::Datatype { .. } => Err(BridgeError::UnsupportedType(
            "Datatype requires module struct registration; use context-aware lowering".to_string(),
        )),
        Ty::Closure { .. } => Err(BridgeError::UnsupportedType(
            "Closure requires module closure-environment registration; use context-aware lowering"
                .to_string(),
        )),
        Ty::Bv(w) => match w {
            8 => Ok(TrustIrTy::I8),
            16 => Ok(TrustIrTy::I16),
            32 => Ok(TrustIrTy::I32),
            64 => Ok(TrustIrTy::I64),
            128 => Ok(TrustIrTy::I128),
            _ => Err(BridgeError::UnsupportedType(format!("Bv({w})"))),
        },
        // A bare generic `Ty::Param` lowers to an OPAQUE, un-modeled `Unit` slot — it can be
        // moved/stored/returned with no numeric/pointer structure the CHC backend can
        // exploit. SOUND: every T-dependent panicking op flags elsewhere off the KEPT
        // `trust_types::Ty` Unsupported{Param} marker — Drop-of-T (place_type declines),
        // call-on-T (resolve_call_target fails closed), field/index/deref-THROUGH-T
        // (project_ty_ref errors); only a whole-value MOVE of the opaque slot succeeds, so a
        // generic fn verifies iff it is genuinely panic-free for all T. FRAGILITY: trust-mc
        // lowers `Unit` to a concrete 0, so a FUTURE change letting a Unit value reach an
        // arith/compare/switch VC would false-prove — the generics soundness oracle MUST pin
        // a `w_generic_eq`/`w_generic_drop`-style witness to lock the "no VC ever ranges over
        // a T value" invariant.
        Ty::Unsupported { kind, .. } if kind == "TyKind::Param" => Ok(TrustIrTy::Unit),
        Ty::Unsupported { kind, detail } if is_unsupported_rustc_closure_kind(kind) => {
            Err(unsupported_rustc_closure_type(kind, detail))
        }
        _ => Err(BridgeError::UnsupportedType(format!("{ty:?}"))),
    }
}

#[cfg(test)]
#[test]
fn map_type_shared_dynamic_ref_uses_stable_trait_object_id() {
    let trait_name = "core::fmt::Debug";
    let ty = Ty::Ref {
        mutable: false,
        inner: Box::new(Ty::Dynamic { trait_name: trait_name.to_string() }),
    };

    assert_eq!(
        map_type(&ty).unwrap(),
        TrustIrTy::FatPtr(trust_ir::FatPtrKind::TraitObject {
            trait_id: trust_ir::stable_trait_object_id(trait_name),
        }),
    );
}

/// Trust: build the `FuncTy` for a `Ty::FnPtr` signature IFF it lies in the producer's
/// admitted fragment (thir-lower `map_fn_ptr_ty`), `None` otherwise (caller falls back to
/// the opaque `Ptr` spelling — fail-visible, never a false agreement):
///   * every param/return maps through the STATELESS `map_type` (so probing is
///     side-effect-free — nothing is registered unless the whole sig is admitted);
///   * NO higher-order signatures: a component that contains a function type refuses,
///     mirroring the producer's `ty_contains_func` wall (recursion through `Tuple` only —
///     `Ref`/`RawPtr`/slice components erase to opaque `Ptr` on BOTH sides, exactly like
///     the producer's mapping, so a fn-ptr behind a pointer is invisible to both);
///   * the producer's unit-return convention: `returns: []` for a unit return.
/// The trust-types `FnSig` carries no ABI/variadic data — the producer only EMITS
/// `Ty::Func` for `extern "Rust"`, non-variadic sigs, and refuses the body otherwise, so
/// any sig that reaches a differential comparison is already in that fragment.
fn fn_ptr_func_ty(sig: &FnSig) -> Option<FuncTy> {
    let component = |ty: &Ty| -> Option<TrustIrTy> {
        if ty_contains_fn_ptr(ty) {
            return None;
        }
        map_type(ty).ok()
    };
    let mut params = Vec::with_capacity(sig.params.len());
    for p in &sig.params {
        params.push(component(p)?);
    }
    let returns = match sig.ret.as_ref() {
        Ty::Unit => vec![],
        Ty::Tuple(elems) if elems.is_empty() => vec![],
        other => vec![component(other)?],
    };
    Some(FuncTy { params, returns, is_vararg: false })
}

/// Trust: does this trust-types type contain a function type at a position the mapping
/// PRESERVES? `Tuple` recursion only — every other composite the admitted fragment maps
/// erases its pointee/element structure (`Ref`/`RawPtr` -> `Ptr`, slices -> fat-ptr tuple),
/// matching the producer's post-map `ty_contains_func` check.
fn ty_contains_fn_ptr(ty: &Ty) -> bool {
    match ty {
        Ty::FnPtr { .. } | Ty::FnDef { .. } => true,
        Ty::Tuple(elems) => elems.iter().any(ty_contains_fn_ptr),
        _ => false,
    }
}

/// Trust (B2-1b): resolve the byte-slice fat type (`[u8]` -> FatPtr(Slice(u8)))
/// from the ctx type cache — pre-interned at ctx construction, so this read-only
/// lookup never misses; a miss is a construction-order bug and fails closed.
fn byte_slice_fat_ty(ctx: &LoweringCtx<'_>) -> Result<TrustIrTy, BridgeError> {
    ctx.type_cache
        .get(&Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) })
        .cloned()
        .ok_or_else(|| {
            BridgeError::UnsupportedType(
                "byte-slice fat type missing from the ctx cache (construction-order bug)"
                    .to_string(),
            )
        })
}

fn is_slice_pointee(ty: &Ty) -> bool {
    // Trust: piece #7a — a const-generic array behind a reference (`&[T; N]`) is
    // modeled as a slice fat pointer on the native path (see `slice_element_type`).
    matches!(ty, Ty::Slice { .. } | Ty::SymArray { .. })
}

fn is_unsupported_rustc_closure_kind(kind: &str) -> bool {
    matches!(kind, "TyKind::Closure")
}

fn unsupported_rustc_closure_type(kind: &str, detail: &str) -> BridgeError {
    BridgeError::UnsupportedType(format!(
        "{kind} reached TrustIr bridge without captured-environment metadata: {detail}; \
         closure aggregate lowering is supported only when the bridge can recover capture slots \
         from AggregateKind::Closure operands"
    ))
}

fn slice_element_type(ty: &Ty) -> Option<Ty> {
    match ty {
        Ty::Slice { elem } => Some((**elem).clone()),
        // Trust: piece #7a — a const-generic array `[T; N]` (symbolic length) is
        // modeled on the NATIVE path exactly like a SLICE: an opaque fat pointer
        // whose index load produces a FRESH symbolic element. SOUNDNESS: the
        // element value is unconstrained (asserts nothing), so no native false
        // proof; the bounds SAFETY comes from the trust-vcgen bounds VC (with the
        // per-param symbolic length), discharged via the ay bridge — the SAME
        // mechanism a real slice uses. This lets the function's native lowering
        // COMPLETE (instead of hard-erroring at the `map_type` wall) while the
        // guarded index proves and the unguarded index refutes.
        Ty::SymArray { elem, .. } => Some((**elem).clone()),
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => match inner.as_ref() {
            Ty::Slice { elem } | Ty::SymArray { elem, .. } => Some((**elem).clone()),
            _ => None,
        },
        _ => None,
    }
}

/// Whether `ty` is one of the two Trust-side spellings of Rust's `usize` on
/// the bridge's pinned 64-bit target.
///
/// The compatibility extractor historically represented `usize` as an
/// unsigned 64-bit integer, while the faithful extractor uses the first-class
/// `PtrSizedInt` spelling.  TrustIr deliberately keeps those value types
/// distinct (`U64` versus `Usize`), even though both have the same runtime bits.
fn is_trust_usize_ty(ty: &Ty) -> bool {
    matches!(ty, Ty::Int { width: 64, signed: false } | Ty::PtrSizedInt { signed: false })
}

// ---------------------------------------------------------------------------
// BinOp mapping
// ---------------------------------------------------------------------------

/// Convert a trust-types `BinOp` to a TrustIr `BinOp` or `ICmpOp`.
///
/// Returns `(Some(binop), None)` for arithmetic ops or `(None, Some(icmp))` for
/// comparison ops.
///
/// The `signed` parameter controls division/remainder (SDiv vs UDiv) and
/// comparison signedness (Slt vs Ult).
pub fn map_binop(op: BinOp, signed: bool) -> Result<BinOpMapping, BridgeError> {
    match op {
        BinOp::Add => Ok(BinOpMapping::Arith(TrustIrBinOp::Add)),
        BinOp::Sub => Ok(BinOpMapping::Arith(TrustIrBinOp::Sub)),
        BinOp::Mul => Ok(BinOpMapping::Arith(TrustIrBinOp::Mul)),
        BinOp::Div if signed => Ok(BinOpMapping::Arith(TrustIrBinOp::SDiv)),
        BinOp::Div => Ok(BinOpMapping::Arith(TrustIrBinOp::UDiv)),
        BinOp::Rem if signed => Ok(BinOpMapping::Arith(TrustIrBinOp::SRem)),
        BinOp::Rem => Ok(BinOpMapping::Arith(TrustIrBinOp::URem)),
        BinOp::BitAnd => Ok(BinOpMapping::Arith(TrustIrBinOp::And)),
        BinOp::BitOr => Ok(BinOpMapping::Arith(TrustIrBinOp::Or)),
        BinOp::BitXor => Ok(BinOpMapping::Arith(TrustIrBinOp::Xor)),
        BinOp::Shl => Ok(BinOpMapping::Arith(TrustIrBinOp::Shl)),
        BinOp::Shr if signed => Ok(BinOpMapping::Arith(TrustIrBinOp::AShr)),
        BinOp::Shr => Ok(BinOpMapping::Arith(TrustIrBinOp::LShr)),
        BinOp::Eq => Ok(BinOpMapping::Cmp(ICmpOp::Eq)),
        BinOp::Ne => Ok(BinOpMapping::Cmp(ICmpOp::Ne)),
        BinOp::Lt if signed => Ok(BinOpMapping::Cmp(ICmpOp::Slt)),
        BinOp::Lt => Ok(BinOpMapping::Cmp(ICmpOp::Ult)),
        BinOp::Le if signed => Ok(BinOpMapping::Cmp(ICmpOp::Sle)),
        BinOp::Le => Ok(BinOpMapping::Cmp(ICmpOp::Ule)),
        BinOp::Gt if signed => Ok(BinOpMapping::Cmp(ICmpOp::Sgt)),
        BinOp::Gt => Ok(BinOpMapping::Cmp(ICmpOp::Ugt)),
        BinOp::Ge if signed => Ok(BinOpMapping::Cmp(ICmpOp::Sge)),
        BinOp::Ge => Ok(BinOpMapping::Cmp(ICmpOp::Uge)),
        BinOp::Cmp => Err(BridgeError::UnsupportedOp(
            "three-way Cmp has no direct TrustIr equivalent".to_string(),
        )),
        _ => Err(BridgeError::UnsupportedOp(format!("BinOp::{op:?}"))),
    }
}

fn map_float_binop(op: BinOp) -> Result<FloatBinOpMapping, BridgeError> {
    match op {
        BinOp::Add => Ok(FloatBinOpMapping::Arith(TrustIrBinOp::FAdd)),
        BinOp::Sub => Ok(FloatBinOpMapping::Arith(TrustIrBinOp::FSub)),
        BinOp::Mul => Ok(FloatBinOpMapping::Arith(TrustIrBinOp::FMul)),
        BinOp::Div => Ok(FloatBinOpMapping::Arith(TrustIrBinOp::FDiv)),
        BinOp::Rem => Ok(FloatBinOpMapping::Arith(TrustIrBinOp::FRem)),
        BinOp::Eq => Ok(FloatBinOpMapping::Cmp(FCmpOp::OEq)),
        BinOp::Ne => Ok(FloatBinOpMapping::Cmp(FCmpOp::UNe)),
        BinOp::Lt => Ok(FloatBinOpMapping::Cmp(FCmpOp::OLt)),
        BinOp::Le => Ok(FloatBinOpMapping::Cmp(FCmpOp::OLe)),
        BinOp::Gt => Ok(FloatBinOpMapping::Cmp(FCmpOp::OGt)),
        BinOp::Ge => Ok(FloatBinOpMapping::Cmp(FCmpOp::OGe)),
        BinOp::Cmp => Err(BridgeError::UnsupportedOp(
            "three-way float Cmp has no direct TrustIr equivalent".to_string(),
        )),
        _ => Err(BridgeError::UnsupportedOp(format!("float BinOp::{op:?}"))),
    }
}

/// Result of mapping a trust-types BinOp: either an arithmetic BinOp or
/// an integer comparison.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinOpMapping {
    Arith(TrustIrBinOp),
    Cmp(ICmpOp),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FloatBinOpMapping {
    Arith(TrustIrBinOp),
    Cmp(FCmpOp),
}

// ---------------------------------------------------------------------------
// UnOp mapping
// ---------------------------------------------------------------------------

/// Convert a trust-types `UnOp` to a TrustIr `UnOp`.
pub fn map_unop(op: UnOp) -> Result<TrustIrUnOp, BridgeError> {
    match op {
        UnOp::Not => Ok(TrustIrUnOp::Not),
        UnOp::Neg => Ok(TrustIrUnOp::Neg),
        UnOp::PtrMetadata => {
            Err(BridgeError::UnsupportedOp("PtrMetadata has no TrustIr equivalent".to_string()))
        }
        _ => Err(BridgeError::UnsupportedOp(format!("UnOp::{op:?}"))),
    }
}

/// Map a trust-types BinOp to an OverflowOp for CheckedBinaryOp.
fn map_checked_binop(op: BinOp) -> Result<OverflowOp, BridgeError> {
    match op {
        BinOp::Add => Ok(OverflowOp::AddOverflow),
        BinOp::Sub => Ok(OverflowOp::SubOverflow),
        BinOp::Mul => Ok(OverflowOp::MulOverflow),
        _ => Err(BridgeError::UnsupportedOp(format!(
            "CheckedBinaryOp({op:?}) has no TrustIr Overflow equivalent"
        ))),
    }
}

fn contextless_symbolic_trust_ir_type(formula: &Formula) -> Result<TrustIrTy, BridgeError> {
    sort_to_contextless_trust_ir_type(&infer_sort(formula))
}

fn contextless_symbolic_trust_type(formula: &Formula) -> Result<Ty, BridgeError> {
    sort_to_contextless_trust_type(&infer_sort(formula))
}

fn sort_to_contextless_trust_ir_type(sort: &Sort) -> Result<TrustIrTy, BridgeError> {
    match sort {
        Sort::Bool => Ok(TrustIrTy::Bool),
        Sort::BitVec(width) => bitvec_trust_ir_type(*width),
        Sort::Int | Sort::Array(_, _) => Err(BridgeError::UnsupportedType(format!(
            "contextless symbolic formula sort {} requires a contextual destination type for proof-grade lowering",
            sort.to_smtlib()
        ))),
        _ => Err(BridgeError::UnsupportedType(
            "unknown contextless symbolic formula sort requires a contextual destination type for proof-grade lowering".to_string(),
        )),
    }
}

fn sort_to_contextless_trust_type(sort: &Sort) -> Result<Ty, BridgeError> {
    match sort {
        Sort::Bool => Ok(Ty::Bool),
        Sort::BitVec(width) => bitvec_trust_type(*width),
        Sort::Int | Sort::Array(_, _) => Err(BridgeError::UnsupportedType(format!(
            "contextless symbolic formula sort {} requires a contextual destination type for proof-grade lowering",
            sort.to_smtlib()
        ))),
        _ => Err(BridgeError::UnsupportedType(
            "unknown contextless symbolic formula sort requires a contextual destination type for proof-grade lowering".to_string(),
        )),
    }
}

fn symbolic_formula_undef_blocker(context: &str) -> BridgeError {
    BridgeError::SymbolicFormulaPreservationBlocked { context: context.to_string() }
}

fn bitvec_trust_ir_type(width: u32) -> Result<TrustIrTy, BridgeError> {
    match width {
        8 => Ok(TrustIrTy::U8),
        16 => Ok(TrustIrTy::U16),
        32 => Ok(TrustIrTy::U32),
        64 => Ok(TrustIrTy::U64),
        128 => Ok(TrustIrTy::U128),
        _ => Err(BridgeError::UnsupportedType(format!(
            "symbolic formula bit-vector width {width} has no scalar TrustIr type"
        ))),
    }
}

fn bitvec_trust_type(width: u32) -> Result<Ty, BridgeError> {
    match width {
        8 | 16 | 32 | 64 | 128 => Ok(Ty::Int { width, signed: false }),
        _ => Err(BridgeError::UnsupportedType(format!(
            "symbolic formula bit-vector width {width} has no scalar TrustIr type"
        ))),
    }
}

fn ensure_symbolic_formula_matches_type(
    formula: &Formula,
    expected_ty: &Ty,
) -> Result<(), BridgeError> {
    let sort = infer_sort(formula);
    let compatible = match (&sort, expected_ty) {
        (Sort::Bool, Ty::Bool) => true,
        (Sort::BitVec(width), Ty::Int { width: ty_width, .. } | Ty::Float { width: ty_width }) => {
            width == ty_width
        }
        (Sort::BitVec(width), Ty::Bv(ty_width)) => width == ty_width,
        (Sort::Int, Ty::Int { .. } | Ty::RawPtr { .. } | Ty::Ref { .. }) => true,
        _ => false,
    };

    if compatible {
        Ok(())
    } else {
        Err(BridgeError::UnsupportedType(format!(
            "symbolic formula sort {} is incompatible with contextual destination type {expected_ty:?}",
            sort.to_smtlib()
        )))
    }
}

fn is_byte_addressed_memory_array_sort(sort: &Sort) -> bool {
    matches!(
        sort,
        Sort::Array(index, elem)
            if matches!(index.as_ref(), Sort::BitVec(64))
                && matches!(elem.as_ref(), Sort::BitVec(8))
    )
}

fn operand_trust_type_with_context(
    op: &Operand,
    expected_ty: Option<&Ty>,
    ctx: &LoweringCtx<'_>,
) -> Result<Ty, BridgeError> {
    match (op, expected_ty) {
        (Operand::Symbolic(formula), Some(ty)) => {
            ensure_symbolic_formula_matches_type(formula, ty)?;
            Ok(ty.clone())
        }
        // An integer literal is typed by inference in Rust; the bridge otherwise
        // defaults every `ConstValue::Int` to i64, which spuriously fails the
        // same-width operand check in checked arithmetic (e.g. `x_i32 + 200`).
        // Adopt the context's integer type for an integer constant — but only
        // when the value is exactly representable in it. A non-fitting
        // constant falls through to the contextless default so the caller's
        // type-match check still fails closed — adoption never truncates or
        // reinterprets.
        (Operand::Constant(ConstValue::Int(value)), Some(ty))
            if int_constant_fits_trust_type(*value, ty) =>
        {
            Ok(ty.clone())
        }
        (Operand::Constant(ConstValue::Uint(value, _)), Some(ty))
            if uint_constant_fits_trust_type(*value, ty) =>
        {
            Ok(ty.clone())
        }
        _ => operand_trust_type(op, ctx),
    }
}

/// Whether a width-less trust-types integer literal is exactly representable
/// in the given integer type (no truncation, no sign reinterpretation).
fn int_constant_fits_trust_type(value: i128, ty: &Ty) -> bool {
    // Trust (v25 B1): the faithful scalar spellings adopt context like their
    // carriers — pointer-width ints at the pinned 64-bit target; a char
    // context adopts ONLY valid Unicode scalars (the trust-ir validator
    // rejects out-of-range char constants, so adoption must too).
    match ty {
        Ty::PtrSizedInt { signed: true } => return i64::try_from(value).is_ok(),
        Ty::PtrSizedInt { signed: false } => return value >= 0 && u64::try_from(value).is_ok(),
        Ty::Char => return (0..=0x10FFFF).contains(&value) && !(0xD800..=0xDFFF).contains(&value),
        _ => {}
    }
    let Ty::Int { width, signed } = ty else {
        return false;
    };
    match (width, signed) {
        (8, true) => i8::try_from(value).is_ok(),
        (16, true) => i16::try_from(value).is_ok(),
        (32, true) => i32::try_from(value).is_ok(),
        (64, true) => i64::try_from(value).is_ok(),
        (128, true) => true,
        (8, false) => u8::try_from(value).is_ok(),
        (16, false) => u16::try_from(value).is_ok(),
        (32, false) => u32::try_from(value).is_ok(),
        (64, false) => u64::try_from(value).is_ok(),
        (128, false) => value >= 0,
        _ => false,
    }
}

/// Whether an unsigned trust-types integer literal is exactly representable in
/// the given integer type (same exact-fit rule as
/// [`int_constant_fits_trust_type`]).
fn uint_constant_fits_trust_type(value: u128, ty: &Ty) -> bool {
    // Trust (v25 B1): faithful scalar arms, the unsigned-domain mirror of
    // `int_constant_fits_trust_type` (char adoption checks the Unicode
    // scalar range, exactly like the trust-ir validator).
    match ty {
        Ty::PtrSizedInt { signed: true } => return value <= i64::MAX as u128,
        Ty::PtrSizedInt { signed: false } => return value <= u64::MAX as u128,
        Ty::Char => return value <= 0x10FFFF && !(0xD800..=0xDFFF).contains(&value),
        _ => {}
    }
    let Ty::Int { width, signed } = ty else {
        return false;
    };
    match (width, signed) {
        (8, true) => value <= i8::MAX as u128,
        (16, true) => value <= i16::MAX as u128,
        (32, true) => value <= i32::MAX as u128,
        (64, true) => value <= i64::MAX as u128,
        (128, true) => value <= i128::MAX as u128,
        (8, false) => value <= u8::MAX as u128,
        (16, false) => value <= u16::MAX as u128,
        (32, false) => value <= u32::MAX as u128,
        (64, false) => value <= u64::MAX as u128,
        // TrustIr v24 carries the upper half canonically as `Constant::U128`.
        (128, false) => true,
        _ => false,
    }
}

// ---------------------------------------------------------------------------
// Lowering context
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct KnownFunctionSignature {
    id: FuncId,
    params: Vec<Ty>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CallArgLowering {
    AsWritten,
    FlattenRustCallTuple {
        field_count: usize,
    },
    /// Rust-call ABI with a FUNCTION-ITEM receiver (`FnOnce::call_once(f, (a, b))`
    /// where `f` is an `FnDef`): the resolved callee takes exactly the tuple
    /// fields — the ZST receiver carries no data and is DROPPED, the tuple is
    /// flattened.
    FnDefRustCallTuple {
        field_count: usize,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ResolvedCall {
    callee: FuncId,
    args: CallArgLowering,
}

/// Internal bridge view of compiler-authenticated authority for one certified
/// paired-condvar wait.
///
/// This view is deliberately absent from [`VerifiableFunction`] and every
/// serialized/public result type. Production can create it only by consuming
/// constructor-free opaque capabilities returned by trust-mir-extract's
/// authenticated collector under the optional compiler-only feature. Plain
/// lowering APIs install no entries, so a forged callee suffix or independently
/// fabricated `VerifiableFunction` remains an ordinary fatal absent call.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct CompilerCertifiedPairedCondvarWaitSite {
    function_def_path: String,
    body_digest: String,
    block: BlockId,
    callee: String,
    _receiver_place: String,
    _guard_place: String,
}

fn paired_condvar_body_digest(
    function_def_path: &str,
    body: &trust_types::VerifiableBody,
) -> Result<String, BridgeError> {
    serde_json::to_vec(body)
        .map(|bytes| trust_types::stable_sha256_hex(&bytes))
        .map_err(|error| BridgeError::PairedCondvarBodyDigest {
            function_def_path: function_def_path.to_owned(),
            reason: error.to_string(),
        })
}

impl CompilerCertifiedPairedCondvarWaitSite {
    #[cfg(feature = "compiler-context")]
    fn from_extractor_capability(
        site: &trust_mir_extract::CertifiedPairedCondvarWaitCallSite,
    ) -> Self {
        Self {
            function_def_path: site.function_def_path().to_owned(),
            body_digest: site.body_digest().to_owned(),
            block: site.block(),
            callee: site.callee().to_owned(),
            _receiver_place: site.receiver_place().to_owned(),
            _guard_place: site.guard_place().to_owned(),
        }
    }

    #[cfg(test)]
    fn test_only(
        function_def_path: String,
        body_digest: String,
        block: BlockId,
        callee: String,
    ) -> Self {
        Self {
            function_def_path,
            body_digest,
            block,
            callee,
            _receiver_place: "test-receiver".into(),
            _guard_place: "test-guard".into(),
        }
    }

    fn authorizes(
        &self,
        function_def_path: &str,
        body_digest: &str,
        block: BlockId,
        callee: &str,
    ) -> bool {
        self.function_def_path == function_def_path
            && self.body_digest == body_digest
            && self.block == block
            && self.callee == callee
    }
}

/// Internal state for the lowering pass.
struct LoweringCtx<'a> {
    /// Local variable declarations from the trust-types body.
    locals: &'a [LocalDecl],
    /// Number of MIR argument locals. MIR args occupy locals `1..=arg_count`.
    arg_count: usize,
    /// TrustIr entry block that receives function arguments as block params.
    entry_block: TrustIrBlockId,
    /// Map from trust-types local index to TrustIr ValueId.
    local_values: FxHashMap<usize, ValueId>,
    /// Values whose semantics originate from a preserved symbolic formula.
    symbolic_values: FxHashSet<ValueId>,
    /// Locals whose current value contains a preserved symbolic formula.
    symbolic_locals: FxHashSet<usize>,
    /// More precise local types recovered during lowering.
    ///
    /// rustc closure locals can enter trust-types as `Ty::Unsupported` when
    /// the type converter lacks environment metadata. `AggregateKind::Closure`
    /// still carries the capture operands, so direct closure materialization can
    /// refine the local to a typed closure environment without weakening later
    /// place/drop checks.
    local_type_refinements: FxHashMap<usize, Ty>,
    /// Memory slots materialized for locals whose address is taken.
    local_ptrs: FxHashMap<usize, ValueId>,
    /// Stable context-aware type mappings for layout-dependent types.
    type_cache: &'a mut FxHashMap<Ty, TrustIrTy>,
    /// Next available ValueId.
    next_value: u32,
    /// TrustIr module being built (for type/struct registration).
    module: &'a mut Module,
    /// Function names/paths that can be targeted by direct calls in this module.
    known_functions: FxHashMap<String, FuncId>,
    /// Callee def-paths that are EXPECTED to be absent from the bundle (unresolved
    /// generic trait dispatch / `#[trust::skip]`, per the caller's
    /// `collect_expected_absent_callees`). An absent-callee arm whose `callee` is in
    /// this set marks its `PanicFreedom` obligation with
    /// `EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX` (→ verify pass DEMOTES, non-fatal)
    /// instead of the fatal `ABSENT_CALLEE_ASSUMPTION_PREFIX`. Empty for single-fn /
    /// plain lowering — those keep the fatal marker (fail-closed). See
    /// `lower_to_trust_ir_functions_with_expected_absent`.
    expected_absent_callees: FxHashSet<String>,
    /// Callee def-paths that are genuinely bodyless foreign non-unwinding
    /// extern-"C" imports and therefore ABI-guaranteed panic-free with respect
    /// to this caller. A matching absent call discharges only its panic-freedom
    /// obligation. The compiler admits only foreign items to this set, so a
    /// local Rust `extern "C" fn` with a real body never receives this authority.
    /// Empty for single-function and plain lowering paths.
    abi_total_panic_free_callees: FxHashSet<String>,
    /// Callees explicitly marked `#[trust::assume_total]`. Their absent-callee
    /// obligation remains an honest may-panic assumption, but carries a
    /// dedicated marker that the compiler records non-fatally in every mode.
    /// Expected-absent membership takes precedence at emission sites.
    assumed_total_callees: FxHashSet<String>,
    /// Exact call identities the COMPILER decided are TOTAL from real tcx
    /// types (today: the `?`-desugar calls whose residual/target error types
    /// are invisible at this layer). Populated only through the
    /// compiler-context entry point; every public lowering API leaves it
    /// empty, so a detached caller can never grant membership.
    compiler_total_callees: FxHashSet<String>,
    /// Exact compiler-authenticated paired-condvar wait call sites. This is a
    /// non-serialized sidecar and is empty on every plain/public lowering path.
    /// Duplicate input identities reject the compiler-context request before
    /// reaching this context.
    certified_paired_condvar_wait_sites: FxHashSet<CompilerCertifiedPairedCondvarWaitSite>,
    /// User-struct def-paths with NO `Drop` impl (per the compiler's
    /// `collect_structural_drop_adts`). A `Drop` of such a struct is recognized
    /// panic-free-drop (its glue is only the field drops) instead of fail-closing
    /// on the drop-glue gate's "non-std Adt may have a panicking `Drop`" default.
    /// Empty for single-fn / plain lowering (fail-closed kept).
    structural_drop_adts: FxHashSet<String>,
    /// Function names/paths with trust-types signatures for callable-shim checks.
    known_function_signatures: FxHashMap<String, KnownFunctionSignature>,
    /// Proof obligations collected during lowering.
    proof_obligations: Vec<ProofObligation>,
    /// Next proof obligation id.
    next_proof_id: u32,
    /// Rust def-path used for stable proof-source ids.
    function_def_path: String,
    /// Function that owns every obligation emitted by this lowering context.
    current_function: FuncId,
    /// Exact digest of the complete VerifiableBody being lowered. Paired-
    /// condvar capabilities must match it byte-for-byte.
    function_body_digest: String,
    /// MIR block ids whose terminator is `Terminator::Unreachable`. rustc emits
    /// these only for paths it has PROVEN infeasible — most commonly the
    /// `otherwise` arm of an exhaustive enum-discriminant `SwitchInt` (the
    /// discriminant is provably a valid variant tag). A switch whose default
    /// targets one of these blocks may therefore soundly assume the discriminant
    /// equals one of its explicit cases, discharging the (genuinely infeasible)
    /// unreachable obligation. Populated once per function in `lower_to_trust_ir`.
    unreachable_block_ids: FxHashSet<usize>,
    /// The whole trust-types block list of the function being lowered.
    ///
    /// Trust (trust-ir-spine Phase 2, L0 safety formulas): read-only access to
    /// every block so the `Terminator::Assert` lowering can recover the binop
    /// operands a safety obligation ranges over — these live in the assert's
    /// SOURCE block (e.g. `Add(a,b)` for an `Overflow(Add)` assert) or its TARGET
    /// block (e.g. `Div(a,b)` for a `DivisionByZero` assert), exactly the same two
    /// places `trust-vcgen`'s `v2_build_assert_*_vc` looks. Used ONLY to
    /// reconstruct the solvable safety `Formula` stamped onto the obligation; the
    /// instruction lowering itself never consults it. Empty for the legacy
    /// single-block fast paths that do not set it (those carry no cross-block
    /// safety recovery).
    all_blocks: &'a [TrustBlock],
    /// Locals written across two or more reachable blocks (see
    /// `multi_block_written_locals`). They are promoted to memory slots at the
    /// top of the entry block so their cross-block joins flow through
    /// `Store`/`Load` instead of an undominated SSA value, which the TrustIr
    /// validator rejects as a use-before-def.
    memory_merge_locals: FxHashSet<usize>,
    /// `module.func_types.len()` at ctx creation: the start of THIS function's
    /// fn-pointer-signature dedup scope (the `Ty::FnPtr -> Ty::Func` arm of
    /// `map_type_ctx` dedups structurally among the entries this ctx registered,
    /// mirroring the producer's per-body `pend_func_ty` first-encounter dedup;
    /// entries of other functions are never aliased). `lower_function_into`
    /// reserves the function's OWN signature slot before creating the ctx, so
    /// this base sits just past it — the producer's slot-0 convention.
    func_ty_base: usize,
}

impl<'a> LoweringCtx<'a> {
    #[allow(clippy::too_many_arguments)]
    fn new(
        locals: &'a [LocalDecl],
        arg_count: usize,
        entry_block: TrustIrBlockId,
        module: &'a mut Module,
        known_functions: FxHashMap<String, FuncId>,
        known_function_signatures: FxHashMap<String, KnownFunctionSignature>,
        closure_env_types: &'a ClosureEnvTypes,
        type_cache: &'a mut FxHashMap<Ty, TrustIrTy>,
        function_def_path: &str,
        all_blocks: &'a [TrustBlock],
    ) -> Self {
        let mut local_type_refinements = FxHashMap::default();
        for local in locals {
            if let Ty::Unsupported { kind, detail } = &local.ty
                && let Some(refined) = closure_env_type_for_unsupported_marker(
                    kind,
                    detail,
                    function_def_path,
                    closure_env_types,
                )
            {
                local_type_refinements.insert(local.index, refined);
            }
        }

        // Obligation ids must be UNIQUE across the WHOLE module, not per-function. In a
        // multi-function bundle (`lower_to_trust_ir_functions`: a caller + its proven-total
        // local callees), each function's obligations are drained into the SAME module, so
        // starting every function's counter at 0 collides — the caller's `ProofId(0..)` and
        // the callee's `ProofId(0..)` overlap, and the native bundle's `ProofLineage`
        // validation rejects the result (`DuplicateObligation`), forcing the caller's OWN
        // arithmetic obligation to UNKNOWN (e.g. `type_max_formula`'s `(1<<width)-1` once it
        // also calls `signed_max`). Continue the counter from the obligations already in the
        // module so ids stay globally unique. (Single-function lowering: the module starts
        // empty, so this is `0` — unchanged.) The obligation's formula + string `source_id`
        // travel WITH it, so renumbering the id breaks no association.
        let next_proof_id = module.proof_obligations.len() as u32;
        let func_ty_base = module.func_types.len();
        let current_function = FuncId::new(module.functions.len() as u32);
        let mut ctx = Self {
            locals,
            arg_count,
            entry_block,
            local_values: FxHashMap::with_capacity_and_hasher(locals.len(), Default::default()),
            symbolic_values: FxHashSet::default(),
            symbolic_locals: FxHashSet::default(),
            local_type_refinements,
            local_ptrs: FxHashMap::default(),
            type_cache,
            next_value: 0,
            module,
            known_functions,
            // Default empty; `lower_function_into` overwrites it from its
            // `expected_absent_callees` param on the multi-fn bundle path.
            expected_absent_callees: FxHashSet::default(),
            abi_total_panic_free_callees: FxHashSet::default(),
            assumed_total_callees: FxHashSet::default(),
            compiler_total_callees: FxHashSet::default(),
            certified_paired_condvar_wait_sites: FxHashSet::default(),
            structural_drop_adts: FxHashSet::default(),
            known_function_signatures,
            proof_obligations: Vec::new(),
            next_proof_id,
            function_def_path: function_def_path.to_string(),
            function_body_digest: String::new(),
            current_function,
            unreachable_block_ids: FxHashSet::default(),
            all_blocks,
            memory_merge_locals: FxHashSet::default(),
            func_ty_base,
        };
        // Assign argument locals first (locals[1..=arg_count] are args in MIR convention).
        for i in 1..=arg_count {
            if locals.iter().any(|l| l.index == i) {
                let val = ValueId::new(ctx.next_value);
                ctx.next_value += 1;
                ctx.local_values.insert(i, val);
            }
        }
        // Then assign remaining locals.
        for local in locals {
            if !ctx.local_values.contains_key(&local.index) {
                let val = ValueId::new(ctx.next_value);
                ctx.next_value += 1;
                ctx.local_values.insert(local.index, val);
            }
        }
        // Trust (B2-1b): pre-intern the BYTE-SLICE fat type (`[u8]` ->
        // FatPtr(Slice(u8))) so the READ-ONLY type queries (`operand_trust_ir_type`'s
        // Str/OpaqueConst/UnitVariantRef arms) can always resolve it from the cache,
        // ordering-independently — the &str Gap-3 lane types every opaque string/table
        // constant at this exact spelling.
        let _ =
            ctx.map_type_ctx(&Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) });
        ctx
    }

    /// Allocate a fresh temporary ValueId.
    fn fresh_value(&mut self) -> ValueId {
        let v = ValueId::new(self.next_value);
        self.next_value += 1;
        v
    }

    fn value_is_symbolic(&self, value: ValueId) -> bool {
        self.symbolic_values.contains(&value)
    }

    fn mark_value_symbolic(&mut self, value: ValueId) {
        self.symbolic_values.insert(value);
    }

    fn mark_value_symbolic_if(&mut self, value: ValueId, symbolic: bool) {
        if symbolic {
            self.mark_value_symbolic(value);
        } else {
            self.symbolic_values.remove(&value);
        }
    }

    fn mark_result_symbolic_from(&mut self, result: ValueId, sources: &[ValueId]) {
        self.mark_value_symbolic_if(
            result,
            sources.iter().any(|source| self.value_is_symbolic(*source)),
        );
    }

    fn ensure_no_symbolic_undef_seed(
        &self,
        context: &str,
        values: &[ValueId],
    ) -> Result<(), BridgeError> {
        if values.iter().any(|value| self.value_is_symbolic(*value)) {
            return Err(symbolic_formula_undef_blocker(context));
        }
        Ok(())
    }

    /// Trust (B2-1b): a U64 constant for LENGTH-lane arithmetic — the metadata lane
    /// is canonically U64, so every value mixed with it (offsets, trims) must match.
    fn emit_u64_const(&mut self, value: u64, body: &mut Vec<InstrNode>) -> ValueId {
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Const {
                ty: TrustIrTy::U64,
                value: TrustIrConstant::Int(value as i128),
            })
            .with_result(result),
        );
        result
    }

    /// Convert between the faithful Rust `usize` value spelling (`Usize`) and
    /// the canonical 64-bit slice-metadata spelling (`U64`) without changing a
    /// bit.  Merely using a different instruction type for the same ValueId is
    /// invalid TrustIr and can let a downstream consumer read the value under a
    /// type it never had; make the representation boundary explicit instead.
    fn emit_exact_usize_metadata_cast(
        &mut self,
        value: ValueId,
        src_ty: TrustIrTy,
        dst_ty: TrustIrTy,
        context: &str,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        if src_ty == dst_ty {
            return Ok(value);
        }
        if !matches!(
            (&src_ty, &dst_ty),
            (TrustIrTy::Usize, TrustIrTy::U64) | (TrustIrTy::U64, TrustIrTy::Usize)
        ) {
            return Err(BridgeError::UnsupportedOp(format!(
                "{context} requires an exact usize/U64 representation boundary; got {src_ty:?} -> {dst_ty:?}"
            )));
        }

        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Cast { op: CastOp::Bitcast, src_ty, dst_ty, operand: value })
                .with_result(result),
        );
        self.mark_result_symbolic_from(result, &[value]);
        Ok(result)
    }

    /// Resolve a Rust `usize` operand and normalize it to the canonical U64
    /// metadata lane required by `FatPtr(Slice(..))`'s PtrFromParts/metadata
    /// contract. Constants adopt the U64 context; faithful `Usize` place values
    /// cross through an explicit same-width bitcast.
    fn resolve_usize_operand_as_u64(
        &mut self,
        operand: &Operand,
        context: &str,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let legacy_usize = Ty::Int { width: 64, signed: false };
        let source_ty = operand_trust_type_with_context(operand, Some(&legacy_usize), self)?;
        if !is_trust_usize_ty(&source_ty) {
            return Err(BridgeError::UnsupportedOp(format!(
                "{context} requires a precise usize operand; got {source_ty:?}"
            )));
        }
        let source_ir_ty = self.map_type_ctx(&source_ty)?;
        let value = self.resolve_operand_as_trust_type(operand, &source_ty, body)?;
        self.emit_exact_usize_metadata_cast(value, source_ir_ty, TrustIrTy::U64, context, body)
    }

    /// Adapt the canonical U64 result of PtrMetadata/Len to the destination's
    /// Rust `usize` spelling. Compatibility inputs already use U64; faithful
    /// inputs receive an explicit U64 -> Usize bitcast.
    fn adapt_u64_metadata_to_destination(
        &mut self,
        metadata: ValueId,
        dest: &Place,
        context: &str,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let dest_ty = place_type(dest, self)?;
        if !is_trust_usize_ty(&dest_ty) {
            return Err(BridgeError::UnsupportedOp(format!(
                "{context} destination must be a precise usize; got {dest_ty:?}"
            )));
        }
        let dest_ir_ty = self.map_type_ctx(&dest_ty)?;
        self.emit_exact_usize_metadata_cast(metadata, TrustIrTy::U64, dest_ir_ty, context, body)
    }

    fn emit_usize_const(&mut self, value: u64, body: &mut Vec<InstrNode>) -> ValueId {
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Const {
                ty: TrustIrTy::I64,
                value: TrustIrConstant::Int(value as i128),
            })
            .with_result(result),
        );
        result
    }

    /// Trust (B2-1b): project the DATA lane of a first-class fat pointer via the
    /// FORMAT's own `PtrData` (the `ExtractField 0` tuple projection retired with
    /// the anonymous spelling). `fat_ty` is the operand's `TrustIrTy::FatPtr(..)`.
    fn emit_slice_data_ptr(
        &mut self,
        fat_ty: TrustIrTy,
        fat_ptr: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> ValueId {
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::PtrData { ptr_ty: fat_ty, ptr: fat_ptr }).with_result(result),
        );
        self.mark_result_symbolic_from(result, &[fat_ptr]);
        result
    }

    /// Trust (B2-1b): project the METADATA lane (the length) via `PtrMetadata` at the
    /// canonical U64 metadata type — the exact gate trust-mc's CHC slice-len bound
    /// keys on (`metadata_ty == Ty::U64` -> symbolic length bvule isize::MAX).
    fn emit_slice_metadata(
        &mut self,
        fat_ty: TrustIrTy,
        fat_ptr: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> ValueId {
        // Trust (B2-3): metadata_ty follows the FAT KIND — a length (canonical U64)
        // for Slice/Str, a vtable pointer for TraitObject. Correct-by-construction
        // beats a guard: a hardcoded U64 on a TraitObject fat value would emit a
        // module the validator rejects wholesale (`check_pointer_metadata_ty`).
        let metadata_ty = match &fat_ty {
            TrustIrTy::FatPtr(trust_ir::FatPtrKind::TraitObject { .. }) => TrustIrTy::Ptr,
            _ => TrustIrTy::U64,
        };
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::PtrMetadata { ptr_ty: fat_ty, metadata_ty, ptr: fat_ptr })
                .with_result(result),
        );
        self.mark_result_symbolic_from(result, &[fat_ptr]);
        result
    }

    /// Trust (B2-1b): assemble a first-class fat pointer via the FORMAT's own
    /// `PtrFromParts` (canonical U64 metadata). The symbolic lane keeps the
    /// DialectOp channel but at the FAT type (a symbolic fat value is one opaque
    /// symbolic term either way — the aggregate seed shape retired with the
    /// anonymous tuple spelling).
    fn emit_slice_fat_pointer(
        &mut self,
        fat_ty: TrustIrTy,
        data_ptr: ValueId,
        len: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        // Trust (B2-3): this assembler's metadata operand is semantically a LENGTH —
        // a TraitObject fat type here is an internal invariant break (its metadata is
        // a vtable pointer no length lane can supply). Err precisely instead of
        // emitting a module the validator rejects wholesale.
        if matches!(&fat_ty, TrustIrTy::FatPtr(trust_ir::FatPtrKind::TraitObject { .. })) {
            return Err(BridgeError::UnsupportedOp(
                "trait-object fat pointer cannot be assembled from a length lane".to_string(),
            ));
        }
        if self.value_is_symbolic(data_ptr) || self.value_is_symbolic(len) {
            return self.emit_symbolic_aggregate(
                "slice_fat_pointer",
                fat_ty,
                &[data_ptr, len],
                body,
            );
        }
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::PtrFromParts {
                ptr_ty: fat_ty,
                metadata_ty: TrustIrTy::U64,
                data: data_ptr,
                metadata: len,
            })
            .with_result(result),
        );
        Ok(result)
    }

    /// Get the TrustIr ValueId for a trust-types local index.
    fn local_value(&self, index: usize) -> Result<ValueId, BridgeError> {
        self.local_values.get(&index).copied().ok_or(BridgeError::MissingLocal(index))
    }

    fn read_local(
        &mut self,
        index: usize,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let Some(ptr) = self.local_ptrs.get(&index).copied() else {
            return self.local_value(index);
        };

        let local_ty = self.local_ty(index)?.clone();
        let ty = self.map_type_ctx(&local_ty)?;
        let result = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Load { ty, ptr, volatile: false, align: None })
                .with_result(result),
        );
        if self.symbolic_locals.contains(&index) {
            self.mark_value_symbolic(result);
        }
        Ok(result)
    }

    fn write_local(
        &mut self,
        index: usize,
        value: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> Result<(), BridgeError> {
        if self.value_is_symbolic(value) {
            self.symbolic_locals.insert(index);
        } else {
            self.symbolic_locals.remove(&index);
        }
        self.local_values.insert(index, value);

        if let Some(ptr) = self.local_ptrs.get(&index).copied() {
            let local_ty = self.local_ty(index)?.clone();
            let ty = self.map_type_ctx(&local_ty)?;
            body.push(InstrNode::new(Inst::Store { ty, ptr, value, volatile: false, align: None }));
        }

        Ok(())
    }

    /// Get the type of a local by index.
    fn local_ty(&self, index: usize) -> Result<&Ty, BridgeError> {
        if let Some(ty) = self.local_type_refinements.get(&index) {
            return Ok(ty);
        }
        self.locals
            .iter()
            .find(|l| l.index == index)
            .map(|l| &l.ty)
            .ok_or(BridgeError::MissingLocal(index))
    }

    fn refine_local_ty(&mut self, index: usize, ty: Ty) {
        self.local_type_refinements.insert(index, ty);
    }

    fn local_is_lifted_memory_state_carrier(&self, index: usize) -> bool {
        self.locals.iter().any(|local| {
            local.index == index
                && local.name.as_deref() == Some("MEM")
                && matches!(local.ty, Ty::Int { width: 64, signed: false })
        })
    }

    fn ensure_local_storage(
        &mut self,
        index: usize,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        if let Some(ptr) = self.local_ptrs.get(&index).copied() {
            return Ok(ptr);
        }

        let local_ty = self.local_ty(index)?.clone();
        let ty = self.map_type_ctx(&local_ty)?;
        let ptr = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Alloca { ty: ty.clone(), count: None, align: None })
                .with_result(ptr),
        );

        let current = self.local_value(index)?;
        body.push(InstrNode::new(Inst::Store {
            ty,
            ptr,
            value: current,
            volatile: false,
            align: None,
        }));
        self.local_ptrs.insert(index, ptr);
        Ok(ptr)
    }

    /// Promote a local to a memory slot. Argument slots retain their real entry
    /// value; non-argument slots begin uninitialized and acquire a value only
    /// from a real MIR write. Used for locals written across multiple blocks:
    /// after this, `write_local` emits a `Store` and `read_local` emits a `Load`,
    /// giving a sound cross-block merge. An invalid load before the first write
    /// therefore remains an uninitialized-memory error instead of observing a
    /// fabricated seed. Idempotent: a local already backed by storage is left
    /// as-is.
    fn promote_local_to_memory(
        &mut self,
        index: usize,
        body: &mut Vec<InstrNode>,
    ) -> Result<(), BridgeError> {
        if self.local_ptrs.contains_key(&index) {
            return Ok(());
        }
        // Argument locals (`1..=arg_count`) already hold the entry block's param
        // ValueId — a real dominating definition. Store THAT into the slot so the
        // incoming argument value is preserved.
        let is_arg = index >= 1 && index <= self.arg_count;
        if is_arg {
            self.ensure_local_storage(index, body)?;
            return Ok(());
        }

        // A non-argument local has no source-level value until its first MIR
        // assignment. Allocate its merge slot without initializing it. The
        // TrustIr interpreter tracks initialized bytes, so any path that Loads
        // before a real Store fails closed as UndefinedBehavior. In particular,
        // do not emit `Undef -> Store`: replacing that declaration seed with a
        // deterministic zero in the differential would invent behavior.
        let local_ty = self.local_ty(index)?.clone();
        let ty = self.map_type_ctx(&local_ty)?;
        let ptr = self.fresh_value();
        body.push(InstrNode::new(Inst::Alloca { ty, count: None, align: None }).with_result(ptr));
        self.local_ptrs.insert(index, ptr);
        Ok(())
    }

    fn address_of_place(
        &mut self,
        place: &Place,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        self.address_of_place_expecting(place, None, body)
    }

    /// [`Self::address_of_place`] with the place's EXPECTED final type from
    /// the consuming context (the pointee of the `Rvalue::Ref` destination's
    /// declared `&FieldTy` type). MIR is type-correct, so the expectation IS
    /// the addressed place's type; it is consulted ONLY to type the
    /// compacted-Datatype fail-soft GEP in [`Self::address_from_pointer`] —
    /// every precise projection still derives its type from the place walk
    /// itself. `None` keeps the historical fail-closed behavior everywhere.
    fn address_of_place_expecting(
        &mut self,
        place: &Place,
        expected_final_ty: Option<&Ty>,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let storage_projections: Vec<&Projection> = place
            .projections
            .iter()
            .filter(|projection| !is_type_only_projection(projection))
            .collect();

        if storage_projections
            .first()
            .is_some_and(|projection| matches!(projection, Projection::Deref))
        {
            let ptr = self.read_local(place.local, body)?;
            let ptr_ty = self.local_ty(place.local)?.clone();
            let pointee_ty = ptr_ty.pointee_ty().cloned().ok_or_else(|| {
                BridgeError::UnsupportedOp(format!(
                    "address-of Deref projection on non-pointer type {ptr_ty:?}"
                ))
            })?;
            return self.address_from_pointer(
                ptr,
                &pointee_ty,
                &storage_projections[1..],
                expected_final_ty,
                body,
            );
        }

        let ptr = self.ensure_local_storage(place.local, body)?;
        let local_ty = self.local_ty(place.local)?.clone();
        self.address_from_pointer(ptr, &local_ty, &storage_projections, expected_final_ty, body)
    }

    fn address_from_pointer(
        &mut self,
        mut ptr: ValueId,
        ty: &Ty,
        projections: &[&Projection],
        expected_final_ty: Option<&Ty>,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let mut current_ty = ty.clone();

        for (proj_index, projection) in projections.iter().enumerate() {
            // Trust (B3-1b G1 hardening): a variant-bearing ADT interior has no
            // representation-independent address walk here. `Downcast` below is
            // type-only and the following `Field(i)` uses a flattened physical
            // index; for a faithful enum that can target the tag/canonical wrong
            // lane, and for a flat enum it can target another variant's field.
            // Reject every address walk, before emitting a GEP. Checking at
            // every step also catches an enum nested inside a struct/array. A
            // whole-enum address/store has no remaining projection and stays
            // supported, as do projections through non-enum aggregates.
            if current_ty.is_enum_adt() {
                return Err(BridgeError::UnsupportedOp(
                    "address walk into variant-bearing ADT interior".to_string(),
                ));
            }

            // Lever A fail-soft, borrow/GEP mirror of the READ-path guard in
            // `resolve_place_expecting` (full regression-class rationale on
            // its doc comment): a `Field` address INTO an opaque
            // `Ty::Datatype` — the extractor's compacted-field marker
            // (`__trust_compacted_aggregate`) or a by-name recursive-ADT
            // reference — cannot be resolved structurally, so `field_type`
            // below hard-fails and drops the WHOLE function (the
            // `certz::qpair_json` class: `Ratio::numer` inlines to
            // `&(*r).0`). When the consumer's expected final (pointee) type
            // is known and mappable and every remaining projection is a pure
            // field walk (`Field`/`Downcast` — never `Index`/`ConstantIndex`,
            // whose bounds panic must stay modeled, and never `Deref`, whose
            // load must stay modeled), model the WHOLE remaining walk as ONE
            // GEP typed at the expectation — the same result shape as the
            // precise arm below.
            //
            // SOUNDNESS: the GEP result carries NO facts — the trust-mc
            // consumer havocs GEP results (fresh symbolic ptr) and flags
            // through-pointer memory ops as unsupported under bounds-checking
            // (the comment on the precise arm below), so this is strictly
            // weaker than real field resolution: it may only WIDEN what the
            // verifier must prove, never narrow it. No `Assume`, no constant,
            // no equality is emitted about the compacted contents. When the
            // expected type is missing or unmappable, the original
            // `field_type` hard fail below is preserved (fail-closed).
            if matches!(current_ty, Ty::Datatype { .. })
                && let Some(expected) = expected_final_ty
                && projections[proj_index..]
                    .iter()
                    .all(|p| matches!(p, Projection::Field(_) | Projection::Downcast(_)))
                && let Some(first_field_idx) = projections[proj_index..]
                    .iter()
                    .find_map(|p| if let Projection::Field(idx) = p { Some(*idx) } else { None })
                && let Ok(expected_trust_ir_ty) = self.map_type_ctx(expected)
            {
                let index = self.emit_usize_const(first_field_idx as u64, body);
                let result = self.fresh_value();
                body.push(
                    InstrNode::new(Inst::GEP {
                        pointee_ty: expected_trust_ir_ty,
                        base: ptr,
                        indices: vec![index],
                        inbounds: false,
                    })
                    .with_result(result),
                );
                self.mark_result_symbolic_from(result, &[ptr, index]);
                return Ok(result);
            }
            match projection {
                Projection::Index(idx_local) => {
                    let index = self.read_local(*idx_local, body)?;
                    let elem_ty = indexed_element_type(&current_ty, "Index")?;
                    ptr = if slice_element_type(&current_ty).is_some() {
                        self.emit_slice_element_ptr(ptr, &current_ty, index, body)?
                    } else {
                        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
                        let result = self.fresh_value();
                        body.push(
                            InstrNode::new(Inst::GEP {
                                pointee_ty: elem_trust_ir_ty,
                                base: ptr,
                                indices: vec![index],
                                inbounds: false,
                            })
                            .with_result(result),
                        );
                        self.mark_result_symbolic_from(result, &[ptr, index]);
                        result
                    };
                    current_ty = elem_ty;
                }
                Projection::ConstantIndex { offset, min_length, from_end } => {
                    let elem_ty = indexed_element_type(&current_ty, "ConstantIndex")?;
                    let index = if slice_element_type(&current_ty).is_some() {
                        let fat_trust_ir = self.map_type_ctx(&current_ty)?;
                        self.constant_slice_index_value(fat_trust_ir, ptr, *offset, *from_end, body)
                    } else {
                        constant_array_index_value(
                            &current_ty,
                            *offset,
                            *min_length,
                            *from_end,
                            self,
                            body,
                        )?
                    };
                    ptr = if slice_element_type(&current_ty).is_some() {
                        self.emit_slice_element_ptr(ptr, &current_ty, index, body)?
                    } else {
                        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
                        let result = self.fresh_value();
                        body.push(
                            InstrNode::new(Inst::GEP {
                                pointee_ty: elem_trust_ir_ty,
                                base: ptr,
                                indices: vec![index],
                                inbounds: false,
                            })
                            .with_result(result),
                        );
                        self.mark_result_symbolic_from(result, &[ptr, index]);
                        result
                    };
                    current_ty = elem_ty;
                }
                Projection::Subslice { from, to, from_end }
                    if matches!(current_ty, Ty::Array { .. }) =>
                {
                    let elem_ty = indexed_element_type(&current_ty, "Subslice")?;
                    let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
                    let index = self.emit_usize_const(*from as u64, body);
                    let result = self.fresh_value();
                    body.push(
                        InstrNode::new(Inst::GEP {
                            pointee_ty: elem_trust_ir_ty,
                            base: ptr,
                            indices: vec![index],
                            inbounds: false,
                        })
                        .with_result(result),
                    );
                    self.mark_result_symbolic_from(result, &[ptr, index]);
                    ptr = result;
                    current_ty = subslice_result_type(&current_ty, *from, *to, *from_end)?;
                }
                Projection::Subslice { from, to, from_end }
                    if slice_element_type(&current_ty).is_some() =>
                {
                    ptr = self.emit_subslice(ptr, &current_ty, *from, *to, *from_end, body)?;
                    current_ty = subslice_result_type(&current_ty, *from, *to, *from_end)?;
                }
                Projection::Downcast(_) => {}
                Projection::Field(idx) => {
                    // Trust Gap 3: `&place.field` — advance the pointer to field
                    // `idx` with a GEP, exactly like the array-index case above.
                    // The trust-mc consumer havocs GEP results (fresh symbolic
                    // ptr) and flags through-pointer memory ops as unsupported
                    // under bounds-checking, so this is a sound over-approximation
                    // (no false facts; precise field-address obligations stay
                    // `unknown`) that inherits the same soundness the array-address
                    // path already relies on. Unblocks lowering of functions that
                    // take field addresses (derived Clone/Default/PartialEq,
                    // `&mut self.field`, ...). field_type fails closed for shapes
                    // it can't resolve, preserving the previous refusal there.
                    let field_ty = field_type(&current_ty, *idx)?;
                    let field_trust_ir_ty = self.map_type_ctx(&field_ty)?;
                    let index = self.emit_usize_const(*idx as u64, body);
                    let result = self.fresh_value();
                    body.push(
                        InstrNode::new(Inst::GEP {
                            pointee_ty: field_trust_ir_ty,
                            base: ptr,
                            indices: vec![index],
                            inbounds: false,
                        })
                        .with_result(result),
                    );
                    self.mark_result_symbolic_from(result, &[ptr, index]);
                    ptr = result;
                    current_ty = field_ty;
                }
                Projection::Deref => {
                    return Err(BridgeError::UnsupportedOp(
                        "nested address-of Deref projection requires pointer-field address lowering".to_string(),
                    ));
                }
                other => {
                    return Err(BridgeError::UnsupportedOp(format!(
                        "address-of projection {other:?}"
                    )));
                }
            }
        }

        Ok(ptr)
    }

    fn block_args_for(
        &mut self,
        target: TrustIrBlockId,
        body: &mut Vec<InstrNode>,
    ) -> Result<Vec<ValueId>, BridgeError> {
        if target != self.entry_block {
            return Ok(vec![]);
        }

        (1..=self.arg_count).map(|index| self.read_local(index, body)).collect()
    }

    /// B61 (CallableItem receiver): resolve a `Fn`/`FnMut`/`FnOnce::call*` shim
    /// whose RECEIVER is a `ConstValue::CallableItem` — a function item or a
    /// non-capturing closure whose code identity extraction PRESERVED (schema v5,
    /// `TyKind::FnDef`/`TyKind::Closure` → `CallableItem { def_path, kind, .. }`).
    /// `operand_trust_type` erases the dataless ZST callable to `Ty::Unit`, so the
    /// `Ty::FnDef`/`Ty::Closure` arms in `resolve_call_target` cannot see it; this
    /// recovers the identity from the constant and resolves to the BUNDLED body by
    /// kind, reusing the exact same ABI helpers/lowerings as those arms.
    ///
    /// Returns `None` — the caller then keeps its FAIL-CLOSED path (the untypeable
    /// may-panic UNKNOWN in the dispatch, or the hard resolve error) — when the
    /// receiver is not a `CallableItem`, when its `def_path` is NOT bundled (absent
    /// from `known_function_signatures`, the SAME map the direct arms consult), or
    /// when the bundled body's ABI does not match the call. A mismatch or an
    /// unbundled target is therefore NEVER a fabricated proof.
    ///
    /// SOUNDNESS: resolving to the ACTUAL bundled body is sound because that body's
    /// OWN guarded panic-freedom obligation is verified and propagated — it is NOT a
    /// type-gated total summary, which WOULD be unsound here since a `FnOnce`
    /// receiver can be a panicking closure. Only a `def_path` that resolves to a
    /// bundled body is typed; everything else stays fail-closed.
    fn resolve_callable_item_receiver(
        &self,
        receiver: &Operand,
        args: &[Operand],
    ) -> Option<ResolvedCall> {
        let Operand::Constant(ConstValue::CallableItem { def_path, kind, .. }) = receiver else {
            return None;
        };
        let signature = self.known_function_signatures.get(def_path)?;
        let actual_tys = args
            .iter()
            .map(|arg| operand_trust_type(arg, self).ok())
            .collect::<Option<Vec<_>>>()?;
        match kind {
            // FUNCTION-ITEM receiver: the callee does NOT take the ZST receiver — its
            // params are exactly the rust-call tuple fields — so drop the receiver and
            // flatten the tuple (the `fn_def_call_tuple_field_count` / `FnDefRustCallTuple`
            // pair the `Ty::FnDef` arm uses).
            CallableKind::FnDef => {
                let field_count = fn_def_call_tuple_field_count(&actual_tys, &signature.params)?;
                Some(ResolvedCall {
                    callee: signature.id,
                    args: CallArgLowering::FnDefRustCallTuple { field_count },
                })
            }
            // NON-CAPTURING-CLOSURE receiver: the closure body's params are
            // `[env, input1, …]` and the receiver IS the `env`. `operand_trust_type`
            // erased the ZST env to `Ty::Unit`, so recover its true type from the
            // bundled signature before the rust-call ABI check (which compares the env
            // position). The env lowers to a `Unit` value on both sides (empty-upvar
            // `Ty::Closure` → `TrustIrTy::Unit`; `emit_const(CallableItem)` → Unit
            // `Undef`), so the emitted `FlattenRustCallTuple`/`AsWritten` call ABI matches.
            CallableKind::Closure => {
                let mut actual_tys = actual_tys;
                if let (Some(slot), Some(env_ty)) =
                    (actual_tys.first_mut(), signature.params.first())
                {
                    *slot = env_ty.clone();
                }
                // FAST PATH: exact `trust_types::Ty` equality — either the args are
                // already spread to match the body params, or the rust-call tuple
                // flattens field-for-field with structurally-identical types.
                if actual_tys == signature.params {
                    return Some(ResolvedCall {
                        callee: signature.id,
                        args: CallArgLowering::AsWritten,
                    });
                }
                if let Some(field_count) =
                    rust_call_tuple_field_count(&actual_tys, &signature.params)
                {
                    return Some(ResolvedCall {
                        callee: signature.id,
                        args: CallArgLowering::FlattenRustCallTuple { field_count },
                    });
                }
                // FALLBACK (the arm that previously returned `None`, sending a
                // BUNDLED non-capturing closure to the fail-closed may-panic arm and
                // its `runtime_checked` absent-callee verdict): the `def_path` has
                // ALREADY uniquely identified the bundled body (the
                // `known_function_signatures.get(def_path)?` at the top of this fn),
                // so binding THIS call to it is sound irrespective of the
                // `trust_types::Ty` representation nits that make the STRICT check
                // above reject a bundled body — a slice's ERASED element type (`&[Rat]`
                // param vs the same-shaped arg spelled with a different element `Ty`
                // both lower to the SAME slice fat pointer), a region/lifetime/
                // mutability difference behind a `&` (both lower to `Ptr`), or a
                // generic-`Param`/`Unit` env recovery. Accept by rust-call ARITY,
                // comparing each flattened tuple field against the body param at the
                // LOWERED TrustIr (`map_type`) level. This is strictly WEAKER than the
                // strict path (structural `Ty` equality implies lowered equality) yet
                // still guarantees the emitted `Inst::Call` is WELL-TYPED, so the
                // module validator's `CallArgTypeMismatch` can never fire; a genuine
                // lowered-type or arity mismatch still returns `None` -> fail-closed.
                // Emits the SAME `FlattenRustCallTuple` call as the strict path — a
                // real call to the ACTUAL body whose OWN guarded panic obligations
                // discharge or fail-closed (the B61 discipline), NEVER a total summary.
                let field_count =
                    rust_call_tuple_lowered_field_count(&actual_tys, &signature.params)?;
                Some(ResolvedCall {
                    callee: signature.id,
                    args: CallArgLowering::FlattenRustCallTuple { field_count },
                })
            }
            // `CallableKind` is `#[non_exhaustive]`: any future kind stays
            // FAIL-CLOSED (resolves to nothing → the untypeable may-panic UNKNOWN),
            // never a fabricated proof.
            _ => None,
        }
    }

    fn resolve_call_target(
        &self,
        callee: &str,
        args: &[Operand],
    ) -> Result<ResolvedCall, BridgeError> {
        if let Some(callee_id) = self.known_functions.get(callee).copied() {
            return Ok(ResolvedCall { callee: callee_id, args: CallArgLowering::AsWritten });
        }

        if !is_rust_callable_trait_call(callee) {
            return Err(BridgeError::UnsupportedOp(format!(
                "Call target `{callee}` is not present in the TrustIr module; use lower_to_trust_ir_functions for multi-function lowering"
            )));
        }

        let Some(receiver) = args.first() else {
            return Err(BridgeError::UnsupportedOp(format!(
                "Rust callable trait shim `{callee}` has no closure receiver argument"
            )));
        };
        // B61: a `CallableItem` receiver (fn-item / non-capturing closure whose
        // identity extraction preserved) resolves to its bundled body directly —
        // `operand_trust_type` erases the ZST to `Ty::Unit`, so the `Ty::FnDef`/
        // `Ty::Closure` arms below cannot see it. `None` (unbundled or ABI mismatch)
        // falls through to those arms and the existing fail-closed resolve error.
        if let Some(resolved) = self.resolve_callable_item_receiver(receiver, args) {
            return Ok(resolved);
        }
        let receiver_ty = operand_trust_type(receiver, self)?;
        // FUNCTION-ITEM receiver (`FnOnce::call_once(some_fn, (a, b))` — e.g. a
        // named fn passed as a mapper): the FnDef names the exact callee
        // STATICALLY. Unlike a closure, the callee does NOT take the receiver
        // (a dataless ZST) — its params are exactly the tuple fields — so
        // resolve directly, drop the receiver, and flatten the tuple. An
        // unbundled FnDef target keeps the fail-closed "body not present"
        // error below (never a silent total call).
        if let Some(fn_name) = callable_receiver_fn_def_name(&receiver_ty) {
            let Some(signature) = self.known_function_signatures.get(fn_name) else {
                return Err(BridgeError::UnsupportedOp(format!(
                    "Rust callable trait shim `{callee}` resolved function item `{fn_name}`, but its body is not present in the TrustIr module"
                )));
            };
            let actual_tys = args
                .iter()
                .map(|arg| operand_trust_type(arg, self))
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(field_count) = fn_def_call_tuple_field_count(&actual_tys, &signature.params)
            {
                return Ok(ResolvedCall {
                    callee: signature.id,
                    args: CallArgLowering::FnDefRustCallTuple { field_count },
                });
            }
            return Err(BridgeError::UnsupportedOp(format!(
                "Rust callable trait shim `{callee}` resolved function item `{fn_name}`, but call ABI argument types {actual_tys:?} do not match its params {:?}",
                signature.params
            )));
        }
        let Some(closure_name) = callable_receiver_closure_name(&receiver_ty) else {
            return Err(BridgeError::UnsupportedOp(format!(
                "Rust callable trait shim `{callee}` requires a typed closure receiver, got {receiver_ty:?}"
            )));
        };

        let Some(signature) = self.known_function_signatures.get(closure_name) else {
            return Err(BridgeError::UnsupportedOp(format!(
                "Rust callable trait shim `{callee}` resolved closure environment `{closure_name}`, but the closure body is not present in the TrustIr module"
            )));
        };

        let actual_tys =
            args.iter().map(|arg| operand_trust_type(arg, self)).collect::<Result<Vec<_>, _>>()?;
        if actual_tys == signature.params {
            return Ok(ResolvedCall { callee: signature.id, args: CallArgLowering::AsWritten });
        }

        if let Some(field_count) = rust_call_tuple_field_count(&actual_tys, &signature.params) {
            return Ok(ResolvedCall {
                callee: signature.id,
                args: CallArgLowering::FlattenRustCallTuple { field_count },
            });
        }

        Err(BridgeError::UnsupportedOp(format!(
            "Rust callable trait shim `{callee}` resolved closure `{closure_name}`, but call ABI argument types {actual_tys:?} do not match closure body params {:?}",
            signature.params
        )))
    }

    /// HOF closure-invocation: for a closure-driving call (`map`/`map_err`/`fold`/
    /// `binary_search_by_key`/…) whose closure ARG resolves to a BUNDLED closure body, return
    /// `(closure_arg_index, closure_FuncId, input_param_types)` so the caller can emit a real
    /// `Inst::Call` into the closure body — making the closure's panic propagate to THIS
    /// function's per-function verdict (a panicking closure REFUTES, a total one VERIFIES — the
    /// asymmetry the conservative may-panic arm cannot give). Returns `None` (→ fall through to
    /// that conservative arm) when no closure arg's body is bundled — e.g. a NON-capturing closure
    /// whose name was erased to `Unit` at extraction, or a fn-pointer / `dyn FnMut`. SOUND: this is
    /// NEVER a total/no-obligation summary, and it fails closed (`None` → conservative) rather than
    /// ever assuming the closure total.
    fn try_resolve_hof_closure(
        &self,
        callee: &str,
        args: &[Operand],
    ) -> Result<Option<(usize, FuncId, Vec<Ty>)>, BridgeError> {
        if !closure_driving_consumer_call(callee) {
            return Ok(None);
        }
        for (i, arg) in args.iter().enumerate() {
            let ty = operand_trust_type(arg, self)?;
            let Some(name) = callable_receiver_closure_name(&ty) else {
                continue;
            };
            let Some(sig) = self.known_function_signatures.get(name) else {
                continue;
            };
            // Closure body params are `[env, input1, …]`: the env is the closure arg itself; the
            // inputs are driven by the HOF internally, so they are modeled as havoc.
            let inputs = sig.params.get(1..).map(<[Ty]>::to_vec).unwrap_or_default();
            return Ok(Some((i, sig.id, inputs)));
        }
        Ok(None)
    }

    // Removed (soundness): the former `external_call_is_pure_uninterpretable`
    // "Lever #1" modeled an external call lacking `&mut`/raw-ptr arguments as a
    // clean total `Undef` with NO proof obligation. That is UNSOUND: an
    // unresolved external callee (not in the module, so never separately
    // verified) — or an eagerly-driven closure/`Pattern` method like
    // `str::find(closure)` — can PANIC, yet the no-obligation total summary
    // PROVES the caller panic-free (a false PROVE). The sound behavior is to
    // fall through to `resolve_call_target` and fail closed (the caller's
    // panic-freedom stays UNKNOWN), matching the `is_panic_call` /
    // `closure_driving_consumer_call` precedents which always either emit a
    // `PanicFreedom` obligation or decline. See
    // `test_lower_unresolved_call_fails_closed` and
    // `str_pattern_method_with_panicking_closure_is_not_summarized_total`.

    /// Map a trust-types Ty in context (can register structs/types in module).
    fn map_type_ctx(&mut self, ty: &Ty) -> Result<TrustIrTy, BridgeError> {
        if let Some(mapped) = self.type_cache.get(ty) {
            return Ok(mapped.clone());
        }

        match ty {
            Ty::Array { elem, len } => {
                let elem_trust_ir = self.map_type_ctx(elem)?;
                let ty_id = self.module.add_type(elem_trust_ir);
                let mapped = TrustIrTy::Array(ty_id, *len);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            Ty::Tuple(elems) if elems.is_empty() => Ok(TrustIrTy::Unit),
            Ty::Tuple(elems) => {
                let fields = elems
                    .iter()
                    .map(|elem| self.map_type_ctx(elem))
                    .collect::<Result<Vec<_>, _>>()?;
                let mapped = TrustIrTy::Tuple(fields);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // Trust (B3-1, RFC TRUST_IR_V2): a FAITHFUL-lane first-class enum — the
            // extractor set the marker ONLY under the FaithfulScalarsGuard and only
            // for register_enum-eligible defs, so this arm is unreachable from every
            // verifier lane (their stream never carries the marker; trust-vcgen's
            // name-keyed `__tag` proof complex and trust-mc's CHC per-field
            // precision see the flat Struct spelling below, byte-identical).
            // Build the trust-ir `EnumDef` STRUCTURALLY EQUAL to the producer's:
            // per-variant field lists (mapped), the EFFECTIVE discriminant values
            // (never variant indexes — the index-vs-discriminant seam), and the
            // carried `#[repr]` hint (its absence would change canonical_tag_repr).
            // `add_enum_def` dedups structurally; a def with no canonical tag
            // fails closed here exactly like the producer's registration gate.
            Ty::Adt { name, variants, faithful_enum_repr: Some(repr_hint), enum_layout, .. }
                if !variants.is_empty() =>
            {
                // The extractor's `VariantDef.discriminant` is the rustc `Discr.val`
                // BIT PATTERN (`val as i128` — `-5` in `repr(i16)` arrives as 65531;
                // the flat lane's SwitchInt matching depends on that convention and
                // must not change). The producer's EnumDef carries REAL sign-extended
                // values (`enum_discriminants` → `sign_extend(val, signed, bits)` over
                // the discriminant's own type), so reinterpret here under the SAME
                // width/signedness: the carried repr hint when pinned, else Rust's
                // default discriminant type `isize` (64-bit signed — exactly the
                // producer's `bit_width().unwrap_or(64)` collapse).
                let (disc_bits, disc_signed): (u32, bool) = match repr_hint {
                    None => (64, true),
                    Some(h) => match h {
                        trust_types::EnumReprHint::U8 => (8, false),
                        trust_types::EnumReprHint::U16 => (16, false),
                        trust_types::EnumReprHint::U32 => (32, false),
                        trust_types::EnumReprHint::U64 => (64, false),
                        trust_types::EnumReprHint::I8 => (8, true),
                        trust_types::EnumReprHint::I16 => (16, true),
                        trust_types::EnumReprHint::I32 => (32, true),
                        trust_types::EnumReprHint::I64 => (64, true),
                    },
                };
                let sign_extend = |pattern: i128| -> i128 {
                    let raw = (pattern as u128) & (u128::MAX >> (128 - disc_bits));
                    if disc_signed && disc_bits < 128 && (raw >> (disc_bits - 1)) & 1 == 1 {
                        (raw | (u128::MAX << disc_bits)) as i128
                    } else {
                        raw as i128
                    }
                };
                let mut ir_variants = Vec::with_capacity(variants.len());
                let mut discs = Vec::with_capacity(variants.len());
                for v in variants {
                    let mut vfields = Vec::with_capacity(v.fields.len());
                    let mut vfield_names = Vec::with_capacity(v.fields.len());
                    for (fname, fty) in &v.fields {
                        vfields.push(self.map_type_ctx(fty)?);
                        vfield_names.push(fname.clone());
                    }
                    ir_variants.push(trust_ir::EnumVariant {
                        name: v.name.clone(),
                        fields: vfields,
                        field_names: vfield_names,
                    });
                    discs.push(Some(sign_extend(v.discriminant)));
                }
                // Id AFTER field mapping (the #46 nested-collision discipline) —
                // though enum variant fields are scalars by eligibility, keep the
                // pattern so a future widening cannot reintroduce the collision.
                let mut def = trust_ir::EnumDef::new(
                    trust_ir::value::EnumId::new(self.module.enums.len() as u32),
                    name.clone(),
                    ir_variants,
                )
                .with_discriminants(discs);
                if let Some(hint) = repr_hint {
                    def = def.with_repr(match hint {
                        trust_types::EnumReprHint::U8 => trust_ir::EnumTagRepr::U8,
                        trust_types::EnumReprHint::U16 => trust_ir::EnumTagRepr::U16,
                        trust_types::EnumReprHint::U32 => trust_ir::EnumTagRepr::U32,
                        trust_types::EnumReprHint::U64 => trust_ir::EnumTagRepr::U64,
                        trust_types::EnumReprHint::I8 => trust_ir::EnumTagRepr::I8,
                        trust_types::EnumReprHint::I16 => trust_ir::EnumTagRepr::I16,
                        trust_types::EnumReprHint::I32 => trust_ir::EnumTagRepr::I32,
                        trust_types::EnumReprHint::I64 => trust_ir::EnumTagRepr::I64,
                    });
                }
                // The producer's registration gate, mirrored: a def the layout
                // machinery cannot size must never be minted (it would trap at
                // first construction; the validator also rejects it module-wide).
                if def.canonical_tag_repr().is_none() {
                    return Err(BridgeError::UnsupportedType(format!(
                        "enum {name} has no canonical tag repr (faithful-lane decline)"
                    )));
                }
                // Trust (B3-3): copy the extractor's concrete layout twin
                // through verbatim (the T3 struct copy-through discipline).
                // The descriptor is NORMATIVE on the trust-ir side, so two
                // extra declines guard the copy: (a) a Direct lane whose rustc
                // tag scalar disagrees with the CANONICAL tag repr this def
                // resolves to — the interpreter/validator size the Direct tag
                // lane at canonical width, and a rustc-widened tag would mint
                // a descriptor whose normative claim is wrong; (b) an
                // unmappable niche lane (unreachable today: eligibility is
                // Direct-only, but the mapping must not rot). A decline keeps
                // layout=None — the documented fail-safe; a producer-side fill
                // asymmetry then surfaces as a coverage-only Err in tys_agree.
                if let Some(el) = enum_layout {
                    let map_hint = |h: &trust_types::EnumReprHint| match h {
                        trust_types::EnumReprHint::U8 => trust_ir::EnumTagRepr::U8,
                        trust_types::EnumReprHint::U16 => trust_ir::EnumTagRepr::U16,
                        trust_types::EnumReprHint::U32 => trust_ir::EnumTagRepr::U32,
                        trust_types::EnumReprHint::U64 => trust_ir::EnumTagRepr::U64,
                        trust_types::EnumReprHint::I8 => trust_ir::EnumTagRepr::I8,
                        trust_types::EnumReprHint::I16 => trust_ir::EnumTagRepr::I16,
                        trust_types::EnumReprHint::I32 => trust_ir::EnumTagRepr::I32,
                        trust_types::EnumReprHint::I64 => trust_ir::EnumTagRepr::I64,
                    };
                    let encoding = match &el.encoding {
                        trust_types::EnumTagEncodingInfo::Direct { tag_offset, tag_ty } => {
                            (def.canonical_tag_repr() == Some(map_hint(tag_ty)))
                                .then_some(trust_ir::EnumTagEncoding::Direct {
                                    tag_offset: *tag_offset,
                                })
                        }
                        trust_types::EnumTagEncodingInfo::Niche {
                            untagged_variant,
                            niche_variants_start,
                            niche_variants_end,
                            niche_start,
                            niche_offset,
                            niche_ty,
                        } => Some(trust_ir::EnumTagEncoding::Niche {
                            untagged_variant: *untagged_variant,
                            niche_variants_start: *niche_variants_start,
                            niche_variants_end: *niche_variants_end,
                            niche_start: *niche_start,
                            niche_offset: *niche_offset,
                            niche_ty: map_hint(niche_ty),
                        }),
                    };
                    if let Some(encoding) = encoding {
                        def.layout = Some(trust_ir::EnumLayoutDescriptor {
                            encoding,
                            size: el.size,
                            align: el.align,
                            variant_field_offsets: el.variant_field_offsets.clone(),
                        });
                    }
                }
                let enum_id = self.module.add_enum_def(def);
                let mapped = TrustIrTy::Enum(enum_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            Ty::Adt { name, fields, layout, .. } => {
                // Trust (B3-4 T3): the extractor's faithful-lane layout carries
                // through verbatim — per-field offsets (source-declaration order,
                // parallel to `fields`), size/align, and the one-hint repr — so
                // the oracle's StructDef matches the THIR producer's T2 fill.
                // Absent layout (verifier lanes, generic/opaque types) keeps
                // every field None: byte-identical pre-T3 behavior.
                let mut trust_ir_fields = Vec::with_capacity(fields.len());
                for (i, (field_name, field_ty)) in fields.iter().enumerate() {
                    trust_ir_fields.push(FieldDef {
                        name: field_name.clone(),
                        ty: self.map_type_ctx(field_ty)?,
                        offset: layout
                            .as_ref()
                            .and_then(|l| l.field_offsets.get(i).copied()),
                    });
                }
                // Trust (#46): compute the struct id AFTER mapping the fields. A
                // NESTED struct field (e.g. `Wrap` inside `Option<Wrap>`) registers
                // its own struct during the loop above, bumping `structs.len()`; an
                // id taken before the loop would COLLIDE with that nested struct's id
                // (both at `len==0`), and since `add_struct` pushes by `sd.id` while
                // `structs.get(id)` indexes by id, the outer struct would then resolve
                // to the nested one — breaking the CHC model (a counterexample for a
                // safe `match Some(Wrap(_))`). Computing the id here makes it the
                // correct next index.
                let struct_id = StructId::new(self.module.structs.len() as u32);
                let repr = match layout.as_ref().map(|l| l.repr.as_str()) {
                    Some("transparent") => StructRepr::Transparent,
                    Some("c") => StructRepr::C,
                    Some(p) if p.starts_with("packed:") => p["packed:".len()..]
                        .parse::<u32>()
                        .map(StructRepr::Packed)
                        .unwrap_or(StructRepr::Rust),
                    // No layout carried (verifier lanes / non-concrete): the
                    // pre-T3 layout-default.
                    _ => StructRepr::Rust,
                };
                self.module.add_struct(StructDef {
                    id: struct_id,
                    name: name.clone(),
                    fields: trust_ir_fields,
                    size: layout.as_ref().map(|l| l.size),
                    align: layout.as_ref().map(|l| l.align),
                    repr,
                });
                let mapped = TrustIrTy::Struct(struct_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            Ty::Closure { upvars, .. } if upvars.is_empty() => {
                let mapped = TrustIrTy::Unit;
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // Trust (B6, RFC TRUST_IR_V2 — v25 Fn/ByValue slice): a by-value FnOnce
            // CAPTURING env respells to the FORMAT's first-class `Ty::Closure`,
            // STRUCTURALLY EQUAL to the producer's spelling: `ClosureTy { func: the
            // closure's call signature (untupled params; unit return = empty returns —
            // the recorded `ClosureCallSig` convention matches the producer's), captures }`.
            // The func-ty id takes the FnPtr arm's discipline (structural dedup from
            // `func_ty_base`); the ClosureTy interns structurally (its identity IS
            // (func, captures) — ty#4145). Fn/FnMut (by-REF env) and a `call: None`
            // (bridge-side refinement, unresolved kind) keep the `closure_env::` struct
            // spelling below — fail-closed, the mode distinction is unrepresentable
            // until the v26 ClosureTy fields.
            Ty::Closure { upvars, call: Some(sig), .. }
                if sig.kind == trust_types::ClosureCallKind::FnOnce =>
            {
                let mut params = Vec::with_capacity(sig.params.len());
                for pty in &sig.params {
                    params.push(self.map_type_ctx(pty)?);
                }
                let returns = match &sig.ret {
                    Some(r) => vec![self.map_type_ctx(r)?],
                    None => Vec::new(),
                };
                let mut captures = Vec::with_capacity(upvars.len());
                for u in upvars {
                    captures.push(self.map_type_ctx(u)?);
                }
                let ft = FuncTy { params, returns, is_vararg: false };
                let existing = self.module.func_types[self.func_ty_base..]
                    .iter()
                    .position(|e| !e.is_vararg && *e == ft);
                let func = match existing {
                    Some(off) => trust_ir::value::FuncTyId::new(
                        u32::try_from(self.func_ty_base + off)
                            .expect("func-type table exceeds u32 id space"),
                    ),
                    None => self.module.add_func_type(ft),
                };
                let ct = trust_ir::ClosureTy { func, captures };
                let cid = match self.module.closure_types.iter().position(|e| *e == ct) {
                    Some(i) => trust_ir::value::ClosureTyId::new(i as u32),
                    None => self.module.add_closure_type(ct),
                };
                let mapped = TrustIrTy::Closure(cid);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            Ty::Closure { name, upvars, .. } => {
                let mut trust_ir_fields = Vec::with_capacity(upvars.len());
                for (index, upvar_ty) in upvars.iter().enumerate() {
                    trust_ir_fields.push(FieldDef {
                        name: format!("__capture{index}"),
                        ty: self.map_type_ctx(upvar_ty)?,
                        offset: None,
                    });
                }
                // Trust (#46): compute the id AFTER mapping captures — a nested-struct
                // capture registers during the loop, so an id taken before would
                // collide (see the Adt case above).
                let struct_id = StructId::new(self.module.structs.len() as u32);
                self.module.add_struct(StructDef {
                    id: struct_id,
                    name: format!("closure_env::{name}"),
                    fields: trust_ir_fields,
                    size: None,
                    align: None,
                    // Trust: compiler-generated closure environments are always
                    // the default Rust layout.
                    repr: StructRepr::Rust,
                });
                let mapped = TrustIrTy::Struct(struct_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // Trust: fn-ptr Func-vs-Ptr model split (wave-3). The PRODUCER maps
            // `fn(..) -> ..` to `Ty::Func(sig)` over a per-body signature table
            // (thir-lower `map_fn_ptr_ty` + `pend_func_ty`); this oracle mapped it to
            // opaque `Ptr`, so every fn-ptr-typed SIGNATURE position diverged
            // (`signature divergence: THIR []->[Func(FuncTyId(1))] vs MIR []->[Ptr]`,
            // 20 ui bodies in the postbuild-wave2 scorecard). Mirror the producer's
            // admitted fragment where the sig is REPRESENTABLE — every param/return
            // maps in the STATELESS fragment (deciding representability is
            // side-effect-free: no struct/functy registration happens unless the whole
            // sig is admitted), no higher-order signatures (a component that is itself
            // function-typed refuses, like the producer's `ty_contains_func` wall),
            // producer unit-return convention (`returns: []`) — and register the
            // `FuncTy` with the producer's id discipline: the function's OWN sig holds
            // the slot `lower_function_into` reserved; fn-ptr sigs take the next ids in
            // first-encounter order with per-ctx structural dedup (`func_ty_base`).
            // NOT representable => opaque `Ptr`, exactly the previous spelling — the
            // divergence stays fail-VISIBLE, never a false agreement.
            Ty::FnPtr { sig } => match fn_ptr_func_ty(sig) {
                Some(ft) => {
                    let existing = self.module.func_types[self.func_ty_base..]
                        .iter()
                        .position(|e| !e.is_vararg && *e == ft);
                    let id = match existing {
                        Some(off) => trust_ir::value::FuncTyId::new(
                            u32::try_from(self.func_ty_base + off)
                                .expect("func-type table exceeds u32 id space"),
                        ),
                        None => self.module.add_func_type(ft),
                    };
                    // Deliberately NOT `type_cache`d: the id is minted under THIS
                    // ctx's dedup scope; a cache hit in a later function of the same
                    // module would alias across scopes.
                    Ok(TrustIrTy::Func(id))
                }
                None => Ok(TrustIrTy::Ptr),
            },
            // Lever A (native lane): `Ty::Datatype` — either a BY-NAME back-reference /
            // compacted-field marker (empty `variants`) or a defining occurrence of a
            // recursive ADT (non-empty) — lowers to a registered OPAQUE zero-field
            // struct. SOUNDNESS: the value becomes a pure havoc slot downstream —
            // trust-mc models a zero-field struct as an opaque per-binding symbol with
            // zero relation leaves (no canonical value, no interpreted equality), so it
            // can never prove a runtime-false fact. STRUCTURAL uses stay fact-free off
            // the KEPT trust_types::Ty (mirroring the `Param`->`Unit` argument, but
            // stronger — no single-valued carrier): a Field READ out of the opaque
            // value fail-softs to a consumer-typed fresh havoc when the consuming
            // context's declared type is known (`resolve_place_expecting` — an
            // unconstrained `Undef`, never a fact) and otherwise still `Err`s in
            // `field_type`'s non-aggregate arm; Discriminant/SetDiscriminant
            // (`explicit_discriminant_field` requires `Ty::Adt`), enum Aggregate
            // construction (requires `Ty::Adt`), projected STOREs into the opaque
            // value, and Drop (`is_trivially_no_drop_ty` / `is_panic_free_drop_ext`
            // both decline a `Datatype`) all `Err`, keeping those functions Unknown
            // rather than falsely proved. Whole-value move/copy/store/call-arg flow
            // succeeds — which is exactly what a sort marker must support.
            // Datatype-PRECISE modeling (constructors/selectors) exists only in the
            // vcgen/SMT lane; this arm is deliberately opaque.
            Ty::Datatype { name, .. } => {
                // Follow the Adt arm: compute the id at registration time (no nested
                // registration can occur for a zero-field struct, but stay uniform).
                let struct_id = StructId::new(self.module.structs.len() as u32);
                self.module.add_struct(StructDef {
                    id: struct_id,
                    name: format!("datatype::{name}"),
                    fields: Vec::new(),
                    size: None,
                    align: None,
                    repr: StructRepr::Rust,
                });
                let mapped = TrustIrTy::Struct(struct_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // Trust: piece #13 step-2 (safe-async native lowering) — a COROUTINE
            // frame (`Ty::Coroutine`, step-1 models it with NO upvars/fields) lowers
            // to a registered OPAQUE zero-field struct, exactly like `Ty::Datatype`.
            // SOUNDNESS (mirrors the Datatype rationale + the vcgen/default lane):
            // the frame becomes a pure havoc slot — trust-mc models a zero-field
            // struct as an opaque per-binding symbol with no interpreted equality, so
            // a value read out of the frame (a former across-await local, the resume
            // STATE discriminant) is unconstrained and can never discharge an
            // overflow/index bound. Every STRUCTURAL use is handled explicitly and
            // obligation-free: the frame Aggregate build (opaque `Undef`),
            // SetDiscriminant on the frame (state-selector WRITE, no-op), and
            // Discriminant read of the frame (state-selector READ → havoc'd dest).
            // A directly-read param of the async fn is itself an unconstrained value
            // of its own type, so a zero-await body's param arithmetic (`x + 1`)
            // still proves-or-refutes exactly.
            Ty::Coroutine { name, .. } => {
                let struct_id = StructId::new(self.module.structs.len() as u32);
                self.module.add_struct(StructDef {
                    id: struct_id,
                    name: format!("coroutine::{name}"),
                    fields: Vec::new(),
                    size: None,
                    align: None,
                    repr: StructRepr::Rust,
                });
                let mapped = TrustIrTy::Struct(struct_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // A FUNCTION ITEM (`FnDef`) is a dataless ZST: the VALUE carries no
            // runtime content — lower it to `Unit` (the `Param`->`Unit`
            // precedent; the KEPT trust_types::Ty still names the function).
            // Every panic-relevant USE resolves off the kept Ty elsewhere: a
            // callable-shim call with an FnDef receiver resolves DIRECTLY to
            // the named function (`callable_receiver_fn_def_name`) or fails
            // closed if its body is absent — never a silent total call.
            Ty::FnDef { .. } => {
                let mapped = TrustIrTy::Unit;
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            // Bare generic `Ty::Param` -> opaque `Unit` slot (soundness + FRAGILITY note at
            // the `map_type` site).
            Ty::Unsupported { kind, .. } if kind == "TyKind::Param" => Ok(TrustIrTy::Unit),
            // Trust (R3, generics): a PARAM-BEARING projection alias (`<S as
            // Serializer>::Ok`, `<B as Flags>::Bits` — the shared
            // `trust_types::PRE_MONO_ALIAS_{KIND,DETAIL}` marker) lowers to a
            // registered opaque ZERO-FIELD STRUCT — the `Ty::Datatype` /
            // `Ty::Coroutine` precedent above, deliberately NOT the
            // `Param`->`Unit` spelling: `Unit` is a single-valued carrier
            // trust-mc concretizes to 0, while a zero-field struct is a
            // per-binding opaque symbol with no interpreted equality and no
            // arithmetic sort, so a value of this type can never discharge (or
            // falsely satisfy) an arith/bounds/switch VC — if a primitive op
            // ever ranged over it, TrustIr type-checking rejects the module
            // (fail-closed), never a silent 0. The marker is ONE `Ty` value
            // (identity-erased by extraction), so `<S as Serializer>::Ok` and
            // `::Error` share the cached struct — sound exactly because the
            // sort is fact-free. Calls on such values hit the absent-callee arm
            // and drops hit the drop-glue arm (`is_trivially_no_drop_ty`
            // declines the marker), both of which force the COUNTED
            // whole-function panic-freedom carrier — never a silent pass.
            // Deliberately NOT added to the stateless `map_type`: its callers
            // (fn-ptr signature probing, shim checks) rely on the `Err`
            // fallback as their fail-closed/decline mechanism.
            Ty::Unsupported { .. } if ty.is_pre_mono_alias_marker() => {
                let struct_id = StructId::new(self.module.structs.len() as u32);
                self.module.add_struct(StructDef {
                    id: struct_id,
                    name: "opaque_alias::pre_monomorphization".to_string(),
                    fields: Vec::new(),
                    size: None,
                    align: None,
                    repr: StructRepr::Rust,
                });
                let mapped = TrustIrTy::Struct(struct_id);
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            Ty::Unsupported { kind, detail } if is_unsupported_rustc_closure_kind(kind) => {
                Err(unsupported_rustc_closure_type(kind, detail))
            }
            // Trust (B2-1b, RFC TRUST_IR_V2): slice fat pointers ([T], &[T], *const [T],
            // sym-arrays) get the FORMAT's first-class spelling —
            // `TrustIrTy::FatPtr(FatPtrKind::Slice(elem TyId))`, the element interned
            // into the module `types` table (position-scan dedup; `add_type` never
            // dedups) so it is STRUCTURALLY EQUAL to the producer's spelling
            // (`tys_agree` resolves both element ids). Handled HERE and not in the
            // stateless mapper, which has no module to intern into (the Closure
            // precedent); the legacy anonymous `Tuple([Ptr, I64])` spelling is retired.
            _ if slice_element_type(ty).is_some() => {
                let elem = slice_element_type(ty).expect("guard checked is_some");
                let elem_mapped = self.map_type_ctx(&elem)?;
                let tid = match self.module.types.iter().position(|e| *e == elem_mapped) {
                    Some(i) => trust_ir::value::TyId::new(i as u32),
                    None => self.module.add_type(elem_mapped),
                };
                let mapped = TrustIrTy::FatPtr(trust_ir::FatPtrKind::Slice(tid));
                self.type_cache.insert(ty.clone(), mapped.clone());
                Ok(mapped)
            }
            _ => map_type(ty),
        }
    }

    /// Resolve an Operand to a TrustIr ValueId, emitting Const instructions as needed.
    fn resolve_operand(
        &mut self,
        op: &Operand,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        match op {
            Operand::Copy(place) | Operand::Move(place) => self.resolve_place(place, body),
            Operand::Constant(cv) => self.emit_const(cv, body),
            Operand::Symbolic(formula) => {
                let ty = contextless_symbolic_trust_ir_type(formula)?;
                self.emit_symbolic_formula(formula, ty, body)
            }
            Operand::Unsupported { kind, detail } => {
                Err(BridgeError::UnsupportedOp(format!("unsupported operand {kind}: {detail}")))
            }
            _ => Err(BridgeError::UnsupportedOp(
                "unsupported non-exhaustive operand variant".to_string(),
            )),
        }
    }

    fn resolve_operand_as_trust_type(
        &mut self,
        op: &Operand,
        expected_ty: &Ty,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        match op {
            Operand::Symbolic(formula) => {
                ensure_symbolic_formula_matches_type(formula, expected_ty)?;
                let ty = self.map_type_ctx(expected_ty)?;
                self.emit_symbolic_formula(formula, ty, body)
            }
            // Emit an integer literal at the expected integer width when the
            // value exactly fits it (same width-typed `Inst::Const` shape
            // `emit_const` already uses for `ConstValue::Uint`). Non-fitting
            // constants fall through to the contextless emission; the caller's
            // type check rejects them before this point. Pairs with
            // operand_trust_type_with_context.
            Operand::Constant(ConstValue::Int(value))
                if int_constant_fits_trust_type(*value, expected_ty) =>
            {
                let ty = self.map_type_ctx(expected_ty)?;
                let result = self.fresh_value();
                body.push(
                    InstrNode::new(Inst::Const { ty, value: TrustIrConstant::Int(*value) })
                        .with_result(result),
                );
                Ok(result)
            }
            Operand::Constant(ConstValue::Uint(v, _))
                if uint_constant_fits_trust_type(*v, expected_ty) =>
            {
                let ty = self.map_type_ctx(expected_ty)?;
                let result = self.fresh_value();
                body.push(
                    InstrNode::new(Inst::Const { ty, value: TrustIrConstant::u128(*v) })
                        .with_result(result),
                );
                Ok(result)
            }
            // A place read resolves normally; the expected type is consulted
            // ONLY for the fail-soft opaque-datatype field-read havoc (see
            // `resolve_place_expecting` — behavior is otherwise identical to
            // `resolve_operand`).
            Operand::Copy(place) | Operand::Move(place) => {
                self.resolve_place_expecting(place, Some(expected_ty), body)
            }
            _ => self.resolve_operand(op, body),
        }
    }

    /// [`Self::resolve_operand`], threading the consumer's expected operand
    /// type into place resolution when one is known. Unlike
    /// [`Self::resolve_operand_as_trust_type`] this NEVER re-types constants or
    /// symbolic formulas — the expectation is consulted only for the fail-soft
    /// opaque-datatype field-read havoc (see `resolve_place_expecting`).
    fn resolve_operand_expecting(
        &mut self,
        op: &Operand,
        expected_ty: Option<&Ty>,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        match (op, expected_ty) {
            (Operand::Copy(place) | Operand::Move(place), Some(expected)) => {
                self.resolve_place_expecting(place, Some(expected), body)
            }
            _ => self.resolve_operand(op, body),
        }
    }

    fn emit_symbolic_formula(
        &mut self,
        formula: &Formula,
        ty: TrustIrTy,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let sort = infer_sort(formula);
        let formula_json = serde_json::to_string(formula).map_err(|err| {
            BridgeError::UnsupportedOp(format!(
                "failed to serialize symbolic formula for TrustIr dialect op: {err}"
            ))
        })?;
        let result = self.fresh_value();
        let op = DialectInst::new(SYMBOLIC_FORMULA_DIALECT, SYMBOLIC_FORMULA_OP)
            .with_result_ty(ty)
            .with_attr(
                SYMBOLIC_FORMULA_ATTR_SCHEMA,
                AttrValue::Str("trust-types.Formula@1".to_string()),
            )
            .with_attr(SYMBOLIC_FORMULA_ATTR_JSON, AttrValue::Str(formula_json))
            .with_attr(SYMBOLIC_FORMULA_ATTR_SMTLIB, AttrValue::Str(formula.to_smtlib()))
            .with_attr(SYMBOLIC_FORMULA_ATTR_SORT, AttrValue::Str(sort.to_smtlib()))
            .with_attr(SYMBOLIC_FORMULA_ATTR_DEBUG, AttrValue::Str(format!("{formula:?}")));
        body.push(InstrNode::new(Inst::DialectOp(Box::new(op))).with_result(result));
        self.mark_value_symbolic(result);
        Ok(result)
    }

    fn emit_symbolic_memory_state_formula(
        &mut self,
        formula: &Formula,
        body: &mut Vec<InstrNode>,
    ) -> Result<(), BridgeError> {
        let sort = infer_sort(formula);
        let formula_json = serde_json::to_string(formula).map_err(|err| {
            BridgeError::UnsupportedOp(format!(
                "failed to serialize symbolic memory formula for TrustIr dialect op: {err}"
            ))
        })?;
        let op = DialectInst::new(SYMBOLIC_FORMULA_DIALECT, SYMBOLIC_MEMORY_STATE_OP)
            .with_attr(
                SYMBOLIC_FORMULA_ATTR_SCHEMA,
                AttrValue::Str("trust-types.Formula@1".to_string()),
            )
            .with_attr(SYMBOLIC_FORMULA_ATTR_CONTEXT, AttrValue::Str("lifted-memory-state".into()))
            .with_attr(SYMBOLIC_FORMULA_ATTR_JSON, AttrValue::Str(formula_json))
            .with_attr(SYMBOLIC_FORMULA_ATTR_SMTLIB, AttrValue::Str(formula.to_smtlib()))
            .with_attr(SYMBOLIC_FORMULA_ATTR_SORT, AttrValue::Str(sort.to_smtlib()))
            .with_attr(SYMBOLIC_FORMULA_ATTR_DEBUG, AttrValue::Str(format!("{formula:?}")));
        body.push(InstrNode::new(Inst::DialectOp(Box::new(op))));
        Ok(())
    }

    fn emit_symbolic_aggregate(
        &mut self,
        kind: &str,
        ty: TrustIrTy,
        fields: &[ValueId],
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let result = self.fresh_value();
        let op = DialectInst::new(SYMBOLIC_FORMULA_DIALECT, SYMBOLIC_AGGREGATE_OP)
            .with_operands(fields.iter().copied())
            .with_result_ty(ty)
            .with_attr(
                SYMBOLIC_FORMULA_ATTR_SCHEMA,
                AttrValue::Str("trust-symbolic.Aggregate@1".to_string()),
            )
            .with_attr(SYMBOLIC_AGGREGATE_ATTR_KIND, AttrValue::Str(kind.to_string()))
            .with_attr(SYMBOLIC_AGGREGATE_ATTR_FIELD_COUNT, AttrValue::U64(fields.len() as u64));
        body.push(InstrNode::new(Inst::DialectOp(Box::new(op))).with_result(result));
        self.mark_result_symbolic_from(result, fields);
        Ok(result)
    }

    /// Resolve a Place to a TrustIr ValueId, emitting projection instructions.
    fn resolve_place(
        &mut self,
        place: &Place,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        self.resolve_place_expecting(place, None, body)
    }

    /// [`Self::resolve_place`] with the place's EXPECTED final type from the
    /// consuming context (the Assign destination's declared type, an aggregate
    /// field's declared type, a known callee's declared param type). MIR is
    /// type-correct, so the expected type IS the place's type; it is consulted
    /// ONLY to type the fail-soft havoc below — every precise projection still
    /// derives its type from the place walk itself.
    ///
    /// Lever A fail-soft (native lane): a `Field` read OUT OF an opaque
    /// `Ty::Datatype` value — the extractor's compacted-field marker
    /// (`__trust_compacted_aggregate`) or a by-name recursive-ADT reference —
    /// cannot be resolved structurally: the datatype's contents are not carried
    /// (see `compact_oversized_field` in trust-mir-extract) and `map_type_ctx`
    /// models the VALUE as an opaque zero-field struct. Previously this hard-
    /// failed in `field_type` ("Field projection .N on non-aggregate type
    /// Datatype{..}"), dropping the WHOLE function from the native lane — the
    /// single largest unsupported source on real workloads (348 notes in
    /// ny-cert, e.g. `certz::qpair_json`). Instead, when the consumer's
    /// expected type is known and every remaining projection is a pure,
    /// non-panicking value read (`Field`/`Downcast` — never `Index`/
    /// `ConstantIndex`, whose bounds panic must stay modeled, and never
    /// `Deref`, whose load must stay modeled), model the WHOLE remaining read
    /// as ONE fresh `Inst::Undef` of the expected type.
    ///
    /// SOUNDNESS: the projected value becomes an UNCONSTRAINED fresh symbol
    /// (trust-mc's `Inst::Undef` semantics is `fresh_symbolic`) — a strict
    /// over-approximation of whatever the compacted field held. NO fact is
    /// emitted about it (no `Assume`, no constant, no equality), so every
    /// obligation that depends on the value stays UNPROVABLE (never a false
    /// PROVE), while the function's OTHER obligations keep native verdicts.
    /// Typing the havoc from the consumer's declared type keeps def-use typing
    /// exact (the validator's `check_operand_matches_declared` on `Copy`/
    /// `InsertField`/call args), because MIR guarantees the place's type
    /// equals the consumer's declared type. If the expected type is itself
    /// unmappable, or no expectation is available, the original hard fail is
    /// preserved (fail-closed).
    fn resolve_place_expecting(
        &mut self,
        place: &Place,
        expected_ty: Option<&Ty>,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let mut current = self.read_local(place.local, body)?;
        let mut current_ty = self.local_ty(place.local)?.clone();
        let mut active_variant = None;

        for (proj_index, proj) in place.projections.iter().enumerate() {
            // Fail-soft opaque-datatype field read (soundness argument on the
            // doc comment above). Trigger BEFORE the projection match so both
            // the plain and the Downcast/variant field paths are covered; the
            // instructions already emitted for the projections BEFORE this
            // point (loads through refs, index bounds) stay in the body, so
            // their obligations are preserved.
            if matches!(current_ty, Ty::Datatype { .. })
                && let Some(expected) = expected_ty
                && place.projections[proj_index..]
                    .iter()
                    .all(|p| matches!(p, Projection::Field(_) | Projection::Downcast(_)))
                && place.projections[proj_index..]
                    .iter()
                    .any(|p| matches!(p, Projection::Field(_)))
                // An unmappable expected type (e.g. `Ty::Unsupported`) keeps
                // the hard fail below — we never fabricate an untyped value.
                && let Ok(trust_ir_ty) = self.map_type_ctx(expected)
            {
                let result = self.fresh_value();
                body.push(InstrNode::new(Inst::Undef { ty: trust_ir_ty }).with_result(result));
                return Ok(result);
            }
            match proj {
                Projection::Field(idx) => {
                    // Trust (B3-1b E3/G2): a FAITHFUL first-class enum base takes the
                    // format's lane model — [tag, active-variant fields...] — so the
                    // payload lane is `1 + within-variant-index` typed at the variant's
                    // OWN field type (the dual of the producer's payload read). The
                    // flat `__v{v}_`-prefix PHYSICAL index below is WRONG here: it
                    // coincides with the lane only when all prior variants are
                    // fieldless (Option/Result masked it); on `enum{A(i64),B(i64,i64)}`
                    // reading `B.0` it silently returns lane 2's value with a
                    // COINCIDING type — a wrong-value class, not an error. A PLAIN
                    // Field (no Downcast) on an enum base has no MIR meaning — the
                    // internal flat `__tag` synthesis is bypassed by the dedicated
                    // Discriminant/SetDiscriminant arms — so it fails closed.
                    let is_faithful_enum = matches!(
                        &current_ty,
                        Ty::Adt { faithful_enum_repr: Some(_), variants, .. }
                            if !variants.is_empty()
                    );
                    let (mapped_field, result_ty) = match active_variant {
                        Some(v_idx) => variant_field_projection(&current_ty, v_idx, *idx)?,
                        None if is_faithful_enum => {
                            return Err(BridgeError::UnsupportedOp(
                                "plain Field projection on a first-class enum (no Downcast)"
                                    .to_string(),
                            ));
                        }
                        None => (*idx as u32, field_type(&current_ty, *idx)?),
                    };

                    let trust_ir_ty = self.map_type_ctx(&result_ty)?;
                    let result = self.fresh_value();
                    body.push(
                        InstrNode::new(Inst::ExtractField {
                            ty: trust_ir_ty,
                            aggregate: current,
                            field: mapped_field,
                        })
                        .with_result(result),
                    );
                    self.mark_result_symbolic_from(result, &[current]);
                    current = result;
                    current_ty = result_ty;
                    // Trust (#46): a `Downcast(V)` records the active variant ONLY for
                    // the immediately-following field lookup (which uses the `__vV_`
                    // field prefix). Once that field is extracted, `current_ty` is the
                    // field's OWN type (e.g. the `(usize, &T)` tuple payload of
                    // `Some` in an `enumerate`/`zip` desugar), so any further `Field`
                    // projection is plain, NOT variant-qualified — MIR re-downcasts
                    // for each field of a variant via separate places. Leaving the
                    // variant set made the next tuple-field projection fail with
                    // "Field projection on non-ADT with active variant N". Reset it.
                    active_variant = None;
                }
                Projection::Index(idx_local) => {
                    let idx_val = self.read_local(*idx_local, body)?;
                    let result_ty = indexed_element_type(&current_ty, "Index")?;
                    let result = if slice_element_type(&current_ty).is_some() {
                        self.emit_slice_index_load(current, &current_ty, idx_val, body)?
                    } else {
                        let trust_ir_ty = self.map_type_ctx(&result_ty)?;
                        let result = self.fresh_value();
                        body.push(
                            InstrNode::new(Inst::ExtractElement {
                                ty: trust_ir_ty,
                                array: current,
                                index: idx_val,
                            })
                            .with_result(result),
                        );
                        self.mark_result_symbolic_from(result, &[current, idx_val]);
                        result
                    };
                    current = result;
                    current_ty = result_ty;
                }
                Projection::Deref => {
                    // For unsized slice pointees, deref produces a place with
                    // the same data pointer and metadata, not a load of `[T]`.
                    let result_ty = current_ty.pointee_ty().cloned().ok_or_else(|| {
                        BridgeError::UnsupportedOp(format!(
                            "Deref projection on non-pointer type {current_ty:?}"
                        ))
                    })?;
                    if matches!(result_ty, Ty::Slice { .. }) {
                        current_ty = result_ty;
                        continue;
                    }

                    // Load through a thin pointer.
                    let trust_ir_ty = self.map_type_ctx(&result_ty)?;
                    let result = self.fresh_value();
                    let mut load = InstrNode::new(Inst::Load {
                        ty: trust_ir_ty,
                        ptr: current,
                        volatile: false,
                        align: None,
                    })
                    .with_result(result);
                    // A load through a SAFE reference (`&T`/`&mut T`) is always
                    // valid — the borrow checker guarantees the referent is live
                    // and initialized — so mark it `ValidBorrow`. The native CHC
                    // honors this to model a load through an unknown-address but
                    // valid reference (e.g. the `&x` a slice iterator yields) as a
                    // fresh-symbolic value instead of fail-closing. A RAW pointer
                    // deref carries no such guarantee and stays unannotated, so its
                    // unknown-address load still fails closed.
                    if matches!(current_ty, Ty::Ref { .. }) {
                        load = load.with_proof(ProofAnnotation::ValidBorrow);
                    }
                    body.push(load);
                    self.mark_result_symbolic_from(result, &[current]);
                    current = result;
                    current_ty = result_ty;
                }
                Projection::Downcast(variant) => {
                    active_variant = Some(*variant);
                }
                Projection::ConstantIndex { offset, min_length, from_end } => {
                    let result_ty = indexed_element_type(&current_ty, "ConstantIndex")?;
                    let absolute_index = match &current_ty {
                        Ty::Array { len, .. } => {
                            if *len < *min_length as u64 {
                                return Err(BridgeError::UnsupportedOp(format!(
                                    "ConstantIndex min_length {min_length} exceeds array length {len}"
                                )));
                            }
                            if *from_end {
                                len.checked_sub(*offset as u64).ok_or_else(|| {
                                    BridgeError::UnsupportedOp(format!(
                                        "ConstantIndex from_end offset {offset} exceeds array length {len}"
                                    ))
                                })? as usize
                            } else {
                                *offset
                            }
                        }
                        Ty::Slice { .. } => {
                            let index = if *from_end {
                                // Trust (B2-1b): the length is the fat pointer's U64
                                // metadata lane — the offset/Sub lane matches it.
                                let fat_trust_ir = self.map_type_ctx(&current_ty)?;
                                let len = self.emit_slice_metadata(fat_trust_ir, current, body);
                                let offset = self.emit_u64_const(*offset as u64, body);
                                let index = self.fresh_value();
                                body.push(
                                    InstrNode::new(Inst::BinOp {
                                        op: TrustIrBinOp::Sub,
                                        ty: TrustIrTy::U64,
                                        lhs: len,
                                        rhs: offset,
                                    })
                                    .with_result(index),
                                );
                                index
                            } else {
                                self.emit_usize_const(*offset as u64, body)
                            };
                            let result =
                                self.emit_slice_index_load(current, &current_ty, index, body)?;
                            current = result;
                            current_ty = result_ty;
                            continue;
                        }
                        _ if *from_end => {
                            return Err(BridgeError::UnsupportedOp(
                                "ConstantIndex from_end requires modeled array/slice length"
                                    .to_string(),
                            ));
                        }
                        _ => *offset,
                    };
                    // Constant index -> emit a const + ExtractElement.
                    let idx_val = self.fresh_value();
                    body.push(
                        InstrNode::new(Inst::Const {
                            ty: TrustIrTy::I64,
                            value: TrustIrConstant::Int(absolute_index as i128),
                        })
                        .with_result(idx_val),
                    );
                    let result = self.fresh_value();
                    let trust_ir_ty = self.map_type_ctx(&result_ty)?;
                    body.push(
                        InstrNode::new(Inst::ExtractElement {
                            ty: trust_ir_ty,
                            array: current,
                            index: idx_val,
                        })
                        .with_result(result),
                    );
                    self.mark_result_symbolic_from(result, &[current, idx_val]);
                    current = result;
                    current_ty = result_ty;
                }
                Projection::Subslice { from, to, from_end } => {
                    let result_ty = subslice_result_type(&current_ty, *from, *to, *from_end)?;
                    current =
                        self.emit_subslice(current, &current_ty, *from, *to, *from_end, body)?;
                    current_ty = result_ty;
                }
                Projection::OpaqueCast(ty) | Projection::UnwrapUnsafeBinder(ty) => {
                    // Type-only projections do not change the value in TrustIr.
                    current_ty = ty.clone();
                }
                _ => {
                    return Err(BridgeError::UnsupportedOp(format!(
                        "unknown projection variant: {proj:?}"
                    )));
                }
            }
        }

        Ok(current)
    }

    fn emit_subslice(
        &mut self,
        base: ValueId,
        source_ty: &Ty,
        from: usize,
        to: usize,
        from_end: bool,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        match source_ty {
            Ty::Array { .. } => {
                self.emit_array_subslice_value(base, source_ty, from, to, from_end, body)
            }
            Ty::Slice { .. } | Ty::Ref { .. } | Ty::RawPtr { .. }
                if slice_element_type(source_ty).is_some() =>
            {
                self.emit_slice_subslice_value(base, source_ty, from, to, from_end, body)
            }
            _ => Err(BridgeError::UnsupportedOp(format!(
                "Subslice projection on non-slice/array type {source_ty:?}"
            ))),
        }
    }

    fn emit_slice_index_load(
        &mut self,
        fat_ptr: ValueId,
        source_ty: &Ty,
        index: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let elem_ty = slice_element_type(source_ty).ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "slice index projection on non-slice fat pointer type {source_ty:?}"
            ))
        })?;
        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
        let fat_trust_ir = self.map_type_ctx(source_ty)?;
        let data_ptr = self.emit_slice_data_ptr(fat_trust_ir, fat_ptr, body);
        let elem_ptr = self.fresh_value();
        body.push(
            InstrNode::new(Inst::GEP {
                pointee_ty: elem_trust_ir_ty.clone(),
                base: data_ptr,
                indices: vec![index],
                inbounds: false,
            })
            .with_result(elem_ptr),
        );
        self.mark_result_symbolic_from(elem_ptr, &[data_ptr, index]);
        let loaded = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Load {
                ty: elem_trust_ir_ty,
                ptr: elem_ptr,
                volatile: false,
                align: None,
            })
            .with_result(loaded),
        );
        self.mark_result_symbolic_from(loaded, &[elem_ptr]);
        Ok(loaded)
    }

    fn emit_slice_element_ptr(
        &mut self,
        fat_ptr: ValueId,
        source_ty: &Ty,
        index: ValueId,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let elem_ty = slice_element_type(source_ty).ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "slice index projection on non-slice fat pointer type {source_ty:?}"
            ))
        })?;
        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
        let fat_trust_ir = self.map_type_ctx(source_ty)?;
        let data_ptr = self.emit_slice_data_ptr(fat_trust_ir, fat_ptr, body);
        let elem_ptr = self.fresh_value();
        body.push(
            InstrNode::new(Inst::GEP {
                pointee_ty: elem_trust_ir_ty,
                base: data_ptr,
                indices: vec![index],
                inbounds: false,
            })
            .with_result(elem_ptr),
        );
        self.mark_result_symbolic_from(elem_ptr, &[data_ptr, index]);
        Ok(elem_ptr)
    }

    fn constant_slice_index_value(
        &mut self,
        fat_ty: TrustIrTy,
        fat_ptr: ValueId,
        offset: usize,
        from_end: bool,
        body: &mut Vec<InstrNode>,
    ) -> ValueId {
        if !from_end {
            return self.emit_usize_const(offset as u64, body);
        }

        // Trust (B2-1b): length-lane arithmetic at the canonical U64 metadata type.
        let len = self.emit_slice_metadata(fat_ty, fat_ptr, body);
        let offset = self.emit_u64_const(offset as u64, body);
        let index = self.fresh_value();
        body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Sub,
                ty: TrustIrTy::U64,
                lhs: len,
                rhs: offset,
            })
            .with_result(index),
        );
        self.mark_result_symbolic_from(index, &[len, offset]);
        index
    }

    fn emit_array_subslice_value(
        &mut self,
        array: ValueId,
        source_ty: &Ty,
        from: usize,
        to: usize,
        from_end: bool,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let Ty::Array { elem, .. } = source_ty else {
            return Err(BridgeError::UnsupportedOp(format!(
                "Subslice projection on non-array type {source_ty:?}"
            )));
        };
        let result_ty = subslice_result_type(source_ty, from, to, from_end)?;
        let result_len = match &result_ty {
            Ty::Array { len, .. } => *len,
            _ => {
                return Err(BridgeError::UnsupportedOp(format!(
                    "array Subslice unexpectedly produced non-array type {result_ty:?}"
                )));
            }
        };

        let elem_ty = (**elem).clone();
        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
        let result_trust_ir_ty =
            self.map_type_ctx(&Ty::Array { elem: Box::new(elem_ty), len: result_len })?;

        self.ensure_no_symbolic_undef_seed("array subslice", &[array])?;
        let mut current = self.fresh_value();
        body.push(
            InstrNode::new(Inst::Undef { ty: result_trust_ir_ty.clone() }).with_result(current),
        );

        for i in 0..result_len {
            let src_idx = self.emit_usize_const(from as u64 + i, body);
            let elem_value = self.fresh_value();
            body.push(
                InstrNode::new(Inst::ExtractElement {
                    ty: elem_trust_ir_ty.clone(),
                    array,
                    index: src_idx,
                })
                .with_result(elem_value),
            );
            self.mark_result_symbolic_from(elem_value, &[array]);

            let dst_idx = self.emit_usize_const(i, body);
            let next = self.fresh_value();
            body.push(
                InstrNode::new(Inst::InsertElement {
                    ty: result_trust_ir_ty.clone(),
                    array: current,
                    index: dst_idx,
                    value: elem_value,
                })
                .with_result(next),
            );
            current = next;
        }

        Ok(current)
    }

    fn emit_slice_subslice_value(
        &mut self,
        fat_ptr: ValueId,
        source_ty: &Ty,
        from: usize,
        to: usize,
        from_end: bool,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        let elem_ty = slice_element_type(source_ty).ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "Subslice projection on non-slice fat pointer type {source_ty:?}"
            ))
        })?;
        if !from_end && to < from {
            return Err(BridgeError::UnsupportedOp(format!(
                "Subslice range {from}..{to} is inverted"
            )));
        }

        let fat_trust_ir = self.map_type_ctx(source_ty)?;
        let data_ptr = self.emit_slice_data_ptr(fat_trust_ir.clone(), fat_ptr, body);
        let start = self.emit_usize_const(from as u64, body);
        let elem_trust_ir_ty = self.map_type_ctx(&elem_ty)?;
        let start_ptr = self.fresh_value();
        body.push(
            InstrNode::new(Inst::GEP {
                pointee_ty: elem_trust_ir_ty,
                base: data_ptr,
                indices: vec![start],
                inbounds: false,
            })
            .with_result(start_ptr),
        );
        self.mark_result_symbolic_from(start_ptr, &[data_ptr, start]);

        let new_len = if from_end {
            // Trust (B2-1b): length-lane arithmetic at the canonical U64 metadata type.
            let base_len = self.emit_slice_metadata(fat_trust_ir.clone(), fat_ptr, body);
            let trim = self.emit_u64_const(from as u64 + to as u64, body);
            let result = self.fresh_value();
            body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Sub,
                    ty: TrustIrTy::U64,
                    lhs: base_len,
                    rhs: trim,
                })
                .with_result(result),
            );
            self.mark_result_symbolic_from(result, &[base_len, trim]);
            result
        } else {
            self.emit_u64_const((to - from) as u64, body)
        };

        // The subslice result is the SAME slice type — same fat spelling.
        self.emit_slice_fat_pointer(fat_trust_ir, start_ptr, new_len, body)
    }

    /// Emit a TrustIr Const instruction for a trust-types ConstValue.
    fn emit_const(
        &mut self,
        cv: &ConstValue,
        body: &mut Vec<InstrNode>,
    ) -> Result<ValueId, BridgeError> {
        // Trust Gap 3: a `&str` literal — model it as an opaque slice fat pointer
        // (`Undef` → fresh symbolic in the consumer). Sound over-approximation:
        // the bytes/length are not asserted, so string-value-dependent obligations
        // stay `unknown` (never falsely proved), but it unblocks every function
        // touching a string literal (panic/format messages, comparisons), which
        // previously failed with "unknown constant variant".
        // `&str` literal and reference-to-slice/array constants (`&[&str]` tables):
        // both model as a fresh-symbolic opaque slice fat pointer (sound — contents
        // not asserted, value-dependent obligations stay `unknown`, never proved).
        // `UnitVariantRef` (promoted `&Option<T>::None`-style reference constant)
        // value-lowers identically to `OpaqueConst`: a fresh symbolic ref. Its
        // variant information is consumed SYNTACTICALLY by the eq-guard channels,
        // never here.
        if let ConstValue::Str { .. }
        | ConstValue::OpaqueConst
        | ConstValue::UnitVariantRef { .. } = cv
        {
            // Trust (B2-1b): the opaque fat value carries the first-class spelling —
            // FatPtr(Slice(u8)) (the byte-slice view; the oracle conflates &str with
            // &[u8] anyway — ty_convert spells both Ref{Slice{u8}}). The Undef stays
            // (fresh symbolic in the consumer, contents never asserted).
            let ty = self
                .map_type_ctx(&Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) })?;
            let result = self.fresh_value();
            body.push(InstrNode::new(Inst::Undef { ty }).with_result(result));
            return Ok(result);
        }
        // A typed opaque integer constant (const-generic `N`, associated const
        // `T::LIMIT`, `size_of::<T>()` in a generic body): lower to a FRESH
        // integer-sorted `Undef` of the matching width/signedness. `fresh_value()`
        // makes every occurrence an independent unconstrained symbol (translate_chc
        // turns a scalar `Undef` into a fresh symbolic of the sort), so the value is
        // never asserted and value/arith/index obligations over it stay `unknown` —
        // and distinct reads are never asserted equal. Unlike the `OpaqueConst` arm
        // above, this keeps the INTEGER sort that arithmetic/indexing uses require.
        if let ConstValue::OpaqueScalar { width, signed } = cv {
            let ty = map_type(&Ty::Int { width: *width, signed: *signed })?;
            let result = self.fresh_value();
            body.push(InstrNode::new(Inst::Undef { ty }).with_result(result));
            return Ok(result);
        }
        // Trust: piece #7a — a const-generic PARAM value on the NATIVE (`-full`)
        // path. Model it as a FRESH integer-sorted `Undef` of the matching
        // width/signedness — the SAME sound over-approximation as `OpaqueScalar`.
        // SOUNDNESS: an independent fresh symbol per occurrence asserts NO value,
        // so value/div/index obligations over it stay `unknown`, never falsely
        // proved. Because each occurrence is a distinct fresh symbol, the native
        // path itself does NOT tie the guard `N` to the array length `N` — but it
        // can therefore never independently PROVE a const-generic bounds VC (a
        // fresh unconstrained `N` cannot make `i >= N` UNSAT). The AUTHORITATIVE
        // bounds discharge comes from the trust-vcgen VC (where the guard `N` and
        // the array length `N` DO share the `__trust_constparam_*` symbol),
        // bridged in via `bridge_v1_ay_proofs_into_native_results`. So this arm is
        // sound: it lets native lowering complete without ever over-claiming.
        if let ConstValue::ConstParam { width, signed, .. } = cv {
            // A BOOL const-generic (in-band `width==1 && !signed`, see
            // trust-mir-extract) is Bool-typed; Rust has no 1-bit integer.
            let ty = if *width == 1 && !*signed {
                map_type(&Ty::Bool)?
            } else {
                map_type(&Ty::Int { width: *width, signed: *signed })?
            };
            let result = self.fresh_value();
            body.push(InstrNode::new(Inst::Undef { ty }).with_result(result));
            return Ok(result);
        }
        // Callable identity is extraction evidence, not a value-level unit
        // literal. TrustIr has no named opaque Unit constant, so lower it to a
        // fresh Unit-typed Undef. This preserves the sort while asserting no
        // equality, behavior, or provenance fact.
        if matches!(cv, ConstValue::CallableItem { .. }) {
            let result = self.fresh_value();
            body.push(InstrNode::new(Inst::Undef { ty: TrustIrTy::Unit }).with_result(result));
            return Ok(result);
        }
        let (ty, value) = match cv {
            ConstValue::Bool(b) => (TrustIrTy::Bool, TrustIrConstant::Bool(*b)),
            // A signed integer literal carries no width in `ConstValue::Int`, so we
            // default to `I64`. EXCEPTION: a value that does NOT fit `i64` (e.g.
            // `i128::MIN = -2^127`) can ONLY be an `i128`, so type it `I128`. Without
            // this, the transport lowering emits `i128::MIN` as an `I64` const while a
            // sibling use of the same value is `I128`, producing a width-inconsistent CFG
            // (`signed_min`'s saturate/return leaves) that made the call-summary `ite`
            // combine fail (previously ICE, now fail-closed). SOUND: the value provably
            // requires `i128`; smaller literals are unaffected.
            ConstValue::Int(val) => {
                let ty = if i64::try_from(*val).is_ok() { TrustIrTy::I64 } else { TrustIrTy::I128 };
                (ty, TrustIrConstant::Int(*val))
            }
            ConstValue::Uint(val, width) => {
                let ty = match width {
                    8 => TrustIrTy::U8,
                    16 => TrustIrTy::U16,
                    32 => TrustIrTy::U32,
                    64 => TrustIrTy::U64,
                    128 => TrustIrTy::U128,
                    _ => return Err(BridgeError::UnsupportedType(format!("u{width}"))),
                };
                // TrustIr v24 has a canonical one-spelling rule: values through
                // `i128::MAX` use `Int`, while the upper half of u128 uses
                // `U128`. Always route through the sanctioned constructor; the
                // old signed-bit-pattern spelling is rejected by the v24
                // validator and binary decoder.
                (ty, TrustIrConstant::u128(*val))
            }
            ConstValue::Float(val) => (TrustIrTy::F64, TrustIrConstant::Float(*val)),
            ConstValue::FloatBits { bits, width: 64 } => {
                let bits = u64::try_from(*bits).map_err(|_| {
                    BridgeError::UnsupportedOp(format!(
                        "f64 FloatBits constant {bits} exceeds 64-bit payload"
                    ))
                })?;
                (TrustIrTy::F64, TrustIrConstant::Float(f64::from_bits(bits)))
            }
            ConstValue::FloatBits { bits, width: 32 } => {
                let bits32 = u32::try_from(*bits).map_err(|_| {
                    BridgeError::UnsupportedOp(format!(
                        "f32 FloatBits constant {bits} exceeds 32-bit payload"
                    ))
                })?;
                let v = f32::from_bits(bits32);
                // The f64 `Constant::Float` carrier is BIT-EXACT for every
                // non-NaN f32: the f32 values (finite incl. subnormals, ±0,
                // ±inf) are a strict subset of f64, the widening is injective,
                // and the f64->f32 demote round-trips exactly. NaN payloads
                // are NOT safely carried (the hardware widen can quiet a
                // signaling NaN, changing the payload a `to_bits` observer
                // could distinguish) — keep NaN fail-closed rather than risk
                // a wrong-bits constant fold.
                if v.is_nan() {
                    return Err(BridgeError::UnsupportedOp(
                        "f32 NaN constant payloads are not bit-exactly representable \
                         through the f64 Constant carrier; fail closed"
                            .to_string(),
                    ));
                }
                (TrustIrTy::F32, TrustIrConstant::Float(f64::from(v)))
            }
            ConstValue::FloatBits { width, .. } => {
                return Err(BridgeError::UnsupportedType(format!("f{width} bits")));
            }
            ConstValue::Unit => (TrustIrTy::Unit, TrustIrConstant::PhantomData),
            _ => {
                return Err(BridgeError::UnsupportedOp("unknown constant variant".to_string()));
            }
        };

        let result = self.fresh_value();
        body.push(InstrNode::new(Inst::Const { ty, value }).with_result(result));
        Ok(result)
    }

    /// Add a proof obligation and return its id.
    fn add_obligation(
        &mut self,
        kind: ObligationKind,
        description: String,
        source: ObligationSourceMetadata,
    ) -> ProofId {
        let id = ProofId::new(self.next_proof_id);
        self.next_proof_id += 1;
        let source_identity = source.to_proof_source_identity(self.module);
        self.proof_obligations.push(
            ProofObligation::new(id, kind, ProofStatus::Pending, description)
                .with_formula(source.into_formula())
                .with_function(self.current_function)
                .with_source(source_identity),
        );
        id
    }
}

/// The machine-readable predicate carried alongside a contract obligation's
/// source metadata. Produced only for contract obligations (requires / ensures
/// / invariants / refinements); MIR-assert and function-aggregate obligations
/// have no contract predicate, so they leave this `None`.
///
/// `Parsed` carries the `trust_types::Formula` the predicate body parsed to (the
/// SAME AST `trust-vcgen` builds via `parse_spec_expr`), so the spine can emit
/// it as JSON + SMT-LIB without any re-parsing downstream. `Unparseable`
/// records — faithfully — that the predicate body did NOT parse, so the
/// lowering FAILS CLOSED (no fabricated formula) rather than guessing.
#[derive(Debug, Clone)]
enum ContractPredicate {
    /// The predicate body parsed to this `trust_types::Formula`.
    Parsed(Formula),
    /// The predicate body could not be parsed; the source string is retained so
    /// the fail-closed payload can still record what was attempted.
    Unparseable(String),
}

/// Extract the bare, parseable predicate expression from a `trust_types::Contract`
/// body, mirroring exactly how `trust-vcgen`'s `contracts.rs` peels each kind
/// before calling `parse_spec_expr` — so the spine's parsed `Formula` is
/// byte-for-byte the one trust-vcgen would build:
///
/// * `Requires` / `Ensures` / `Invariant` — strip the compiler-lowered
///   `__trust_lowered_compiler_contract__:` marker prefix (if present), then the
///   remainder is the bare spec expr (`trust-vcgen contracts.rs:155-160`).
/// * `LoopInvariant` — strip the `bb<N>:` header-block prefix; the remainder is
///   the invariant expr (`parse_loop_invariant_body`, contracts.rs:218-226).
/// * `TypeRefinement` — split on the FIRST `:`; the part after it is the bare
///   predicate (`parse_refinement_body`, contracts.rs:231-237).
/// * `Decreases` / `Modifies` — metadata, no predicate obligation is emitted
///   for them in the lowering, so they never reach this function.
///
/// Returns the bare predicate string to feed to `parse_spec_expr`. The actual
/// parse + fail-closed decision happens in `ContractPredicate::from_body`.
fn contract_predicate_expr(kind: ContractKind, body: &str) -> Option<String> {
    const LOWERED_CONTRACT_PREFIX: &str = "__trust_lowered_compiler_contract__:";
    match kind {
        ContractKind::Requires | ContractKind::Ensures | ContractKind::Invariant => {
            Some(body.strip_prefix(LOWERED_CONTRACT_PREFIX).unwrap_or(body).to_string())
        }
        ContractKind::LoopInvariant => {
            // "bb<N>: <expr>" → <expr>; fall back to the whole body (block 0).
            if let Some(rest) = body.strip_prefix("bb")
                && let Some((block_str, expr)) = rest.split_once(':')
                && block_str.trim().parse::<usize>().is_ok()
            {
                Some(expr.trim().to_string())
            } else {
                Some(body.to_string())
            }
        }
        ContractKind::TypeRefinement => {
            // "var: predicate" → predicate; fall back to the whole body.
            Some(match body.split_once(':') {
                Some((_var, pred)) => pred.trim().to_string(),
                None => body.to_string(),
            })
        }
        // Decreases / Modifies emit no predicate obligation, and future kinds are
        // handled fail-closed by the caller; no bare predicate is extractable.
        _ => None,
    }
}

impl ContractPredicate {
    /// Build the machine-readable predicate for a contract clause, parsing its
    /// body with the SAME grammar (`trust_types::parse_spec_expr`) trust-vcgen
    /// uses. On any parse failure this returns [`ContractPredicate::Unparseable`]
    /// (fail-closed); it never fabricates a `Formula`.
    fn from_contract(kind: ContractKind, body: &str) -> Option<Self> {
        let expr = contract_predicate_expr(kind, body)?;
        Some(match trust_types::parse_spec_expr(&expr) {
            Some(formula) => ContractPredicate::Parsed(formula),
            None => ContractPredicate::Unparseable(expr),
        })
    }
}

// ===========================================================================
// L0 SAFETY-FORMULA RECONSTRUCTION (trust-ir-spine Phase 2/3)
// ===========================================================================
//
// `docs/TRUST_IR_SPINE.md` Phase 2/3: for the trust-ir spine to become the
// VERDICT source of record without regression, an L0 safety obligation lowered
// onto trust-ir must carry a SOLVABLE SMT-bearing formula that is EQUIVALENT to
// the one `trust_vcgen` produces — otherwise a future verdict flip could
// regress a `proved` to `unknown` (the formula trust-vcgen refutes UNSAT would
// be missing on the spine).
//
// **Why we reconstruct at lowering time (the prompt's Route B), not from the
// trust-ir SSA graph.** The trust-ir `Inst::Assert { cond }` carries only the
// lowered boolean condition value — for the canonical rustc overflow/bounds
// shapes that condition is the abstract "did it overflow / is it in bounds"
// FLAG (a `const false`/`const true` in the synthetic fixtures, an opaque
// boolean in real MIR), NOT a predicate over the operation's operands. The
// solvable trust-vcgen formula (`a + b ∉ [MIN,MAX]`, `divisor == 0`) is
// SYNTHESIZED by trust-vcgen from the binop OPERANDS, which live on a sibling
// node (`Inst::BinOp`/`Inst::Overflow`), not on the assert. Reconstructing the
// exact trust-vcgen SMT-LIB *string* (variable names `a`,`b`, …) from raw
// `ValueId`s post-lowering is not faithful (names are lost). So we reconstruct
// the formula HERE, where the trust-types `VerifiableFunction` (with its named
// locals and operands) is in hand, mirroring trust-vcgen byte-for-byte, and
// STAMP it onto the obligation's `ProofFormula` — exactly the contract-predicate
// enrichment pattern above, lifted to safety obligations. `lower.rs` is
// Trust-owned, so this is an allowed enrichment.
//
// **Soundness discipline (a wrong safety formula is worse than none).** Every
// reconstruction below is a point-for-point mirror of a specific `trust_vcgen`
// builder, reproduced with the SAME `trust_types` primitives. We reconstruct
// ONLY the SELF-CONTAINED CORE predicate each builder forms over the operands —
// `v2_build_overflow_vc_for_operands`'s `body` (range ∧ range ∧ out-of-range)
// and `v2_divisor_is_zero_formula`'s `divisor == 0` — and ONLY for the
// simple-local integer operand shapes where `place_to_var_name` is the bare
// local name and `operand_to_formula` is `Var(name, Int)` / `Int(n)`. For any
// operand shape outside that envelope (projections, symbolic operands, floats,
// the bitvector mul path, …) we FAIL CLOSED and stamp NO formula — never a
// guessed one. The `#[cfg(test)]` oracle in `parity.rs` asserts byte-exact
// SMT-LIB equality against the live `trust_vcgen` formula for every covered
// case, so a reconstruction that drifts from trust-vcgen FAILS the build.
//
// **What we deliberately do NOT reproduce: the solver-tuned block-def /
// arg-range / slice-len conjuncts** (`v2_formula_with_block_defs`,
// `conjoin_arg_type_ranges`, `conjoin_slice_len_bounds`) live in private
// trust-vcgen helpers we cannot call. Those conjuncts only ADD sound
// assumptions (block dataflow, parameter type ranges) that STRENGTHEN the
// solver's hand — dropping them can only make a VC HARDER to prove, never
// easier, so omitting them can never manufacture a false `proved`. The core
// violation predicate we stamp is the obligation's solvable heart; equivalence
// is asserted against the trust-vcgen CORE (the block-def-free fixtures), and
// the relationship to the block-def-wrapped form is documented per-case in
// `parity.rs`.

/// The reconstructed, solvable L0 safety predicate stamped onto a MIR-assert
/// safety obligation — the trust-ir-native counterpart to a contract clause's
/// [`ContractPredicate`].
///
/// `Reconstructed` carries the `trust_types::Formula` that byte-mirrors the core
/// `trust_vcgen` safety formula for this obligation (so the spine emits it as
/// JSON + SMT-LIB with no re-derivation). `NotReconstructed` records — honestly
/// — that the operand shape fell outside the faithful envelope, so the lowering
/// FAILS CLOSED (no fabricated formula) and the obligation keeps source metadata
/// only, exactly as before this enrichment.
#[derive(Debug, Clone)]
enum SafetyPredicate {
    /// The core safety predicate reconstructed to this `trust_types::Formula`,
    /// byte-equal to the corresponding `trust_vcgen` core formula.
    Reconstructed(Formula),
    /// The obligation is a safety check, but its operands were not in the
    /// faithful-reconstruction envelope; no formula is stamped (fail-closed).
    /// The string names which builder declined, for the payload's audit field.
    NotReconstructed(String),
}

/// The SMT sort an L0 safety violation predicate always has: `Bool`. Overflow
/// out-of-range, divisor-is-zero, and index-out-of-bounds are all boolean
/// assertions, matching how `trust_vcgen` always yields a `Bool`-sorted VC
/// formula at the top level.
const TRUST_SAFETY_PREDICATE_SORT: &str = "Bool";

/// trust-ir-native reproduction of `trust_vcgen::place_to_var_name` for the
/// faithful envelope (a direct local with no projections).
///
/// Mirrors `trust_vcgen/src/lib.rs::place_to_var_name`: the variable name is the
/// local's declared `name`, or `_<index>` when unnamed. We support ONLY the
/// no-projection case here — a projected place (field/index/deref) is outside
/// the envelope and the caller fails closed — so the canonicalization and
/// projection-suffix logic trust-vcgen runs is not needed (it is the identity
/// for projection-free places). Returns `None` if the local is missing.
fn safety_place_var_name(locals: &[LocalDecl], place: &Place) -> Option<String> {
    if !place.projections.is_empty() {
        return None;
    }
    locals.iter().find(|d| d.index == place.local)?;
    Some(collision_safe_local_name(locals, place.local))
}

/// The SMT variable name for `local`, mirroring `trust_vcgen::place_to_var_name`'s
/// name-collision guard EXACTLY: use the local's SOURCE name only when it is UNIQUE
/// across the function's locals; otherwise fall back to the per-local `_<local>` name.
///
/// Trust #soundness (name-collision false proof): a source name is NOT unique across
/// distinct MIR locals — shadowing (`let s = outer; { let s = inner; … }`) or
/// debug-name coalescing gives two DISTINCT locals the SAME name. A FACT keyed to one
/// local (a slice-length guard `i < s__slice_len`, an accumulator bound) would then be
/// conjoined onto the OTHER same-named local's VC and vacuously discharge its real
/// obligation — a CONFIRMED FALSE PROOF (the adversarial audit's `collide` fixture:
/// two `&[u32]` both named `s`, guard on `len(outer)` discharged the bounds check on
/// `inner`). vcgen fixed this at the root; the native/canonicalization path must too,
/// and mirroring vcgen's rule keeps the byte-equality flip candidates identical.
fn collision_safe_local_name(locals: &[LocalDecl], local: usize) -> String {
    let fallback = format!("_{local}");
    let name_is_fallback_shaped = |name: &str| -> bool {
        name.strip_prefix('_')
            .and_then(|suffix| suffix.parse::<usize>().ok())
            .is_some_and(|index| index < locals.len())
    };
    match locals.iter().find(|d| d.index == local).and_then(|d| d.name.as_deref()) {
        Some(name)
            if locals.iter().filter(|d| d.name.as_deref() == Some(name)).count() <= 1
                && !name_is_fallback_shaped(name)
                && trust_types::source_contract_synthetic_name_collision(name).is_none() =>
        {
            name.to_string()
        }
        _ => fallback,
    }
}

#[cfg(test)]
#[test]
fn collision_safe_local_name_reserves_generated_formula_namespace() {
    let locals = vec![
        LocalDecl { index: 0, ty: Ty::Unit, name: None },
        LocalDecl {
            index: 1,
            ty: Ty::Ref { mutable: false, inner: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }) },
            name: Some("s".into()),
        },
        LocalDecl { index: 2, ty: Ty::usize(), name: Some("s__slice_len".into()) },
        LocalDecl { index: 3, ty: Ty::usize(), name: Some("__trust_constparam_0_N".into()) },
        LocalDecl { index: 4, ty: Ty::usize(), name: Some("_1".into()) },
    ];

    let slice = collision_safe_local_name(&locals, 1);
    let scalar_len = collision_safe_local_name(&locals, 2);
    let scalar_const = collision_safe_local_name(&locals, 3);
    assert_eq!(slice, "s");
    assert_eq!(scalar_len, "_2");
    assert_eq!(scalar_const, "_3");
    assert_eq!(collision_safe_local_name(&locals, 4), "_4");
    assert_ne!(scalar_len, format!("{slice}__slice_len"));
    assert_ne!(scalar_const, trust_types::const_param_symbol(0, "N"));
}

/// trust-ir-native reproduction of `trust_vcgen::operand_to_formula` for the
/// faithful integer envelope.
///
/// Mirrors `trust_vcgen/src/lib.rs::operand_to_formula` for exactly the operand
/// shapes a no-block-def safety VC ranges over: a direct integer local
/// (`Copy`/`Move` of a projection-free place) → `Var(name, Int)`, and an integer
/// constant → `Int(n)` (with the same `Uint`→`Int` narrowing trust-vcgen uses).
/// Any other shape (projected place, symbolic, bool/float/str constant, …) is
/// OUTSIDE the envelope and returns `None`, so the caller fails closed rather
/// than emitting a formula that might not match trust-vcgen's encoding.
///
/// NOTE: this is intentionally the SCALAR `Sort::Int` path. trust-vcgen routes
/// some operands to `Sort::BitVec` (when `operand_sort` resolves a bitvector,
/// e.g. for the BV mul/float paths); those are gated out by the caller (we only
/// reconstruct add/sub overflow and integer div-by-zero), so `Sort::Int` is the
/// faithful sort here, matching the dumped trust-vcgen formulas.
fn safety_operand_to_formula(locals: &[LocalDecl], op: &Operand) -> Option<Formula> {
    match op {
        Operand::Copy(place) | Operand::Move(place) => {
            let name = safety_place_var_name(locals, place)?;
            Some(Formula::var(&name, Sort::Int))
        }
        Operand::Constant(ConstValue::Int(n)) => Some(Formula::Int(*n)),
        Operand::Constant(ConstValue::Uint(n, _)) => match i128::try_from(*n) {
            Ok(n) => Some(Formula::Int(n)),
            Err(_) => Some(Formula::UInt(*n)),
        },
        _ => None,
    }
}

/// The `(width, signed)` of a binary op's integer type, recovered the way
/// `trust_vcgen::int_op_type` does for the faithful envelope: take the type from
/// whichever operand is a non-constant local (a width-less integer literal loses
/// its type), requiring BOTH operands to agree (or one to be a literal). Returns
/// `None` for non-integer or mismatched-width operands (outside the envelope).
fn safety_int_op_type(locals: &[LocalDecl], lhs: &Operand, rhs: &Operand) -> Option<(u32, bool)> {
    let local_int_ty = |op: &Operand| -> Option<(u32, bool)> {
        let place = match op {
            Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
            _ => return None,
        };
        let ty = &locals.iter().find(|d| d.index == place.local)?.ty;
        Some((ty.int_width()?, ty.is_signed()))
    };
    match (local_int_ty(lhs), local_int_ty(rhs)) {
        // Both local: require identical (width, signed) — a mixed-width op is
        // outside the envelope (trust-vcgen would model it differently), so it
        // declines (`None`) rather than guess a width.
        (Some(l), Some(r)) => (l == r).then_some(l),
        // One local, one CONSTANT operand: the local carries the true type (the
        // literal adopts it, exactly as `int_op_type` does — it takes the type
        // from whichever operand is NON-constant, regardless of the constant's
        // kind). This MUST accept BOTH `ConstValue::Int` (signed/untyped literal)
        // AND `ConstValue::Uint` (unsigned literal): rustc lowers `x + 1` on a
        // u32 `x` to `CheckedAdd(x, Uint(1, 32))`, so restricting to `Int` would
        // (wrongly) fail-close the extremely common `unsigned_local OP literal`
        // shape (`x + 1`, `x * 2`, `len - 1`). The formula reconstruction is still
        // gated by `safety_operand_to_formula` (projected/symbolic/non-int
        // operands decline), so widening the width recovery cannot over-flip.
        (Some(l), None) if matches!(rhs, Operand::Constant(_)) => Some(l),
        (None, Some(r)) if matches!(lhs, Operand::Constant(_)) => Some(r),
        _ => None,
    }
}

/// Reproduce `trust_vcgen::range::input_range_constraint` exactly:
/// `And([Le(min, var), Le(var, max)])`.
fn safety_input_range_constraint(var: &Formula, width: u32, signed: bool) -> Formula {
    Formula::And(vec![
        Formula::Le(Box::new(safety_type_min_formula(width, signed)), Box::new(var.clone())),
        Formula::Le(Box::new(var.clone()), Box::new(safety_type_max_formula(width, signed))),
    ])
}

/// Reproduce `trust_vcgen::range::type_min_formula`.
fn safety_type_min_formula(width: u32, signed: bool) -> Formula {
    if signed {
        let min = if width == 128 { i128::MIN } else { -(1i128 << (width - 1)) };
        Formula::Int(min)
    } else {
        Formula::Int(0)
    }
}

/// Reproduce `trust_vcgen::range::type_max_formula`.
fn safety_type_max_formula(width: u32, signed: bool) -> Formula {
    if signed {
        let max = if width == 128 { i128::MAX } else { (1i128 << (width - 1)) - 1 };
        Formula::Int(max)
    } else if width == 128 {
        Formula::UInt(u128::MAX)
    } else {
        Formula::Int((1i128 << width) - 1)
    }
}

/// Reconstruct the CORE overflow `body` predicate `trust_vcgen` builds for a
/// non-mul integer `lhs OP rhs` (Add/Sub) in `v2_build_overflow_vc_for_operands`:
///
/// ```text
/// And([ input_range(lhs), input_range(rhs),
///       Or([ Lt(result, type_min), Gt(result, type_max) ]) ])
/// ```
///
/// where `result = Add|Sub(lhs_f, rhs_f)`. This is byte-identical to the `body`
/// variable in trust-vcgen — the SELF-CONTAINED solvable heart of the overflow
/// obligation, and the INNERMOST subterm of trust-vcgen's emitted formula.
///
/// **Why we stamp the core `body`, not trust-vcgen's full emitted formula.**
/// trust-vcgen wraps `body` in TWO further layers of the SAME parameter
/// type-range constraints — once via the block-definition pass
/// (`v2_formula_with_block_defs`, which surfaces arg type ranges as block defs)
/// and once via `conjoin_arg_type_ranges`. Those layers re-conjoin
/// `range(a) ∧ range(b)` that `body` ALREADY contains, so trust-vcgen's emitted
/// formula is `range(a) ∧ range(b) ∧ ( range(a) ∧ range(b) ∧ ( body ) )` — and
/// since `range(p)` is idempotent (`P ∧ P ≡ P`), it is LOGICALLY EQUIVALENT to
/// `body`: identical models, identical satisfiability, so identical verdict.
/// Those redundant layers are built by PRIVATE trust-vcgen helpers
/// (`extract_block_definitions`) we cannot call; reproducing them by hand would
/// be a fragile duplication of trust-vcgen internals (the soundness hazard this
/// module's header warns against). So the stamp is `body`, and the parity test
/// asserts the documented relationship: the stamp equals trust-vcgen's INNERMOST
/// `body` subterm byte-for-byte, and is logically equivalent to the full formula.
///
/// General MUL routes through the fixed-width BITVECTOR encoding in trust-vcgen
/// (`v2_*_bv_overflow_formula`, fresh BV vars), which the scalar `Sort::Int` path
/// here does not model. The ONE mul family on the scalar path is trust-vcgen's
/// `linear_const_mul` routing (91d8dcb9f8): a constant-multiplier, non-widening
/// mul is emitted in Int/LIA form — the Mul arm's caller offers that Int form as
/// an extra candidate (a never-matching candidate is inert under the exact gate).
fn reconstruct_overflow_body(
    locals: &[LocalDecl],
    op: BinOp,
    lhs: &Operand,
    rhs: &Operand,
) -> Option<Formula> {
    let formula_op = match op {
        BinOp::Add => Formula::Add as fn(Box<Formula>, Box<Formula>) -> Formula,
        BinOp::Sub => Formula::Sub as fn(Box<Formula>, Box<Formula>) -> Formula,
        // Mul only for trust-vcgen's linear const-mul routing (91d8dcb9f8).
        BinOp::Mul => Formula::Mul as fn(Box<Formula>, Box<Formula>) -> Formula,
        _ => return None,
    };
    let (width, signed) = safety_int_op_type(locals, lhs, rhs)?;
    // signed-128 add/sub are emitted by trust-vcgen in BV (the native LIA lane cannot
    // represent ±2^127). Mirror its `w+1`-bit sign-extension overflow check for the
    // BARE operand case; the guarded/block-def case carries conjuncts we cannot
    // reproduce (the flip then keeps trust-vcgen's BV formula — fail-closed, sound).
    if signed && width >= 128 {
        return reconstruct_bv_signed_addsub_overflow_body(locals, op, lhs, rhs, width);
    }
    let lhs_f = safety_operand_to_formula(locals, lhs)?;
    let rhs_f = safety_operand_to_formula(locals, rhs)?;
    let result = formula_op(Box::new(lhs_f.clone()), Box::new(rhs_f.clone()));
    let lhs_range = safety_input_range_constraint(&lhs_f, width, signed);
    let rhs_range = safety_input_range_constraint(&rhs_f, width, signed);
    let min_f = safety_type_min_formula(width, signed);
    let max_f = safety_type_max_formula(width, signed);
    let out_of_range = Formula::Or(vec![
        Formula::Lt(Box::new(result.clone()), Box::new(min_f)),
        Formula::Gt(Box::new(result), Box::new(max_f)),
    ]);
    Some(Formula::And(vec![lhs_range, rhs_range, out_of_range]))
}

/// Reconstruct the BITVECTOR signed add/sub overflow (failure) condition trust-vcgen
/// builds for a SIGNED >=128-bit `lhs OP rhs` (`OP` in Add/Sub) in
/// `v2_signed_bv_addsub_overflow_formula`, for the BARE operand case (integer
/// constants / projection-free locals, no conjoined block-defs / guard bounds). This
/// is byte-identical to trust-vcgen's `bv_formula` for that case.
///
///   `Not(Eq( extract[w:w](OP(sext(a,1), sext(b,1))),
///            extract[w-1:w-1](OP(sext(a,1), sext(b,1))) ))`
///
/// where `OP` = `BvAdd`/`BvSub` at width `w+1`, and operands are encoded by
/// `reconstruct_bv_operand_term` (mirrors `v2_bv_operand_term`). The guarded /
/// block-def-carrying case (`signed_max`'s `_5 - 1`) has a WIDER live formula and so
/// does NOT byte-match — the flip then keeps trust-vcgen's formula (fail-closed, sound).
/// `None` when an operand is outside the bare envelope or width is out of range.
fn reconstruct_bv_signed_addsub_overflow_body(
    locals: &[LocalDecl],
    op: BinOp,
    lhs: &Operand,
    rhs: &Operand,
    width: u32,
) -> Option<Formula> {
    if width == 0 || width > 128 || !matches!(op, BinOp::Add | BinOp::Sub) {
        return None;
    }
    let a = reconstruct_bv_operand_term(locals, lhs, width, "lhs")?;
    let b = reconstruct_bv_operand_term(locals, rhs, width, "rhs")?;
    // BYTE-IDENTICAL to trust-vcgen's `signed_bv_addsub_overflow_sign_test`: the
    // SIGN-BIT overflow test in pure QF_BV (BvULt + BvAdd/BvSub at width `w` +
    // And/Or/Not + BitVec), avoiding the `w+1`-bit sign-extension / bit-extraction
    // form (which the native typed-CHC lane returns `Unsupported` for).
    let msb = Formula::BitVec {
        value: if width == 128 { i128::MIN } else { 1i128 << (width - 1) },
        width,
    };
    let nonneg = |v: &Formula| Formula::BvULt(Box::new(v.clone()), Box::new(msb.clone()), width);
    let result = match op {
        BinOp::Add => Formula::BvAdd(Box::new(a.clone()), Box::new(b.clone()), width),
        BinOp::Sub => Formula::BvSub(Box::new(a.clone()), Box::new(b.clone()), width),
        _ => unreachable!("guarded above to Add/Sub"),
    };
    let nn_a = nonneg(&a);
    let nn_b = nonneg(&b);
    let nn_r = nonneg(&result);
    let differ = |x: &Formula, y: &Formula| {
        Formula::Or(vec![
            Formula::And(vec![x.clone(), Formula::Not(Box::new(y.clone()))]),
            Formula::And(vec![Formula::Not(Box::new(x.clone())), y.clone()]),
        ])
    };
    let result_sign_flips = differ(&nn_r, &nn_a);
    let sign_relation = match op {
        BinOp::Add => Formula::Not(Box::new(differ(&nn_a, &nn_b))),
        BinOp::Sub => differ(&nn_a, &nn_b),
        _ => unreachable!("guarded above to Add/Sub"),
    };
    Some(Formula::And(vec![sign_relation, result_sign_flips]))
}

/// Reconstruct the BITVECTOR signed NEGATION overflow (failure) condition trust-vcgen
/// builds for a SIGNED >=128-bit `-x` in `v2_signed_bv_neg_overflow_formula`, for the
/// BARE operand case: `Eq(x_bv, INT_MIN)` where `x_bv` is the fresh `__trust_ovf_bv_neg_*`
/// var (role "neg") and `INT_MIN` is the `width`-bit sign-bit pattern. Byte-identical to
/// trust-vcgen's bare-case formula; the guarded / block-def case does not byte-match
/// (flip keeps trust-vcgen's formula — sound). `None` outside the bare envelope.
fn reconstruct_bv_signed_neg_overflow_body(
    locals: &[LocalDecl],
    operand: &Operand,
    width: u32,
) -> Option<Formula> {
    if width == 0 || width > 128 {
        return None;
    }
    let x = reconstruct_bv_operand_term(locals, operand, width, "neg")?;
    let int_min = if width == 128 {
        Formula::BitVec { value: i128::MIN, width }
    } else {
        Formula::BitVec { value: 1i128 << (width - 1), width }
    };
    Some(Formula::Eq(Box::new(x), Box::new(int_min)))
}

/// Reconstruct the CORE signed div/rem overflow predicate `trust_vcgen` builds in
/// `v2_build_signed_div_overflow_vc` for a signed `lhs OP rhs` (`OP` in Div/Rem):
///
/// ```text
/// And([ input_range(lhs, width, signed=true), input_range(rhs, width, signed=true),
///       Eq(lhs, INT_MIN), Eq(rhs, -1) ])
/// ```
///
/// This is the EXACT signed-overflow UB condition: `INT_MIN / -1` (and
/// `INT_MIN % -1`) is the single input pair whose mathematical result
/// (`-INT_MIN`) is unrepresentable in the signed range. SOUND BY CONSTRUCTION —
/// the conjunction is SAT iff a violating input pair exists within the operand
/// ranges, so an UNSAT formula certifies the obligation safe (a guard that rules
/// out `lhs == INT_MIN` or `rhs == -1` discharges it).
///
/// Only SIGNED operands carry this obligation: rustc emits the `Overflow(Div|Rem)`
/// assert exclusively for signed division (unsigned division cannot overflow). An
/// unsigned or out-of-envelope operand returns `None` (fail-closed). The width is
/// recovered from the non-constant operand via `safety_int_op_type` so a width-less
/// signed constant lhs (`(-128i8) / y`) does not fabricate the wrong `INT_MIN`.
fn reconstruct_signed_div_overflow_body(
    locals: &[LocalDecl],
    lhs: &Operand,
    rhs: &Operand,
) -> Option<Formula> {
    let (width, signed) = safety_int_op_type(locals, lhs, rhs)?;
    if !signed {
        return None;
    }
    let lhs_f = safety_operand_to_formula(locals, lhs)?;
    let rhs_f = safety_operand_to_formula(locals, rhs)?;
    let lhs_range = safety_input_range_constraint(&lhs_f, width, true);
    let rhs_range = safety_input_range_constraint(&rhs_f, width, true);
    let int_min = safety_type_min_formula(width, true);
    Some(Formula::And(vec![
        lhs_range,
        rhs_range,
        Formula::Eq(Box::new(lhs_f), Box::new(int_min)),
        Formula::Eq(Box::new(rhs_f), Box::new(Formula::Int(-1))),
    ]))
}

/// Reconstruct the fixed-width BITVECTOR overflow (failure) condition trust-vcgen
/// builds for an integer `lhs * rhs` (`BinOp::Mul`) in
/// `v2_unsigned_bv_overflow_formula` / `v2_signed_bv_overflow_formula`, for the
/// BARE operand case (integer constants and projection-free locals, no
/// value-preserving widening-cast operand, no conjoined dominating-guard /
/// precondition BV constraints). This is byte-identical to trust-vcgen's
/// `bv_formula` for that case — the value the Mul/BV arm of
/// `v2_build_overflow_vc_for_operands` returns BEFORE the final-pass
/// `conjoin_arg_type_ranges` wrapping (reproduced by the caller's `base` arm) and
/// BEFORE the abstract-interp param-range env (reproduced by
/// `augment_candidates_with_param_env`).
///
///   * UNSIGNED: `And([ Not(Eq(a, 0)), Not(Eq(BvUDiv(BvMul(a,b), a), b)) ])`
///     (the `a ≠ 0 ∧ bvudiv(bvmul(a,b),a) ≠ b` hardware mul-overflow check).
///   * SIGNED:   `Not(Or([ Eq(slice, 0), Eq(slice, all_ones) ]))` where
///     `slice = BvExtract(BvMul(sext(a,w), sext(b,w)), high=2w-1, low=w-1)` — the
///     standard `bvsmulo` two's-complement width-doubling expansion.
///
/// Operand encoding mirrors `v2_bv_operand_term` for the bare case (constant →
/// `BitVec`, plain local `base` → fresh `Var("__trust_ovf_bv_{role}_{base}",
/// BitVec(width))`). A value-preserving WIDENING-cast operand (`(x as u64) * …`)
/// is encoded by trust-vcgen as a zero/sign-extension of a narrower fresh var; we
/// do NOT reproduce that here, and a mul carrying conjoined dominating-guard or
/// precondition BV constraints (`v2_bv_mul_dominating_guard_constraints`) has a
/// wider live formula — in BOTH cases this bare reconstruction does not byte-match
/// the live formula, so the exact-equality gate keeps trust-vcgen's own formula
/// (fail-closed). Sound: the gate flips only on EXACT `Formula`-AST byte-equality.
///
/// `None` (fail-closed) when an operand is outside the bare envelope
/// (projected/symbolic/non-integer constant), the width is 0, or — for the signed
/// path — the width exceeds 64 (trust-vcgen declines the 256-bit i128 multiplier
/// and falls back to the Int path, so no BV formula is emitted to match).
fn reconstruct_bv_mul_overflow_body(
    locals: &[LocalDecl],
    lhs: &Operand,
    rhs: &Operand,
) -> Option<Formula> {
    let (width, signed) = safety_int_op_type(locals, lhs, rhs)?;
    if width == 0 || (signed && width > 64) {
        return None;
    }
    let a = reconstruct_bv_operand_term(locals, lhs, width, "lhs")?;
    let b = reconstruct_bv_operand_term(locals, rhs, width, "rhs")?;
    Some(bv_mul_failure_formula(a, b, width, signed))
}

/// Build trust-vcgen's fixed-width BV mul OVERFLOW (failure) condition for the
/// given operand terms `a`/`b` of mul `width`/`signed`. Byte-faithful to
/// `v2_signed_bv_overflow_formula` (signed) / `v2_unsigned_bv_overflow_formula`'s
/// Mul arm (unsigned). The operand terms are supplied by the caller (bare fresh
/// vars OR widening zero/sign-extension terms), so this shared builder serves both
/// the bare and widening reconstructions. The signed `width > 64` guard is the
/// caller's responsibility (trust-vcgen declines the 256-bit i128 multiplier).
fn bv_mul_failure_formula(a: Formula, b: Formula, width: u32, signed: bool) -> Formula {
    if signed {
        // v2_signed_bv_overflow_formula: width-doubling sign-extended product check.
        let dw = width * 2;
        let sa = Formula::BvSignExt(Box::new(a), width);
        let sb = Formula::BvSignExt(Box::new(b), width);
        let prod = Formula::BvMul(Box::new(sa), Box::new(sb), dw);
        let high = dw - 1;
        let low = width - 1;
        let slice_w = high - low + 1; // == width + 1
        let slice = Formula::BvExtract { inner: Box::new(prod), high, low };
        let zeros = Formula::BitVec { value: 0, width: slice_w };
        let all_ones = Formula::BitVec { value: (1i128 << slice_w) - 1, width: slice_w };
        let fits = Formula::Or(vec![
            Formula::Eq(Box::new(slice.clone()), Box::new(zeros)),
            Formula::Eq(Box::new(slice), Box::new(all_ones)),
        ]);
        Formula::Not(Box::new(fits))
    } else {
        // v2_unsigned_bv_overflow_formula Mul arm.
        let zero = Formula::BitVec { value: 0, width };
        let a_ne_zero = Formula::Not(Box::new(Formula::Eq(Box::new(a.clone()), Box::new(zero))));
        let prod = Formula::BvMul(Box::new(a.clone()), Box::new(b.clone()), width);
        let recovered = Formula::BvUDiv(Box::new(prod), Box::new(a), width);
        let mismatch = Formula::Not(Box::new(Formula::Eq(Box::new(recovered), Box::new(b))));
        Formula::And(vec![a_ne_zero, mismatch])
    }
}

/// Enumerate trust-vcgen's BV mul OVERFLOW formula CANDIDATES for `lhs * rhs`,
/// covering BOTH the bare and the value-preserving WIDENING-cast operand encodings.
///
/// `v2_bv_operand_term` encodes a widening-cast operand (`(x as u64) * …`) as a
/// zero/sign-extension of a narrower fresh var — but ONLY when the cast destination
/// is `index_local_stable` (unique reaching def, no alias mutation); otherwise it
/// uses the bare full-width var. Rather than port that staleness analysis (a deep
/// `index_local_stable`/`array_local_escapes` chain), we ENUMERATE both encodings
/// per operand — bare AND, when a value-preserving widening cast def exists, the
/// extension form read directly from that cast — and offer the cartesian product
/// as candidates. The flip's exact-equality gate accepts whichever trust-vcgen
/// actually emitted; the others simply do not byte-match (fail-closed). This is
/// SOUND (the gate is exact) and complete for the common widening multiply
/// regardless of staleness, without reproducing the staleness decision.
fn reconstruct_bv_mul_overflow_candidates(
    locals: &[LocalDecl],
    all_blocks: &[TrustBlock],
    lhs: &Operand,
    rhs: &Operand,
) -> Vec<Formula> {
    let Some((width, signed)) = safety_int_op_type(locals, lhs, rhs) else {
        return Vec::new();
    };
    if width == 0 || (signed && width > 64) {
        return Vec::new();
    }
    let lhs_terms = reconstruct_bv_operand_terms(locals, all_blocks, lhs, width, "lhs");
    let rhs_terms = reconstruct_bv_operand_terms(locals, all_blocks, rhs, width, "rhs");
    let mut out = Vec::with_capacity(lhs_terms.len() * rhs_terms.len());
    for a in &lhs_terms {
        for b in &rhs_terms {
            out.push(bv_mul_failure_formula(a.clone(), b.clone(), width, signed));
        }
    }
    out
}

/// Mirror `trust_vcgen::v2_bv_operand_term` for the BARE (non-widening) case: an
/// integer constant → `BitVec { value, width }` (`Uint` reinterpreted as the
/// low `width` bits, the same `as i128` trust-vcgen uses); a projection-free
/// local `base` → a FRESH `width`-bit BV var named `__trust_ovf_bv_{role}_{base}`
/// (namespaced exactly as trust-vcgen does so it never collides with the Int-sorted
/// var of the same source local). Widening-cast operands and every other shape
/// return `None` (fail-closed — see `reconstruct_bv_mul_overflow_body`).
fn reconstruct_bv_operand_term(
    locals: &[LocalDecl],
    op: &Operand,
    width: u32,
    role: &str,
) -> Option<Formula> {
    match op {
        Operand::Constant(ConstValue::Int(n)) => Some(Formula::BitVec { value: *n, width }),
        Operand::Constant(ConstValue::Uint(n, _)) => {
            Some(Formula::BitVec { value: *n as i128, width })
        }
        Operand::Copy(place) | Operand::Move(place) if place.projections.is_empty() => {
            let base = safety_place_var_name(locals, place)?;
            Some(Formula::var_owned(format!("__trust_ovf_bv_{role}_{base}"), Sort::BitVec(width)))
        }
        _ => None,
    }
}

/// A `<var> CMP <const>` comparison direction, for translating an Int dominating guard
/// onto a fresh BV mul-operand var. Mirrors `trust_vcgen::BvGuardCmp`.
#[derive(Clone, Copy, PartialEq)]
enum BvGuardCmp {
    Le,
    Lt,
    Ge,
    Gt,
    Eq,
}

/// Extract a `<var> CMP <integer-const>` fact (`name`, cmp, const), faithful port of
/// `trust_vcgen::v2_linear_var_const_fact`. Recognises `Lt/Le/Gt/Ge/Eq` of an
/// `Sort::Int` var against an integer literal (incl. the `Neg(Int(c))` shape for negative
/// bounds like `n >= -1000`), mirroring the operands either way, and `Not(inner)` by
/// inverting the comparison (an `Eq`/`!=` yields no usable bound).
fn native_linear_var_const_fact(fact: &Formula) -> Option<(String, BvGuardCmp, i128)> {
    use BvGuardCmp::{Eq, Ge, Gt, Le, Lt};
    fn int_const(f: &Formula) -> Option<i128> {
        match f {
            Formula::Int(c) => Some(*c),
            Formula::Neg(inner) => match inner.as_ref() {
                Formula::Int(c) => c.checked_neg(),
                _ => None,
            },
            _ => None,
        }
    }
    fn extract(
        a: &Formula,
        b: &Formula,
        cmp: BvGuardCmp,
        mirrored: BvGuardCmp,
    ) -> Option<(String, BvGuardCmp, i128)> {
        match (a, b) {
            (Formula::Var(name, Sort::Int), other) => {
                int_const(other).map(|c| (name.clone(), cmp, c))
            }
            (other, Formula::Var(name, Sort::Int)) => {
                int_const(other).map(|c| (name.clone(), mirrored, c))
            }
            _ => None,
        }
    }
    match fact {
        Formula::Le(a, b) => extract(a, b, Le, Ge),
        Formula::Lt(a, b) => extract(a, b, Lt, Gt),
        Formula::Ge(a, b) => extract(a, b, Ge, Le),
        Formula::Gt(a, b) => extract(a, b, Gt, Lt),
        Formula::Eq(a, b) => extract(a, b, Eq, Eq),
        Formula::Not(inner) => {
            let (name, cmp, c) = native_linear_var_const_fact(inner)?;
            let inverted = match cmp {
                Le => Gt,
                Lt => Ge,
                Ge => Lt,
                Gt => Le,
                Eq => return None,
            };
            Some((name, inverted, c))
        }
        _ => None,
    }
}

/// BV-encode one `<bv_var> CMP <const>` fact over the fresh `width`-bit BV mul-operand
/// var — faithful port of `trust_vcgen::v2_bv_guard_constraint`. EXACT-FIT ONLY: a
/// constant outside the operand type's value range is DECLINED (`None`), which is always
/// sound (a weaker violation formula can only under-prove, never mask a real overflow).
fn native_bv_guard_constraint(
    bv_name: &str,
    cmp: BvGuardCmp,
    c: i128,
    width: u32,
    signed: bool,
) -> Option<Formula> {
    if width == 0 || width > 64 {
        return None;
    }
    let (min, max) = if signed {
        (-(1i128 << (width - 1)), (1i128 << (width - 1)) - 1)
    } else if width == 64 {
        (0, u64::MAX as i128)
    } else {
        (0, (1i128 << width) - 1)
    };
    if c < min || c > max {
        return None;
    }
    let var = || Box::new(Formula::var_owned(bv_name.to_string(), Sort::BitVec(width)));
    let bvc = || Box::new(Formula::BitVec { value: c, width });
    Some(match (cmp, signed) {
        (BvGuardCmp::Le, false) => Formula::BvULe(var(), bvc(), width),
        (BvGuardCmp::Lt, false) => Formula::BvULt(var(), bvc(), width),
        (BvGuardCmp::Ge, false) => Formula::BvULe(bvc(), var(), width),
        (BvGuardCmp::Gt, false) => Formula::BvULt(bvc(), var(), width),
        (BvGuardCmp::Le, true) => Formula::BvSLe(var(), bvc(), width),
        (BvGuardCmp::Lt, true) => Formula::BvSLt(var(), bvc(), width),
        (BvGuardCmp::Ge, true) => Formula::BvSLe(bvc(), var(), width),
        (BvGuardCmp::Gt, true) => Formula::BvSLt(bvc(), var(), width),
        (BvGuardCmp::Eq, _) => Formula::Eq(var(), bvc()),
    })
}

/// Translate the SOUND dominating guards reaching the mul's block into BV constraints over
/// its fresh operand vars (`__trust_ovf_bv_{role}_{base}`) — port of
/// `v2_bv_mul_dominating_guard_constraints`, the fix for the conservative false-Failed on a
/// mul that is safe only because of a guard (`if a < 1000 && b < 1000 { a * b }`). The BV
/// mul violation uses FRESH operand vars, so the Int-lane dominating guards conjoined
/// elsewhere never constrain them; this re-emits each `operand CMP const` dominating fact
/// in BV form. SOUND: `reconstruct_sound_dominating_guards` already returns only facts that
/// hold on EVERY path to the block (so a real overflow witness satisfies them — conjoining
/// removes only infeasible cexs); a constant divisor / operand reassigned in the block is
/// excluded (the latter would be stale); out-of-range constants are declined.
fn native_bv_mul_guard_constraints(
    func: &VerifiableFunction,
    block_id: BlockId,
    lhs: &Operand,
    rhs: &Operand,
    width: u32,
    signed: bool,
) -> Vec<Formula> {
    let locals = &func.body.locals;
    let block = func.body.blocks.iter().find(|b| b.id == block_id);
    // Plain-local operands (base name, fresh BV var name); skip a constant, a projected
    // place, or an operand the block itself reassigns (stale by the time the mul runs).
    let mut targets: Vec<(String, String)> = Vec::new();
    for (op, role) in [(lhs, "lhs"), (rhs, "rhs")] {
        let (Operand::Copy(place) | Operand::Move(place)) = op else {
            continue;
        };
        if !place.projections.is_empty() {
            continue;
        }
        let assigned_in_block = block.is_some_and(|b| {
            b.stmts
                .iter()
                .any(|s| matches!(s, Statement::Assign { place: p, .. } if p.local == place.local))
        });
        if assigned_in_block {
            continue;
        }
        let Some(base) = safety_place_var_name(locals, place) else {
            continue;
        };
        targets.push((base.clone(), format!("__trust_ovf_bv_{role}_{base}")));
    }
    if targets.is_empty() {
        return Vec::new();
    }
    let mut constraints = Vec::new();
    for fact in reconstruct_sound_dominating_guards(func, block_id) {
        let Some((name, cmp, c)) = native_linear_var_const_fact(&fact) else {
            continue;
        };
        for (base, bv_name) in &targets {
            if *base == name
                && let Some(constraint) = native_bv_guard_constraint(bv_name, cmp, c, width, signed)
            {
                constraints.push(constraint);
            }
        }
    }
    constraints
}

/// Enumerate the candidate BV operand terms for `op` (the bare full-width fresh
/// var AND, when a value-preserving widening cast into `width` exists, the
/// zero/sign-extension of a narrower fresh var). Constants have a single encoding.
/// See `reconstruct_bv_mul_overflow_candidates` for why both forms are offered.
fn reconstruct_bv_operand_terms(
    locals: &[LocalDecl],
    all_blocks: &[TrustBlock],
    op: &Operand,
    width: u32,
    role: &str,
) -> Vec<Formula> {
    match op {
        Operand::Constant(ConstValue::Int(n)) => vec![Formula::BitVec { value: *n, width }],
        Operand::Constant(ConstValue::Uint(n, _)) => {
            vec![Formula::BitVec { value: *n as i128, width }]
        }
        Operand::Copy(place) | Operand::Move(place) if place.projections.is_empty() => {
            let Some(base) = safety_place_var_name(locals, place) else {
                return Vec::new();
            };
            let bare =
                Formula::var_owned(format!("__trust_ovf_bv_{role}_{base}"), Sort::BitVec(width));
            // Offer the widening extension form FIRST (trust-vcgen prefers it when
            // the cast destination is stable), bare second.
            if let Some((sw, src_signed)) =
                reconstruct_bv_widening_source(locals, all_blocks, op, width)
            {
                let narrow =
                    Formula::var_owned(format!("__trust_ovf_bv_{role}_{base}"), Sort::BitVec(sw));
                let added = width - sw;
                let widened = if src_signed {
                    Formula::BvSignExt(Box::new(narrow), added)
                } else {
                    Formula::BvZeroExt(Box::new(narrow), added)
                };
                vec![widened, bare]
            } else {
                vec![bare]
            }
        }
        _ => Vec::new(),
    }
}

/// Mirror `trust_vcgen::v2_widening_bv_source`'s cast scan (WITHOUT the
/// `index_local_stable` staleness gate — see `reconstruct_bv_mul_overflow_candidates`
/// for why staleness is handled by enumeration instead). If `op` is a bare local
/// whose UNIQUE reaching cast def(s) all value-preservingly widen a narrower
/// integer into `width` bits, return the `(source_width, source_signed)` of the
/// pre-cast value. Strict value-preserving widening only (`width > sw`, never
/// signed→unsigned), exactly as `widening_cast_result_range`/#52 gates it.
fn reconstruct_bv_widening_source(
    locals: &[LocalDecl],
    all_blocks: &[TrustBlock],
    op: &Operand,
    width: u32,
) -> Option<(u32, bool)> {
    let (Operand::Copy(place) | Operand::Move(place)) = op else {
        return None;
    };
    if !place.projections.is_empty() {
        return None;
    }
    let local = place.local;
    let mut found: Option<(u32, bool)> = None;
    for block in all_blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place: dest, rvalue: Rvalue::Cast(inner, to_ty), .. } = stmt
            else {
                continue;
            };
            if dest.local != local || !dest.projections.is_empty() {
                continue;
            }
            let Ty::Int { width: dw, signed: ds } = to_ty else {
                return None;
            };
            if *dw != width {
                return None;
            }
            let (sw, ss) = operand_int_ty(locals, inner)?;
            // Strict, value-preserving widening only (mirror #52 / vcgen).
            if *dw <= sw || (ss && !*ds) {
                return None;
            }
            let cand = (sw, ss);
            match found {
                Some(prev) if prev != cand => return None,
                _ => found = Some(cand),
            }
        }
    }
    found
}

/// The `(width, signed)` of a single integer operand: a projection-free integer
/// local → its declared `(width, signed)`. Other shapes return `None`. Used by the
/// widening-cast scan to recover the pre-cast source type.
fn operand_int_ty(locals: &[LocalDecl], op: &Operand) -> Option<(u32, bool)> {
    let place = match op {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
        _ => return None,
    };
    let ty = &locals.iter().find(|d| d.index == place.local)?.ty;
    Some((ty.int_width()?, ty.is_signed()))
}

/// Reconstruct the CORE divisor-is-zero predicate `trust_vcgen` builds for an
/// integer `Div`/`Rem` whose divisor is a non-constant local, from
/// `v2_divisor_is_zero_formula`: `Eq(Var(divisor, Int), Int(0))`.
///
/// A constant divisor is handled by trust-vcgen as `Bool(true/false)` and the
/// emission is gated by `v2_divisor_is_nonzero_constant`, so we only reconstruct
/// the variable-divisor case (the one that yields a real proof obligation). A
/// projected/symbolic/float divisor is outside the envelope → `None`
/// (fail-closed). Float divisors take a different (bitvector-magnitude) encoding
/// in trust-vcgen, so the caller must restrict this to integer divisors.
fn reconstruct_divisor_is_zero(locals: &[LocalDecl], divisor: &Operand) -> Option<Formula> {
    let place = match divisor {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
        _ => return None,
    };
    let decl = locals.iter().find(|d| d.index == place.local)?;
    // Integer divisor only — float divisors use the BV-magnitude encoding.
    decl.ty.int_width()?;
    let name = safety_place_var_name(locals, place)?;
    Some(Formula::Eq(Box::new(Formula::var(&name, Sort::Int)), Box::new(Formula::Int(0))))
}

/// Reconstruct the historical cast-losslessness predicate for compatibility
/// with a legacy/external `VcKind::CastOverflow`.
///
/// ```text
/// And([ input_range_constraint(value, from_width, from_signed),
///       Or([ Lt(value, to_min), Gt(value, to_max) ]) ])
/// ```
///
/// where `(to_min, to_max)` are the TARGET integer type's bounds and
/// `from_width`/`from_signed` are the SOURCE integer type's. Current trust-vcgen
/// deliberately emits no obligation for a defined integer `as` conversion; this
/// helper is never an obligation mint. It only lets the verdict flip preserve an
/// already-present historical VC by exact formula match.
///
/// `None` (fail-closed) when the cast is NOT a narrowing integer overflow cast
/// (`legacy_cast_needs_range_check` recognizes that historical predicate),
/// the operand is outside the faithful envelope (projected/symbolic/non-direct), or
/// the source/target bounds are not recoverable — in every such case the flip keeps
/// trust-vcgen's own formula.
fn reconstruct_cast_overflow_body(
    locals: &[LocalDecl],
    operand: &Operand,
    from_ty: &Ty,
    to_ty: &Ty,
) -> Option<Formula> {
    if !legacy_cast_needs_range_check(from_ty, to_ty) {
        return None;
    }
    let (to_min, to_max) = cast_integer_bounds(to_ty)?;
    let from_width = from_ty.int_width()?;
    let value = safety_operand_to_formula(locals, operand)?;
    Some(Formula::And(vec![
        safety_input_range_constraint(&value, from_width, from_ty.is_signed()),
        Formula::Or(vec![
            Formula::Lt(Box::new(value.clone()), Box::new(Formula::Int(to_min))),
            Formula::Gt(Box::new(value), Box::new(Formula::Int(to_max))),
        ]),
    ]))
}

/// Find the FIRST `Rvalue::BinaryOp(op, lhs, rhs)` OR
/// `Rvalue::CheckedBinaryOp(op, lhs, rhs)` in `block`'s statements whose op
/// matches `want`, returning its operands. BYTE-FOR-BYTE mirror of trust-vcgen's
/// `v2_find_block_binary_operands` (`generate.rs`), which matches BOTH rvalue
/// shapes (`Rvalue::BinaryOp(_, a, b) | Rvalue::CheckedBinaryOp(_, a, b)`).
///
/// Matching `CheckedBinaryOp` is REQUIRED for the canonical rustc overflow shape
/// `_t = CheckedAdd(a, b); Assert { Overflow(Add) } on _t.1` — there the operands
/// live on a `CheckedBinaryOp` statement, not a plain `BinaryOp`. The prior
/// version matched only `BinaryOp`, so on real MIR (which uses `CheckedBinaryOp`)
/// the overflow operand recovery failed, no spine candidate formula was
/// reconstructed, and the verdict-flip kept trust-vcgen's formula instead of
/// flipping to the byte-equal spine reconstruction. trust-vcgen recovers the SAME
/// operands from EITHER shape via its unified finder, so mirroring that here is
/// the faithful reproduction (the flip's byte-equality gate is the ultimate
/// guard regardless).
fn find_block_binary_operands(block: &TrustBlock, want: BinOp) -> Option<(&Operand, &Operand)> {
    for stmt in &block.stmts {
        if let Statement::Assign {
            rvalue: Rvalue::BinaryOp(op, lhs, rhs) | Rvalue::CheckedBinaryOp(op, lhs, rhs),
            ..
        } = stmt
            && *op == want
        {
            return Some((lhs, rhs));
        }
    }
    None
}

/// Round-4 / Part 2: like [`find_block_binary_operands`], but for the literal-shift
/// discharge gate — ALSO returns the assignment DESTINATION place and whether the
/// rvalue was a `CheckedBinaryOp` (tuple `(value, bool)` dest). The destination is
/// where trust-vcgen recovers the shifted-value width for a WIDTH-LESS constant
/// shiftee (`1i128 << 23`, whose `ConstValue::Int` carries no width), and the
/// checked flag says which tuple field holds the value type. READ-ONLY MIR scan:
/// the `Shl`/`Shr` rvalue lowering itself is never touched.
fn find_block_shift_assign<'a>(
    block: &'a TrustBlock,
    want: BinOp,
) -> Option<(&'a Place, bool, &'a Operand, &'a Operand)> {
    block.stmts.iter().find_map(|stmt| match stmt {
        Statement::Assign { place, rvalue: Rvalue::BinaryOp(op, lhs, rhs), .. } if *op == want => {
            Some((place, false, lhs, rhs))
        }
        Statement::Assign { place, rvalue: Rvalue::CheckedBinaryOp(op, lhs, rhs), .. }
            if *op == want =>
        {
            Some((place, true, lhs, rhs))
        }
        _ => None,
    })
}

/// The operand `x` of the first `_d = Neg(x)` (`UnOp::Neg`) statement in `block`.
/// Mirrors `trust_vcgen::v2_find_target_neg_operand` — the negation-overflow assert
/// passes its TARGET block (where `-x` runs), so this finds the negated operand to
/// reconstruct the BV neg-overflow VC for signed >=128-bit.
fn find_block_neg_operand(block: &TrustBlock) -> Option<&Operand> {
    block.stmts.iter().find_map(|stmt| match stmt {
        Statement::Assign { rvalue: Rvalue::UnaryOp(UnOp::Neg, op), .. } => Some(op),
        _ => None,
    })
}

/// The integer type `(width, signed)` of a single direct (projection-free) local
/// operand, looked up in `locals`. `None` for a constant, a projected place, or a
/// non-integer local — exactly the shapes outside the faithful bounds/shift
/// envelope, where the caller fails closed.
fn safety_operand_int_ty(locals: &[LocalDecl], op: &Operand) -> Option<(u32, bool)> {
    let place = match op {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
        _ => return None,
    };
    let ty = &locals.iter().find(|d| d.index == place.local)?.ty;
    Some((ty.int_width()?, ty.is_signed()))
}

/// Like [`safety_operand_int_ty`], but ALSO recovers the integer `(width, signed)`
/// of a CONSTANT operand from its carried type — mirroring `trust_vcgen::operand_ty`
/// (crates/trust-vcgen/src/lib.rs:589-601), whose constant arms accept these shapes.
///
/// The shift-overflow reconstruction MUST use this at the amount-type gate: for a
/// constant shift amount (`k >> R`, where the named const `R` was const-evaluated to
/// `Uint(47, 32)`), `safety_operand_int_ty` fails closed on the constant, so the
/// trust-ir-bridge mirror declined a VC that trust-vcgen builds normally — leaving the
/// obligation with no stamped formula and stranding it as `UnsupportedMir` in the
/// trust-mc lane. Accepting the const-carried width/sign here makes the bridge stamp
/// the SAME `And([shift_range, invalid_shift])` trust-vcgen already emits.
///
/// SOUNDNESS: monotone / fail-safe. It only ENABLES the exact violation formula
/// trust-vcgen trusts, using the same const-carried type; a genuinely unknown-valued
/// const (`OpaqueScalar` from a const-generic / unresolved associated const) keeps its
/// unconstrained symbol, so an out-of-range or unknown amount stays satisfiable
/// (Unknown/Failed) — never falsely proved.
fn safety_operand_int_ty_or_const(locals: &[LocalDecl], op: &Operand) -> Option<(u32, bool)> {
    if let Some(ws) = safety_operand_int_ty(locals, op) {
        return Some(ws);
    }
    match op {
        Operand::Constant(ConstValue::Uint(_, w)) => Some((*w, false)),
        Operand::Constant(ConstValue::OpaqueScalar { width, signed }) => Some((*width, *signed)),
        // Trust: piece #7a — a const-generic PARAM carries its declared int width.
        // A BOOL const-generic (in-band `width==1 && !signed`) has no integer
        // width — None keeps the arithmetic-width machinery off it.
        Operand::Constant(ConstValue::ConstParam { width: 1, signed: false, .. }) => None,
        Operand::Constant(ConstValue::ConstParam { width, signed, .. }) => Some((*width, *signed)),
        Operand::Constant(ConstValue::Int(v)) => {
            let width =
                if (i128::from(i64::MIN)..=i128::from(i64::MAX)).contains(v) { 64 } else { 128 };
            Some((width, true))
        }
        _ => None,
    }
}

/// Find the FIRST statement in `block` that assigns the projection-free local
/// `cond_local` from a `Rvalue::BinaryOp(op, lhs, rhs)`, returning `(op, lhs, rhs)`.
/// Mirrors `trust_vcgen::v2_find_condition_binary_operands`, the helper the bounds
/// VC uses to recover the `idx < len` comparison that DEFINES an assert's boolean
/// condition local (the direct-comparison bounds path).
fn find_condition_binary_operands<'a>(
    block: &'a TrustBlock,
    cond: &Operand,
) -> Option<(BinOp, &'a Operand, &'a Operand)> {
    let cond_local = match cond {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p.local,
        _ => return None,
    };
    block.stmts.iter().find_map(|stmt| {
        let Statement::Assign { place, rvalue: Rvalue::BinaryOp(op, lhs, rhs), .. } = stmt else {
            return None;
        };
        if place.local != cond_local || !place.projections.is_empty() {
            return None;
        }
        Some((*op, lhs, rhs))
    })
}

/// Reconstruct the CORE bounds-violation predicate `trust_vcgen` builds on its
/// DIRECT-COMPARISON path (`v2_build_bounds_assert_vc`), for a `BoundsCheck`
/// assert whose condition local is defined by `idx < len` in the SOURCE block:
///
/// ```text
/// unsigned idx:  Ge(idx, len)
/// signed   idx:  Or([ Lt(idx, 0), Ge(idx, len) ])
/// ```
///
/// This is byte-identical to the INNERMOST violation subterm of trust-vcgen's
/// emitted bounds formula. trust-vcgen wraps it in the block definition
/// `cond == (idx < len)` (kept because it shares `idx`/`len` with the violation),
/// but that conjunct only BINDS the fresh boolean `cond` (which appears nowhere
/// else in the violation), so it cannot change the satisfiability of the violation
/// over `idx`/`len`: `∃cond. (cond == (idx<len)) ∧ violation(idx,len)` is satisfiable
/// iff `violation(idx,len)` is — identical models over the real variables,
/// identical verdict. So we stamp the violation core (the same equivalence
/// argument the overflow path uses for its idempotent arg-range wrappers).
///
/// `None` (fail-closed) when: the condition is not defined by a `Lt` comparison
/// (the abstract-flag shape — `array_index_bounds` — where vcgen instead emits a
/// flag-failure formula with no operand-level meaning), or either comparison
/// operand is outside the faithful envelope (projected/symbolic/non-integer). The
/// signedness is read from the index (`lhs`) operand's type, exactly as
/// `v2_build_bounds_assert_vc` does (`operand_ty(lhs).is_signed()`).
fn reconstruct_bounds_violation(
    locals: &[LocalDecl],
    block: &TrustBlock,
    cond: &Operand,
) -> SafetyPredicate {
    let (op, lhs, rhs) = match find_condition_binary_operands(block, cond) {
        Some(found) => found,
        // ABSTRACT-FLAG shape (`array_index_bounds`): the cond is a plain boolean
        // with no defining `idx < len` comparison. trust-vcgen emits a flag-failure
        // formula here with no operand-level meaning, so there is nothing faithful
        // to reconstruct — fail closed with the audit marker (the check is never
        // dropped; only its solvable formula is absent).
        None => {
            return SafetyPredicate::NotReconstructed(
                "bounds condition is an abstract flag (no defining `idx < len` comparison) — \
                 trust-vcgen emits only a flag-failure formula here; declined"
                    .into(),
            );
        }
    };
    if op != BinOp::Lt {
        // Only the `idx < len` direct-comparison shape is faithful; any other
        // comparison defining the cond is not the trust-vcgen bounds shape.
        return SafetyPredicate::NotReconstructed(format!(
            "bounds condition defined by {op:?}, not the `idx < len` comparison vcgen recovers"
        ));
    }
    let lhs_f = match safety_operand_to_formula(locals, lhs) {
        Some(f) => f,
        None => {
            return SafetyPredicate::NotReconstructed(
                "bounds index operand outside faithful envelope (projected/symbolic/non-direct)"
                    .into(),
            );
        }
    };
    let rhs_f = match safety_operand_to_formula(locals, rhs) {
        Some(f) => f,
        None => {
            return SafetyPredicate::NotReconstructed(
                "bounds length operand outside faithful envelope (projected/symbolic/non-direct)"
                    .into(),
            );
        }
    };
    // Signedness from the index operand's declared type, matching trust-vcgen's
    // `operand_ty(lhs).is_signed()`. A width-less/constant index (no integer type)
    // is treated as unsigned only when it is genuinely a direct integer local;
    // otherwise fail closed.
    let signed = match safety_operand_int_ty(locals, lhs) {
        Some((_, signed)) => signed,
        // Index is a constant or has no integer type: trust-vcgen's
        // `operand_ty(...).is_some_and(Ty::is_signed)` yields `false` (unsigned
        // branch) for a `None`/non-signed type, so mirror that (unsigned violation).
        None => false,
    };
    let violation = if signed {
        Formula::Or(vec![
            Formula::Lt(Box::new(lhs_f.clone()), Box::new(Formula::Int(0))),
            Formula::Ge(Box::new(lhs_f), Box::new(rhs_f)),
        ])
    } else {
        Formula::Ge(Box::new(lhs_f), Box::new(rhs_f))
    };
    SafetyPredicate::Reconstructed(violation)
}

/// Reconstruct the CORE shift-overflow predicate `trust_vcgen` builds for an
/// `Overflow(Shl|Shr)` assert (`v2_build_shift_overflow_vc`), recovering the
/// `value << amount` operands from the SOURCE block first then the TARGET block
/// (exactly where `v2_build_assert_overflow_vc` looks), and building:
///
/// ```text
/// And([ shift_range(amount), invalid_shift(amount) ])
///   shift_range:  input_range_constraint(amount, amount_width, amount_signed)
///   invalid_shift (unsigned amount):  Ge(amount, value_bitwidth)
///   invalid_shift (signed   amount):  Or([ Lt(amount, 0), Ge(amount, value_bitwidth) ])
/// ```
///
/// `value_bitwidth` is the SHIFTED VALUE's width (the result type). This is
/// byte-identical to the INNERMOST `And([shift_range, invalid_shift])` subterm of
/// trust-vcgen's emitted formula; trust-vcgen additionally conjoins the block
/// definition `_result == <bvshl …>` (because the shifted result local is
/// defined in the same block), but that conjunct only BINDS the fresh result var
/// `_result`, which never appears in `And([shift_range, invalid_shift])` (a
/// formula over the shift AMOUNT alone) — so it cannot change the violation's
/// satisfiability over `amount`. Identical models over the real variable,
/// identical verdict (the same fresh-var equivalence the bounds/overflow paths
/// use).
///
/// `None`/`NotReconstructed` (fail-closed) when: no `Shl`/`Shr` op is found, the
/// shifted value's width cannot be recovered (e.g. a width-less constant shifted
/// value, whose width trust-vcgen recovers from the assignment DESTINATION — a
/// shape we conservatively decline), or the amount operand is outside the faithful
/// envelope.
fn reconstruct_shift_violation(
    locals: &[LocalDecl],
    all_blocks: &[TrustBlock],
    source_block: BlockId,
    target: BlockId,
    op: BinOp,
) -> SafetyPredicate {
    let block_by_id = |id: BlockId| all_blocks.iter().find(|b| b.id == id);
    let operands = block_by_id(source_block)
        .and_then(|b| find_block_binary_operands(b, op))
        .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, op)));
    let (value, amount) = match operands {
        Some(pair) => pair,
        None => {
            return SafetyPredicate::NotReconstructed(format!(
                "no {op:?} binary op found in source/target block for shift-overflow assert"
            ));
        }
    };
    // The shifted-VALUE width drives `amount >= width`. We require a direct
    // integer local value (so the width is unambiguous) — a width-less constant
    // shifted value (`1i32 << n`) makes trust-vcgen recover the width from the
    // assignment destination, a shape we decline rather than risk a wrong width.
    let value_width = match safety_operand_int_ty(locals, value) {
        Some((w, _)) => w,
        None => {
            return SafetyPredicate::NotReconstructed(
                "shifted-value width not directly recoverable (constant/projected/non-integer); \
                 trust-vcgen reads it from the assignment destination — declined"
                    .into(),
            );
        }
    };
    let amount_f = match safety_operand_to_formula(locals, amount) {
        Some(f) => f,
        None => {
            return SafetyPredicate::NotReconstructed(
                "shift amount operand outside faithful envelope (projected/symbolic/non-direct)"
                    .into(),
            );
        }
    };
    // trust-vcgen's shift-range conjunct: `input_range_constraint(amount, …)` when
    // the amount has an integer width, else `Bool(true)`. A direct integer local
    // amount always has a width here.
    // Use the const-tolerant variant: a constant shift amount (`k >> R`, R a named
    // const evaluated to `Uint(47, 32)`) carries its own width/sign, which trust-vcgen
    // recovers via `operand_ty` — declining it here diverges from trust-vcgen and drops
    // the VC to `UnsupportedMir` in the trust-mc lane. (`safety_operand_int_ty` itself is
    // left unchanged; its None-for-constant behavior is relied on by the bounds path.)
    let (amount_width, amount_signed) = match safety_operand_int_ty_or_const(locals, amount) {
        Some(ws) => ws,
        None => {
            return SafetyPredicate::NotReconstructed(
                "shift amount has no integer type (outside faithful envelope)".into(),
            );
        }
    };
    let shift_range = safety_input_range_constraint(&amount_f, amount_width, amount_signed);
    let bit_width = i128::from(value_width);
    let invalid_shift = if amount_signed {
        Formula::Or(vec![
            Formula::Lt(Box::new(amount_f.clone()), Box::new(Formula::Int(0))),
            Formula::Ge(Box::new(amount_f), Box::new(Formula::Int(bit_width))),
        ])
    } else {
        Formula::Ge(Box::new(amount_f), Box::new(Formula::Int(bit_width)))
    };
    SafetyPredicate::Reconstructed(Formula::And(vec![shift_range, invalid_shift]))
}

/// Reconstruct the core L0 safety predicate for a `Terminator::Assert`, mirroring
/// the operand recovery + formula construction `trust_vcgen` performs for the
/// matching `AssertMessage`. Returns `None` for assert messages that carry no
/// reconstructable arithmetic/bounds core (null/misaligned/custom/…), in which
/// case the obligation keeps source metadata only (unchanged behavior).
///
/// * `Overflow(Add|Sub)` — recover the binop operands from the assert's SOURCE
///   block (where the checked op was computed) or its TARGET block (the
///   success edge), the two places `v2_build_assert_overflow_vc` searches, then
///   build the overflow body. Mul declines (BV path).
/// * `Overflow(Shl|Shr)` — recover the `value << amount` operands and build the
///   shift-range violation `And([range(amount), invalid_shift(amount)])`,
///   mirroring `v2_build_shift_overflow_vc`.
/// * `DivisionByZero` / `RemainderByZero` — recover the `Div`/`Rem` divisor from
///   the TARGET block (the division runs after the guard passes) and build
///   `divisor == 0`.
/// * `BoundsCheck` — on the DIRECT-COMPARISON shape (the assert's condition local
///   is defined by `idx < len` in the source block), build the bounds violation
///   `Ge(idx, len)` (unsigned) / `Or(Lt(idx,0), Ge(idx,len))` (signed), mirroring
///   `v2_build_bounds_assert_vc`. The abstract-flag shape declines.
///
/// `cond` is the assert's boolean condition operand, needed to find its defining
/// `idx < len` comparison for the bounds path.
///
/// Returns a [`SafetyPredicate`]: `Reconstructed` on success, `NotReconstructed`
/// when the message IS a reconstructable class but its operands were outside the
/// faithful envelope (so the obligation records a fail-closed audit marker), or
/// `None` for non-arithmetic messages (no predicate expected at all).
fn reconstruct_assert_safety_predicate(
    locals: &[LocalDecl],
    all_blocks: &[TrustBlock],
    source_block: BlockId,
    target: BlockId,
    cond: &Operand,
    msg: &AssertMessage,
) -> Option<SafetyPredicate> {
    let block_by_id = |id: BlockId| all_blocks.iter().find(|b| b.id == id);
    match msg {
        AssertMessage::Overflow(op @ (BinOp::Add | BinOp::Sub)) => {
            // Recover operands from the source block first (the canonical
            // `_r = a OP b; assert(!overflow)` shape), then the target block.
            let operands = block_by_id(source_block)
                .and_then(|b| find_block_binary_operands(b, *op))
                .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, *op)));
            Some(match operands {
                Some((lhs, rhs)) => match reconstruct_overflow_body(locals, *op, lhs, rhs) {
                    Some(f) => SafetyPredicate::Reconstructed(f),
                    None => SafetyPredicate::NotReconstructed(format!(
                        "overflow operands outside faithful envelope for {op:?}"
                    )),
                },
                None => SafetyPredicate::NotReconstructed(format!(
                    "no {op:?} binary op found in source/target block for overflow assert"
                )),
            })
        }
        // Shift overflow: recover the `value << amount` operands (source then
        // target block, as `v2_build_assert_overflow_vc` does) and build the
        // shift-range violation, mirroring `v2_build_shift_overflow_vc`.
        AssertMessage::Overflow(op @ (BinOp::Shl | BinOp::Shr)) => {
            Some(reconstruct_shift_violation(locals, all_blocks, source_block, target, *op))
        }
        // Mul overflow uses the fixed-width BITVECTOR encoding in trust-vcgen
        // (`v2_signed/unsigned_bv_overflow_formula`, fresh BV vars). For the BARE
        // operand case (integer constants / projection-free locals, no widening
        // cast, no conjoined dominating-guard / precondition constraints) we now
        // reconstruct that BV failure condition byte-for-byte via
        // `reconstruct_bv_mul_overflow_body`. Operands are recovered the same way
        // as Add/Sub (source block — the canonical `_t = CheckedMul(a,b)` shape —
        // then target). The widening/guarded/wide-signed cases return `None` and
        // stay fail-closed (the byte-equality gate keeps trust-vcgen's formula).
        AssertMessage::Overflow(op @ BinOp::Mul) => {
            let operands = block_by_id(source_block)
                .and_then(|b| find_block_binary_operands(b, *op))
                .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, *op)));
            Some(match operands {
                Some((lhs, rhs)) => match reconstruct_bv_mul_overflow_body(locals, lhs, rhs) {
                    Some(f) => SafetyPredicate::Reconstructed(f),
                    None => SafetyPredicate::NotReconstructed(
                        "mul overflow operands outside the bare BV envelope \
                         (widening cast / guarded / wide-signed) — declined"
                            .into(),
                    ),
                },
                None => SafetyPredicate::NotReconstructed(
                    "no Mul binary op found in source/target block for overflow assert".into(),
                ),
            })
        }
        // Div/Rem SIGNED-overflow (`INT_MIN / -1`, `INT_MIN % -1`): the exact UB
        // condition `And([Eq(lhs, INT_MIN), Eq(rhs, -1)])` (range-bounded),
        // reconstructed on the SCALAR `Sort::Int` path via
        // `reconstruct_signed_div_overflow_body` — sound by construction (the
        // formula is SAT iff a violating input exists, so UNSAT ⇒ safe). Operands
        // recovered from the source block (the `_r = a OP b` shape) then the target
        // block, exactly as Add/Sub. (This is a pure-int linear formula — no
        // bitvector encoding needed for the single-point INT_MIN/-1 violation.)
        AssertMessage::Overflow(op @ (BinOp::Div | BinOp::Rem)) => {
            let operands = block_by_id(source_block)
                .and_then(|b| find_block_binary_operands(b, *op))
                .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, *op)));
            Some(match operands {
                Some((lhs, rhs)) => match reconstruct_signed_div_overflow_body(locals, lhs, rhs) {
                    Some(f) => SafetyPredicate::Reconstructed(f),
                    None => SafetyPredicate::NotReconstructed(format!(
                        "div/rem overflow operands outside the signed scalar envelope for {op:?}"
                    )),
                },
                None => SafetyPredicate::NotReconstructed(format!(
                    "no {op:?} binary op found in source/target block for div/rem overflow assert"
                )),
            })
        }
        // Defensive: every overflow op (Add/Sub/Mul/Shl/Shr/Div/Rem) is handled
        // above, so no `Overflow(_)` reaches here — fail closed if one ever does.
        AssertMessage::Overflow(other) => Some(SafetyPredicate::NotReconstructed(format!(
            "unhandled overflow op {other:?} — declined"
        ))),
        // Negation overflow ASSERT path: trust-vcgen's `v2_build_assert_negation_vc`
        // builds `v2_formula_with_block_defs(block, v2_assert_failure_formula(cond,
        // expected))`. For the canonical rustc shape
        //   `_c = (a == MIN); Assert { OverflowNeg } on _c`  (expected = false)
        // `v2_assert_failure_formula` returns `operand_to_formula(cond)` = the bare
        // cond var `Var(cond_name, Bool)`, and the block-def layer surfaces the cond's
        // defining comparison `Eq(cond_name, Eq(a, MIN))` (kept, since `cond_name` is
        // referenced) — so the emitted formula is `And([ Eq(cond_name, Eq(a, MIN)),
        // cond_name ])`. The CORE (innermost violation `body`) is therefore the bare
        // cond var; the cond binding is reconstructed in
        // `reconstruct_full_safety_formula_candidates` (the same self-contained
        // `Eq`-defining-comparison wrapper the shift class uses). Operand recovery is
        // fully deterministic from the function — this is NOT the abstract-flag
        // (const-false) shape; the cond is a real `a == MIN` comparison local. Fail
        // closed only when the cond is not a projection-free local (no recoverable
        // var name).
        AssertMessage::OverflowNeg => {
            // signed-128 neg → BV: trust-vcgen emits `Eq(x_bv, INT_MIN)` directly on the
            // negated operand (the native LIA lane cannot represent INT_MIN = -2^127).
            // Mirror that for the BARE operand case; the negated operand is the `-x` in
            // the TARGET block (`v2_find_target_neg_operand`). The guarded/block-def case
            // (signed_min) does not byte-match → flip keeps trust-vcgen's formula (sound).
            let neg_operand = block_by_id(target).and_then(find_block_neg_operand);
            if let Some(neg_op) = neg_operand
                && let Some((width, true)) = operand_int_ty(locals, neg_op)
                && width >= 128
                && let Some(f) = reconstruct_bv_signed_neg_overflow_body(locals, neg_op, width)
            {
                return Some(SafetyPredicate::Reconstructed(f));
            }
            Some(match cond {
                Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => {
                    match safety_place_var_name(locals, p) {
                        Some(name) => {
                            SafetyPredicate::Reconstructed(Formula::var(&name, Sort::Bool))
                        }
                        None => SafetyPredicate::NotReconstructed(
                            "negation-overflow cond local has no recoverable var name".into(),
                        ),
                    }
                }
                _ => SafetyPredicate::NotReconstructed(
                    "negation-overflow cond is not a projection-free boolean local — declined"
                        .into(),
                ),
            })
        }
        AssertMessage::DivisionByZero | AssertMessage::RemainderByZero => {
            let want =
                if matches!(msg, AssertMessage::DivisionByZero) { BinOp::Div } else { BinOp::Rem };
            // The division/remainder runs on the success edge (target block).
            let divisor = block_by_id(target)
                .and_then(|b| find_block_binary_operands(b, want))
                .map(|(_, divisor)| divisor)
                // Fall back to the source block (some shapes compute it there).
                .or_else(|| {
                    block_by_id(source_block)
                        .and_then(|b| find_block_binary_operands(b, want))
                        .map(|(_, divisor)| divisor)
                });
            Some(match divisor {
                Some(divisor) => match reconstruct_divisor_is_zero(locals, divisor) {
                    Some(f) => SafetyPredicate::Reconstructed(f),
                    None => SafetyPredicate::NotReconstructed(
                        "div/rem divisor outside faithful envelope (projected/symbolic/float)"
                            .into(),
                    ),
                },
                None => SafetyPredicate::NotReconstructed(
                    "no Div/Rem op found in target/source block for div-by-zero assert".into(),
                ),
            })
        }
        // Bounds checks: the trust-vcgen bounds VC has two shapes.
        //   * DIRECT-COMPARISON (`v2_build_bounds_assert_vc`'s `Lt` branch): the
        //     assert's condition local is DEFINED by `idx < len` in the source
        //     block, and the violation is `Ge(idx, len)` (unsigned) /
        //     `Or(Lt(idx,0), Ge(idx,len))` (signed). We reconstruct exactly this,
        //     reading the comparison operands from the cond's defining statement.
        //   * ABSTRACT-FLAG (`array_index_bounds`): the cond is a plain boolean
        //     with no defining `Lt`, so trust-vcgen emits a flag-failure formula
        //     with no operand-level meaning — `reconstruct_bounds_violation`
        //     returns `NotReconstructed` and we fail closed (never a guessed flag
        //     predicate). The check is never dropped either way.
        AssertMessage::BoundsCheck => {
            let block = block_by_id(source_block)?;
            Some(reconstruct_bounds_violation(locals, block, cond))
        }
        // Non-arithmetic / non-bounds panic-class messages carry no
        // reconstructable safety predicate — no formula expected.
        _ => None,
    }
}

// ===========================================================================
// trust-ir-spine VERDICT FLIP: FULL-formula reconstruction (byte-equal target)
//
// The verdict flip (`crate::flip`) needs the spine to reconstruct trust-vcgen's
// FULL dispatched formula, not just the violation CORE the obligation stamp
// carries — because the solver pipeline is verdict-identical only on the
// byte-EQUAL formula, not merely an equisatisfiable subterm (this was the prior
// attempt's regression). The functions below extend the per-class core
// reconstruction with the OUTER wrappers trust-vcgen applies that are
// DETERMINISTIC FROM THE FUNCTION ALONE (no private block-dataflow helper):
//
//   * overflow Add/Sub: `conjoin_arg_type_ranges(body)` — an idempotent
//     re-conjunction of every integer PARAMETER's type range, derived purely
//     from `func.body.locals[1..=arg_count]` (NOT from block defs). This is the
//     ONE wrapper that makes the overflow stamp differ from the dispatched
//     formula in the no-block-def case, and it is faithfully reproducible.
//   * bounds / shift / div-rem: trust-vcgen wraps the core ONLY in
//     `v2_formula_with_block_defs[_…]` (a fresh-var-binding block-def layer) — no
//     arg-range/slice-len wrapper. In the no-block-def case that layer is the
//     identity, so the core IS the full formula. We therefore return the core
//     unchanged for these classes.
//
// We deliberately do NOT reproduce `v2_formula_with_block_defs` /
// `conjoin_slice_len_bounds` (private helpers; reproducing block dataflow by hand
// is the documented soundness hazard). When trust-vcgen's actual formula DOES
// carry those conjuncts, our reconstruction will simply NOT be byte-equal, the
// flip's runtime SMT-LIB equality gate fails, and the VC keeps trust-vcgen's
// formula (fail-closed — never a regression). So this reconstruction is a
// *best-effort byte-equal candidate*: when it matches, the formula is genuinely
// spine-sourced; when it doesn't, the flip falls back, soundly.
// ===========================================================================

/// Reproduce `trust_vcgen::generate::conjoin_arg_type_ranges` byte-for-byte: for
/// every integer PARAMETER (`func.body.locals` with `1 <= index <= arg_count`),
/// conjoin its `input_range_constraint`, pushing the bounds in local order then
/// the formula last — exactly `And([range(p1), …, range(pk), formula])`. A
/// parameter name is `decl.name` or `_<index>` when unnamed, matching trust-vcgen.
/// Returns `formula` unchanged when there are no integer parameters.
fn conjoin_arg_type_ranges_full(func: &VerifiableFunction, formula: Formula) -> Formula {
    let mut bounds = Vec::new();
    for decl in &func.body.locals {
        if decl.index < 1 || decl.index > func.body.arg_count {
            continue;
        }
        let Some(width) = decl.ty.int_width() else {
            continue;
        };
        let name = decl.name.clone().unwrap_or_else(|| format!("_{}", decl.index));
        bounds.push(safety_input_range_constraint(
            &Formula::var(&name, Sort::Int),
            width,
            decl.ty.is_signed(),
        ));
    }
    if bounds.is_empty() {
        return formula;
    }
    bounds.push(formula);
    Formula::And(bounds)
}

/// Reproduce `trust_vcgen::generate::conjoin_live_preconditions` for the
/// straight-line case: prepend the function's declared precondition formulas (in
/// `func.preconditions` order) before `formula`, collapsing into
/// `And([pre_1, …, pre_n, formula])`. Returns `formula` unchanged when there are
/// no preconditions.
///
/// trust-vcgen additionally DROPS a precondition at a block that may have
/// reassigned one of its free variables (`formula_survives_redefs`). For a
/// straight-line single-Return body no parameter is reassigned, so every
/// precondition survives and this reproduction is byte-exact. We do NOT model the
/// reassignment kill here: a function that reassigns a precondition's free
/// variable would produce a different live formula, and the exact-equality gate
/// then declines our (all-preconditions) candidate — fail-closed, never a wrong
/// match. This is a pure function of `func`; an additive candidate only.
fn conjoin_live_preconditions_full(func: &VerifiableFunction, formula: Formula) -> Formula {
    if func.preconditions.is_empty() {
        return formula;
    }
    let mut conjuncts: Vec<Formula> = func.preconditions.clone();
    conjuncts.push(formula);
    Formula::And(conjuncts)
}

/// Reproduce trust-vcgen's GLOBAL checked-arith pair-field facts byte-for-byte
/// (`build_checked_sub_result_facts` then `build_checked_add_result_facts`, in
/// the exact concatenation order `build_global_invariant_facts` uses: SUB
/// first, then ADD). Since ebd0cb739b the v2 block-VC lane conjoins the
/// function-wide invariant fact set onto EVERY already-built per-VC formula
/// (`And([facts…, vc_formula])`), and the final range pass re-conjoins the arg
/// type ranges AROUND that facts layer — so an overflow VC in a function whose
/// checked result `.0` is copied into a whole local (`_0 = move (_2.0)` —
/// every straight-line `x + 1` return) now emits
/// `env ∧ range(x) ∧ (Or(lhs + rhs > TYPE_MAX, dst == lhs + rhs) ∧ (range(x) ∧
/// body))` (verified against the live add1_u32 dump: the facts layer sits
/// BETWEEN two arg-range applications). Without this mirror the
/// unsigned-literal add (`fn add1(x: u32) { x + 1 }`) stopped byte-matching
/// and fell back to KEPT-formula — the common-case flip gap this closes.
///
/// Mirrored gates (kept in lock-step with trust-vcgen's builders):
/// * SSA-stability: unprojected statement-assign dests AND call dests each
///   counted once; a local assigned more than once is unstable (no fact).
/// * SUB: `_c = CheckedBinaryOp(Sub, lhs, rhs)` with UNSIGNED lhs and a stable
///   whole-local copy `_dst = copy/move (_c.0)` emits
///   `Or(lhs < rhs, dst == lhs - rhs)`.
/// * ADD: same shape with UNSIGNED lhs of width < 127 emits
///   `Or(lhs + rhs > TYPE_MAX, dst == lhs + rhs)`.
/// * Operand formulas / names go through the same `safety_operand_to_formula`
///   / `collision_safe_local_name` mirrors of `operand_to_formula` /
///   `place_to_var_name` (the builders' `stable_op` gate restricts operands to
///   projection-free locals / constants, all inside the faithful envelope).
///
/// These two are the only global-fact builders that fire on the faithful
/// straight-line integer envelope (min/max, modulo, cast, accumulator, … facts
/// all require call / cast / loop shapes outside it). When ANY other builder
/// fires on the live path, the candidate this feeds simply does not byte-match
/// and the flip keeps trust-vcgen's formula — fail-closed, never a wrong
/// verdict; adding candidates can only widen the spine-sourced envelope.
fn reconstruct_checked_pair_result_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    // Mirror the builders' `assign_count` SSA-stability gate.
    let mut assign_count: FxHashMap<usize, usize> = FxHashMap::default();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            if let Statement::Assign { place, .. } = stmt
                && place.projections.is_empty()
            {
                *assign_count.entry(place.local).or_insert(0) += 1;
            }
        }
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.projections.is_empty()
        {
            *assign_count.entry(dest.local).or_insert(0) += 1;
        }
    }
    let stable = |l: usize| assign_count.get(&l).copied().unwrap_or(0) <= 1;
    let stable_op = |op: &Operand| match op {
        Operand::Constant(_) => true,
        Operand::Copy(p) | Operand::Move(p) => p.projections.is_empty() && stable(p.local),
        _ => false,
    };
    // Mirror `operand_ty_cow`'s unsigned-integer resolution for the shapes
    // `stable_op` admits: a projection-free local read or an integer constant.
    let unsigned_width = |op: &Operand| -> Option<u32> {
        match op {
            Operand::Copy(p) | Operand::Move(p) => {
                match &locals.iter().find(|d| d.index == p.local)?.ty {
                    Ty::Int { width, signed: false } => Some(*width),
                    _ => None,
                }
            }
            Operand::Constant(ConstValue::Uint(_, w)) => Some(*w),
            _ => None,
        }
    };
    // The whole-local copies `_dst = copy/move (_c.0)` of a checked tuple `_c`.
    let field0_copies = |tuple_local: usize| -> Vec<usize> {
        let mut dsts = Vec::new();
        for b2 in &func.body.blocks {
            for s2 in &b2.stmts {
                let Statement::Assign {
                    place: dst,
                    rvalue: Rvalue::Use(Operand::Copy(p) | Operand::Move(p)),
                    ..
                } = s2
                else {
                    continue;
                };
                if dst.projections.is_empty()
                    && stable(dst.local)
                    && p.local == tuple_local
                    && matches!(p.projections.as_slice(), [Projection::Field(0)])
                {
                    dsts.push(dst.local);
                }
            }
        }
        dsts
    };
    let mut facts = Vec::new();
    // SUB facts first (matching `build_global_invariant_facts` order).
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: sub_place,
                rvalue: Rvalue::CheckedBinaryOp(BinOp::Sub, lhs, rhs),
                ..
            } = stmt
            else {
                continue;
            };
            if !sub_place.projections.is_empty()
                || !stable(sub_place.local)
                || !stable_op(lhs)
                || !stable_op(rhs)
                || unsigned_width(lhs).is_none()
            {
                continue;
            }
            let (Some(lhs_f), Some(rhs_f)) =
                (safety_operand_to_formula(locals, lhs), safety_operand_to_formula(locals, rhs))
            else {
                continue;
            };
            for dst_local in field0_copies(sub_place.local) {
                let idx_var =
                    Formula::var(&collision_safe_local_name(locals, dst_local), Sort::Int);
                facts.push(Formula::Or(vec![
                    Formula::Lt(Box::new(lhs_f.clone()), Box::new(rhs_f.clone())),
                    Formula::Eq(
                        Box::new(idx_var),
                        Box::new(Formula::Sub(Box::new(lhs_f.clone()), Box::new(rhs_f.clone()))),
                    ),
                ]));
            }
        }
    }
    // ADD facts second.
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: add_place,
                rvalue: Rvalue::CheckedBinaryOp(BinOp::Add, lhs, rhs),
                ..
            } = stmt
            else {
                continue;
            };
            if !add_place.projections.is_empty()
                || !stable(add_place.local)
                || !stable_op(lhs)
                || !stable_op(rhs)
            {
                continue;
            }
            let Some(width) = unsigned_width(lhs) else { continue };
            if width >= 127 {
                continue;
            }
            let type_max = (1i128 << width) - 1;
            let (Some(lhs_f), Some(rhs_f)) =
                (safety_operand_to_formula(locals, lhs), safety_operand_to_formula(locals, rhs))
            else {
                continue;
            };
            for dst_local in field0_copies(add_place.local) {
                let dst_var =
                    Formula::var(&collision_safe_local_name(locals, dst_local), Sort::Int);
                let sum = Formula::Add(Box::new(lhs_f.clone()), Box::new(rhs_f.clone()));
                facts.push(Formula::Or(vec![
                    Formula::Gt(Box::new(sum.clone()), Box::new(Formula::Int(type_max))),
                    Formula::Eq(Box::new(dst_var), Box::new(sum)),
                ]));
            }
        }
    }
    facts
}

/// The place name a block-definition fact DEFINES: the top-level lhs Var of an
/// `Eq`/range comparison, with any `#token` version suffix stripped. Mirrors
/// `trust_vcgen::generate::block_def_subject`. `None` for shapes with no single
/// defined-Var subject. Used to prune a `vc_block` return-source def the version
/// flip disconnects on the cross-block return-pin path.
fn block_def_subject_name(def: &Formula) -> Option<String> {
    let lhs = match def {
        Formula::Eq(l, _)
        | Formula::Lt(l, _)
        | Formula::Le(l, _)
        | Formula::Gt(l, _)
        | Formula::Ge(l, _) => l,
        _ => return None,
    };
    match &**lhs {
        Formula::Var(name, _) => Some(name.split('#').next().unwrap_or(name).to_string()),
        _ => None,
    }
}

/// Reconstruct the BOUNDS direct-comparison fresh-var block definition
/// trust-vcgen conjoins onto the violation core, BYTE-FOR-BYTE.
///
/// On the direct-comparison bounds path (`v2_build_bounds_assert_vc`), the assert's
/// boolean condition local `cond` is DEFINED by `cond = idx < len` in the SOURCE
/// block. trust-vcgen wraps the violation core in `v2_formula_with_block_defs`,
/// which surfaces that definition as the conjunct
///
/// ```text
/// Eq(Var(<cond_name>, Bool), Lt(idx_f, len_f))
/// ```
///
/// and `combine_relevant_block_defs` KEEPS it because its RHS (`idx`, `len`) shares
/// variables with the violation. The result trust-vcgen emits is exactly
/// `And([ <this binding>, <violation core> ])` (proven empirically:
/// `(and (= in_bounds (< i len)) (>= i len))`).
///
/// The fresh-var name `<cond_name>` is `trust_vcgen::place_to_var_name(cond)` — for
/// the projection-free boolean cond local of the direct-comparison shape that is
/// just the local's declared name (reproduced here by `safety_place_var_name`),
/// fully DETERMINISTIC from the `VerifiableFunction` (no counter, no global state).
/// The `Lt` operands are reconstructed with the same `safety_operand_to_formula`
/// the violation core uses, so the binding is byte-identical to trust-vcgen's def.
///
/// Returns `None` (fail-closed) when the cond is not defined by an `idx < len`
/// comparison in the source block, the cond name is unrecoverable, or either
/// comparison operand is outside the faithful envelope — in those cases the flip
/// keeps trust-vcgen's own formula.
///
/// SOUNDNESS: this reproduces a SINGLE, narrow, self-contained block definition
/// (a fresh boolean binding) — NOT trust-vcgen's full private block-dataflow
/// (`extract_block_definitions` with its array-theory prepass / CHC binop lowering
/// / cast ranges / guard paths). The candidate it builds is only ever ACCEPTED by
/// the flip's exact byte-equality gate; if the real source block contributes any
/// OTHER relevant block def, this reconstruction will simply not byte-match and the
/// flip falls back to trust-vcgen's formula. So it can never manufacture a wrong
/// verdict — it widens the byte-equal envelope for the clean single-binding shape.
fn reconstruct_bounds_cond_binding(
    locals: &[LocalDecl],
    source_block: &TrustBlock,
    cond: &Operand,
) -> Option<Formula> {
    let cond_name = match cond {
        Operand::Copy(p) | Operand::Move(p) => safety_place_var_name(locals, p)?,
        _ => return None,
    };
    let (op, lhs, rhs) = find_condition_binary_operands(source_block, cond)?;
    if op != BinOp::Lt {
        return None;
    }
    let lhs_f = safety_operand_to_formula(locals, lhs)?;
    let rhs_f = safety_operand_to_formula(locals, rhs)?;
    Some(Formula::Eq(
        Box::new(Formula::var(&cond_name, Sort::Bool)),
        Box::new(Formula::Lt(Box::new(lhs_f), Box::new(rhs_f))),
    ))
}

/// Reproduce `trust_vcgen::slice_len_formula` BYTE-FOR-BYTE for the operand shapes
/// the bounds path's length term ranges over: a `Copy`/`Move` of a projection-free
/// place whose type is `&[T]` / `&mut [T]` (`Ty::Ref` with a `Slice` inner),
/// `*[T]` (`Ty::RawPtr` to a `Slice`), or a bare `Ty::Slice`. In all three cases
/// trust-vcgen emits `Var("{place_name}__slice_len", Int)`, where `place_name` is
/// the slice operand's declared name (its local name when projection-free), matching
/// `slice_len_formula`/`place_to_var_name`. A `Ty::Array { len }` resolves to the
/// constant `Int(len)`. Returns `None` (fail-closed) for any other operand/type —
/// the flip then keeps trust-vcgen's own formula.
fn reconstruct_slice_len_formula(locals: &[LocalDecl], operand: &Operand) -> Option<Formula> {
    let place = match operand {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
        _ => return None,
    };
    let decl = locals.iter().find(|d| d.index == place.local)?;
    // COLLISION-SAFE name (mirrors `place_to_var_name`): a slice debug name shared by
    // two distinct slice locals (`let s = outer; { let s = inner; … }`) must NOT
    // collapse to one `s__slice_len`, or a guard on `len(outer)` would discharge a
    // bounds check on `inner` — the audit's confirmed false proof. Unique names are
    // unchanged (the common case), so byte-equality with vcgen is preserved.
    let name = collision_safe_local_name(locals, place.local);
    match &decl.ty {
        Ty::Ref { inner, .. } if matches!(inner.as_ref(), Ty::Slice { .. }) => {
            Some(Formula::var(&format!("{name}__slice_len"), Sort::Int))
        }
        Ty::RawPtr { pointee, .. } if matches!(pointee.as_ref(), Ty::Slice { .. }) => {
            Some(Formula::var(&format!("{name}__slice_len"), Sort::Int))
        }
        Ty::Slice { .. } => Some(Formula::var(&format!("{name}__slice_len"), Sort::Int)),
        Ty::Array { len, .. } => Some(Formula::Int(i128::from(*len))),
        _ => None,
    }
}

/// Reconstruct the SLICE-LENGTH fresh-var block definition trust-vcgen surfaces on
/// the direct-comparison bounds path when the length operand of the `idx < len`
/// comparison is itself a local DEFINED by `len_local = PtrMetadata(slice)` /
/// `len_local = Len(slice)` in the SOURCE block, BYTE-FOR-BYTE.
///
/// Real rustc slice-index MIR is `_3 = PtrMetadata(s); _4 = i < _3; assert(_4)`,
/// so the comparison's RHS is `_3` (a derived local), not the slice directly.
/// `guards::extract_block_definitions` turns the `_3 = PtrMetadata(s)` statement
/// into the conjunct `Eq(Var("_3", Int), slice_len_formula(s))` =
/// `Eq(Var("_3", Int), Var("s__slice_len", Int))`, which `combine_relevant_block_defs`
/// KEEPS because `_3` is referenced by the cond binding / violation. The result
/// trust-vcgen emits is exactly
/// `And([ Eq(_3, s__slice_len), Eq(_4, Lt(i, _3)), Ge(i, _3) ])` (verified
/// empirically against the LIVE builder on the dumped `idx` function).
///
/// `rhs` is the comparison's RHS operand (the `_3` length local). This finds the
/// statement `rhs_local = PtrMetadata(slice)` / `rhs_local = Len(slice)` in
/// `source_block` and returns `Eq(Var(rhs_name, Int), slice_len_formula(slice))`.
/// Returns `None` (fail-closed) when the RHS is not a projection-free local, has no
/// such defining `PtrMetadata`/`Len` statement, or the slice operand is outside the
/// `slice_len_formula` envelope — in those cases the bounds candidate omits the
/// slice-len binding and the flip falls back if the live formula carries it.
///
/// SOUNDNESS: reproduces a SINGLE, self-contained fresh-var binding (`rhs_local`
/// names nothing but this slice's length), ACCEPTED only by the flip's exact
/// byte-equality gate. Any other relevant block def the real source block emits
/// makes the reconstruction not byte-match, and the flip keeps trust-vcgen's
/// formula — never a wrong verdict.
fn reconstruct_bounds_slice_len_binding(
    locals: &[LocalDecl],
    source_block: &TrustBlock,
    rhs: &Operand,
) -> Option<Formula> {
    // The RHS length local of the `idx < len` comparison.
    let rhs_place = match rhs {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
        _ => return None,
    };
    let rhs_name = safety_place_var_name(locals, rhs_place)?;
    // Find `rhs_local = PtrMetadata(slice)` or `rhs_local = Len(slice)` in source.
    let slice_len = source_block.stmts.iter().find_map(|stmt| {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            return None;
        };
        if place.local != rhs_place.local || !place.projections.is_empty() {
            return None;
        }
        match rvalue {
            Rvalue::UnaryOp(UnOp::PtrMetadata, slice_op) => {
                reconstruct_slice_len_formula(locals, slice_op)
            }
            Rvalue::Len(slice_place) => {
                reconstruct_slice_len_formula(locals, &Operand::Copy(slice_place.clone()))
            }
            _ => None,
        }
    })?;
    Some(Formula::Eq(Box::new(Formula::var(&rhs_name, Sort::Int)), Box::new(slice_len)))
}

/// Reconstruct the ABSTRACT-FLAG-shape fresh-var cond binding `Eq(cond, defn)`
/// trust-vcgen surfaces for an assert whose boolean condition local `cond` is
/// DEFINED by an arbitrary `BinaryOp` in the SOURCE block (not only `idx < len`).
///
/// On the div/rem/shift/custom assert path trust-vcgen builds the VC formula as
/// `v2_formula_with_block_defs(block, v2_assert_failure_formula(cond, expected))`.
/// The block-def layer surfaces the cond's defining statement as
/// `Eq(Var(cond_name, Bool), <defn>)`, where `<defn>` is the `BinaryOp` rvalue
/// lowered to a `Formula` exactly as `extract_block_definitions` does. We reproduce
/// it for the SELF-CONTAINED boolean-defining comparisons the dumped functions use:
///
/// | rvalue `BinaryOp`         | reproduced `<defn>`                |
/// |---------------------------|------------------------------------|
/// | `Eq(x, y)`                | `Eq(x_f, y_f)`  (div/rem `b == 0`) |
/// | `Lt(x, y)`                | `Lt(x_f, y_f)`  (shift `n < bits`) |
/// | `Le`/`Gt`/`Ge`            | the same relation                  |
///
/// Operands are reconstructed with the same `safety_operand_to_formula` the core
/// uses, so the binding is byte-identical to trust-vcgen's def. Returns `None`
/// (fail-closed) when the cond is not a projection-free local defined by one of
/// these comparisons in the source block, or an operand is outside the envelope.
fn reconstruct_assert_flag_cond_binding(
    locals: &[LocalDecl],
    source_block: &TrustBlock,
    cond: &Operand,
) -> Option<Formula> {
    let cond_name = match cond {
        Operand::Copy(p) | Operand::Move(p) => safety_place_var_name(locals, p)?,
        _ => return None,
    };
    let (op, lhs, rhs) = find_condition_binary_operands(source_block, cond)?;
    let lhs_f = safety_operand_to_formula(locals, lhs)?;
    let rhs_f = safety_operand_to_formula(locals, rhs)?;
    let defn = match op {
        BinOp::Eq => Formula::Eq(Box::new(lhs_f), Box::new(rhs_f)),
        BinOp::Lt => Formula::Lt(Box::new(lhs_f), Box::new(rhs_f)),
        BinOp::Le => Formula::Le(Box::new(lhs_f), Box::new(rhs_f)),
        BinOp::Gt => Formula::Gt(Box::new(lhs_f), Box::new(rhs_f)),
        BinOp::Ge => Formula::Ge(Box::new(lhs_f), Box::new(rhs_f)),
        // Other defining ops (Ne, arithmetic, bitwise) are outside the
        // self-contained-comparison envelope — fail closed.
        _ => return None,
    };
    Some(Formula::Eq(Box::new(Formula::var(&cond_name, Sort::Bool)), Box::new(defn)))
}

/// Reconstruct the checked-add result facts that `trust_vcgen::build_checked_add_result_facts`
/// conjoins onto every VC. This is deliberately the flip's narrow, byte-faithful mirror of that
/// ONE global-fact producer rather than a general reconstruction of vcgen's private fact set.
///
/// For an unsigned `_pair = CheckedAdd(lhs, rhs)` whose `.0` result is copied into a stable
/// whole local `_dst`, the emitted fact is
///
/// ```text
/// (lhs + rhs > TYPE_MAX) OR (_dst == lhs + rhs)
/// ```
///
/// The first arm makes the fact vacuous on the overflow edge; the equality is asserted only when
/// the mathematical sum is representable. Consequently a genuine overflow remains satisfiable
/// and refutable. Projection-free/single-assignment gates mirror vcgen exactly enough for the
/// faithful scalar envelope; any unsupported operand or name fails closed to no candidate. The
/// flip still requires exact formula equality before changing provenance and always keeps vcgen's
/// live formula as the proof formula.
fn reconstruct_checked_add_result_facts_for_flip(func: &VerifiableFunction) -> Vec<Formula> {
    let mut assignment_count: FxHashMap<usize, usize> = FxHashMap::default();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            if let Statement::Assign { place, .. } = stmt
                && place.projections.is_empty()
            {
                *assignment_count.entry(place.local).or_default() += 1;
            }
        }
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.projections.is_empty()
        {
            *assignment_count.entry(dest.local).or_default() += 1;
        }
    }

    let stable = |local: usize| assignment_count.get(&local).copied().unwrap_or(0) <= 1;
    let stable_operand = |operand: &Operand| match operand {
        Operand::Constant(_) => true,
        Operand::Copy(place) | Operand::Move(place) => {
            place.projections.is_empty() && stable(place.local)
        }
        _ => false,
    };

    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: add_place,
                rvalue: Rvalue::CheckedBinaryOp(BinOp::Add, lhs, rhs),
                ..
            } = stmt
            else {
                continue;
            };
            if !add_place.projections.is_empty()
                || !stable(add_place.local)
                || !stable_operand(lhs)
                || !stable_operand(rhs)
            {
                continue;
            }

            let Some(Ty::Int { signed: false, width }) = native_operand_ty(locals, lhs) else {
                continue;
            };
            // Matches vcgen's scalar-Int bound: 2^width must fit in i128.
            if width >= 127 {
                continue;
            }
            let type_max = (1i128 << width) - 1;

            for copy_block in &func.body.blocks {
                for copy_stmt in &copy_block.stmts {
                    let Statement::Assign {
                        place: dest,
                        rvalue: Rvalue::Use(Operand::Copy(source) | Operand::Move(source)),
                        ..
                    } = copy_stmt
                    else {
                        continue;
                    };
                    if !dest.projections.is_empty()
                        || !stable(dest.local)
                        || source.local != add_place.local
                        || !matches!(source.projections.as_slice(), [Projection::Field(0)])
                    {
                        continue;
                    }

                    let Some(dest_name) = safety_place_var_name(locals, dest) else {
                        continue;
                    };
                    let Some(lhs_formula) = safety_operand_to_formula(locals, lhs) else {
                        continue;
                    };
                    let Some(rhs_formula) = safety_operand_to_formula(locals, rhs) else {
                        continue;
                    };
                    let sum = Formula::Add(Box::new(lhs_formula), Box::new(rhs_formula));
                    facts.push(Formula::Or(vec![
                        Formula::Gt(Box::new(sum.clone()), Box::new(Formula::Int(type_max))),
                        Formula::Eq(
                            Box::new(Formula::var_owned(dest_name, Sort::Int)),
                            Box::new(sum),
                        ),
                    ]));
                }
            }
        }
    }
    facts
}

/// Reconstruct CANDIDATE full trust-vcgen formulas for the L0 safety obligation
/// at `target_span` whose trust-vcgen `VcKind` is `vc_kind`. Each candidate is a
/// best-effort byte-equal target for the formula trust-vcgen dispatches; the
/// caller (the flip) accepts a candidate ONLY when its SMT-LIB is byte-equal to
/// trust-vcgen's, so proposing several does not weaken soundness — every
/// candidate is logically equivalent to the violation core (the wrappers are
/// idempotent re-conjunctions of facts the core already implies), and only an
/// EXACT byte match is ever used.
///
/// Returns an empty vec when no matching assert is found, the message is outside
/// the faithful envelope, or the class has no reconstructable core — in every
/// such case the flip keeps trust-vcgen's own formula (fail-closed).
///
/// Why CANDIDATES: trust-vcgen wraps the violation core in `conjoin_arg_type_ranges`
/// and `v2_formula_with_block_defs`, and depending on which emission path a given
/// MIR shape takes the idempotent arg-range layer is applied ZERO, ONE, or TWO
/// times (e.g. the direct-`Rvalue::BinaryOp` path and the assert-terminator path
/// can each contribute one). Rather than reproduce the exact private dataflow
/// (the documented soundness hazard), we enumerate the sound idempotent wrappings
/// and let the byte-equality gate select the one trust-vcgen actually emitted.
///
/// Span match: the obligation the lowering stamps uses the assert TERMINATOR's
/// span, the same span trust-vcgen records on the VC's `location`, so span
/// equality pins the same assert; `vc_kind` additionally guards the message class.
///
/// `pub(crate)` for the flip module; a pure function of the trust-types
/// `VerifiableFunction` (reconstructed the same Route-B way the obligation stamp
/// is — at lowering time with named operands in hand).
pub(crate) fn reconstruct_full_safety_formula_candidates(
    func: &VerifiableFunction,
    target_span: &TrustSourceSpan,
    vc_kind: &VcKind,
) -> Vec<Formula> {
    let all_blocks = &func.body.blocks;

    // Backward compatibility for a historical/external CastOverflow VC. Current
    // trust-vcgen and MIR lowering never mint one for Rust `as` syntax, but an
    // already-present legacy VC can still be preserved by exact formula match.
    if matches!(vc_kind, VcKind::CastOverflow { .. }) {
        return reconstruct_cast_formula_candidates(func, target_span);
    }

    // Find the assert block whose terminator span equals the target span AND whose
    // message class matches the `VcKind` we were asked for. Matching on BOTH is
    // REQUIRED for signed div/rem: rustc emits TWO asserts at the SAME span — a
    // `DivisionByZero` and an `Overflow(Div)` — so a span-only match would always
    // return the first (DivisionByZero) and the `Overflow(Div)` VC would then fail the
    // class guard and reconstruct NOTHING. Filtering by `(span, kind)` together selects
    // the correct assert for each of the two same-span div/rem VCs.
    let Some((block_id, target, cond, expected, msg)) =
        all_blocks.iter().find_map(|b| match &b.terminator {
            Terminator::Assert { span, target, cond, expected, msg, .. }
                if span == target_span && assert_message_matches_vc_kind(msg, vc_kind) =>
            {
                Some((b.id, *target, cond, *expected, msg))
            }
            _ => None,
        })
    else {
        return Vec::new();
    };

    // DIV/REM-BY-ZERO ABSTRACT-FLAG shape (the canonical rustc shape, e.g.
    // `_3 = (b == 0); Assert { DivisionByZero } on _3`): trust-vcgen's
    // `DivisionByZero` ASSERT VC is built as `v2_formula_with_block_defs(block,
    // v2_assert_failure_formula(_3, false))` = `And([ Eq(_3, Eq(b, 0)), _3 ])` (the
    // bare cond var, with the cond's defining `b == 0` comparison surfaced as the
    // block def), wrapped in the param-range env. This is the SAME abstract-flag
    // shape as negation/shift; reproduce it from the cond directly (NOT from the
    // divisor-zero core, which lives on the bare `Div` STATEMENT VC at the same span
    // and carries unreproducible signed-div path guards — see the same-span
    // ambiguity note in `flip.rs`). The byte-equality gate accepts this candidate
    // only for the assert VC whose formula it reproduces, so it picks the
    // abstract-flag assert VC out of the two same-span div/rem-by-zero VCs.
    if matches!(msg, AssertMessage::DivisionByZero | AssertMessage::RemainderByZero) {
        let Some(cond_name) = (match cond {
            Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => {
                safety_place_var_name(&func.body.locals, p)
            }
            _ => None,
        }) else {
            return Vec::new();
        };
        // Mirror `v2_assert_failure_formula(cond, expected)`: the failure formula is
        // `Not(cond)` when the assert expects `true` (failure = cond is false), else
        // the bare `cond` when it expects `false` (failure = cond is true — the
        // canonical rustc `_3 = (b == 0); assert(_3, expected=false)` divisor shape).
        let cond_var = Formula::var(&cond_name, Sort::Bool);
        let core = if expected { Formula::Not(Box::new(cond_var)) } else { cond_var };
        let base = match all_blocks
            .iter()
            .find(|b| b.id == block_id)
            .and_then(|b| reconstruct_assert_flag_cond_binding(&func.body.locals, b, cond))
        {
            Some(binding) => vec![Formula::And(vec![binding, core.clone()]), core],
            None => vec![core],
        };
        return augment_candidates_with_param_env(func, base);
    }

    let core = match reconstruct_assert_safety_predicate(
        &func.body.locals,
        all_blocks,
        block_id,
        target,
        cond,
        msg,
    ) {
        Some(SafetyPredicate::Reconstructed(f)) => f,
        // Reconstructable class but operands outside the faithful envelope, or a
        // non-arithmetic message: no candidate (flip keeps vcgen formula).
        Some(SafetyPredicate::NotReconstructed(_)) | None => return Vec::new(),
    };

    // Enumerate sound idempotent wrappings. Overflow Add/Sub carries the
    // `conjoin_arg_type_ranges` layer (applied 1 or 2× depending on the emission
    // path); bounds / shift / div-rem carry no arg-range wrapper, so the core (and
    // a single defensive arg-range wrap) are the candidates. Order: most-wrapped
    // first is NOT required — byte-equality is exact — but we list the bare core
    // last so a trivially-unwrapped formula still matches.
    let base: Vec<Formula> = match msg {
        AssertMessage::Overflow(BinOp::Add | BinOp::Sub) => {
            let one = conjoin_arg_type_ranges_full(func, core.clone());
            let two = conjoin_arg_type_ranges_full(func, one.clone());
            // PRECONDITION-BEARING overflow (trust-ir-spine simple case). When the
            // function carries `#[requires]`, trust-vcgen's overflow-assert path
            // ALSO conjoins the live preconditions (`conjoin_live_preconditions`)
            // BETWEEN the two `conjoin_arg_type_ranges` layers, emitting
            // `conjoin_arg_type_ranges(conjoin_live_preconditions(one))`
            // (verified byte-equal against the live `both`/`pre` overflow VC). We
            // offer that wrapped form as an EXTRA candidate; the exact-equality gate
            // accepts it only when it byte-matches, so a function whose live
            // precondition set differs (a killed/unsurvivable precondition, an
            // unsupported shape) simply does not match and falls back (fail-closed).
            let mut cands = vec![two, one.clone(), core];
            if matches!(msg, AssertMessage::Overflow(BinOp::Add)) {
                let mut checked_add_facts = reconstruct_checked_add_result_facts_for_flip(func);
                if !checked_add_facts.is_empty() {
                    // vcgen conjoins global facts after the builder's first arg-range
                    // layer, then its final ArithmeticOverflow pass adds the outer
                    // arg-range layer. Preserve that exact nesting/order.
                    checked_add_facts.push(one.clone());
                    let with_global_facts = Formula::And(checked_add_facts);
                    cands.insert(0, conjoin_arg_type_ranges_full(func, with_global_facts));
                }
            }
            if !func.preconditions.is_empty() {
                let pre_wrapped =
                    conjoin_arg_type_ranges_full(func, conjoin_live_preconditions_full(func, one));
                // Most-specific (precondition-bearing) candidate FIRST.
                cands.insert(0, pre_wrapped);
            }
            // GLOBAL-INVARIANT checked-pair layer (ebd0cb739b): the v2 lane
            // conjoins the function-wide invariant fact set onto every
            // ALREADY-BUILT per-VC formula (`And([facts…, vc_formula])`), and
            // the final range pass then re-conjoins the arg type ranges once
            // more AROUND the facts layer. For the straight-line checked add
            // the live emission is therefore
            // `env ∧ range(x) ∧ ( pair_fact ∧ ( range(x) ∧ body ) )` —
            // verified against the live add1_u32 dump: the facts layer sits
            // BETWEEN two arg-range applications. Offer, for every existing
            // candidate depth `c`, both the re-wrapped `range(facts ∧ c)` and
            // the bare `facts ∧ c` forms, most-specific FIRST; the exact-
            // equality gate picks whichever trust-vcgen actually emitted, and
            // a function where OTHER global builders also fire simply never
            // matches (fail-closed — the flip keeps trust-vcgen's formula).
            // See `reconstruct_checked_pair_result_facts`.
            let pair_facts = reconstruct_checked_pair_result_facts(func);
            if !pair_facts.is_empty() {
                let mut facts_forms = Vec::with_capacity(cands.len() * 2);
                for c in &cands {
                    let mut conj = pair_facts.clone();
                    conj.push(c.clone());
                    let flat = Formula::And(conj);
                    facts_forms.push(conjoin_arg_type_ranges_full(func, flat.clone()));
                    facts_forms.push(flat);
                }
                cands.splice(0..0, facts_forms);
            }
            cands
        }
        // Mul overflow: the BV mul VC formula is the `bv_formula`
        // (`reconstruct_bv_mul_overflow_candidates` enumerates the bare AND
        // widening-cast operand encodings) wrapped EXACTLY ONCE by the final-pass
        // `conjoin_arg_type_ranges`. Unlike Add/Sub, the BV arm of
        // `v2_build_overflow_vc_for_operands` returns BEFORE the scalar path's
        // internal `conjoin_arg_type_ranges`, so the arg-range layer is applied a
        // single time (the post-generation loop over `ArithmeticOverflow` VCs),
        // giving `And([range(a), range(b), bv_formula])`. Offer, for each enumerated
        // bv core, the once-wrapped form and the bare core; the byte-equality gate
        // selects whichever trust-vcgen actually emitted (and keeps trust-vcgen's
        // formula if none match — fail-closed). The guard-bounded mul
        // (`v2_bv_mul_dominating_guard_constraints` conjoins extra BV facts) is NOT
        // reconstructed here and stays sound fail-closed.
        AssertMessage::Overflow(BinOp::Mul) => {
            let operands = all_blocks
                .iter()
                .find(|b| b.id == block_id)
                .and_then(|b| find_block_binary_operands(b, BinOp::Mul))
                .or_else(|| {
                    all_blocks
                        .iter()
                        .find(|b| b.id == target)
                        .and_then(|b| find_block_binary_operands(b, BinOp::Mul))
                });
            match operands {
                Some((lhs, rhs)) => {
                    let cores = reconstruct_bv_mul_overflow_candidates(
                        &func.body.locals,
                        all_blocks,
                        lhs,
                        rhs,
                    );
                    let mut cands = Vec::with_capacity(cores.len() * 2);
                    for c in cores {
                        cands.push(conjoin_arg_type_ranges_full(func, c.clone()));
                        cands.push(c);
                    }
                    // Mirror trust-vcgen's `linear_const_mul` routing (91d8dcb9f8):
                    // a constant-multiplier mul is emitted on the Int/LIA path with
                    // the Add/Sub-style arg-range wrapping (the BV arm is skipped).
                    // Offer those Int-form candidates too, most-wrapped first; the
                    // exact-equality gate picks whichever form trust-vcgen actually
                    // emitted (a never-matching extra candidate is inert). No
                    // widening-source gate on the spine side: offering both the Int
                    // and BV candidate families is the existing enumeration
                    // strategy, and a widening mul simply never matches Int-form.
                    if matches!(lhs, Operand::Constant(_)) || matches!(rhs, Operand::Constant(_)) {
                        if let Some(int_core) =
                            reconstruct_overflow_body(&func.body.locals, BinOp::Mul, lhs, rhs)
                        {
                            let one = conjoin_arg_type_ranges_full(func, int_core.clone());
                            let two = conjoin_arg_type_ranges_full(func, one.clone());
                            cands.splice(0..0, [two, one, int_core]);
                        }
                    }
                    // Defensive fallback: if enumeration produced nothing, keep the
                    // single (bare) core the predicate reconstructed.
                    if cands.is_empty() {
                        cands.push(core);
                    }
                    cands
                }
                None => vec![core],
            }
        }
        // Bounds direct-comparison: trust-vcgen wraps the violation core in the
        // source block's relevant fresh-var block definitions. In the clean
        // single-comparison case (`_4 = i < len; assert(_4)`) that is just the cond
        // binding `Eq(cond, idx < len)`. In the real rustc slice-index case
        // (`_3 = PtrMetadata(s); _4 = i < _3; assert(_4)`) the length is itself a
        // local, so trust-vcgen ALSO surfaces the slice-len binding
        // `Eq(_3, s__slice_len)` before the cond binding, yielding
        // `And([ Eq(_3, s__slice_len), Eq(_4, Lt(i, _3)), Ge(i, _3) ])`. We
        // reproduce BOTH bindings byte-for-byte and offer the most-wrapped form
        // first, the cond-binding-only form next, and the bare core last. The
        // byte-equality gate selects whichever trust-vcgen actually emitted; an
        // extra unreproduced block def simply fails the match (fail-closed).
        AssertMessage::BoundsCheck => {
            let source = all_blocks.iter().find(|b| b.id == block_id);
            let cond_binding =
                source.and_then(|b| reconstruct_bounds_cond_binding(&func.body.locals, b, cond));
            // The slice-len binding for the comparison's RHS length local, when it
            // is defined by `PtrMetadata`/`Len` of a slice in the source block.
            let slice_len_binding = source.and_then(|b| {
                let (_op, _lhs, rhs) = find_condition_binary_operands(b, cond)?;
                reconstruct_bounds_slice_len_binding(&func.body.locals, b, rhs)
            });
            match (slice_len_binding, cond_binding) {
                // Full real-MIR shape: slice-len def + cond binding + violation.
                (Some(slen), Some(binding)) => {
                    let full = Formula::And(vec![slen, binding.clone(), core.clone()]);
                    let cond_only = Formula::And(vec![binding, core.clone()]);
                    vec![full, cond_only, core]
                }
                // No slice-len local: the clean single-comparison shape.
                (None, Some(binding)) => {
                    let full = Formula::And(vec![binding, core.clone()]);
                    vec![full, core]
                }
                // No reproducible cond binding: bare core only.
                _ => vec![core],
            }
        }
        // Shift overflow: trust-vcgen builds the shift VC's formula via
        // `v2_assert_failure_formula` wrapped in block-defs — the assert's boolean
        // cond local `_3` is DEFINED by `n < bits` in the source block, surfaced as
        // `Eq(_3, Lt(n, bits))`, conjoined before the shift-range violation core
        // `And([range(amount), invalid_shift(amount)])`. So the emitted formula is
        // `And([ Eq(_3, Lt(n, bits)), <core> ])`. Reproduce the cond binding
        // byte-for-byte (a self-contained `Lt`-defining comparison) and offer the
        // wrapped form first, the bare core last (block-def-free shape). The
        // byte-equality gate selects whichever trust-vcgen actually emitted.
        AssertMessage::Overflow(BinOp::Shl | BinOp::Shr) => {
            match all_blocks
                .iter()
                .find(|b| b.id == block_id)
                .and_then(|b| reconstruct_assert_flag_cond_binding(&func.body.locals, b, cond))
            {
                Some(binding) => {
                    let full = Formula::And(vec![binding, core.clone()]);
                    vec![full, core]
                }
                None => vec![core],
            }
        }
        // Negation overflow: trust-vcgen's `v2_build_assert_negation_vc` emits
        // `v2_formula_with_block_defs(block, v2_assert_failure_formula(cond, false))`.
        // The core is the bare cond var; the block-def layer surfaces the cond's
        // defining `_c = (a == MIN)` comparison as `Eq(_c, Eq(a, MIN))` (kept,
        // since `_c` is referenced). So the emitted formula is
        // `And([ Eq(_c, Eq(a, MIN)), _c ])`. Reproduce the cond binding with the
        // SAME self-contained-comparison helper the shift class uses (the
        // `BinOp::Eq` arm of `reconstruct_assert_flag_cond_binding`), offer the
        // wrapped form first and the bare core last; the byte-equality gate selects
        // whichever trust-vcgen actually emitted.
        AssertMessage::OverflowNeg => {
            match all_blocks
                .iter()
                .find(|b| b.id == block_id)
                .and_then(|b| reconstruct_assert_flag_cond_binding(&func.body.locals, b, cond))
            {
                Some(binding) => {
                    let full = Formula::And(vec![binding, core.clone()]);
                    vec![full, core]
                }
                None => vec![core],
            }
        }
        _ => vec![core],
    };

    // LIVE-PATH abstract-state augmentation. The daily-driver does NOT dispatch
    // the bare `generate_vcs` formula: it runs `generate_vcs_with_discharge`,
    // which conjoins the merged abstract-interpretation environment onto every
    // non-discharged VC via `augment_vc_with_abstract_state`
    // (`Formula::And([interval_domain_to_formula(env), <vcgen formula>])`). For a
    // function whose merged interval environment is exactly its integer
    // PARAMETERS' type ranges — the no-precondition, no-fixpoint-tightening case
    // (verified empirically for `add_ovf`: merged env == initial state ==
    // `And([Ge(a,MIN),Le(a,MAX),Ge(b,MIN),Le(b,MAX)])`) — that prepended
    // conjunct is DETERMINISTIC FROM THE FUNCTION ALONE. We reconstruct it
    // byte-for-byte and offer `And([env, base])` for every base candidate, so the
    // spine can byte-match the LIVE dispatched overflow formula (not just the
    // bare `generate_vcs` one).
    //
    // SOUNDNESS: this is a best-effort EXTRA candidate, never a replacement. The
    // flip accepts a candidate only on EXACT `Formula` AST byte-equality, so an
    // `And([env, base])` candidate fires only when the live formula IS that
    // formula byte-for-byte. When the real fixpoint env differs (a precondition
    // tightened a bound, the fixpoint bounded a result/intermediate local, loop
    // widening, an unreachable/Top edge, a non-integer-but-bounded param such as a
    // raw pointer the spine does not model), the reconstructed env simply does not
    // byte-match and the flip falls back to trust-vcgen's own formula
    // (fail-closed). Adding candidates can only WIDEN the spine-sourced envelope;
    // it can never manufacture a wrong verdict.
    augment_candidates_with_param_env(func, base)
}

/// Prepend the LIVE-path abstract-state param-range env conjunct to each base
/// candidate (offering the env-augmented forms FIRST, then the bare forms as a
/// fallback for the Top-env path). Shared by the assert-based and cast-based
/// candidate reconstructions. See `reconstruct_abstract_state_param_env` for the
/// soundness argument: every candidate is accepted only on exact byte-equality, so
/// adding env-augmented candidates can only widen the spine-sourced envelope.
fn augment_candidates_with_param_env(
    func: &VerifiableFunction,
    base: Vec<Formula>,
) -> Vec<Formula> {
    let mut out = base;
    if let Some(env) = reconstruct_abstract_state_param_env(func) {
        // Mirror trust-vcgen's `augment_vc_with_abstract_state` WELL-SORTEDNESS guard
        // (abstract_interp/discharge.rs): a BV-THEORY VC — a signed/unsigned mul
        // overflow, whose formula models its operands as declared-width bitvectors —
        // is left UNAUGMENTED. Conjoining the Int-sorted interval env onto a bitvector
        // formula is ill-sorted (the same variable would carry both an Int and a
        // BitVec sort), so vcgen returns those rows unchanged (the BV width already
        // carries the type-range information the env facts would add). Reproduce that
        // skip PER-CANDIDATE so `generate_native_safety_vcs` — which takes the FIRST
        // candidate as its canonical native formula — byte-matches the live vcgen
        // formula on the BV overflow lane instead of prepending a spurious Int env
        // conjunct. Int-theory candidates (shift/neg/div/bounds/add-sub) are still
        // augmented, matching the vcgen rows that DO carry the merged interval env.
        let augmented: Vec<Formula> = out
            .iter()
            .filter(|base| !trust_types::formula_mentions_bitvector_theory(base))
            .map(|base| Formula::And(vec![env.clone(), base.clone()]))
            .collect();
        let mut combined = augmented;
        combined.append(&mut out);
        out = combined;
    }
    out
}

// ============================================================================
// trust-ir-NATIVE VC generation (the obligation-birth cutover, Stage B/C).
//
// `generate_native_safety_vcs` produces the COMPLETE L0 safety
// `VerificationCondition` set with trust-ir as the SOURCE: the lowered module's
// safety-obligation set is the authoritative enumeration of WHICH obligations
// exist (proven `== trust-vcgen`'s L0 VC set by span+class — see the bridge
// `dbg_module_obligation_completeness` evidence), the routing `VcKind` is
// reconstructed from the assert/cast operands, and the solvable `formula` comes
// from the validated `reconstruct_full_safety_formula_*` machinery. NO
// `trust_vcgen` is consulted at generation time. The caller cross-checks the set
// against trust-vcgen during migration and only dispatches it on an exact match,
// so a partial/mis-shaped native set can never change a verdict (it falls back);
// as coverage → 100% the cross-check and trust-vcgen leave the path entirely.
// ============================================================================

/// Generate the complete L0 safety VC set natively from the spine, or `None` if any
/// L0 safety site is outside the reconstructed envelope (caller falls back).
/// Conjoin the SOUND dominating path facts reaching `block_id` onto `formula`.
/// Every fact holds whenever `block_id` is reached, so the result is SOUND (never
/// false-proves) and at least as complete. No-op when there are no dominating facts
/// (straight-line code), so it never changes the straight-line native formula.
fn enrich_with_sound_dominating_guards(
    func: &VerifiableFunction,
    block_id: BlockId,
    formula: Formula,
) -> Formula {
    let mut conj = reconstruct_sound_dominating_guards(func, block_id);
    // Also conjoin the REACHABILITY CONDITION `OR over paths (AND facts)` when soundly
    // computable — it is TIGHTER than the all-paths intersection and discharges a
    // DISJUNCTIVE guard (`if d!=0 && !(n==MIN && d==-1) { n/d }`), where the obligation is
    // reached via two branches whose only common fact is `d!=0`. Additive: `None` (a CFG
    // with calls/drops, an unconditional path, or the path cap) leaves the audited
    // intersection unchanged.
    if let Some(reach) = reconstruct_reachability_condition(func, block_id) {
        conj.push(reach);
    }
    if conj.is_empty() {
        return formula;
    }
    conj.push(formula);
    Formula::And(conj)
}

/// The REACHABILITY CONDITION of `target` — `OR over paths (AND of the path's facts)` —
/// a SOUND over-approximation of when `target` is reached, TIGHTER than
/// [`reconstruct_sound_dominating_guards`]'s all-paths intersection. It discharges a
/// DISJUNCTIVE guard: `if d != 0 && !(n == i32::MIN && d == -1) { n / d }` reaches the
/// div-overflow obligation via two branches (`n != MIN`, or `n == MIN && d != -1`) whose
/// only COMMON fact is `d != 0`; the OR
/// `(d!=0 ∧ n!=MIN) ∨ (d!=0 ∧ n==MIN ∧ d!=-1)` = `d!=0 ∧ !(n==MIN ∧ d==-1)` REFUTES the
/// `n==MIN ∧ d==-1` violation, where the bare intersection (`d!=0`) cannot.
///
/// SOUNDNESS: `target reached ⟹ some enumerated path's facts hold ⟹ the OR`, so the OR
/// is a sound over-approximation of reachability — conjoining it removes only INFEASIBLE
/// counterexamples (a real violation reaches `target`, hence satisfies the OR), never a
/// real one. This holds ONLY when EVERY path is enumerated, so we BAIL to `None` (→ the
/// audited intersection alone) when the CFG carries a Call/Drop/Opaque terminator (whose
/// successors the walk does not thread — a missed path would UNDER-approximate the OR and
/// be unsound), when the path cap is exceeded, or when a path reaches `target`
/// UNCONDITIONALLY (`OR = true`, no constraint). Same cyclic handling as the intersection
/// (`keep_block_defs` drops loop-stale block-defs; the loop-guard EDGE facts hold every
/// iteration). Bool defs are dropped so the OR stays pure-int (QF_LIA, certifiable).
fn reconstruct_reachability_condition(
    func: &VerifiableFunction,
    target: BlockId,
) -> Option<Formula> {
    const MAX_PATHS: usize = 64;
    let blocks = &func.body.blocks;
    // SOUND-enumeration precondition: every terminator must be one the walk threads
    // COMPLETELY (Goto/Assert/SwitchInt) or a terminal (Return/Unreachable/Resume). A
    // Call/Drop/Opaque could route a path to `target` the walk does not follow, making the
    // OR an UNDER-approximation (unsound) — bail to the intersection.
    for b in blocks {
        match &b.terminator {
            Terminator::Goto(_)
            | Terminator::Assert { .. }
            | Terminator::SwitchInt { .. }
            | Terminator::Return
            | Terminator::Unreachable
            | Terminator::Resume => {}
            _ => return None,
        }
    }
    let keep_block_defs = !cfg_has_back_edge(func);
    let mut paths: Vec<Vec<Formula>> = Vec::new();
    // Per-path state carries, beyond the facts and the visited set, the set of
    // block-def DEST NAMES already bound on this path. The flat AND-of-facts encoding
    // assumes every envelope dest is SINGLE-ASSIGNMENT (one stable value); a SECOND
    // def of the same dest on one path (`_3 = a` then `_3 = b`) breaks that — the
    // conjunction `_3=a ∧ _3=b` is contradictory, which would make this disjunct
    // spuriously FALSE and DROP a real reaching path from the OR (under-approximation,
    // unsound). The audited intersection only conjoins so it never drops a disjunct;
    // the OR can, so it needs this guard the intersection does not. On any such
    // cross-block reassignment we BAIL the whole reachability to None (→ the audited
    // intersection alone). Sound (bail is conservative) and rare (the reproducible
    // envelope — Use / comparison / Len — is SSA in practice).
    let mut stack: Vec<(BlockId, Vec<Formula>, Vec<BlockId>, Vec<String>)> =
        vec![(BlockId(0), Vec::new(), Vec::new(), Vec::new())];
    while let Some((bid, facts, visited, def_dests)) = stack.pop() {
        if bid == target {
            let mut final_facts = facts;
            let mut final_dests = def_dests;
            if keep_block_defs
                && let Some(tb) = blocks.iter().find(|b| b.id == target)
                && let Some(defs) = reconstruct_block_definitions(func, tb, true)
            {
                for d in defs.into_iter().filter(|d| !is_bool_eq_def(d)) {
                    if let Some(name) = block_def_dest_name(&d) {
                        if final_dests.contains(&name) {
                            return None; // cross-block reassignment → unsound, bail
                        }
                        final_dests.push(name);
                    }
                    final_facts.push(d);
                }
            }
            paths.push(final_facts);
            if paths.len() > MAX_PATHS {
                return None; // too complex → conservative (no reachability constraint)
            }
            continue;
        }
        if visited.contains(&bid) {
            continue; // back-edge cut (acyclic enumeration)
        }
        let Some(block) = blocks.iter().find(|b| b.id == bid) else {
            continue;
        };
        let mut next_visited = visited.clone();
        next_visited.push(bid);
        let mut next_facts = facts.clone();
        let mut next_dests = def_dests.clone();
        if keep_block_defs && let Some(defs) = reconstruct_block_definitions(func, block, true) {
            for d in defs.into_iter().filter(|d| !is_bool_eq_def(d)) {
                if let Some(name) = block_def_dest_name(&d) {
                    if next_dests.contains(&name) {
                        return None; // cross-block reassignment → unsound, bail
                    }
                    next_dests.push(name);
                }
                next_facts.push(d);
            }
        }
        match &block.terminator {
            Terminator::Goto(t) | Terminator::Assert { target: t, .. } => {
                stack.push((*t, next_facts, next_visited, next_dests));
            }
            Terminator::SwitchInt { discr, targets, otherwise, .. } => {
                let bool_discr = switchint_discr_fact(func, discr);
                for (val, t) in targets {
                    let mut ff = next_facts.clone();
                    if let Some(d) = &bool_discr {
                        ff.push(if *val == 0 {
                            Formula::Not(Box::new(d.clone()))
                        } else {
                            d.clone()
                        });
                    }
                    stack.push((*t, ff, next_visited.clone(), next_dests.clone()));
                }
                let mut ff = next_facts;
                if let Some(d) = &bool_discr
                    && targets.len() == 1
                    && targets[0].0 == 0
                {
                    ff.push(d.clone());
                }
                stack.push((*otherwise, ff, next_visited, next_dests));
            }
            _ => {}
        }
    }
    if paths.is_empty() {
        return None;
    }
    // OR over paths of (AND of that path's facts). A path with NO facts reaches `target`
    // UNCONDITIONALLY → its conjunction is `true` → the whole OR is `true` (no constraint);
    // bail to None (conservative — an unguarded path means the violation is feasible).
    let mut disjuncts: Vec<Formula> = Vec::with_capacity(paths.len());
    for fs in paths {
        match fs.len() {
            0 => return None,
            1 => disjuncts.push(fs.into_iter().next().expect("len 1")),
            _ => disjuncts.push(Formula::And(fs)),
        }
    }
    Some(match disjuncts.len() {
        1 => disjuncts.into_iter().next().expect("len 1"),
        _ => Formula::Or(disjuncts),
    })
}

/// The SOUND dominating path facts for `target` — the SwitchInt edge conditions +
/// block-defs that hold on EVERY acyclic path from entry to `target` (set
/// intersection). Each fact is VALID whenever `target` executes, so conjoining them
/// onto an obligation formula is sound (it can only refute infeasible
/// counterexamples — flip Failed→Proved only when no feasible violation exists,
/// never hide one). Bool SwitchInt edges (`if cond`) contribute `cond` / `Not(cond)`;
/// int/multi-target switches and unrepresentable discriminants contribute NO edge
/// fact (conservative). Path enumeration is capped (sound: a too-complex CFG yields
/// no facts, i.e. the bare conservative formula). A back-edge (loop) is cut by the
/// per-path visited set, so a loop body keeps the loop-entry guard (valid on every
/// iteration) without the loop-carried facts (conservative).
fn reconstruct_sound_dominating_guards(func: &VerifiableFunction, target: BlockId) -> Vec<Formula> {
    const MAX_PATHS: usize = 64;
    let blocks = &func.body.blocks;
    // SOUNDNESS (loops): in a CYCLIC function, a block-DEF on the path to `target`
    // (`i = 0` before the loop) is STALE on later iterations — `target` re-executes
    // with a different `i`, so the def does NOT hold every time `target` runs.
    // Including it would FALSE-PROVE a loop-body obligation that depends on it (e.g.
    // `loop { arr[i]; i += 1 }` — `arr[i]` is in-bounds only on the `i=0` iteration).
    // So for a cyclic CFG we keep ONLY the SwitchInt EDGE guards (a loop-header
    // condition `i < len` IS re-checked and holds every iteration the body runs) and
    // DROP all block-defs. Acyclic CFGs have no staleness, so they keep both.
    let keep_block_defs = !cfg_has_back_edge(func);
    let mut paths: Vec<Vec<Formula>> = Vec::new();
    // (block, facts-so-far, blocks-visited-on-this-path)
    let mut stack: Vec<(BlockId, Vec<Formula>, Vec<BlockId>)> =
        vec![(BlockId(0), Vec::new(), Vec::new())];
    while let Some((bid, facts, visited)) = stack.pop() {
        if bid == target {
            // Include the TARGET block's OWN block-defs — the obligation lives here, so
            // a length/operand temp computed IN this block holds when the obligation
            // runs. Notably a CONSTANT-index access (`s[3]`) recomputes `_4 = Len(s)`
            // locally rather than reusing the guard's `Len` temp; without its
            // `Eq(_4, s__slice_len)` link a dominating `if s.len() > 5` guard cannot
            // discharge `3 >= _4` (the temp stays unconstrained → spurious CEX). Sound:
            // SSA value-defs, position-independent and true whenever the block runs;
            // bool defs dropped (ay-certify); for a cyclic CFG `keep_block_defs` is
            // false so a loop-carried target def is never assumed. An UNGUARDED access
            // gets the link too but no `i < _4` guard, so its violation stays SAT and
            // the mutant still fails closed.
            let mut final_facts = facts;
            if keep_block_defs
                && let Some(tb) = blocks.iter().find(|b| b.id == target)
                && let Some(defs) = reconstruct_block_definitions(func, tb, true)
            {
                final_facts.extend(defs.into_iter().filter(|d| !is_bool_eq_def(d)));
            }
            paths.push(final_facts);
            if paths.len() > MAX_PATHS {
                return Vec::new(); // too complex → conservative (no facts)
            }
            continue;
        }
        if visited.contains(&bid) {
            continue; // back-edge / revisit → cut (conservative)
        }
        let Some(block) = blocks.iter().find(|b| b.id == bid) else {
            continue;
        };
        let mut next_visited = visited.clone();
        next_visited.push(bid);
        // Accumulate this block's definitions (sound — real definitions). A block
        // whose defs we cannot reproduce contributes none (conservative).
        let mut next_facts = facts.clone();
        if keep_block_defs && let Some(defs) = reconstruct_block_definitions(func, block, true) {
            // Drop BOOL defs (`Eq(_2:Bool, x<100)`): the SwitchInt edge fact is
            // already RESOLVED to the pure-int comparison (`x<100`) directly, so
            // keeping the bool def would re-introduce a bool var and the bool+int
            // MIXED structure that ay's UNSAT-proof reconstruction cannot certify
            // (it falls back to "trust" → the obligation is retained runtime-checked
            // instead of statically discharged). Dropping a sound assumption is
            // conservative (never unsound). Pure-int (QF_LIA) facts certify.
            next_facts.extend(defs.into_iter().filter(|d| !is_bool_eq_def(d)));
        }
        match &block.terminator {
            Terminator::Goto(t) | Terminator::Assert { target: t, .. } => {
                stack.push((*t, next_facts, next_visited));
            }
            Terminator::SwitchInt { discr, targets, otherwise, .. } => {
                let bool_discr = switchint_discr_fact(func, discr);
                for (val, t) in targets {
                    let mut ff = next_facts.clone();
                    if let Some(d) = &bool_discr {
                        // bool switch: value 0 ⇒ `Not(d)`, non-zero ⇒ `d`.
                        ff.push(if *val == 0 {
                            Formula::Not(Box::new(d.clone()))
                        } else {
                            d.clone()
                        });
                    }
                    stack.push((*t, ff, next_visited.clone()));
                }
                // The `otherwise` edge is the complement of every listed value. For
                // the common single-target bool `if` (`targets = [(0, else)]`,
                // `otherwise = then`) that is `d` (true). For any other shape we add
                // NO otherwise fact (conservative).
                let mut ff = next_facts;
                if let Some(d) = &bool_discr
                    && targets.len() == 1
                    && targets[0].0 == 0
                {
                    ff.push(d.clone());
                }
                stack.push((*otherwise, ff, next_visited));
            }
            // Return/Unreachable/Resume: no successor toward `target`. Drop/Call/Opaque:
            // not threaded (a `target` reached only through one is simply never found →
            // no path → no facts; conservative).
            _ => {}
        }
    }
    if paths.is_empty() {
        return Vec::new();
    }
    let (first, rest) = paths.split_first().expect("non-empty");
    // Keep only facts present on EVERY path (sound dominating intersection).
    first.iter().filter(|f| rest.iter().all(|p| p.contains(f))).cloned().collect()
}

/// The SwitchInt edge fact for a bool `if`-discriminant, RESOLVED to a pure-int
/// formula whenever possible. `if x < 100 { … }` lowers to `_2 = (x < 100);
/// SwitchInt(_2)` — we return the underlying comparison `Lt(x, 100)` (the
/// `_2`-definition's RHS) so the edge fact is pure QF_LIA (`x < 100`), NOT the bool
/// var `_2`. This keeps the obligation formula bool-free, which ay's UNSAT-proof
/// reconstruction can certify (a bool+int mixed formula trips it). When `_2` has no
/// reproducible comparison definition we fall back to the bare bool `Var(_2, Bool)`
/// (sound, but won't certify); a non-bool discriminant contributes no fact.
fn switchint_discr_fact(func: &VerifiableFunction, discr: &Operand) -> Option<Formula> {
    let (Operand::Copy(p) | Operand::Move(p)) = discr else {
        return None;
    };
    if !p.projections.is_empty() {
        return None;
    }
    let decl = func.body.locals.iter().find(|d| d.index == p.local)?;
    if !matches!(decl.ty, Ty::Bool) {
        return None;
    }
    // Resolve `_2` to its defining comparison `cmp(a, b)` (pure-int).
    if let Some(resolved) = resolve_bool_comparison_def(func, p.local) {
        return Some(resolved);
    }
    // Fallback: the bare bool var (sound; bool+int won't certify).
    let name = safety_place_var_name(&func.body.locals, p)?;
    Some(Formula::var(&name, Sort::Bool))
}

/// The pure-int comparison `cmp(a, b)` defining bool local `local` (`_local = a < b`),
/// reproduced via `reconstruct_comparison_binop` — but ONLY when `local` has EXACTLY ONE
/// (projection-free) assignment in the whole function.
///
/// Trust #soundness (non-dominating guard false proof): the resolved comparison is used
/// as a SwitchInt edge fact (a dominating path guard). That is sound only if the
/// comparison is the discriminant's reaching definition on EVERY path to the switch. A
/// discriminant assigned a comparison on one path and something else on another
/// (`let cond = if k==0 { i < s.len() } else { true }; if cond { s[i] }`) is NOT
/// path-invariant: resolving it to `i < len` and conjoining that onto the bounds
/// violation FALSELY PROVES the access on the `k!=0` path where `cond` was `true` and
/// `s[i]` runs UNGUARDED (the adversarial audit's `f` fixture). REQUIRING a SINGLE
/// assignment closes this: in valid MIR a local used at the switch must be initialised on
/// every path to it, so a uniquely-assigned local's one definition DOMINATES the switch
/// and the comparison genuinely holds on all paths. Multiple assignments ⇒ return `None`
/// (the caller falls back to the bare bool var, which conjoins no useful fact — sound,
/// conservative).
fn resolve_bool_comparison_def(func: &VerifiableFunction, local: usize) -> Option<Formula> {
    let locals = &func.body.locals;
    // Count projection-free assignments to `local` across the whole function; resolve the
    // comparison ONLY if there is exactly one (so it path-dominates every use).
    let mut found: Option<Formula> = None;
    let mut assignment_count = 0usize;
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else {
                continue;
            };
            if place.local != local || !place.projections.is_empty() {
                continue;
            }
            assignment_count += 1;
            if assignment_count > 1 {
                // Multiple definitions: not path-invariant — fail closed.
                return None;
            }
            if let Rvalue::BinaryOp(op, lhs, rhs) = rvalue {
                // SOUNDNESS (P0, comparison-guard staleness): the resolved comparison
                // `Lt(i, 4)` becomes a SwitchInt EDGE FACT (a dominating guard) over the
                // LIVE `i` symbol. If an operand local is REASSIGNED (`if i<4 { i=b; a[i] }`,
                // or a projected `t.0 = b`) before the guarded access, the one-symbol model
                // makes the guard bind the REASSIGNED index and kernel-CERTIFIES an OOB —
                // the `bf592a1ff1` bug expressed through a comparison guard rather than a
                // copy (which `copy_source_is_single_valued`/`gate_stale_copies` already
                // closes). Drop the comparison (→ bare bool var, no useful fact) unless
                // EVERY operand is single-valued.
                if !operand_value_is_stable(func, lhs) || !operand_value_is_stable(func, rhs) {
                    return None;
                }
                let l = safety_operand_to_formula(locals, lhs)?;
                let r = safety_operand_to_formula(locals, rhs)?;
                found = reconstruct_comparison_binop(*op, l, r);
            }
            // A non-comparison single assignment leaves `found = None` (no fact).
        }
    }
    found
}

/// Whether a block-def is a BOOL equality `Eq(Var(_, Bool), _)` — the comparison
/// defs (`_2 = x<100`) that the resolved SwitchInt edge fact makes redundant and
/// whose bool var would re-introduce the bool+int mix that defeats certification.
fn is_bool_eq_def(def: &Formula) -> bool {
    matches!(def, Formula::Eq(a, _) if matches!(a.as_ref(), Formula::Var(_, Sort::Bool)))
}

/// The DEST var NAME of a block-def `Eq(Var(name, _), rhs)`, applied ONLY to the
/// output of [`reconstruct_block_definitions`] (genuine assignment defs, whose LHS is
/// always the assignment destination — a temp/local, never a param), so
/// [`reconstruct_reachability_condition`] can detect a cross-block reassignment of the
/// same dest on one path (which would make the flat AND-of-defs encoding contradictory
/// and unsoundly drop a disjunct). Edge facts are pushed on a separate code path and
/// never reach this helper.
fn block_def_dest_name(def: &Formula) -> Option<String> {
    if let Formula::Eq(lhs, _) = def
        && let Formula::Var(name, _) = lhs.as_ref()
    {
        Some(name.clone())
    } else {
        None
    }
}

/// Map each SLICE-LENGTH local's var NAME to its CANONICAL slice-length formula, for
/// every local in `func` defined by `_l = PtrMetadata(slice)` or `_l = Len(slice)`
/// whose `slice` resolves through [`reconstruct_slice_len_formula`] (a `&[T]`/`*[T]`/
/// `[T]` slice → `Var("{slice}__slice_len", Int)`; an array → its constant length).
///
/// WHY this is needed for sound-AND-complete native bounds proofs. rustc lowers a
/// guarded slice index `if i < s.len() { s[i] }` to TWO INDEPENDENT length locals:
/// `_4 = PtrMetadata(s)` for the user's `i < s.len()` SwitchInt guard, and a SECOND
/// `_5 = PtrMetadata(s)` for the bounds-check `assert(i < _5)`. The native formula is
/// then `env ∧ guard(Lt(i,_4)) ∧ violation(Ge(i,_5))` — and because `_4` and `_5` are
/// distinct free variables, that is SATISFIABLE at `i=0, _4=1, _5=0`: a SPURIOUS
/// counterexample (the guard does not bind the violation's length), so a genuinely
/// in-bounds access is FALSELY REFUTED. Both locals are DEFINED as `PtrMetadata(s)`
/// of the SAME slice, hence provably equal to `len(s)`; rewriting both to the single
/// canonical `s__slice_len` asserts that true equality and lets the guard bind the
/// violation, so `Lt(i,L) ∧ Ge(i,L)` is UNSAT and the access proves.
///
/// Two length locals from the SAME slice map to the SAME canonical formula; locals
/// from DIFFERENT slices map to different ones (so guarding `len(s)` never spuriously
/// bounds an index into a different slice `t`).
fn slice_length_local_canonical_map(func: &VerifiableFunction) -> FxHashMap<String, Formula> {
    let locals = &func.body.locals;
    let mut map = FxHashMap::default();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else {
                continue;
            };
            if !place.projections.is_empty() {
                continue;
            }
            let canonical = match rvalue {
                Rvalue::UnaryOp(UnOp::PtrMetadata, slice_op) => {
                    resolve_ptr_metadata_slice_len(func, slice_op)
                }
                Rvalue::Len(slice_place) => {
                    reconstruct_slice_len_formula(locals, &Operand::Copy(slice_place.clone()))
                }
                _ => None,
            };
            if let Some(canonical) = canonical
                && let Some(name) = safety_place_var_name(locals, place)
            {
                map.insert(name, canonical);
            }
        }
    }
    map
}

/// Resolve the canonical slice-length formula for the operand of a
/// `PtrMetadata(operand)`, threading through a REBORROW / RAW-POINTER of the slice.
///
/// The direct case is `PtrMetadata(s)` for a `&[T]`/`*[T]`/`[T]` local `s` → handled
/// by [`reconstruct_slice_len_formula`]. But a `&mut [T]` re-reads its length through
/// a synthetic reborrow: rustc lowers `dst.len()` (and the bounds check's length) to
/// `_p = &(*dst)` / `_p = &raw const *dst` then `PtrMetadata(_p)`. The reborrow's
/// length metadata is COPIED from the slice, so `PtrMetadata(&(*dst)) == len(dst)`;
/// we therefore resolve `_p` back to its base slice `dst` and return `dst__slice_len`.
/// Without this, the user-guard length (`PtrMetadata(&(*dst))`) and the bounds-check
/// length (`PtrMetadata(&raw const *dst)`) canonicalize to DIFFERENT intermediate
/// names and the guard fails to bind the violation (the `&mut` analogue of the
/// two-`PtrMetadata(s)`-locals problem). SOUND: the reborrow provably shares the base
/// slice's length, so unifying them only conjoins a true equality.
fn resolve_ptr_metadata_slice_len(func: &VerifiableFunction, operand: &Operand) -> Option<Formula> {
    let locals = &func.body.locals;
    // REBORROW / raw-ptr FIRST: `PtrMetadata(_p)` where `_p = Ref(_, *base)` or
    // `_p = AddressOf(_, *base)` (the canonical `&mut [T]` length re-read). Thread to
    // the BASE slice BEFORE the direct case — the reborrow result `_p` is ITSELF a
    // `&[T]`/`*[T]` local, so `reconstruct_slice_len_formula(_p)` would otherwise
    // succeed and stamp the intermediate `_p__slice_len`, leaving the user-guard and
    // bounds-check lengths (two distinct reborrow temps of the SAME `base`) named
    // differently and unable to unify. Resolving to `base__slice_len` for BOTH is what
    // makes the guard bind the violation. The base place must be exactly `*base` (a
    // single `Deref` of the slice local).
    if let Some(place) = match operand {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => Some(p),
        _ => None,
    } {
        for block in &func.body.blocks {
            for stmt in &block.stmts {
                let Statement::Assign { place: dest, rvalue, .. } = stmt else {
                    continue;
                };
                if dest.local != place.local || !dest.projections.is_empty() {
                    continue;
                }
                let base_place = match rvalue {
                    Rvalue::Ref { place: bp, .. } | Rvalue::AddressOf(_, bp) => bp,
                    _ => continue,
                };
                if base_place.projections.as_slice() == [Projection::Deref] {
                    return reconstruct_slice_len_formula(
                        locals,
                        &Operand::Copy(Place::local(base_place.local)),
                    );
                }
            }
        }
    }
    // Direct slice operand (`PtrMetadata(s)` for a slice/array param or local).
    reconstruct_slice_len_formula(locals, operand)
}

/// Rewrite every `Var(length_local, Int)` in `formula` to its canonical slice-length
/// formula (see [`slice_length_local_canonical_map`]). SOUND: each rewritten local is
/// provably equal to `len(slice)` (it IS `PtrMetadata(slice)`/`Len(slice)`), so the
/// substitution only conjoins true equalities — it can REMOVE infeasible models (where
/// two `len(s)` locals disagreed), never add one, so UNSAT is preserved and the VC
/// stays sound (UNSAT ⇒ safe). No-op when the function has no slice-length locals
/// (every non-bounds VC), so it never perturbs overflow/div/shift/neg/cast formulas.
///
/// Applied ONLY to the dispatched NATIVE formula, NOT to the byte-equality flip
/// candidates (which must keep trust-vcgen's raw-local encoding), so the flip path is
/// unaffected.
fn canonicalize_slice_lengths(func: &VerifiableFunction, formula: Formula) -> Formula {
    let map = slice_length_local_canonical_map(func);
    if map.is_empty() {
        return formula;
    }
    formula.map(&mut |f| match &f {
        Formula::Var(name, Sort::Int) => map.get(name).cloned().unwrap_or(f),
        _ => f,
    })
}

/// True when `local` has EXACTLY ONE projection-free assignment in the whole function —
/// `trust_vcgen::is_single_static_assignment`. Required for soundness of every GLOBAL
/// fact keyed to a derived local (`dest = a & m ⟹ dest <= m`): if `dest` were assigned
/// elsewhere too, the fact would not hold for that other value.
fn native_is_single_assignment(func: &VerifiableFunction, local: usize) -> bool {
    func.body
        .blocks
        .iter()
        .flat_map(|b| &b.stmts)
        .filter(|s| {
            matches!(s, Statement::Assign { place, .. } if place.local == local && place.projections.is_empty())
        })
        .count()
        == 1
}

/// Global facts from unsigned `dest = a & m` with a CONSTANT non-negative mask `m`:
/// `dest <= m` holds unconditionally (bitwise-AND only clears bits), so conjoining it
/// onto every VC is SOUND (a provably-true fact — removes infeasible models, never adds
/// one) and discharges a masked index `s[i & 15]` into `[_; 16]` (`i & 15 <= 15 < 16`)
/// and a masked narrowing cast `(x & 0xFF) as u8`. Faithful port of
/// `trust_vcgen::build_bitmask_bound_facts` (single-assignment dest, unsigned operand,
/// non-negative constant mask, collision-safe dest var name) so the dispatched native
/// formula carries the same fact vcgen proves with.
fn native_bitmask_bound_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: dest,
                rvalue: Rvalue::BinaryOp(BinOp::BitAnd, a, b),
                ..
            } = stmt
            else {
                continue;
            };
            if !dest.projections.is_empty() || !native_is_single_assignment(func, dest.local) {
                continue;
            }
            // Unsigned masked operand only (so `a & m <= m`; a signed `a` could be
            // negative and the bound would not hold).
            if !native_operand_ty(locals, a)
                .is_some_and(|t| t.int_width().is_some() && !t.is_signed())
            {
                continue;
            }
            let mask = match b {
                Operand::Constant(ConstValue::Uint(v, _)) if *v <= i128::MAX as u128 => *v as i128,
                Operand::Constant(ConstValue::Int(v)) if *v >= 0 => *v,
                _ => continue,
            };
            let dest_var = Formula::var(&collision_safe_local_name(locals, dest.local), Sort::Int);
            facts.push(Formula::Le(Box::new(dest_var), Box::new(Formula::Int(mask))));
        }
    }
    facts
}

/// `(min, max)` integer range of a `(width, signed)` type as `i128`. `None` for widths
/// over 64 (conservative — the 128-bit range does not fit `i128`, so such a cast is not
/// treated as value-preserving and gets no fact).
fn native_int_min_max(width: u32, signed: bool) -> Option<(i128, i128)> {
    if width == 0 || width > 64 {
        return None;
    }
    if signed {
        Some((-(1i128 << (width - 1)), (1i128 << (width - 1)) - 1))
    } else {
        Some((0, (1i128 << width) - 1))
    }
}

/// True when `from as to` PRESERVES the mathematical value for EVERY input — i.e. the
/// source type's range is a SUBSET of the target's (`u8 -> u32`, `i8 -> i32`, `u8 -> i32`).
/// A signed-to-unsigned or any narrowing cast is NOT value-preserving (`i8 -> u32` maps
/// negatives to large values; `u32 -> u8` truncates), so it returns false.
fn cast_is_value_preserving(from: &Ty, to: &Ty) -> bool {
    let (Some(fw), Some(tw)) = (from.int_width(), to.int_width()) else {
        return false;
    };
    let (Some((fmin, fmax)), Some((tmin, tmax))) =
        (native_int_min_max(fw, from.is_signed()), native_int_min_max(tw, to.is_signed()))
    else {
        return false;
    };
    fmin >= tmin && fmax <= tmax
}

/// Global facts from value-preserving WIDENING casts `_d = a as Wider` (`u8 -> u32`):
/// the widened value equals the source value, so `_d` stays within the SOURCE type's
/// range — conjoin `from_min <= _d <= from_max` (`0 <= _d <= 255`). Sound (a theorem of
/// value-preserving widening), discharges `(a as u32) + 1` overflow (`_d <= 255` ⟹
/// `_d + 1` cannot overflow u32). Gated on a single-assignment, projection-free dest and
/// `cast_is_value_preserving` (so a narrowing / signed->unsigned cast — which can change
/// the value — gets NO fact).
fn native_widening_cast_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place: dest, rvalue: Rvalue::Cast(operand, to_ty), .. } = stmt
            else {
                continue;
            };
            if !dest.projections.is_empty() || !native_is_single_assignment(func, dest.local) {
                continue;
            }
            let Some(from_ty) = native_operand_ty(locals, operand) else {
                continue;
            };
            if !cast_is_value_preserving(&from_ty, to_ty) {
                continue;
            }
            let Some(from_width) = from_ty.int_width() else {
                continue;
            };
            let dest_var = Formula::var(&collision_safe_local_name(locals, dest.local), Sort::Int);
            facts.push(safety_input_range_constraint(&dest_var, from_width, from_ty.is_signed()));
            // Trust: a value-preserving widening cast is the IDENTITY on the value, so the
            // dest EQUALS the source. Conjoin `_d == src` (not merely the STATIC source RANGE
            // above) to carry a DYNAMIC bound across the cast — e.g. `n >= 1` from
            // `num_partitions.max(1) as u64`, so `h % n` cannot divide by zero.
            // SOUNDNESS: `Eq(dest, src)` is a stale-link hazard if `src`'s base local is
            // REASSIGNED (the global fact is conjoined onto EVERY VC, not just those the cast
            // dominates) — exactly the P0 copy-equality channel `reconstruct_block_definitions`
            // guards. Gate on `operand_value_is_stable` (source written at most once total, a
            // param needs zero stores, never mut-borrowed / address-of'd; a constant is always
            // stable). The DEST is already single-assignment + projection-free (guarded above).
            if operand_value_is_stable(func, operand)
                && let Some(src_f) = safety_operand_to_formula(locals, operand)
            {
                facts.push(Formula::Eq(Box::new(dest_var), Box::new(src_f)));
            }
        }
    }
    facts
}

/// Trust (Imp5, native lane): every slice/array length (`Rvalue::Len`) is in `[0, isize::MAX]`
/// — no Rust allocation exceeds `isize::MAX` bytes — so emit `0 <= len <= isize::MAX` for the
/// length result local. The native lane already bounds canonical `*__slice_len` vars
/// (`conjoin_native_slice_len_bounds`), but a BARE `let n = s.len(); n * 2` keeps the length in
/// an ordinary local that machinery never reaches, so the `n * 2` overflow had no bound and
/// fail-FAILED. Bounding the `Rvalue::Len` dest directly tightens that length arithmetic.
/// SOUND: a direct consequence of Rust's allocation invariant — conjoining a true fact can only
/// refute infeasible counterexamples. `isize::MAX = i64::MAX` on the 64-bit targets astream
/// builds for (a weaker-but-true bound on a narrower target). Gated on a single-assignment,
/// projection-free dest (a stable name), exactly like `native_widening_cast_facts`.
fn native_slice_len_value_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place: dest, rvalue: Rvalue::Len(_), .. } = stmt else {
                continue;
            };
            if !dest.projections.is_empty() || !native_is_single_assignment(func, dest.local) {
                continue;
            }
            let dest_var = Formula::var(&collision_safe_local_name(locals, dest.local), Sort::Int);
            facts.push(Formula::Ge(Box::new(dest_var.clone()), Box::new(Formula::Int(0))));
            facts.push(Formula::Le(Box::new(dest_var), Box::new(Formula::Int(i64::MAX as i128))));
        }
    }
    facts
}

/// Trust (native modulo-result bound): for an UNSIGNED `dest = a % b`, the remainder is in
/// `[0, b)` — `0 <= dest` and (when `b != 0`) `dest < b`. Emit `0 <= dest` and
/// `(b == 0) || (dest < b)`. Combined with a dynamic divisor bound (e.g. `n <= u32::MAX`
/// from the value-preserving cast Eq), this discharges astream's `(h % n) as u32` narrowing
/// in `assign_partition`: `h % n < n <= u32::MAX`, so the cast is lossless. SOUND — an
/// unsigned remainder is provably `< its non-zero divisor` (and `>= 0`); the `b == 0`
/// disjunct keeps the fact true on the (here unreachable, since `n = _.max(1) >= 1`)
/// zero-divisor path. Gated on a single-assignment, projection-free dest, like the cast facts.
fn native_modulo_bound_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: dest,
                rvalue: Rvalue::BinaryOp(trust_types::BinOp::Rem, _a, b),
                ..
            } = stmt
            else {
                continue;
            };
            if !dest.projections.is_empty() || !native_is_single_assignment(func, dest.local) {
                continue;
            }
            // Unsigned remainder only: a signed `%` can be negative (`-7 % 3 == -1`).
            let Some(b_ty) = native_operand_ty(locals, b) else { continue };
            if b_ty.int_width().is_none() || b_ty.is_signed() {
                continue;
            }
            let Some(b_f) = safety_operand_to_formula(locals, b) else { continue };
            let dest_var = Formula::var(&collision_safe_local_name(locals, dest.local), Sort::Int);
            facts.push(Formula::Ge(Box::new(dest_var.clone()), Box::new(Formula::Int(0))));
            facts.push(Formula::Or(vec![
                Formula::Eq(Box::new(b_f.clone()), Box::new(Formula::Int(0))),
                Formula::Lt(Box::new(dest_var), Box::new(b_f)),
            ]));
        }
    }
    facts
}

/// The canonical `Ord`-trait method of a stdlib min/max/clamp call. This is only
/// a name recognizer; consumers must additionally authenticate a concrete
/// primitive receiver. A std trait path does not identify the selected impl.
fn native_ord_method(callee: &str) -> Option<&'static str> {
    let method = callee.rsplit("::").next()?.split('<').next().unwrap_or_default().trim();
    match method {
        "min" | "max" | "clamp"
            if is_canonical_trait_method(callee, &["core::cmp::Ord", "std::cmp::Ord"], method) =>
        {
            Some(match method {
                "min" => "min",
                "max" => "max",
                "clamp" => "clamp",
                _ => unreachable!(),
            })
        }
        _ => None,
    }
}

/// True iff `local` is assigned EXACTLY ONCE (Assign stmt OR Call dest) and is never mutably
/// borrowed / raw-pointed — a bridge-local port of `trust_vcgen::is_single_static_assignment`.
/// SOUNDNESS (P0, hunt-5): without the mut-borrow guard, `let mut d = a.min(3); let p = &mut d;
/// *p = e` reassigns `d` (the store's place is `*p`, not `d`, so the def scan misses it), and
/// the stale `Ord` fact `d <= a` survives + kernel-CERTIFIES a violated VC. A `*const`/`*mut`
/// raw pointer is a valid mutation root, so `AddressOf(_)` of either mutability also disqualifies.
fn native_local_is_stable(func: &VerifiableFunction, local: usize) -> bool {
    let mut count = 0u32;
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            if let Statement::Assign { place, rvalue, .. } = stmt {
                if let Rvalue::Ref { mutable: true, place: borrowed }
                | Rvalue::AddressOf(_, borrowed) = rvalue
                    && borrowed.local == local
                {
                    return false;
                }
                if place.local == local {
                    if place.projections.first() == Some(&trust_types::Projection::Deref) {
                        continue;
                    }
                    if !place.projections.is_empty() {
                        return false;
                    }
                    count += 1;
                }
            }
        }
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.local == local
        {
            if !dest.projections.is_empty() {
                return false;
            }
            count += 1;
        }
    }
    count == 1
}

/// True iff `local` holds a SINGLE value everywhere — sound to use as the SOURCE of a
/// copy-equality `Eq(dest, src)` that is conjoined as a GLOBAL block-def fact. Unlike
/// `native_local_is_stable` (which is `count == 1`, correct only for a non-param temp
/// that needs its one def), this is PARAM-AWARE: a parameter carries an implicit ENTRY
/// value, so ANY store to it is a REASSIGNMENT and overloads its single symbol. A
/// mutable borrow / raw pointer of `local` is a valid mutation root and also disqualifies.
///
/// SOUNDNESS (P0 regression, native-L0 default-on): `reconstruct_block_definitions` emitted
/// `Eq(_5, _1)` for `_5 = Copy(_1)` even when `_1` is reassigned (`if i<4 { let _5=i; i=b;
/// a[i] }`). With one symbol per local, `_5 == _1` (capturing `i_before`) is asserted at
/// LEVEL 0 alongside the reassignment `_1 == b`, so the guard `_5 < 4 ∧ _5 == _1` bounds the
/// REASSIGNED index `_1` and kernel-CERTIFIES an out-of-bounds access. Gating the copy
/// equality on this predicate drops the stale link; the legit non-reassigned `if i<4 {a[i]}`
/// keeps it (param `i` has zero stores) and still proves.
fn copy_source_is_single_valued(func: &VerifiableFunction, local: usize) -> bool {
    let is_param = local >= 1 && local <= func.body.arg_count;
    let mut assigns = 0u32;
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            if let Statement::Assign { place, rvalue, .. } = stmt {
                if let Rvalue::Ref { mutable: true, place: borrowed }
                | Rvalue::AddressOf(_, borrowed) = rvalue
                    && borrowed.local == local
                {
                    return false;
                }
                if place.local == local && place.projections.is_empty() {
                    assigns += 1;
                }
            }
        }
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.local == local
            && dest.projections.is_empty()
        {
            assigns += 1;
        }
    }
    if is_param { assigns == 0 } else { assigns <= 1 }
}

/// SOUNDNESS (comparison-operand staleness, P0): whether the VALUE read by `operand` is
/// stable across the function — i.e. its base local is written AT MOST ONCE total. Unlike
/// [`copy_source_is_single_valued`] (which counts only PROJECTION-FREE whole-local
/// stores, the right gate for a `dest = Copy(src)` whole-value link), this counts
/// PROJECTED stores too (`t.0 = b`), so it also closes the tuple-field reassignment
/// channel. A constant operand is always stable; a mut-borrow / address-of of the local
/// disqualifies it (an aliased store could reassign). Used to gate a resolved comparison
/// EDGE GUARD `Lt(i, 4)`: if `i` is reassigned the guard would bind the reassigned index.
fn operand_value_is_stable(func: &VerifiableFunction, operand: &Operand) -> bool {
    let (Operand::Copy(p) | Operand::Move(p)) = operand else {
        return true; // a constant carries no reassignable local
    };
    let local = p.local;
    let is_param = local >= 1 && local <= func.body.arg_count;
    let mut stores = 0u32;
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            if let Statement::Assign { place, rvalue, .. } = stmt {
                if let Rvalue::Ref { mutable: true, place: borrowed }
                | Rvalue::AddressOf(_, borrowed) = rvalue
                    && borrowed.local == local
                {
                    return false;
                }
                // Count BOTH whole-local and projected (`t.0 = …`) stores.
                if place.local == local {
                    stores += 1;
                }
            }
        }
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.local == local
        {
            stores += 1;
        }
    }
    if is_param { stores == 0 } else { stores <= 1 }
}

/// Global facts from the ordered stdlib `min`/`max`/`clamp` calls — port of
/// trust-vcgen's Ord-call modeling. For `_d = min(a, b)`: `_d <= a ∧ _d <= b`; for
/// `max`: `_d >= a ∧ _d >= b`; for `clamp(x, lo, hi)`: `lo <= _d ∧ _d <= hi`. Each is a
/// THEOREM of the integer `Ord` op, so conjoining onto every VC is sound and discharges a
/// clamped index `arr[n.min(3)]` (`min(n,3) <= 3 < len`). dest is projection-free,
/// int-typed, collision-safe, and SINGLE-STATIC-ASSIGNMENT (not mut-borrowed/reassigned —
/// else the bound goes stale, a P0 false proof); args via the faithful operand formula.
fn native_ord_minmax_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut facts = Vec::new();
    for block in &func.body.blocks {
        let Terminator::Call { func: callee, args, dest, .. } = &block.terminator else {
            continue;
        };
        let Some(method) = native_ord_method(callee) else {
            continue;
        };
        if !dest.projections.is_empty() {
            continue;
        }
        if !native_local_is_stable(func, dest.local) {
            continue;
        }
        // Int-typed dest only (the operand formulas are `Sort::Int`).
        if !locals
            .iter()
            .find(|d| d.index == dest.local)
            .is_some_and(|d| d.ty.int_width().is_some())
        {
            continue;
        }
        let Some(dest_ty) = locals.iter().find(|d| d.index == dest.local).map(|d| &d.ty) else {
            continue;
        };
        if !matches!(dest_ty, Ty::Int { .. } | Ty::PtrSizedInt { .. })
            || !args
                .iter()
                .all(|arg| native_operand_ty(locals, arg).is_some_and(|arg_ty| &arg_ty == dest_ty))
        {
            continue;
        }
        let dest_var = Formula::var(&collision_safe_local_name(locals, dest.local), Sort::Int);
        let arg_f =
            |i: usize| -> Option<Formula> { safety_operand_to_formula(locals, args.get(i)?) };
        match method {
            "min" if args.len() == 2 => {
                for i in 0..2 {
                    if let Some(a) = arg_f(i) {
                        facts.push(Formula::Le(Box::new(dest_var.clone()), Box::new(a)));
                    }
                }
            }
            "max" if args.len() == 2 => {
                for i in 0..2 {
                    if let Some(a) = arg_f(i) {
                        facts.push(Formula::Ge(Box::new(dest_var.clone()), Box::new(a)));
                    }
                }
            }
            "clamp" if args.len() == 3 => {
                // SOUNDNESS (P0, hunt-5): `clamp(x, lo, hi)` PANICS when `lo > hi`, so
                // `lo <= dest <= hi` holds ONLY on the `lo <= hi` path. Emitting it
                // unconditionally made `lo > hi` a CONTRADICTION that vacuously proved (and
                // kernel-CERTIFIED!) any downstream obligation while clamp panics at runtime.
                // Emit the CONDITIONAL bound `(lo <= hi) -> (lo <= dest <= hi)` (mirrors the
                // trust-vcgen default-mode fix): no constraint when `lo > hi`, the bound when
                // `lo <= hi`. Both operands required.
                if let (Some(lo), Some(hi)) = (arg_f(1), arg_f(2)) {
                    facts.push(Formula::Or(vec![
                        Formula::Gt(Box::new(lo.clone()), Box::new(hi.clone())),
                        Formula::And(vec![
                            Formula::Ge(Box::new(dest_var.clone()), Box::new(lo)),
                            Formula::Le(Box::new(dest_var.clone()), Box::new(hi)),
                        ]),
                    ]));
                }
            }
            _ => {}
        }
    }
    facts
}

// ===========================================================================================
// #50 BOUNDED-REDUCTION ACCUMULATOR FACTS — trust-ir-native PORT of trust-vcgen's
// `build_accumulator_bound_facts` recognizer (generate.rs). The native universal lane drops
// block-defs for cyclic CFGs (sound, anti-staleness), so it lacks the loop-invariant
// accumulator bound `t <= C + K*MAX(ELEM)` that lets a per-iteration overflow check on a
// fixed-array reduction discharge. This is a FAITHFUL hand-port (the existing native_*_facts
// pattern keeps the bridge's production link closure vcgen-free; trust-vcgen stays a dev-only
// dep used solely by the parity oracle). Every gate that makes the bound SOUND is preserved
// verbatim from vcgen — the single-loop const trip count, the `accumulator_init_const`
// mut-borrow / raw-pointer / call-clobber withholding, and the self-limiting `init + K*M`
// arithmetic. A faithfulness parity test (`accumulator_port_matches_vcgen`) pins this port to
// `trust_vcgen::accumulator_bound_pairs`. Function names mirror their vcgen originals.
// ===========================================================================================

/// Port of `trust_vcgen`'s crate-level `local_ty`: the declared type of `local`.
fn acc_local_ty(func: &VerifiableFunction, local: usize) -> Option<Ty> {
    func.body.locals.iter().find(|d| d.index == local).map(|d| d.ty.clone())
}

/// Port of `trust_vcgen::unique_whole_local_def` (lib.rs) INCLUDING the soundness-critical
/// deref-store skip: a write THROUGH the reference (`*L = v`) mutates the POINTEE, not what
/// `L` is, so it does not make L's value ambiguous; a field/index store or a SECOND whole-local
/// def does. Returns the sole whole-local rvalue def, or None if ambiguous.
fn acc_unique_whole_local_def(func: &VerifiableFunction, local: usize) -> Option<&Rvalue> {
    let mut found: Option<&Rvalue> = None;
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else { continue };
            if place.local != local {
                continue;
            }
            if place.projections.first() == Some(&Projection::Deref) {
                continue;
            }
            if !place.projections.is_empty() || found.is_some() {
                return None;
            }
            found = Some(rvalue);
        }
    }
    found
}

/// Read an operand as a known integer constant. Port of `operand_const_int`.
fn acc_operand_const_int(op: &Operand) -> Option<i128> {
    match op {
        Operand::Constant(ConstValue::Int(c)) => Some(*c),
        Operand::Constant(ConstValue::Uint(c, _)) if *c <= i128::MAX as u128 => Some(*c as i128),
        _ => None,
    }
}

/// The Some-payload projection `[Downcast(1), Field(0)]`. Port of `is_some_payload_projection`.
fn acc_is_some_payload_projection(projections: &[Projection]) -> bool {
    matches!(projections, [Projection::Downcast(1), Projection::Field(0)])
}

fn acc_callee_is_iterator_next(callee: &str) -> bool {
    is_canonical_iterator_method(callee, "Iterator", "::next")
}

fn acc_callee_is_into_iter(callee: &str) -> bool {
    is_canonical_iterator_method(callee, "IntoIterator", "::into_iter")
}

/// `Iterator::rev` — transparent for tracing the underlying `[start,end)` Range (yields the
/// same value set reversed). Port of `callee_is_rev`.
fn acc_callee_is_rev(callee: &str) -> bool {
    is_canonical_iterator_method(callee, "Iterator", "::rev")
}

/// EXCLUSIVE `std::ops::Range` only. Port of `aggregate_is_exclusive_range`.
fn acc_aggregate_is_exclusive_range(name: &str) -> bool {
    matches!(name, "std::ops::Range" | "core::ops::Range" | "core::ops::range::Range")
}

/// CFG successors of a terminator. Port of `terminator_succs`.
fn acc_terminator_succs(t: &Terminator) -> Vec<usize> {
    match t {
        Terminator::Goto(b) => vec![b.0],
        Terminator::SwitchInt { targets, otherwise, .. } => {
            targets.iter().map(|(_, b)| b.0).chain(std::iter::once(otherwise.0)).collect()
        }
        Terminator::Assert { target, .. } | Terminator::Drop { target, .. } => vec![target.0],
        Terminator::Call { target, .. } => target.iter().map(|b| b.0).collect(),
        Terminator::Opaque { targets, .. } => targets.iter().map(|b| b.0).collect(),
        _ => Vec::new(),
    }
}

/// Distinct loop headers = distinct back-edge targets via iterative DFS. Port of
/// `count_back_edges` (measures the loop count EXACTLY for any CFG).
fn acc_count_back_edges(func: &VerifiableFunction) -> usize {
    let blocks = &func.body.blocks;
    if blocks.is_empty() {
        return 0;
    }
    let succ: FxHashMap<usize, Vec<usize>> =
        blocks.iter().map(|b| (b.id.0, acc_terminator_succs(&b.terminator))).collect();
    let mut color: FxHashMap<usize, u8> = blocks.iter().map(|b| (b.id.0, 0u8)).collect();
    let mut headers: FxHashSet<usize> = FxHashSet::default();
    let entry = blocks[0].id.0;
    color.insert(entry, 1);
    let mut stack: Vec<(usize, usize)> = vec![(entry, 0)];
    while let Some(&(u, i)) = stack.last() {
        let edges = succ.get(&u).map(Vec::as_slice).unwrap_or(&[]);
        if i < edges.len() {
            stack.last_mut().unwrap().1 += 1;
            let v = edges[i];
            match color.get(&v).copied().unwrap_or(2) {
                0 => {
                    color.insert(v, 1);
                    stack.push((v, 0));
                }
                1 => {
                    headers.insert(v);
                }
                _ => {}
            }
        } else {
            color.insert(u, 2);
            stack.pop();
        }
    }
    headers.len()
}

/// True if block `start` lies on a CYCLE (its successors can reach it again). Port of
/// `block_is_on_cycle` — distinguishes a loop-driving `next()` from a stray one-shot `next()`.
fn acc_block_is_on_cycle(func: &VerifiableFunction, start: usize) -> bool {
    let succ: FxHashMap<usize, Vec<usize>> =
        func.body.blocks.iter().map(|b| (b.id.0, acc_terminator_succs(&b.terminator))).collect();
    let mut stack: Vec<usize> = succ.get(&start).cloned().unwrap_or_default();
    let mut seen: FxHashSet<usize> = FxHashSet::default();
    while let Some(b) = stack.pop() {
        if b == start {
            return true;
        }
        if seen.insert(b)
            && let Some(s) = succ.get(&b)
        {
            stack.extend(s.iter().copied());
        }
    }
    false
}

/// Trace an `Iterator::next` receiver back to the originating exclusive-`Range`'s
/// `(start, end)` operands, hopping the for-loop desugar + transparent `into_iter`/`rev`.
/// Port of `trace_local_to_range_aggregate`.
fn acc_trace_local_to_range_aggregate(
    func: &VerifiableFunction,
    local: usize,
    fuel: u32,
) -> Option<(&Operand, &Operand)> {
    if fuel == 0 {
        return None;
    }
    if let Some(rvalue) = acc_unique_whole_local_def(func, local) {
        return match rvalue {
            Rvalue::Aggregate(
                trust_types::AggregateKind::Adt { name, variant: 0, .. },
                operands,
            ) if acc_aggregate_is_exclusive_range(name) && operands.len() == 2 => {
                Some((&operands[0], &operands[1]))
            }
            Rvalue::Ref { place, .. } if place.projections.is_empty() => {
                acc_trace_local_to_range_aggregate(func, place.local, fuel - 1)
            }
            Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) if p.projections.is_empty() => {
                acc_trace_local_to_range_aggregate(func, p.local, fuel - 1)
            }
            _ => None,
        };
    }
    for block in &func.body.blocks {
        if let Terminator::Call { func: callee, args, dest, .. } = &block.terminator
            && dest.local == local
            && dest.projections.is_empty()
            && (acc_callee_is_into_iter(callee) || acc_callee_is_rev(callee))
            && args.len() == 1
        {
            if let Operand::Copy(p) | Operand::Move(p) = &args[0]
                && p.projections.is_empty()
            {
                return acc_trace_local_to_range_aggregate(func, p.local, fuel - 1);
            }
            return None;
        }
    }
    None
}

/// Find the `Iterator::next` call with dest `next_result_local`, trace to its Range bounds.
/// Port of `next_call_range_operands`.
fn acc_next_call_range_operands(
    func: &VerifiableFunction,
    next_result_local: usize,
    fuel: u32,
) -> Option<(&Operand, &Operand)> {
    for block in &func.body.blocks {
        if let Terminator::Call { func: callee, args, dest, .. } = &block.terminator
            && dest.local == next_result_local
            && dest.projections.is_empty()
            && acc_callee_is_iterator_next(callee)
            && args.len() == 1
        {
            if let Operand::Copy(p) | Operand::Move(p) = &args[0]
                && p.projections.is_empty()
            {
                return acc_trace_local_to_range_aggregate(func, p.local, fuel);
            }
            return None;
        }
    }
    None
}

/// Trace an iterator local back to its `into_iter` ARGUMENT (the iterated collection). Port
/// of `trace_iter_to_into_iter_arg`.
fn acc_trace_iter_to_into_iter_arg(
    func: &VerifiableFunction,
    local: usize,
    fuel: u32,
) -> Option<Operand> {
    if fuel == 0 {
        return None;
    }
    if let Some(rvalue) = acc_unique_whole_local_def(func, local) {
        return match rvalue {
            Rvalue::Ref { place, .. } if place.projections.is_empty() => {
                acc_trace_iter_to_into_iter_arg(func, place.local, fuel - 1)
            }
            Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) if p.projections.is_empty() => {
                acc_trace_iter_to_into_iter_arg(func, p.local, fuel - 1)
            }
            _ => None,
        };
    }
    for block in &func.body.blocks {
        if let Terminator::Call { func: callee, args, dest, .. } = &block.terminator
            && dest.local == local
            && dest.projections.is_empty()
            && args.len() == 1
            && acc_callee_is_into_iter(callee)
        {
            return Some(args[0].clone());
        }
    }
    None
}

/// Find the `Iterator::next` call with dest `next_result_local`, trace receiver to the
/// iterated array operand. Port of `next_call_to_array_operand`.
fn acc_next_call_to_array_operand(
    func: &VerifiableFunction,
    next_result_local: usize,
    fuel: u32,
) -> Option<Operand> {
    for block in &func.body.blocks {
        if let Terminator::Call { func: callee, args, dest, .. } = &block.terminator
            && dest.local == next_result_local
            && dest.projections.is_empty()
            && acc_callee_is_iterator_next(callee)
            && args.len() == 1
            && let Operand::Copy(p) | Operand::Move(p) = &args[0]
            && p.projections.is_empty()
        {
            return acc_trace_iter_to_into_iter_arg(func, p.local, fuel);
        }
    }
    None
}

/// `(N, MAX(ELEM))` for a fixed array `[ELEM; N]` with unsigned integer `ELEM`. Port of
/// `fixed_array_elem_bound`.
fn acc_fixed_array_elem_bound(elem: &Ty, len: u64) -> Option<(i128, i128)> {
    let width = elem.int_width()?;
    if elem.is_signed() || !elem.is_integer() || width >= 127 {
        return None;
    }
    Some((len as i128, (1i128 << width) - 1))
}

/// For a for-each element local `x` over a FIXED array `[ELEM; N]` (unsigned ELEM), return
/// `(N, MAX(ELEM))`. Port of `for_each_element_fixed_array_bound`.
fn acc_for_each_element_fixed_array_bound(
    func: &VerifiableFunction,
    x_local: usize,
) -> Option<(i128, i128)> {
    const FUEL: u32 = 16;
    let deref_src = match acc_unique_whole_local_def(func, x_local)? {
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
            if matches!(p.projections.as_slice(), [Projection::Deref]) =>
        {
            p.local
        }
        _ => return None,
    };
    let some_local = match acc_unique_whole_local_def(func, deref_src)? {
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
            if matches!(
                p.projections.as_slice(),
                [Projection::Downcast(_), Projection::Field(0)]
            ) =>
        {
            p.local
        }
        _ => return None,
    };
    let array_op = acc_next_call_to_array_operand(func, some_local, FUEL)?;
    match native_operand_ty(&func.body.locals, &array_op)? {
        Ty::Array { elem, len } => acc_fixed_array_elem_bound(&elem, len),
        Ty::Ref { inner, .. } => match *inner {
            Ty::Array { elem, len } => acc_fixed_array_elem_bound(&elem, len),
            _ => None,
        },
        _ => None,
    }
}

/// The index LOCAL of the last `Index(_)` projection in `place`. Port of `index_local_of_place`.
fn acc_index_local_of_place(place: &Place) -> Option<usize> {
    place.projections.iter().rev().find_map(|p| match p {
        Projection::Index(i) => Some(*i),
        _ => None,
    })
}

/// `(K, MAX(ELEM))` for a manual-INDEX reduction addend `x = a[i]` whose unsigned element is
/// indexed by an exclusive-`Range` payload (trip count `K = end - start`). Port of
/// `index_range_reduction_bound`.
fn acc_index_range_reduction_bound(
    func: &VerifiableFunction,
    x_local: usize,
) -> Option<(i128, i128)> {
    const FUEL: u32 = 16;
    let idx_local = match acc_unique_whole_local_def(func, x_local)? {
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) => acc_index_local_of_place(p)?,
        _ => return None,
    };
    let elem_ty = acc_local_ty(func, x_local)?;
    let width = elem_ty.int_width()?;
    if elem_ty.is_signed() || !elem_ty.is_integer() || width >= 127 {
        return None;
    }
    let elem_max = (1i128 << width) - 1;
    let opt_local = match acc_unique_whole_local_def(func, idx_local)? {
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
            if acc_is_some_payload_projection(&p.projections) =>
        {
            p.local
        }
        _ => return None,
    };
    let (start_op, end_op) = acc_next_call_range_operands(func, opt_local, FUEL)?;
    let k = acc_operand_const_int(end_op)?.checked_sub(acc_operand_const_int(start_op)?)?;
    if k < 0 {
        return None;
    }
    Some((k, elem_max))
}

/// The constant init `C` of a self-accumulator IFF its only two whole-local defs are a const
/// `C >= 0` and the self-add. Port of `accumulator_init_const` INCLUDING the soundness guards:
/// bail on a `Call`-terminator dest (`acc = f()` unconstrained), and on a `&mut acc` / raw
/// `AddressOf` of either mutability (aliased write).
fn acc_accumulator_init_const(
    func: &VerifiableFunction,
    acc: usize,
    ck_dest: usize,
) -> Option<i128> {
    let mut init: Option<i128> = None;
    let mut saw_self_add = false;
    let mut def_count = 0usize;
    for block in &func.body.blocks {
        if let Terminator::Call { dest, .. } = &block.terminator
            && dest.local == acc
            && dest.projections.is_empty()
        {
            return None;
        }
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else { continue };
            if let Rvalue::Ref { mutable: true, place: aliased } | Rvalue::AddressOf(_, aliased) =
                rvalue
                && aliased.local == acc
            {
                return None;
            }
            if place.local != acc || !place.projections.is_empty() {
                continue;
            }
            def_count += 1;
            match rvalue {
                Rvalue::Use(Operand::Constant(ConstValue::Int(c))) if *c >= 0 => init = Some(*c),
                Rvalue::Use(Operand::Constant(ConstValue::Uint(c, _)))
                    if *c <= i128::MAX as u128 =>
                {
                    init = Some(*c as i128)
                }
                Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
                    if p.local == ck_dest
                        && matches!(p.projections.as_slice(), [Projection::Field(0)]) =>
                {
                    saw_self_add = true
                }
                _ => return None,
            }
        }
    }
    if def_count == 2 && saw_self_add { init } else { None }
}

/// The single loop's trip count from a reduction element local (array `N` or range
/// `end-start`). Port of `reduction_trip_count`.
fn acc_reduction_trip_count(func: &VerifiableFunction, elem_local: usize) -> Option<i128> {
    acc_for_each_element_fixed_array_bound(func, elem_local)
        .or_else(|| acc_index_range_reduction_bound(func, elem_local))
        .map(|(k, _)| k)
}

/// Upper bound on body executions = PRODUCT of every loop's const trip count; requires every
/// loop to be a const-bounded Range/for-each (so `#on-cycle-next == #back-edges`). Port of
/// `total_loop_iterations`.
fn acc_total_loop_iterations(func: &VerifiableFunction) -> Option<i128> {
    const FUEL: u32 = 16;
    let next_dests: Vec<usize> = func
        .body
        .blocks
        .iter()
        .filter_map(|b| match &b.terminator {
            Terminator::Call { func: callee, dest, .. }
                if acc_callee_is_iterator_next(callee)
                    && dest.projections.is_empty()
                    && acc_block_is_on_cycle(func, b.id.0) =>
            {
                Some(dest.local)
            }
            _ => None,
        })
        .collect();
    if next_dests.is_empty() || next_dests.len() != acc_count_back_edges(func) {
        return None;
    }
    let mut k: i128 = 1;
    for dest in next_dests {
        let tc = if let Some((start, end)) = acc_next_call_range_operands(func, dest, FUEL) {
            acc_operand_const_int(end)?.checked_sub(acc_operand_const_int(start)?)?
        } else if let Some(arr) = acc_next_call_to_array_operand(func, dest, FUEL) {
            match native_operand_ty(&func.body.locals, &arr)? {
                Ty::Array { len, .. } => len as i128,
                Ty::Ref { inner, .. } => match *inner {
                    Ty::Array { len, .. } => len as i128,
                    _ => return None,
                },
                _ => return None,
            }
        } else {
            return None;
        };
        if tc < 0 {
            return None;
        }
        k = k.checked_mul(tc)?;
    }
    Some(k)
}

/// `(l, r)` of a `Mul` (direct or `CheckedMul.0`) producing the addend. Port of
/// `reduction_mul_operands`.
fn acc_reduction_mul_operands(
    func: &VerifiableFunction,
    addend_local: usize,
) -> Option<(Operand, Operand)> {
    match acc_unique_whole_local_def(func, addend_local)? {
        Rvalue::CheckedBinaryOp(BinOp::Mul, l, r) | Rvalue::BinaryOp(BinOp::Mul, l, r) => {
            Some((l.clone(), r.clone()))
        }
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
            if matches!(p.projections.as_slice(), [Projection::Field(0)]) =>
        {
            match acc_unique_whole_local_def(func, p.local)? {
                Rvalue::CheckedBinaryOp(BinOp::Mul, l, r) => Some((l.clone(), r.clone())),
                _ => None,
            }
        }
        _ => None,
    }
}

/// `(base, shift)` of a left-shift (direct or `CheckedShl.0`) producing the addend. Port of
/// `reduction_shl_operands`.
fn acc_reduction_shl_operands(
    func: &VerifiableFunction,
    addend_local: usize,
) -> Option<(Operand, Operand)> {
    match acc_unique_whole_local_def(func, addend_local)? {
        Rvalue::CheckedBinaryOp(BinOp::Shl, l, r) | Rvalue::BinaryOp(BinOp::Shl, l, r) => {
            Some((l.clone(), r.clone()))
        }
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
            if matches!(p.projections.as_slice(), [Projection::Field(0)]) =>
        {
            match acc_unique_whole_local_def(func, p.local)? {
                Rvalue::CheckedBinaryOp(BinOp::Shl, l, r) => Some((l.clone(), r.clone())),
                _ => None,
            }
        }
        _ => None,
    }
}

/// Upper bound on a multiply FACTOR: a non-negative const, or the source-type max of an
/// unsigned-int `Cast`. Port of `factor_max`.
fn acc_factor_max(func: &VerifiableFunction, op: &Operand) -> Option<i128> {
    match op {
        Operand::Constant(ConstValue::Int(c)) if *c >= 0 => Some(*c),
        Operand::Constant(ConstValue::Uint(c, _)) if *c <= i128::MAX as u128 => Some(*c as i128),
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => {
            let Rvalue::Cast(src, _) = acc_unique_whole_local_def(func, p.local)? else {
                return None;
            };
            let ty = native_operand_ty(&func.body.locals, src)?;
            let w = ty.int_width()?;
            if ty.is_signed() || !ty.is_integer() || w >= 127 {
                return None;
            }
            Some((1i128 << w) - 1)
        }
        _ => None,
    }
}

/// The reduction ELEMENT local underlying a multiply factor `x as A`. Port of
/// `factor_elem_local`.
fn acc_factor_elem_local(func: &VerifiableFunction, op: &Operand) -> Option<usize> {
    let (Operand::Copy(p) | Operand::Move(p)) = op else { return None };
    if !p.projections.is_empty() {
        return None;
    }
    let Rvalue::Cast(Operand::Copy(xp) | Operand::Move(xp), _) =
        acc_unique_whole_local_def(func, p.local)?
    else {
        return None;
    };
    if !xp.projections.is_empty() {
        return None;
    }
    Some(xp.local)
}

/// `(trip count K, per-iteration addend max M)` for a recognized addend: (a) widened element
/// `x as A`, (b) product, (c) left-shift `(x as A) << k`. Port of `addend_per_iteration_bound`.
fn acc_addend_per_iteration_bound(
    func: &VerifiableFunction,
    addend_local: usize,
) -> Option<(i128, i128)> {
    if let Some(Rvalue::Cast(Operand::Copy(xp) | Operand::Move(xp), _)) =
        acc_unique_whole_local_def(func, addend_local)
        && xp.projections.is_empty()
        && let Some(kb) = acc_for_each_element_fixed_array_bound(func, xp.local)
            .or_else(|| acc_index_range_reduction_bound(func, xp.local))
    {
        return Some(kb);
    }
    if let Some((base, shift)) = acc_reduction_shl_operands(func, addend_local) {
        let k = acc_operand_const_int(&shift)?;
        if !(0..64).contains(&k) {
            return None;
        }
        let elem = acc_factor_elem_local(func, &base)?;
        let (trip, elem_max) = acc_for_each_element_fixed_array_bound(func, elem)
            .or_else(|| acc_index_range_reduction_bound(func, elem))?;
        let per = elem_max.checked_mul(1i128.checked_shl(k as u32)?)?;
        return Some((trip, per));
    }
    let (f1, f2) = acc_reduction_mul_operands(func, addend_local)?;
    let per = acc_factor_max(func, &f1)?.checked_mul(acc_factor_max(func, &f2)?)?;
    let elem = acc_factor_elem_local(func, &f1).or_else(|| acc_factor_elem_local(func, &f2))?;
    let k = acc_reduction_trip_count(func, elem)?;
    Some((k, per))
}

/// Raw `(accumulator local, upper bound)` pairs — the trip-count × addend-max recognizer.
/// Port of `build_accumulator_bound_facts`'s driver (returns raw locals so the native lane
/// applies its own naming). Soundness inherited verbatim from the ported gates above.
fn acc_bound_pairs(func: &VerifiableFunction) -> Vec<(usize, i128)> {
    let mut pairs = Vec::new();
    let Some(k) = acc_total_loop_iterations(func) else {
        return pairs;
    };
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign {
                place: ck_dest,
                rvalue: Rvalue::CheckedBinaryOp(BinOp::Add, lhs, rhs),
                ..
            } = stmt
            else {
                continue;
            };
            if !ck_dest.projections.is_empty() {
                continue;
            }
            let (Operand::Copy(acc_p) | Operand::Move(acc_p)) = lhs else { continue };
            if !acc_p.projections.is_empty() {
                continue;
            }
            let acc = acc_p.local;
            let per_max = match rhs {
                Operand::Constant(ConstValue::Int(c)) if *c >= 0 => *c,
                Operand::Constant(ConstValue::Uint(c, _)) if *c <= i128::MAX as u128 => *c as i128,
                Operand::Copy(rp) | Operand::Move(rp) if rp.projections.is_empty() => {
                    match acc_addend_per_iteration_bound(func, rp.local) {
                        Some((_, per)) => per,
                        None => continue,
                    }
                }
                _ => continue,
            };
            let Some(init_c) = acc_accumulator_init_const(func, acc, ck_dest.local) else {
                continue;
            };
            let Some(bound) = k.checked_mul(per_max).and_then(|nm| init_c.checked_add(nm)) else {
                continue;
            };
            pairs.push((acc, bound));
        }
    }
    pairs
}

/// Bounded fixed-array REDUCTION accumulator bound (#50) for the trust-ir-native lane: emit
/// the global fact `acc <= C + K*MAX(ELEM)` for each recognized accumulator, under the native
/// `collision_safe_local_name` (the SAME symbol the native overflow obligation names it, so
/// the fact binds). The recognizer `acc_bound_pairs` is a faithful port of vcgen's, so every
/// soundness gate is preserved; a mismatched / absent name can only make the fact vacuous
/// (sound), never wrong.
fn native_accumulator_bound_facts(func: &VerifiableFunction) -> Vec<Formula> {
    let locals = &func.body.locals;
    acc_bound_pairs(func)
        .into_iter()
        .map(|(acc, bound)| {
            Formula::Le(
                Box::new(Formula::var(&collision_safe_local_name(locals, acc), Sort::Int)),
                Box::new(Formula::Int(bound)),
            )
        })
        .collect()
}

/// Conjoin `facts` (provably-true global facts) before `formula`, matching how
/// trust-vcgen prepends its global-fact set. No-op when there are no facts.
fn conjoin_native_global_facts(facts: &[Formula], formula: Formula) -> Formula {
    if facts.is_empty() {
        return formula;
    }
    let mut conj = facts.to_vec();
    conj.push(formula);
    Formula::And(conj)
}

/// Conservatively true only for element types provably >= 1 byte — faithful port of
/// `trust_vcgen::ty_is_definitely_non_zst`. Recurses through Array/Tuple/Adt; returns
/// false for `()`/ZST aggregates/`[T;0]`/unknown (fail-closed toward NOT bounding, the
/// SOUND direction). Gates the slice-length `isize::MAX` upper bound below.
fn native_ty_is_definitely_non_zst(ty: &Ty) -> bool {
    match ty {
        Ty::Bool
        | Ty::Int { .. }
        | Ty::Float { .. }
        | Ty::Ref { .. }
        | Ty::RawPtr { .. }
        | Ty::FnPtr { .. } => true,
        Ty::Bv(w) => *w > 0,
        Ty::Array { elem, len } => *len > 0 && native_ty_is_definitely_non_zst(elem),
        Ty::Tuple(tys) => tys.iter().any(native_ty_is_definitely_non_zst),
        Ty::Adt { fields, .. } => fields.iter().any(|(_, t)| native_ty_is_definitely_non_zst(t)),
        _ => false,
    }
}

/// The `{name}__slice_len` var names whose slice element is provably NON-ZST, from the
/// function's slice-typed locals — port of `trust_vcgen::nonzst_slice_len_vars` (using
/// the collision-safe local name so the canonical `__slice_len` matches the bounds
/// path). Only these names may take the `len <= isize::MAX` upper bound.
fn native_nonzst_slice_len_vars(func: &VerifiableFunction) -> FxHashSet<String> {
    let mut set = FxHashSet::default();
    for decl in &func.body.locals {
        let elem = match &decl.ty {
            Ty::Ref { inner, .. } => match inner.as_ref() {
                Ty::Slice { elem } => Some(elem.as_ref()),
                _ => None,
            },
            Ty::Slice { elem } => Some(elem.as_ref()),
            _ => None,
        };
        if let Some(elem) = elem
            && native_ty_is_definitely_non_zst(elem)
        {
            set.insert(format!(
                "{}__slice_len",
                collision_safe_local_name(&func.body.locals, decl.index)
            ));
        }
    }
    set
}

/// Conjoin slice/array length bounds for every `*__slice_len` term `formula` references
/// — faithful port of `trust_vcgen::conjoin_slice_len_bounds`. The lower bound
/// `0 <= len` holds for ANY element type; the upper bound `len <= isize::MAX` is added
/// ONLY for a provably NON-ZST element. SOUNDNESS-CRITICAL: a ZST slice (`&[()]`) can
/// reach `usize::MAX`, so an unconditional upper bound would FALSE-PROVE `zst.len() + k`
/// overflow — the ZST gate keeps only the (always-true) lower bound there (a false-FAIL
/// at worst, never a false-PROVE). Discharges `s.len() + 1` and guarded length arith for
/// the overwhelmingly common non-ZST slices. Applied AFTER canonicalization so the
/// canonical `__slice_len` vars are present.
fn conjoin_native_slice_len_bounds(func: &VerifiableFunction, formula: Formula) -> Formula {
    let names = formula.free_variables();
    if !names.iter().any(|n| n.ends_with("__slice_len")) {
        return formula;
    }
    let non_zst = native_nonzst_slice_len_vars(func);
    let mut bounds = Vec::new();
    for name in names {
        if name.ends_with("__slice_len") {
            let var = Formula::var(&name, Sort::Int);
            bounds.push(Formula::Ge(Box::new(var.clone()), Box::new(Formula::Int(0))));
            if non_zst.contains(&name) {
                bounds.push(Formula::Le(Box::new(var), Box::new(Formula::Int(i64::MAX as i128))));
            }
        }
    }
    if bounds.is_empty() {
        return formula;
    }
    bounds.push(formula);
    Formula::And(bounds)
}

pub fn generate_native_safety_vcs(func: &VerifiableFunction) -> Option<Vec<VerificationCondition>> {
    let all_blocks = &func.body.blocks;
    let locals = &func.body.locals;
    let function: trust_types::Symbol = func.name.clone().into();
    let mut vcs: Vec<VerificationCondition> = Vec::new();
    // GLOBAL FACTS (provably-true, conjoined onto every VC like trust-vcgen): the
    // unsigned bitmask bound `a & const_mask <= mask` (masked index / narrowing cast) and
    // the ordered `min`/`max`/`clamp` result bounds (`min(n,3) <= 3`). Sound — each fact
    // is a theorem over the function's locals, so conjoining it can only refute infeasible
    // counterexamples, never manufacture a proof.
    let mut global_facts = native_bitmask_bound_facts(func);
    global_facts.extend(native_ord_minmax_facts(func));
    global_facts.extend(native_widening_cast_facts(func));
    // Slice/array length value bound (`0 <= Rvalue::Len <= isize::MAX`) for bare length locals
    // the `*__slice_len` canonicalization does not reach (`let n = s.len(); n * 2`). See
    // `native_slice_len_value_facts`.
    global_facts.extend(native_slice_len_value_facts(func));
    // Unsigned modulo result bound (`0 <= a % b` and `b != 0 -> a % b < b`) so a result
    // narrowing like astream's `(h % n) as u32` proves lossless. See
    // `native_modulo_bound_facts`.
    global_facts.extend(native_modulo_bound_facts(func));
    // Bounded fixed-array reduction accumulator bounds (`t <= C + K*MAX(ELEM)`) — reuses
    // trust-vcgen's exact recognizer so a default-mode-proved reduction proves natively too,
    // closing the superiority gap WITHOUT a divergent native re-derivation. See
    // `native_accumulator_bound_facts`.
    global_facts.extend(native_accumulator_bound_facts(func));
    // SAME-SPAN AMBIGUITY guard (Trust #soundness): the per-class assert reconstruction
    // (`reconstruct_full_safety_formula_candidates`) re-finds the assert by (span, kind),
    // so TWO asserts with the SAME (span, kind) — two `BoundsCheck`s, two same-typed
    // overflows on one source span (macro-expanded code) — would BOTH reconstruct the
    // FIRST one's formula, dispatching the second's obligation with a formula about the
    // first operand (a FALSE PROOF if the second is the unsafe one — the audit's same-span
    // borrow). When a duplicate (span, kind) appears we fail closed (fall back to the
    // flip, which disambiguates by formula-match-count). Signed div/rem's two same-span
    // asserts have DIFFERENT kinds (DivByZero vs ArithmeticOverflow) so they are NOT a
    // collision.
    let mut assert_keys: FxHashSet<String> = FxHashSet::default();

    for block in all_blocks {
        // Assert-terminator safety obligations (overflow/shift/neg/div/rem/bounds).
        if let Terminator::Assert { span, msg, .. } = &block.terminator {
            // A non-safety assert (user `assert!`, panic, unreachable) is modeled
            // differently by trust-vcgen; we cannot reproduce it natively, so the
            // whole function falls back.
            let kind = reconstruct_assert_vc_kind(func, block.id, msg)?;
            if !assert_keys.insert(format!("{span:?}|{kind:?}")) {
                return None; // duplicate (span, kind) → reconstruction is ambiguous
            }
            let base =
                reconstruct_full_safety_formula_candidates(func, span, &kind).into_iter().next()?;
            // COMPLETENESS (sound): conjoin the SOUND dominating path facts reaching
            // this obligation's block (`if x < 100 { x + 1 }` → the `x<100` guard), so
            // a guard-bounded-safe obligation PROVES instead of conservatively failing.
            // Every conjoined fact holds whenever the block is reached, so this can
            // only make the formula MORE provable, never unsound.
            let formula = enrich_with_sound_dominating_guards(func, block.id, base);
            // Conjoin the obligation block's OWN integer defs (`_2 = 2`, `_idx = i * 2`)
            // so a constant / scaled index discharges — these execute in the same
            // iteration as the assert, so they are sound to conjoin (never stale). See
            // `reconstruct_native_own_block_defs`.
            let own_defs = reconstruct_native_own_block_defs(func, block);
            let formula = conjoin_native_global_facts(&own_defs, formula);
            // CANONICALIZE slice-length locals so a guarded slice index's dominating
            // guard binds the bounds violation (rustc emits two distinct `len(s)`
            // locals — one for `i < s.len()`, one for the bounds check). Sound (both
            // are provably `len(s)`); no-op for non-bounds formulas. See
            // `canonicalize_slice_lengths`.
            let formula = canonicalize_slice_lengths(func, formula);
            // Conjoin the slice-length range facts (`0 <= len`, `len <= isize::MAX` for
            // non-ZST) so length arithmetic / guarded length bounds discharge.
            let formula = conjoin_native_slice_len_bounds(func, formula);
            // Conjoin the provably-true global facts (bitmask bounds) so a masked index
            // `s[i & 15]` discharges, exactly as trust-vcgen does.
            let formula = conjoin_native_global_facts(&global_facts, formula);
            // GUARDED BV MUL: the mul-overflow violation uses FRESH bitvector operand vars,
            // which the scalar dominating guards above never constrain — so a mul safe only
            // because of a guard (`if a < 1000 && b < 1000 { a * b }`) would false-Fail.
            // Re-emit each dominating `operand CMP const` fact in BV form over the fresh
            // operand var. Sound (the facts dominate; out-of-range constants declined).
            let formula = if let VcKind::ArithmeticOverflow { op: BinOp::Mul, .. } = &kind {
                let mul_ops = find_block_binary_operands(block, BinOp::Mul).or_else(|| {
                    all_blocks
                        .iter()
                        .find(|b| matches!(&block.terminator, Terminator::Assert { target, .. } if b.id == *target))
                        .and_then(|tb| find_block_binary_operands(tb, BinOp::Mul))
                });
                match mul_ops
                    .and_then(|(l, r)| safety_int_op_type(locals, l, r).map(|(w, s)| (l, r, w, s)))
                {
                    Some((l, r, width, signed)) => {
                        let bv_guards =
                            native_bv_mul_guard_constraints(func, block.id, l, r, width, signed);
                        conjoin_native_global_facts(&bv_guards, formula)
                    }
                    None => formula,
                }
            } else {
                formula
            };
            vcs.push(VerificationCondition {
                kind,
                function: function.clone(),
                location: span.clone(),
                formula,
                contract_metadata: None,
            });
        }
    }

    // COMPLETENESS GATE: the lowered module's safety-obligation set is the
    // authoritative enumeration; require the native count to match it so we never
    // dispatch a set that silently dropped an obligation. (Cases where trust-vcgen
    // emits MORE VCs than the module — e.g. the div/rem assert + co-located
    // statement VC — are caught by the caller's exact set cross-check and fall back.)
    let module = lower_to_trust_ir(func).ok()?;
    let module_safety = module
        .proof_obligations
        .iter()
        .filter(|o| {
            matches!(o.kind, ObligationKind::ArithmeticSafety | ObligationKind::BoundsCheck)
        })
        .count();
    if module_safety != vcs.len() {
        return None;
    }
    Some(vcs)
}

/// Reconstruct the routing `VcKind` of an assert-terminator L0 safety obligation,
/// reading operand types from the assert's binary op / cast / index the way
/// trust-vcgen labels its VCs. `None` for a non-safety assert or an operand outside
/// the envelope (→ the function falls back).
fn reconstruct_assert_vc_kind(
    func: &VerifiableFunction,
    source_block: BlockId,
    msg: &AssertMessage,
) -> Option<VcKind> {
    let all_blocks = &func.body.blocks;
    let locals = &func.body.locals;
    let block_by_id = |id: BlockId| all_blocks.iter().find(|b| b.id == id);
    let target = block_by_id(source_block).and_then(|b| match &b.terminator {
        Terminator::Assert { target, .. } => Some(*target),
        _ => None,
    })?;
    let find_ops = |op: BinOp| {
        block_by_id(source_block)
            .and_then(|b| find_block_binary_operands(b, op))
            .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, op)))
    };
    match msg {
        AssertMessage::Overflow(
            op @ (BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem),
        ) => {
            let (lhs, rhs) = find_ops(*op)?;
            Some(VcKind::ArithmeticOverflow {
                op: *op,
                operand_tys: (native_operand_ty(locals, lhs)?, native_operand_ty(locals, rhs)?),
            })
        }
        AssertMessage::Overflow(op @ (BinOp::Shl | BinOp::Shr)) => {
            let (value, amount) = find_ops(*op)?;
            Some(VcKind::ShiftOverflow {
                op: *op,
                operand_ty: native_operand_ty(locals, value)?,
                shift_ty: native_operand_ty(locals, amount)?,
            })
        }
        AssertMessage::OverflowNeg => {
            let operand = find_target_neg_operand(all_blocks, target, source_block)?;
            Some(VcKind::NegationOverflow { ty: native_operand_ty(locals, operand)? })
        }
        AssertMessage::DivisionByZero => Some(VcKind::DivisionByZero),
        AssertMessage::RemainderByZero => Some(VcKind::RemainderByZero),
        AssertMessage::BoundsCheck => Some(reconstruct_bounds_vc_kind(func)),
        // Non-safety asserts (user assert!, etc.) are not generated natively.
        _ => None,
    }
}

/// `Some` operand of the `UnaryOp(Neg, _)` that the negation-overflow assert guards,
/// found in the assert's target block (then the source block), mirroring
/// trust-vcgen's `v2_find_target_neg_operand`.
fn find_target_neg_operand<'a>(
    all_blocks: &'a [TrustBlock],
    target: BlockId,
    source_block: BlockId,
) -> Option<&'a Operand> {
    let find_in = |id: BlockId| {
        all_blocks.iter().find(|b| b.id == id).and_then(|b| {
            b.stmts.iter().find_map(|s| match s {
                Statement::Assign { rvalue: Rvalue::UnaryOp(UnOp::Neg, op), .. } => Some(op),
                _ => None,
            })
        })
    };
    find_in(target).or_else(|| find_in(source_block))
}

/// Slice vs array bounds: trust-vcgen labels a slice index `SliceBoundsCheck` and an
/// array index `IndexOutOfBounds`. A slice length is recovered via `PtrMetadata`
/// (`v2_place_uses_slice`); an array length is a compile-time constant. So the
/// presence of a `PtrMetadata` length read in the function is the slice signal.
fn reconstruct_bounds_vc_kind(func: &VerifiableFunction) -> VcKind {
    let uses_ptr_metadata = func.body.blocks.iter().any(|b| {
        b.stmts.iter().any(|s| {
            matches!(s, Statement::Assign { rvalue: Rvalue::UnaryOp(UnOp::PtrMetadata, _), .. })
        })
    });
    if uses_ptr_metadata { VcKind::SliceBoundsCheck } else { VcKind::IndexOutOfBounds }
}

/// `(width, signed)`-faithful operand `Ty`, mirroring `trust_vcgen::operand_ty` for
/// the native-generation envelope: a projection-free local → its declared `Ty`; an
/// integer/bool constant → its `operand_ty` type (`Int(64,signed)` for `Int`,
/// `Int(w,unsigned)` for `Uint(_,w)`, `Bool`). Projected/symbolic operands → `None`
/// (→ the function falls back, exactly as the formula reconstruction does).
fn native_operand_ty(locals: &[LocalDecl], op: &Operand) -> Option<Ty> {
    match op {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => {
            locals.iter().find(|d| d.index == p.local).map(|d| d.ty.clone())
        }
        Operand::Constant(ConstValue::Bool(_)) => Some(Ty::Bool),
        Operand::Constant(ConstValue::Int(_)) => Some(Ty::Int { width: 64, signed: true }),
        Operand::Constant(ConstValue::Uint(_, w)) => Some(Ty::Int { width: *w, signed: false }),
        _ => None,
    }
}

/// Reconstruct candidates for a historical/external `CastOverflow` VC at
/// `target_span`. Current trust-vcgen deliberately emits none for integer `as`
/// conversions. This compatibility path does not create an obligation; it only
/// preserves one already supplied to the verdict flip, and only on an exact
/// formula match.
fn reconstruct_cast_formula_candidates(
    func: &VerifiableFunction,
    target_span: &TrustSourceSpan,
) -> Vec<Formula> {
    // Find the `Rvalue::Cast` statement whose span equals the target span.
    let cast = func.body.blocks.iter().find_map(|b| {
        b.stmts.iter().find_map(|stmt| match stmt {
            Statement::Assign { rvalue: Rvalue::Cast(operand, to_ty), span, .. }
                if span == target_span =>
            {
                Some((operand, to_ty))
            }
            _ => None,
        })
    });
    let Some((operand, to_ty)) = cast else {
        return Vec::new();
    };
    // The source type of the cast operand (a direct local or constant).
    let Some(from_ty) = cast_operand_ty(&func.body.locals, operand) else {
        return Vec::new();
    };
    let Some(core) = reconstruct_cast_overflow_body(&func.body.locals, operand, &from_ty, to_ty)
    else {
        return Vec::new();
    };
    augment_candidates_with_param_env(func, vec![core])
}

/// The integer `Ty` of a cast operand that is a direct (projection-free) local or
/// an integer constant — the faithful envelope for cast reconstruction. `None`
/// otherwise (the cast is then not reconstructed; the flip keeps vcgen's formula).
fn cast_operand_ty(locals: &[LocalDecl], operand: &Operand) -> Option<Ty> {
    match operand {
        Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => {
            locals.iter().find(|d| d.index == p.local).map(|d| d.ty.clone())
        }
        _ => None,
    }
}

/// Reconstruct, BYTE-FOR-BYTE, the abstract-interpretation environment formula
/// that the LIVE compiler path conjoins onto every non-discharged safety VC.
///
/// The daily-driver runs `trust_vcgen::generate_vcs_with_discharge`, which builds
/// a merged interval environment and then calls `augment_vc_with_abstract_state`,
/// prepending `interval_domain_to_formula(merged_env)` as the first conjunct of
/// every surviving VC's formula. This function reconstructs that prepended
/// conjunct for the COMMON case where the merged environment is exactly the
/// function's integer PARAMETERS at their full type ranges — i.e. the function
/// has no preconditions that tighten a parameter and the fixpoint introduces no
/// other finitely-bounded local. That case is fully determined by
/// `func.body.locals[1..=arg_count]`.
///
/// It mirrors `trust_vcgen::abstract_interp`'s
/// `type_aware_initial_state` → `interval_domain_to_formula` exactly:
///
///   * Variables are the integer parameters, keyed by their formula NAME
///     (`decl.name` or `_<index>` when unnamed). The trust-vcgen `IntervalDomain`
///     stores them in a `BTreeMap<String, Interval>`, so the emission order is
///     SORTED BY NAME — not local order. We sort identically.
///   * For each parameter's type interval `[lo, hi]`: emit `Ge(Var(name,Int),
///     Int(lo))` iff `lo != i128::MIN`, then `Le(Var(name,Int), Int(hi))` iff
///     `hi != i128::MAX` — matching the MIN/MAX filter in
///     `interval_domain_to_formula`. (`Int` bounds even for unsigned, matching
///     the upstream, which always emits `Formula::Int`.)
///   * The collapse rule is the upstream's: 0 conjuncts → no env (None here, so
///     no augmented candidate is offered), 1 → the bare conjunct, ≥2 → `And(..)`.
///
/// Returns `None` when there are no integer parameters with a finite bound (the
/// upstream would yield a `Bool(true)` env, which `augment_vc_with_abstract_state`
/// treats as Top and leaves the VC UNCHANGED — so the bare candidates already
/// cover that case).
///
/// SOUNDNESS: a pure function of `func`. The candidate it contributes is only ever
/// ACCEPTED by the flip's exact byte-equality gate; whenever the real merged
/// environment differs from the integer-parameter-type-range reconstruction, the
/// candidate does not byte-match and the flip falls back to trust-vcgen's formula.
#[cfg(test)]
pub(crate) fn reconstruct_abstract_state_param_env_for_test(
    func: &VerifiableFunction,
) -> Option<Formula> {
    reconstruct_abstract_state_param_env(func)
}

fn reconstruct_abstract_state_param_env(func: &VerifiableFunction) -> Option<Formula> {
    // Collect integer parameters keyed by formula name, sorted by name to match
    // the trust-vcgen `IntervalDomain` `BTreeMap` iteration order.
    let mut params: Vec<(String, u32, bool)> = Vec::new();
    for decl in &func.body.locals {
        if decl.index < 1 || decl.index > func.body.arg_count {
            continue;
        }
        let Some(width) = decl.ty.int_width() else {
            continue;
        };
        let name = decl.name.clone().unwrap_or_else(|| format!("_{}", decl.index));
        params.push((name, width, decl.ty.is_signed()));
    }
    params.sort_by(|a, b| a.0.cmp(&b.0));

    let mut conjuncts: Vec<Formula> = Vec::new();
    for (name, width, signed) in &params {
        // The interval bounds trust-vcgen's `type_to_interval` assigns. Note: it
        // only models widths 1..=128; a signed i128 yields `[i128::MIN,
        // i128::MAX]` (both filtered), and unsigned u128 yields `[0, i128::MAX]`
        // (upper filtered) — handled by the MIN/MAX filter below.
        let (mut lo, mut hi) = if *signed {
            if *width == 128 {
                (i128::MIN, i128::MAX)
            } else {
                let half = 1i128 << (width - 1);
                (-half, half - 1)
            }
        } else if *width == 128 {
            (0i128, i128::MAX)
        } else {
            (0i128, (1i128 << width) - 1)
        };
        // PRECONDITION REFINEMENT (trust-ir-spine simple-case port). trust-vcgen
        // folds `#[requires]` into the abstract-interp INITIAL state via
        // `refine_state_with_precondition` (transfer.rs:296), intersecting each
        // parameter's type interval with whatever single-variable bound a SIMPLE
        // precondition exposes (`x>0`, `x>=c`, `x<c`, `x<=c`, and conjunctions).
        // For a straight-line body the fixpoint adds nothing beyond this refined
        // initial state (the merged env == the refined initial state — verified
        // empirically for `both`/`pre`), so reproducing the refinement here makes
        // the spine env byte-equal to the live merged env. We model ONLY the simple
        // shapes `refine_state_with_precondition` recognises for a single named
        // variable; any other precondition shape is left as the unrefined type
        // range (sound: the exact-equality gate then fails closed if trust-vcgen
        // refined differently). `i128`-saturating arithmetic mirrors trust-vcgen's
        // `saturating_add`/`saturating_sub`.
        for pre in &func.preconditions {
            refine_param_interval_with_precondition(name, pre, &mut lo, &mut hi);
        }
        // A precondition could empty the interval (`lo > hi`); trust-vcgen would
        // then emit `Bool(false)`. We decline to reconstruct that bottom case
        // (return `None` for the whole env), so the candidate is not offered and
        // the flip keeps trust-vcgen's formula (fail-closed). Straight-line simple
        // preconditions never empty a parameter's range, so this is a guard only.
        if lo > hi {
            return None;
        }
        let var = Formula::var(name, Sort::Int);
        if lo != i128::MIN {
            conjuncts.push(Formula::Ge(Box::new(var.clone()), Box::new(Formula::Int(lo))));
        }
        if hi != i128::MAX {
            conjuncts.push(Formula::Le(Box::new(var), Box::new(Formula::Int(hi))));
        }
    }

    match conjuncts.len() {
        0 => None,
        1 => conjuncts.pop(),
        _ => Some(Formula::And(conjuncts)),
    }
}

/// Intersect parameter `name`'s interval `[lo, hi]` with the bound a SIMPLE
/// precondition `formula` exposes about it, mirroring
/// `trust_vcgen::abstract_interp::refine_state_with_precondition` byte-for-byte
/// for the shapes it recognises over a single named integer variable:
/// `var </<=/>/>= lit` (and the literal-on-the-left mirrors), and conjunctions
/// (recursive). Other shapes are ignored (the interval stays as-is), exactly as
/// trust-vcgen leaves unrecognised preconditions available only as a hypothesis.
///
/// Only the conjunct mentioning THIS parameter tightens it; a conjunct about a
/// different variable is a no-op here. The saturating arithmetic and the
/// strict-vs-nonstrict `±1` offsets match trust-vcgen exactly (`Lt` ⇒
/// `v.saturating_sub(1)` on the upper bound; `Gt` ⇒ `v.saturating_add(1)` on the
/// lower bound).
fn refine_param_interval_with_precondition(
    name: &str,
    formula: &Formula,
    lo: &mut i128,
    hi: &mut i128,
) {
    // `Not(Eq(var, c))` (divisor != 0) is intentionally NOT modelled: trust-vcgen
    // refines it only when it abuts a current bound, and that bound depends on the
    // prior refinement order — a state-dependent shape outside the simple
    // single-variable envelope. Declining it keeps the spine env exact for the
    // straight-line simple cases and fail-closed otherwise.
    let meet = |lo: &mut i128, hi: &mut i128, blo: i128, bhi: i128| {
        *lo = (*lo).max(blo);
        *hi = (*hi).min(bhi);
    };
    let var_named = |f: &Formula| -> bool {
        matches!(f, Formula::Var(n, _) if n == name)
            || matches!(f, Formula::SymVar(n, _) if n.as_str() == name)
    };
    let int_const = |f: &Formula| -> Option<i128> {
        match f {
            Formula::Int(v) => Some(*v),
            Formula::UInt(v) => i128::try_from(*v).ok(),
            _ => None,
        }
    };
    match formula {
        Formula::And(conjuncts) => {
            for c in conjuncts {
                refine_param_interval_with_precondition(name, c, lo, hi);
            }
        }
        Formula::Le(l, r) => {
            if var_named(l) {
                if let Some(v) = int_const(r) {
                    meet(lo, hi, i128::MIN, v);
                }
            } else if var_named(r) {
                if let Some(v) = int_const(l) {
                    meet(lo, hi, v, i128::MAX);
                }
            }
        }
        Formula::Lt(l, r) => {
            if var_named(l) {
                if let Some(v) = int_const(r) {
                    meet(lo, hi, i128::MIN, v.saturating_sub(1));
                }
            } else if var_named(r) {
                if let Some(v) = int_const(l) {
                    meet(lo, hi, v.saturating_add(1), i128::MAX);
                }
            }
        }
        Formula::Ge(l, r) => {
            if var_named(l) {
                if let Some(v) = int_const(r) {
                    meet(lo, hi, v, i128::MAX);
                }
            } else if var_named(r) {
                if let Some(v) = int_const(l) {
                    meet(lo, hi, i128::MIN, v);
                }
            }
        }
        Formula::Gt(l, r) => {
            if var_named(l) {
                if let Some(v) = int_const(r) {
                    meet(lo, hi, v.saturating_add(1), i128::MAX);
                }
            } else if var_named(r) {
                if let Some(v) = int_const(l) {
                    meet(lo, hi, i128::MIN, v.saturating_sub(1));
                }
            }
        }
        _ => {}
    }
}

/// Name a single-field-projection place (`_N.k`) the way
/// `trust_vcgen::place_to_var_name` does for a value-bearing tuple field — the
/// return-pin RHS in the straight-line postcondition case is `Move(_N.0)`, named
/// `{base}.0`. Returns `None` for any other projection shape (outside the simple
/// envelope → the postcondition reconstruction declines and the flip keeps
/// trust-vcgen's formula).
fn field_place_var_name(locals: &[LocalDecl], place: &Place) -> Option<String> {
    let [Projection::Field(idx)] = place.projections.as_slice() else {
        return None;
    };
    let fallback = format!("_{}", place.local);
    let base = locals
        .iter()
        .find(|d| d.index == place.local)
        .and_then(|d| d.name.as_deref())
        .unwrap_or(&fallback)
        .to_string();
    Some(format!("{base}.{idx}"))
}

/// Reproduce `trust_vcgen::guards::extract_assert_passed_semantics` BYTE-FOR-BYTE
/// for the overflow-assert block whose `cond` is `Move/Copy(_N.1)` defined by a
/// `CheckedBinaryOp(Add|Sub|Mul, lhs, rhs)` assigned to `_N`.
///
/// trust-vcgen produces exactly four conjuncts, in this order:
///   `[ in_range, result_def, lhs_range, rhs_range ]`
/// where
///   * `in_range`   = `And([Le(min, lhs OP rhs), Le(lhs OP rhs, max)])`
///   * `result_def` = `Eq(Var("{tuple}.0", Int), lhs OP rhs)`
///   * `lhs_range`  = `input_range_constraint(lhs_f, width, signed)`
///   * `rhs_range`  = `input_range_constraint(rhs_f, width, signed)`
///
/// This is the per-Return-block "semantic guard" the postcondition VC threads in
/// (via `build_semantic_guard_map`, which for a straight-line single-assert body
/// reduces to exactly this block's assert-passed semantics propagated to the
/// return block). Returns `None` for any shape outside this faithful envelope
/// (the postcondition reconstruction then declines → fail-closed).
fn reconstruct_assert_passed_semantics(
    locals: &[LocalDecl],
    block: &TrustBlock,
) -> Option<Vec<Formula>> {
    let Terminator::Assert { cond, expected: false, .. } = &block.terminator else {
        return None;
    };
    let cond_place = match cond {
        Operand::Copy(p) | Operand::Move(p) => p,
        _ => return None,
    };
    // The overflow flag is the `.1` field of the CheckedBinaryOp tuple.
    let [Projection::Field(1)] = cond_place.projections.as_slice() else {
        return None;
    };
    let tuple_local = cond_place.local;

    for stmt in &block.stmts {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            continue;
        };
        if place.local != tuple_local || !place.projections.is_empty() {
            continue;
        }
        let Rvalue::CheckedBinaryOp(op, lhs, rhs) = rvalue else {
            continue;
        };
        let lhs_f = safety_operand_to_formula(locals, lhs)?;
        let rhs_f = safety_operand_to_formula(locals, rhs)?;
        let (width, signed) = safety_int_op_type(locals, lhs, rhs)?;
        let result = match op {
            BinOp::Add => Formula::Add(Box::new(lhs_f.clone()), Box::new(rhs_f.clone())),
            BinOp::Sub => Formula::Sub(Box::new(lhs_f.clone()), Box::new(rhs_f.clone())),
            BinOp::Mul => Formula::Mul(Box::new(lhs_f.clone()), Box::new(rhs_f.clone())),
            _ => return None,
        };
        let min_f = safety_type_min_formula(width, signed);
        let max_f = safety_type_max_formula(width, signed);
        let in_range = Formula::And(vec![
            Formula::Le(Box::new(min_f), Box::new(result.clone())),
            Formula::Le(Box::new(result.clone()), Box::new(max_f)),
        ]);
        // The tuple result-field name: `{tuple_name}.0` where `tuple_name` is the
        // local's declared name or `_<index>` (matching trust-vcgen).
        let tuple_name = locals
            .iter()
            .find(|d| d.index == tuple_local)
            .and_then(|d| d.name.as_deref())
            .map_or_else(|| format!("_{tuple_local}"), str::to_string);
        let result_def = Formula::Eq(
            Box::new(Formula::var(&format!("{tuple_name}.0"), Sort::Int)),
            Box::new(result),
        );
        let lhs_range = safety_input_range_constraint(&lhs_f, width, signed);
        let rhs_range = safety_input_range_constraint(&rhs_f, width, signed);
        return Some(vec![in_range, result_def, lhs_range, rhs_range]);
    }
    None
}

/// Reconstruct, BYTE-FOR-BYTE, the body-aware `Postcondition` VC formula
/// `trust_vcgen::generate_v2_contract_vcs_impl` emits for the SIMPLE straight-line
/// single-`Return` case, so the trust-ir spine can become the verdict-FORMULA
/// source for simple postconditions.
///
/// SCOPE (everything outside it fails closed → flip keeps trust-vcgen's formula):
///   * exactly one block with a `Return` terminator (the return block);
///   * that return block has exactly one predecessor, an overflow-`Assert` block
///     (the canonical `x OP c` straight-line shape: `assert` block → return block);
///   * exactly one `ensures` postcondition predicate (`func.postconditions`);
///   * the return value is pinned by a single `_0 = Use(Move(_N.k))` assignment in
///     the return block (the CheckedBinaryOp result-field read).
///
/// For that shape the live formula (matched against
/// `generate_vcs_with_discharge_and_summaries` + `filter` + `dedupe`) is exactly:
/// ```text
/// And([ env_refined,
///       conjoin_live_preconditions(
///         And([ <assert-passed-semantics(predecessor)...>,
///               And([ Eq(_0, <ret-pin-rhs>), Not(post) ]) ]) ) ])
/// ```
/// — i.e. the refined abstract-interp env, then (live) preconditions, then the
/// predecessor's four assert-passed semantic guards, then the return-pin +
/// negated postcondition. Every sub-piece is reconstructed with the same helpers
/// the L0 reconstruction uses; the flip accepts the result ONLY on exact
/// `Formula` byte-equality, so any shape the reconstruction does not capture (a
/// branch, a loop, multiple returns, a non-`Use` return pin, a complex
/// precondition, a bool-sorted return needing the `__ret`→`_0` rename to bite)
/// simply does not byte-match and the flip keeps trust-vcgen's formula.
///
/// Returns `None` when the function is outside the simple scope.
fn reconstruct_simple_postcondition_formula(func: &VerifiableFunction) -> Option<Formula> {
    // Exactly one `Return` block.
    let mut return_blocks =
        func.body.blocks.iter().filter(|b| matches!(b.terminator, Terminator::Return));
    let ret_block = return_blocks.next()?;
    if return_blocks.next().is_some() {
        return None;
    }

    // Exactly one ensures predicate. (The dumped `postconditions` carry the parsed
    // predicate over `_0`; trust-vcgen ALSO folds in `Ensures` contracts, but for
    // the simple fixtures both resolve to the same single predicate. If there is
    // not exactly one, the live builder emits multiple/zero VCs we do not model.)
    if func.postconditions.len() != 1 {
        return None;
    }
    let post = &func.postconditions[0];

    // The return block's single predecessor must be an overflow-`Assert` block
    // targeting it (`vc_block` in trust-vcgen). The straight-line shape has the
    // assert block fall through to the return block.
    let predecessors: Vec<&TrustBlock> = func
        .body
        .blocks
        .iter()
        .filter(|pred| terminator_targets_block(&pred.terminator, ret_block.id))
        .collect();
    let [pred] = predecessors.as_slice() else {
        return None;
    };
    // The return slot's sort must be the default Int (the postcond parser models
    // `_0` as Int); a non-Int return needs the `__ret`→`_0` rename to bite, which
    // is outside the simple envelope.
    let ret_decl = func.body.locals.iter().find(|d| d.index == 0)?;
    if ret_decl.ty.int_width().is_none() {
        return None;
    }

    // (1) `formula = Not(post)`.
    let mut formula = Formula::Not(Box::new(post.clone()));

    // (2) RETURN-PIN: a single `_0 = Use(Move(_N.k))` (or `Copy`) in the return
    // block pins `_0 == <field>`. trust-vcgen pins `Eq(Var("_0", ret_sort),
    // rvalue_to_formula(Use(...)))`; for a value-bearing field read that is
    // `Var("{base}.k", Int)`. We require exactly this shape (the CheckedBinaryOp
    // result-field read); any other return assignment is outside the envelope.
    let ret_pin = ret_block.stmts.iter().find_map(|stmt| match stmt {
        Statement::Assign { place, rvalue: Rvalue::Use(operand), .. }
            if place.local == 0 && place.projections.is_empty() =>
        {
            let inner = match operand {
                Operand::Copy(p) | Operand::Move(p) => p,
                _ => return None,
            };
            let name = field_place_var_name(&func.body.locals, inner)?;
            Some(name)
        }
        _ => None,
    })?;
    let ret_pin_eq = Formula::Eq(
        Box::new(Formula::var("_0", Sort::Int)),
        Box::new(Formula::var(&ret_pin, Sort::Int)),
    );
    formula = Formula::And(vec![ret_pin_eq, formula]);

    // (3) LIVE PRECONDITIONS: conjoined as part of the THREADED return-block guard,
    // wrapping the `[ret_pin, Not(post)]` body (straight-line ⇒ all survive).
    //
    // Post-S2c (trust-vcgen commit `47060f15ba`): the precondition is no longer a
    // top-level prepend; it is threaded with the predecessor's assert-passed
    // semantics into the return block (`build_semantic_guard_map` /
    // `conjoin_preconditions_versioned`), landing INSIDE the sem-guard group and
    // ADJACENT to the return-pin — `And([sem_guards..., And([pre..., And([ret_pin,
    // Not(post)])])])` — not `And([pre..., And([sem_guards..., body])])`. Mirror
    // that placement so the spine reconstruction byte-matches the LIVE formula
    // (modulo the SSA version tokens the spine does not reproduce).
    formula = conjoin_live_preconditions_full(func, formula);

    // (4) SEMANTIC GUARDS: the predecessor's assert-passed semantics, threaded to
    // the return block by `build_semantic_guard_map` (which, for a straight-line
    // single-assert body, propagates exactly the predecessor block's four
    // assert-passed-semantic conjuncts to its assert target — the return block).
    let sem_guards = reconstruct_assert_passed_semantics(&func.body.locals, pred)?;
    let mut sem_conjuncts = sem_guards;
    sem_conjuncts.push(formula);
    formula = Formula::And(sem_conjuncts);

    // (5) REFINED ENV: the abstract-interp env conjunct (precondition-refined),
    // prepended exactly as `augment_vc_with_abstract_state` does. When the env is
    // Top (no integer params / no finite bound) the live builder leaves the VC
    // unchanged — but a no-param function has no `x` to range over, so the simple
    // postcondition fixtures always have a non-Top env. If the env is None we
    // decline (the live path would have an unaugmented formula we do not model
    // here — fail-closed).
    let env = reconstruct_abstract_state_param_env(func)?;
    Some(Formula::And(vec![env, formula]))
}

/// True when a terminator transfers control to `target` (the predecessor test for
/// the simple postcondition return block). Mirrors `v2_terminator_targets`
/// membership for the terminator kinds the simple straight-line shape uses.
fn terminator_targets_block(terminator: &Terminator, target: BlockId) -> bool {
    match terminator {
        Terminator::Assert { target: t, .. }
        | Terminator::Goto(t)
        | Terminator::Call { target: Some(t), .. }
        | Terminator::Drop { target: t, .. } => *t == target,
        Terminator::SwitchInt { targets, otherwise, .. } => {
            *otherwise == target || targets.iter().any(|(_, t)| *t == target)
        }
        Terminator::Opaque { targets, .. } => targets.contains(&target),
        _ => false,
    }
}

// =====================================================================
// ACYCLIC BRANCHING POSTCONDITION RECONSTRUCTION
//
// The next tier above the straight-line single-Return case: an ACYCLIC CFG
// with `if/else` branches (`SwitchInt`) and/or multiple `Return` blocks. For
// such bodies `generate_v2_contract_vcs_impl` emits ONE `Postcondition` VC per
// (Return block × predecessor) pair — each carrying that path's branch-condition
// guard, the predecessor+return block-defs, the return-pin, the join-weakened
// semantic guards, the live preconditions, and the refined env. This module
// reproduces that per-pair formula BYTE-FOR-BYTE for the reproducible envelope,
// so the trust-ir spine becomes the verdict-FORMULA source for branching-body
// postconditions too.
//
// SOUNDNESS: every reproduction is gated by the flip's exact `Formula`
// byte-equality, so any shape we do not capture (a loop / back-edge, a rvalue
// outside the Use/Constant/comparison envelope, a non-Int return slot, a complex
// precondition) simply does not byte-match and the flip keeps trust-vcgen's
// formula. We additionally FAIL CLOSED — returning NO candidates — the instant
// the CFG has a back-edge (a loop, whose `build_semantic_guard_map` widening we
// do NOT model) or any block carries a rvalue/terminator we cannot reproduce
// exactly. A wrong postcondition formula flipping a verdict is the worst
// outcome, so we never emit a candidate we are not certain mirrors the live
// path.
// =====================================================================

/// The plain (non-Panic) successor block ids of a terminator, used to drive the
/// acyclic-CFG walks below. Mirrors the union of `discovered_clauses` block
/// targets and `unguarded_successors` (the SAME successor set
/// `build_semantic_guard_map` / `v2_build_path_guard_map` enqueue).
fn block_successors(terminator: &Terminator) -> Vec<BlockId> {
    let mut succs = match terminator {
        Terminator::Goto(t) | Terminator::Drop { target: t, .. } => vec![*t],
        Terminator::Assert { target, .. } => vec![*target],
        Terminator::Call { target: Some(t), .. } => vec![*t],
        Terminator::Call { target: None, .. } => vec![],
        Terminator::SwitchInt { targets, otherwise, .. } => {
            let mut out: Vec<BlockId> = targets.iter().map(|(_, t)| *t).collect();
            out.push(*otherwise);
            out
        }
        Terminator::Opaque { targets, .. } => targets.clone(),
        Terminator::Return | Terminator::Unreachable | Terminator::Resume => vec![],
        // `Terminator` is `#[non_exhaustive]`: an unknown variant is treated as
        // having no successors (the acyclic detector below then treats it as a
        // leaf, and the per-pair reconstruction never threads through it).
        _ => vec![],
    };
    // Faithful unwind modeling: keep this in lockstep with the model's
    // `unguarded_successors` (which this function is documented to mirror, and
    // which `build_semantic_guard_map` / `v2_build_path_guard_map` enqueue) by
    // appending the cleanup/unwind successor. SOUND for both consumers: for
    // `cfg_has_back_edge`, an extra edge can only make loop detection MORE
    // conservative (fail closed), never mask a loop; for the guard map, a real
    // cleanup successor is threaded exactly like any other block.
    if let Some(cleanup) = terminator.unwind_cleanup_target() {
        succs.push(cleanup);
    }
    succs
}

/// True when the CFG (entry `bb0`) contains a back-edge reachable from entry — a
/// loop. We FAIL CLOSED on loops: `build_semantic_guard_map`'s widening is
/// explicitly out of scope (the prompt leaves loops fail-closed), so we must NOT
/// offer a candidate for any function whose CFG is cyclic. Detected by a DFS that
/// flags an edge into a node currently on the recursion stack.
fn cfg_has_back_edge(func: &VerifiableFunction) -> bool {
    let n = func.body.blocks.len();
    if n == 0 {
        return false;
    }
    #[derive(Clone, Copy, PartialEq)]
    enum State {
        Unvisited,
        OnStack,
        Done,
    }
    let mut state = vec![State::Unvisited; n];
    // Iterative DFS with an explicit (node, next-successor-index) stack.
    let mut stack: Vec<(usize, usize)> = Vec::new();
    state[0] = State::OnStack;
    stack.push((0, 0));
    while let Some(&(node, succ_idx)) = stack.last() {
        let Some(block) = func.body.blocks.get(node) else {
            stack.pop();
            continue;
        };
        let succs = block_successors(&block.terminator);
        if succ_idx >= succs.len() {
            state[node] = State::Done;
            stack.pop();
            continue;
        }
        // Advance this frame's cursor.
        if let Some(top) = stack.last_mut() {
            top.1 += 1;
        }
        let target = succs[succ_idx];
        let Some(tnode) = func.body.blocks.iter().position(|b| b.id == target) else {
            continue;
        };
        match state[tnode] {
            State::OnStack => return true, // edge into an on-stack node ⇒ back-edge
            State::Done => {}
            State::Unvisited => {
                state[tnode] = State::OnStack;
                stack.push((tnode, 0));
            }
        }
    }
    false
}

/// Port of `trust_vcgen::generate::build_semantic_guard_map` for the ACYCLIC
/// envelope, RESTRICTED to the block-definition shapes the spine can reproduce
/// exactly. Returns `None` (fail-closed for the whole reconstruction) the moment
/// a block carries a definition shape we do not model — never a partial map.
///
/// Faithful to the original: a BFS from `bb0` threading accumulated assert-passed
/// semantics + block-defs forward; a block revisited (a join) with DIFFERENT
/// guards is WEAKENED to `[Bool(true)]` (the terminal state); the first
/// predecessor's guards are recorded otherwise. For the `if/else` join (two
/// predecessors threading different `__ret = …` block-defs) this yields exactly
/// the live `[Bool(true)]` at the join — the signal the per-pair formula carries.
///
/// SCOPE: we reproduce `extract_block_definitions` for the Use/Constant/Comparison
/// rvalue shapes the branch fixtures use (plus the empty-Adt aggregate, which
/// contributes NO defs). `extract_assert_passed_semantics` is reused from the L0
/// reconstruction. Any block whose statements include an rvalue outside this
/// envelope makes the whole map `None` (the reconstruction then offers no
/// candidate and the flip keeps trust-vcgen's formula).
fn reconstruct_semantic_guard_map(
    func: &VerifiableFunction,
) -> Option<FxHashMap<BlockId, Vec<Formula>>> {
    use std::collections::VecDeque;

    const NOT_VISITED: u8 = 0;
    const VISITED_PRECISE: u8 = 1;
    const VISITED_WEAKENED: u8 = 2;

    let n = func.body.blocks.len();
    let mut result: FxHashMap<BlockId, Vec<Formula>> = FxHashMap::default();
    let mut visited = vec![NOT_VISITED; n];
    let index_of = |id: BlockId| func.body.blocks.iter().position(|b| b.id == id);

    let mut queue: VecDeque<(BlockId, Vec<Formula>)> = VecDeque::new();
    queue.push_back((BlockId(0), Vec::new()));

    while let Some((block_id, mut acc_guards)) = queue.pop_front() {
        let Some(idx) = index_of(block_id) else {
            continue;
        };
        let block = &func.body.blocks[idx];

        // Reproduce the block's definitions (statement-level redefs). `None`
        // anywhere ⇒ the whole reconstruction fails closed.
        let block_defs = reconstruct_block_definitions(func, block, false)?;
        let redefined: FxHashSet<String> =
            block_defs.iter().filter_map(formula_def_name).map(str::to_string).collect();
        if !redefined.is_empty() {
            acc_guards.retain(|f| formula_survives_redefs(f, &redefined));
        }

        match visited[idx] {
            VISITED_WEAKENED => continue,
            VISITED_PRECISE => {
                let existing = result.get(&block_id).cloned().unwrap_or_default();
                if existing == acc_guards {
                    continue;
                }
                acc_guards = vec![Formula::Bool(true)];
                result.insert(block_id, acc_guards.clone());
                visited[idx] = VISITED_WEAKENED;
            }
            NOT_VISITED => {
                visited[idx] = VISITED_PRECISE;
                if !acc_guards.is_empty() {
                    result.insert(block_id, acc_guards.clone());
                }
            }
            _ => unreachable!("semantic guard visitation state"),
        }

        let mut next_guards = acc_guards;
        for f in reconstruct_assert_passed_semantics(&func.body.locals, block).into_iter().flatten()
        {
            if formula_survives_redefs(&f, &redefined) {
                next_guards.push(f);
            }
        }
        next_guards.extend(block_defs);

        // We do NOT model the total-call / Ord min/max/clamp result-bound facts:
        // a `Call` terminator with such a callee is outside the envelope and is
        // rejected by `reconstruct_block_definitions`/successor reproduction
        // below (we only thread Goto/SwitchInt/Assert/Return successors that carry
        // no synthesized call facts). A `Call` with a `target` whose callee adds
        // such facts would make our map diverge, so we conservatively decline any
        // `Call` terminator (see successor handling) — keeping the map exact.
        match &block.terminator {
            Terminator::Assert { target, .. } | Terminator::Goto(target) => {
                queue.push_back((*target, next_guards));
            }
            Terminator::SwitchInt { targets, otherwise, .. } => {
                for (_, target) in targets {
                    queue.push_back((*target, next_guards.clone()));
                }
                queue.push_back((*otherwise, next_guards));
            }
            Terminator::Return | Terminator::Unreachable | Terminator::Resume => {}
            // Drop/Call/Opaque carry dataflow (drop glue, call facts) we do not
            // model exactly; decline the whole reconstruction (fail-closed).
            _ => return None,
        }
    }

    Some(result)
}

/// Reproduce `trust_vcgen::guards::extract_block_definitions` for the rvalue
/// shapes the acyclic branch fixtures use, BYTE-FOR-BYTE, with the SAME
/// last-write-wins (`seen_dests`, reverse iteration) discipline. Returns `None`
/// (fail-closed) for ANY rvalue shape outside the reproducible envelope, so a
/// block we cannot mirror exactly aborts the whole reconstruction rather than
/// emitting a partial (and thus non-byte-equal, or worse subtly-wrong) def list.
///
/// Envelope (exactly the shapes these fixtures need; extend only with a matching
/// live-path byte-equality proof):
///   * `Use(Copy/Move(_n))` / `Use(Constant(Int/Uint))` → `Eq(dest, rhs)`;
///   * `Aggregate(Adt, [])` (the `__ensures_checker` empty-variant marker) →
///     NO def (empty operands ⇒ `aggregate_field_definitions` is empty);
///   * `CheckedBinaryOp(..)` → skipped (its def rides on the semantic guard).
/// Any other rvalue (`BinaryOp`, `Cast`, non-empty `Aggregate`, `Repeat`,
/// `UnaryOp`, …) ⇒ `None`.
fn reconstruct_block_definitions(
    func: &VerifiableFunction,
    block: &TrustBlock,
    gate_stale_copies: bool,
) -> Option<Vec<Formula>> {
    let locals = &func.body.locals;
    let mut defs: Vec<Formula> = Vec::new();
    let mut seen_dests: FxHashSet<String> = FxHashSet::default();

    for stmt in block.stmts.iter().rev() {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            // Non-Assign statements (SetDiscriminant, StorageLive/Dead, …) are
            // outside the reproducible envelope here: SetDiscriminant would add
            // discriminant defs we don't model. Fail closed.
            match stmt {
                Statement::Assign { .. } => unreachable!(),
                // A pure storage/no-op statement contributes no def; allow it.
                Statement::Nop | Statement::StorageLive(_) | Statement::StorageDead(_) => continue,
                _ => return None,
            }
        };

        // Empty-operand Adt aggregate (the ensures/requires checker marker):
        // contributes no field defs. Skip it WITHOUT consuming a `seen_dests`
        // slot for a value we don't actually define.
        if let Rvalue::Aggregate(AggregateKind::Adt { .. }, operands) = rvalue {
            if operands.is_empty() {
                continue;
            }
            return None;
        }

        let dest_name = field_or_local_var_name(locals, place)?;
        if !seen_dests.insert(dest_name.clone()) {
            continue;
        }

        // CheckedBinaryOp: its result def is handled by the semantic guards, not
        // here (mirrors `extract_block_definitions`' explicit skip).
        if matches!(rvalue, Rvalue::CheckedBinaryOp(..)) {
            continue;
        }

        // SOUNDNESS (P0 regression, native-L0 default-on): in a DOMINATING-guard
        // collection, a copy `dest = Copy/Move(src)` emits the GLOBAL equality
        // `Eq(dest, src)`, STALE when `src` is reassigned downstream (one symbol per
        // local — the equality captures `src`'s value at the copy but the symbol moves
        // on). `if i<4 { let _g=i; i=b; a[i] }` collected `Eq(_g, i)` from the guard
        // block and `i=b` from the then-block, so `_g<4 ∧ _g==i` bound the REASSIGNED
        // index and kernel-CERTIFIED an OOB. The existing cross-block-reassignment bail
        // catches a DEST collision, NOT this SOURCE staleness — the "acyclic CFGs have
        // no staleness" assumption is false for a STRAIGHT-LINE reassignment. Drop the
        // stale copy-equality (the dominating-guard callers pass `gate_stale_copies`;
        // the semantic/contract callers do not, keeping their own handling). The legit
        // non-reassigned copy (param `i`, zero stores) keeps its def and still proves.
        if gate_stale_copies {
            // (a) Use copy-equality `Eq(dest, src)`: drop if the whole-local SOURCE is
            //     reassigned (the `bf592a1ff1` copy channel).
            if let Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) = rvalue
                && p.projections.is_empty()
                && !copy_source_is_single_valued(func, p.local)
            {
                continue;
            }
            // (b) Comparison def `_c = Lt(i, 4)`: an EDGE GUARD `_c` resolves to a fact
            //     over the LIVE operand symbols, so a reassigned operand (`i = b`, or
            //     `t.0 = b`) binds a STALE value → false-PROVE an OOB. Drop it.
            if let Rvalue::BinaryOp(_, lhs, rhs) = rvalue
                && (!operand_value_is_stable(func, lhs) || !operand_value_is_stable(func, rhs))
            {
                continue;
            }
            // (c) Slice-length def `_5 = Len(s)` / `PtrMetadata(s)`: keyed on the live `s`
            //     symbol. If `s` is REBOUND to a different slice (`s = t`), `_5 = len(s)`
            //     aliases a stale length and discharges OOB on the wrong slice. Drop it.
            let slice_local = match rvalue {
                Rvalue::Len(sp) => Some(sp.local),
                Rvalue::UnaryOp(UnOp::PtrMetadata, Operand::Copy(p) | Operand::Move(p)) => {
                    Some(p.local)
                }
                _ => None,
            };
            if let Some(sl) = slice_local
                && !copy_source_is_single_valued(func, sl)
            {
                continue;
            }
        }

        let dest_sort = local_place_sort(locals, place);
        let rhs = match rvalue {
            Rvalue::Use(operand) => block_def_operand_formula(locals, operand)?,
            // Integer COMPARISON binop (`_2 = x < 100`): the branch-condition def
            // that lets a SOUND dominating SwitchInt guard (`_2`) constrain its
            // operands (`_2 ∧ (_2 = x<100) ⇒ x<100`), recovering guard-bounded
            // completeness. Reproduce trust-vcgen's `extract_block_definitions`
            // comparison encoding via the shared `reconstruct_comparison_binop`; a
            // non-comparison binop is outside the envelope and fails closed.
            Rvalue::BinaryOp(op, lhs, rhs) => {
                let l = safety_operand_to_formula(locals, lhs)?;
                let r = safety_operand_to_formula(locals, rhs)?;
                reconstruct_comparison_binop(*op, l, r)?
            }
            // Slice-length read (`_5 = Len(s)` / `_5 = PtrMetadata(s)`): reproduce
            // trust-vcgen's `extract_block_definitions` Len/PtrMetadata def,
            // `Eq(_5, slice_len_formula(s))` = `Eq(_5, s__slice_len)`. WITHOUT this,
            // a dominating `if i < s.len()` guard threads only `i < _5` while `_5`
            // stays unlinked to the slice's length metadata, so the `s[i]` bounds
            // obligation `i >= s__slice_len` is spuriously SAT (false CEX at
            // `i=0, _5=1, s__slice_len=0`) — the regression that forced native L0
            // generation off-by-default. With the link, `i < _5 ∧ _5 = s__slice_len`
            // contradicts `i >= s__slice_len` and the access discharges natively.
            // SOUND: `Len`/`PtrMetadata` of a slice IS its length, true whenever the
            // statement runs; conjoining a true fact only refutes infeasible CEXs,
            // never hides a real violation (an UNGUARDED `s[i]` has no `i < _5` guard,
            // so the def alone leaves `i >= s_len` SAT — the mutant still fails).
            Rvalue::Len(slice_place) => {
                reconstruct_slice_len_formula(locals, &Operand::Copy(slice_place.clone()))?
            }
            Rvalue::UnaryOp(UnOp::PtrMetadata, slice_op) => {
                reconstruct_slice_len_formula(locals, slice_op)?
            }
            // Any other rvalue is outside the reproducible envelope.
            _ => return None,
        };
        defs.push(Formula::Eq(Box::new(Formula::var(&dest_name, dest_sort)), Box::new(rhs)));
    }

    Some(defs)
}

/// The blocks present on EVERY acyclic SUCCESS-edge path from entry to `target` — its
/// dominators in the VERIFIED CFG. An `Assert` terminator contributes ONLY its success
/// target (the failure edge panics, so a verified path never takes it), so a block on
/// every path means its asserts all passed by the time `target` runs. Returns EMPTY
/// (conservative — no dominators, so callers decline) when the path cap is exceeded OR an
/// unmodeled terminator with successors is hit (missing a path would FALSELY report
/// dominance, hence unsound; bailing is the safe direction).
fn block_dominators(func: &VerifiableFunction, target: BlockId) -> FxHashSet<BlockId> {
    const MAX_PATHS: usize = 64;
    let blocks = &func.body.blocks;
    let mut path_sets: Vec<FxHashSet<BlockId>> = Vec::new();
    let mut stack: Vec<(BlockId, FxHashSet<BlockId>)> = vec![(BlockId(0), FxHashSet::default())];
    while let Some((bid, visited)) = stack.pop() {
        if bid == target {
            path_sets.push(visited);
            if path_sets.len() > MAX_PATHS {
                return FxHashSet::default();
            }
            continue;
        }
        if visited.contains(&bid) {
            continue; // back-edge cut (acyclic enumeration)
        }
        let Some(block) = blocks.iter().find(|b| b.id == bid) else {
            continue;
        };
        let mut nv = visited.clone();
        nv.insert(bid);
        match &block.terminator {
            Terminator::Goto(t)
            | Terminator::Assert { target: t, .. }
            | Terminator::Drop { target: t, .. }
            | Terminator::Call { target: Some(t), .. } => stack.push((*t, nv)),
            Terminator::SwitchInt { targets, otherwise, .. } => {
                for (_, t) in targets {
                    stack.push((*t, nv.clone()));
                }
                stack.push((*otherwise, nv));
            }
            Terminator::Opaque { targets, .. } => {
                for t in targets {
                    stack.push((*t, nv.clone()));
                }
            }
            // Terminal (no successor toward `target`): a dead end, not a path.
            Terminator::Return | Terminator::Unreachable | Terminator::Resume => {}
            Terminator::Call { target: None, .. } => {}
            // Unknown (non_exhaustive): cannot enumerate successors safely → bail.
            _ => return FxHashSet::default(),
        }
    }
    if path_sets.is_empty() {
        return FxHashSet::default();
    }
    let (first, rest) = path_sets.split_first().expect("non-empty");
    first.iter().filter(|b| rest.iter().all(|s| s.contains(b))).copied().collect()
}

/// Resolve `_t.0` (a CheckedBinaryOp result field) to its EXACT mathematical value
/// `op(a, b)` — but ONLY when the matching `Overflow(op)` assert for `_t.1` DOMINATES
/// `obligation_block`. Soundness: a CheckedBinaryOp wraps on overflow, so
/// `Eq(_t.0, math_op(a, b))` is false in general; but if the overflow assert dominates the
/// obligation, every VERIFIED path to it took the assert's SUCCESS edge ⟹ no overflow
/// occurred ⟹ `_t.0` IS the exact math value (an overflowing execution panics at the
/// assert and never reaches the obligation). So the equality holds on every execution that
/// reaches the obligation — sound to conjoin for ANY violation direction (unlike a bare
/// wrapping arith def). This is what lets a scaled index `a[i * 2]` discharge: `_4 = i*2`
/// (exact, the overflow assert dominates) ∧ the dominating guard `i < 4` ⟹ `_4 < 8`.
fn resolve_checked_result_through_dominating_overflow_assert(
    func: &VerifiableFunction,
    obligation_block: BlockId,
    operand: &Operand,
) -> Option<Formula> {
    let locals = &func.body.locals;
    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return None;
    };
    // The result is the `.0` field of the CheckedBinaryOp tuple local.
    if place.projections.as_slice() != [Projection::Field(0)] {
        return None;
    }
    let tuple_local = place.local;
    // Find `_t = CheckedBinaryOp(op, a, b)` for op in Add/Sub/Mul.
    let (op, a, b) = func.body.blocks.iter().flat_map(|blk| &blk.stmts).find_map(|s| match s {
        Statement::Assign {
            place: p,
            rvalue: Rvalue::CheckedBinaryOp(op @ (BinOp::Add | BinOp::Sub | BinOp::Mul), a, b),
            ..
        } if p.local == tuple_local && p.projections.is_empty() => Some((*op, a, b)),
        _ => None,
    })?;
    // Find the block whose terminator is the `Overflow(op)` assert on `_t.1`.
    let assert_block = func.body.blocks.iter().find_map(|blk| match &blk.terminator {
        Terminator::Assert {
            cond: Operand::Copy(c) | Operand::Move(c),
            msg: AssertMessage::Overflow(aop),
            ..
        } if *aop == op
            && c.local == tuple_local
            && c.projections.as_slice() == [Projection::Field(1)] =>
        {
            Some(blk.id)
        }
        _ => None,
    })?;
    // The overflow assert MUST dominate the obligation (else `_t.0` may be a wrapped value).
    if !block_dominators(func, obligation_block).contains(&assert_block) {
        return None;
    }
    let af = safety_operand_to_formula(locals, a)?;
    let bf = safety_operand_to_formula(locals, b)?;
    Some(match op {
        BinOp::Add => Formula::Add(Box::new(af), Box::new(bf)),
        BinOp::Sub => Formula::Sub(Box::new(af), Box::new(bf)),
        _ => Formula::Mul(Box::new(af), Box::new(bf)),
    })
}

/// Reconstruct the INTEGER block definitions of `block` (the obligation's OWN block) for
/// NATIVE generation — a SOUND, PARTIAL set: each `_d = rvalue` (last assignment before
/// the terminator) with an INT-valued dest becomes the true fact `Eq(_d, rhs)` for the
/// FAITHFUL non-arithmetic rvalues (constant/copy `Use`, `Len`/`PtrMetadata`); every other
/// rvalue (aggregates, comparisons, CASTS, ARITHMETIC, calls, unknown) is SKIPPED.
///
/// The assert's per-class base (`reconstruct_full_safety_formula_candidates`) reproduces
/// the cond / slice-len bindings but NOT a same-block constant binding like `_2 = 2`
/// (a constant array index), so `arr[2]` was dispatched with the index var UNBOUND and
/// falsely refused. These defs execute in the SAME ITERATION as the assert (sequentially,
/// before the terminator), so they are NEVER stale — sound to conjoin even inside a loop.
/// Skipping a def leaves its dest unbound → fail-closed, never a false proof, so a partial
/// set is sound. Kept NATIVE-ONLY (not the shared `reconstruct_block_definitions`) so the
/// byte-equality flip path is untouched; bool/comparison defs are dropped (the base
/// already carries the cond binding, and a fresh bool var would defeat ay's pure-int
/// certification). Names are collision-safe so a shadowed same-name local cannot conflate.
///
/// ARITHMETIC rvalues (`Add`/`Sub`/`Mul`) are deliberately EXCLUDED: the MIR op is
/// WRAPPING (mod 2^width), but `Eq(_d, math_op(a,b))` uses MATHEMATICAL arithmetic. When
/// the op overflows the two disagree, and conjoining the (then-false) equality onto a
/// `Lt`-direction violation (a cast's `Lt(value, to_min)`, a signed bounds `Lt(idx, 0)`,
/// a shift) can SILENTLY DROP a real counterexample where `wrapped < bound < math` — a
/// false proof. Only the wrap-free `Use`/`Len` defs are admitted; a scaled/derived index
/// stays conservatively unbound (fail-closed) until a sound non-overflow-gated encoding.
fn reconstruct_native_own_block_defs(
    func: &VerifiableFunction,
    block: &TrustBlock,
) -> Vec<Formula> {
    let locals = &func.body.locals;
    let mut defs = Vec::new();
    let mut seen: FxHashSet<String> = FxHashSet::default();
    for stmt in block.stmts.iter().rev() {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            continue;
        };
        if !place.projections.is_empty() {
            continue;
        }
        // INT-valued dest only (so `Eq(dest:Int, rhs)` is well-sorted; a bool/comparison
        // dest is skipped — the base carries the cond binding).
        let Some(decl) = locals.iter().find(|d| d.index == place.local) else {
            continue;
        };
        if decl.ty.int_width().is_none() {
            continue;
        }
        let Some(dest_name) = safety_place_var_name(locals, place) else {
            continue;
        };
        if !seen.insert(dest_name.clone()) {
            continue; // keep only the LAST assignment before the assert
        }
        let rhs = match rvalue {
            // A direct local/constant Use, OR `_d = _t.0` where `_t` is a CheckedBinaryOp
            // whose overflow assert DOMINATES this block — then `_t.0` is the exact math
            // value (no wrapping), so a scaled/checked index `a[i*2]` discharges. The
            // dominance gate is what makes the math equality sound (see the resolver).
            // SOUNDNESS (P0 staleness): skip when the source local is REASSIGNED
            // function-globally — `Eq(_d, src)` would bind a stale value (a checked-op
            // temp `_t.0` is a fresh single-store temp, so the scaled-index case is kept).
            Rvalue::Use(operand) if operand_value_is_stable(func, operand) => {
                safety_operand_to_formula(locals, operand).or_else(|| {
                    resolve_checked_result_through_dominating_overflow_assert(
                        func, block.id, operand,
                    )
                })
            }
            // Slice-length own-def: skip when the slice local is rebound (`s = t`), else
            // `Eq(_d, len(s))` aliases a stale length onto the live `s` symbol.
            Rvalue::Len(slice_place) if copy_source_is_single_valued(func, slice_place.local) => {
                reconstruct_slice_len_formula(locals, &Operand::Copy(slice_place.clone()))
            }
            Rvalue::UnaryOp(UnOp::PtrMetadata, slice_op) => {
                // Gate the common `PtrMetadata(Copy/Move(s))` on `s` not being rebound; a
                // reborrow form (`&(*dst)`) is threaded by `reconstruct_slice_len_formula`
                // and kept (its underlying reassignment is out of this envelope).
                let stable = match slice_op {
                    Operand::Copy(p) | Operand::Move(p) => {
                        copy_source_is_single_valued(func, p.local)
                    }
                    _ => true,
                };
                if stable { reconstruct_slice_len_formula(locals, slice_op) } else { None }
            }
            _ => None,
        };
        if let Some(rhs) = rhs {
            defs.push(Formula::Eq(Box::new(Formula::var(&dest_name, Sort::Int)), Box::new(rhs)));
        }
    }
    defs
}

/// The destination variable name for a block-def's place: a projection-free local
/// (`place_to_var_name`'s base) or a single tuple-field projection (`{base}.k`).
/// Returns `None` for any deeper projection shape (outside the envelope).
fn field_or_local_var_name(locals: &[LocalDecl], place: &Place) -> Option<String> {
    if place.projections.is_empty() {
        return safety_place_var_name(locals, place);
    }
    field_place_var_name(locals, place)
}

/// The declared `Sort` of a projection-free integer/bool local place, matching
/// `trust_vcgen::place_sort` for the envelope (Int for integers, Bool for bools).
/// Defaults to `Int` (as trust-vcgen's `.unwrap_or(Sort::Int)` does) for an
/// unknown/other type — but the operand-formula reproduction itself only succeeds
/// for the shapes whose sort is Int, so a non-Int def never byte-matches unless it
/// genuinely is one.
fn local_place_sort(locals: &[LocalDecl], place: &Place) -> Sort {
    if place.projections.is_empty()
        && let Some(decl) = locals.iter().find(|d| d.index == place.local)
    {
        if matches!(decl.ty, Ty::Bool) {
            return Sort::Bool;
        }
    }
    Sort::Int
}

/// Reproduce `trust_vcgen::operand_to_formula` for the block-def RHS envelope:
/// an integer local (`Var(name, Int)`) or an integer constant (`Int`/`UInt`
/// narrowing). Shares the exact encoding `safety_operand_to_formula` uses.
fn block_def_operand_formula(locals: &[LocalDecl], operand: &Operand) -> Option<Formula> {
    safety_operand_to_formula(locals, operand)
}

/// Reproduce `formula_def_name` from trust-vcgen (the lhs variable name of a
/// top-level `Eq(Var(name), _)` definition), used to compute the per-block
/// `redefined` kill set in the semantic-guard BFS.
fn formula_def_name(formula: &Formula) -> Option<&str> {
    match formula {
        Formula::Eq(lhs, _) => match lhs.as_ref() {
            Formula::Var(name, _) => Some(name.as_str()),
            _ => None,
        },
        _ => None,
    }
}

/// Reproduce `trust_vcgen::generate::formula_survives_redefs`: a fact survives
/// past a block iff NONE of its free variables were reassigned (`redefined`).
fn formula_survives_redefs(formula: &Formula, redefined: &FxHashSet<String>) -> bool {
    let mut names: FxHashSet<String> = FxHashSet::default();
    collect_formula_var_names(formula, &mut names);
    !names.iter().any(|n| redefined.contains(n))
}

/// Collect the free variable names of a formula (the subset of node kinds the
/// branch-postcondition envelope produces). Mirrors trust-vcgen's
/// `collect_formula_var_names` for those kinds; an unmodeled node contributes no
/// names (sound here — it only ever UNDER-approximates the kill, and a fact we
/// fail to kill that should have been killed would simply not byte-match the live
/// formula and fail closed).
fn collect_formula_var_names(formula: &Formula, out: &mut FxHashSet<String>) {
    match formula {
        Formula::Var(name, _) => {
            out.insert(name.to_string());
        }
        Formula::SymVar(name, _) => {
            out.insert(name.to_string());
        }
        Formula::Not(inner) | Formula::Neg(inner) => collect_formula_var_names(inner, out),
        Formula::And(children) | Formula::Or(children) => {
            for c in children {
                collect_formula_var_names(c, out);
            }
        }
        Formula::Implies(a, b)
        | Formula::Eq(a, b)
        | Formula::Lt(a, b)
        | Formula::Le(a, b)
        | Formula::Gt(a, b)
        | Formula::Ge(a, b)
        | Formula::Add(a, b)
        | Formula::Sub(a, b)
        | Formula::Mul(a, b)
        | Formula::Div(a, b)
        | Formula::Rem(a, b) => {
            collect_formula_var_names(a, out);
            collect_formula_var_names(b, out);
        }
        _ => {}
    }
}

/// Mirror trust-vcgen's final postcondition-only cleanup: remove an outer
/// `_0 == value` pin only when the same equality is already present, AST-identical,
/// on the unconditional `And` spine of its body.  In particular, a matching term
/// beneath `Or`, `Not`, or `Implies` is conditional and does not qualify.
fn dedup_identical_return_slot_pin(formula: Formula) -> Formula {
    formula.map(&mut |node| {
        let Formula::And(conjuncts) = &node else {
            return node;
        };
        let [outer_pin, body] = conjuncts.as_slice() else {
            return node;
        };
        let is_return_pin = matches!(outer_pin, Formula::Eq(lhs, _)
            if lhs.var_name() == Some("_0"));
        if is_return_pin && unconditional_and_spine_contains(body, outer_pin) {
            body.clone()
        } else {
            node
        }
    })
}

fn unconditional_and_spine_contains(formula: &Formula, expected: &Formula) -> bool {
    formula == expected
        || matches!(formula, Formula::And(conjuncts)
            if conjuncts
                .iter()
                .any(|conjunct| unconditional_and_spine_contains(conjunct, expected)))
}

/// Reproduce `combine_relevant_block_defs`: attach only the block-def conjuncts
/// whose variables are transitively referenced by `formula`, walking defs in
/// REVERSE (so `_4 = _3` pulls in `_3`'s def) and re-prepending in original
/// order. BYTE-FOR-BYTE with trust-vcgen (same relevance heuristic, same final
/// `And([kept..., formula])` shape).
fn combine_relevant_block_defs(defs: Vec<Formula>, formula: Formula) -> Formula {
    if defs.is_empty() {
        return formula;
    }
    let mut needed: FxHashSet<String> = FxHashSet::default();
    collect_formula_var_names(&formula, &mut needed);

    let mut keep_rev: Vec<Formula> = Vec::new();
    for def in defs.into_iter().rev() {
        let mut def_vars: FxHashSet<String> = FxHashSet::default();
        collect_formula_var_names(&def, &mut def_vars);
        let intersects = def_vars.iter().any(|name| needed.contains(name));
        if intersects {
            for name in def_vars {
                needed.insert(name);
            }
            keep_rev.push(def);
        }
    }
    if keep_rev.is_empty() {
        return formula;
    }
    let mut conjuncts: Vec<Formula> = keep_rev.into_iter().rev().collect();
    conjuncts.push(formula);
    Formula::And(conjuncts)
}

/// Port of `trust_vcgen::generate::v2_build_path_guard_map` for the ACYCLIC
/// envelope: a BFS from `bb0` accumulating per-edge `GuardCondition`s, yielding
/// for each block the LIST of guard-condition paths that reach it. We carry the
/// guards as already-lowered `Formula`s (built by `reconstruct_guard_formula`),
/// failing closed (`None`) on any guard shape we cannot reproduce. The path-block
/// cycle guard mirrors the original (a node already on the current path is not
/// re-expanded); combined with the back-edge fail-closed this stays bounded.
fn reconstruct_path_guard_map(
    func: &VerifiableFunction,
) -> Option<FxHashMap<BlockId, Vec<Vec<Formula>>>> {
    use std::collections::VecDeque;
    let mut result: FxHashMap<BlockId, Vec<Vec<Formula>>> = FxHashMap::default();
    if func.body.blocks.is_empty() {
        return Some(result);
    }
    let index_of = |id: BlockId| func.body.blocks.iter().position(|b| b.id == id);

    let mut queue: VecDeque<(BlockId, Vec<Formula>, Vec<BlockId>)> =
        VecDeque::from([(BlockId(0), Vec::new(), Vec::new())]);

    while let Some((block_id, path_guards, mut path_blocks)) = queue.pop_front() {
        let Some(idx) = index_of(block_id) else {
            continue;
        };
        if path_blocks.contains(&block_id) {
            continue;
        }
        path_blocks.push(block_id);

        result.entry(block_id).or_default().push(path_guards.clone());

        let block = &func.body.blocks[idx];
        for guarded in block.terminator.discovered_clauses(block_id) {
            if let trust_types::ClauseTarget::Block(target) = guarded.target {
                let guard_f = reconstruct_guard_formula(func, &guarded.guard)?;
                let mut next = path_guards.clone();
                next.push(guard_f);
                queue.push_back((target, next, path_blocks.clone()));
            }
        }
        for target in block.terminator.unguarded_successors() {
            queue.push_back((target, path_guards.clone(), path_blocks.clone()));
        }
    }
    Some(result)
}

/// Reproduce `trust_vcgen::guards::guard_to_formula` for the guard shapes the
/// acyclic branch envelope produces: a Bool-discriminant `SwitchInt` match /
/// otherwise (the `if b { … } else { … }` condition), yielding `b` / `Not(b)`
/// exactly as trust-vcgen does for an UNDEFINED (parameter / havoc'd) Bool
/// discriminant. Returns `None` for any other guard shape (a non-Bool switch, a
/// Bool whose condition is DEFINED by an in-block comparison — which trust-vcgen
/// would inline — an assert guard, …), failing the whole reconstruction closed.
fn reconstruct_guard_formula(
    func: &VerifiableFunction,
    guard: &trust_types::GuardCondition,
) -> Option<Formula> {
    use trust_types::GuardCondition;
    // We only reproduce a discriminant that is a bare Bool parameter / local
    // (projection-free `Copy`/`Move`) that is NOT defined by an in-block
    // comparison — for which `guard_to_formula` falls through to `b` / `Not(b)`.
    // If the Bool condition has an in-block definition (`_3 = i < len`),
    // trust-vcgen inlines it (`bool_condition_definition`), which is outside this
    // envelope → `None`.
    let bool_local_var = |discr: &Operand| -> Option<String> {
        let place = match discr {
            Operand::Copy(p) | Operand::Move(p) if p.projections.is_empty() => p,
            _ => return None,
        };
        let decl = func.body.locals.iter().find(|d| d.index == place.local)?;
        if !matches!(decl.ty, Ty::Bool) {
            return None;
        }
        // The discriminant must NOT be defined by an in-block statement anywhere
        // (a defined Bool cond is inlined by trust-vcgen — outside the envelope).
        if bool_local_has_definition(func, place.local) {
            return None;
        }
        safety_place_var_name(&func.body.locals, place)
    };
    match guard {
        GuardCondition::SwitchIntMatch { discr, value } => {
            let name = bool_local_var(discr)?;
            let v = Formula::var(&name, Sort::Bool);
            // Bool match: value 0 ⇒ `Not(b)`, nonzero ⇒ `b`.
            Some(if *value == 0 { Formula::Not(Box::new(v)) } else { v })
        }
        GuardCondition::SwitchIntOtherwise { discr, excluded_values } => {
            let name = bool_local_var(discr)?;
            let v = Formula::var(&name, Sort::Bool);
            let excludes_false = excluded_values.contains(&0);
            let excludes_true = excluded_values.iter().any(|value| *value != 0);
            match (excludes_false, excludes_true) {
                // otherwise excludes `false` ⇒ the value is `true` ⇒ `b`.
                (true, false) => Some(v),
                // otherwise excludes `true` ⇒ `Not(b)`.
                (false, true) => Some(Formula::Not(Box::new(v))),
                // Both/neither excluded: `Bool(false)`/`Bool(true)` — degenerate
                // shapes we decline (outside the clean if/else envelope).
                _ => None,
            }
        }
        // Assert guards (and any future variant) are outside the envelope.
        _ => None,
    }
}

/// True if a projection-free Bool local is DEFINED by an assignment anywhere in
/// the body (so `guard_to_formula`/`bool_condition_definition` would inline it).
/// For the clean `if b { … }` shape `b` is an undefined parameter, so this is
/// false and the guard reproduces as the bare `b` / `Not(b)`.
fn bool_local_has_definition(func: &VerifiableFunction, local: usize) -> bool {
    func.body.blocks.iter().any(|b| {
        b.stmts.iter().any(|s| {
            matches!(s, Statement::Assign { place, .. } if place.local == local && place.projections.is_empty())
        })
    })
}

/// Reproduce the live path-guard conjunction over the lowered guard list: an
/// empty list returns `formula` unchanged; otherwise the guard assumption (the
/// single guard or `And([g…])`) conjoined with the body.
///
/// Trust: mirror the upstream 2026-07-05 flatten (5441c9e462, "restore R1
/// recursion inductive-bound fact"): `v2_formula_with_path_guards` now splices an
/// `And` body FLAT beside the path guards — `And([g, f1, f2, …])`, no longer
/// `And([g, And([f1, f2, …])])` — so the R1 discharge gate sees `¬P[σ]` as a
/// DIRECT conjunct. Pure ∧-associativity, verdict-identical; but the flip accepts
/// a spine candidate only on BYTE equality, so the reconstruction must spell the
/// conjunction the same flat way (the nested spelling broke the clamp_branch/pick
/// branch-postcondition byte-match). A non-`And` body is pushed whole, as live.
fn apply_guarded_formula(guards: &[Formula], formula: Formula) -> Formula {
    if guards.is_empty() {
        return formula;
    }
    let assumption =
        if guards.len() == 1 { guards[0].clone() } else { Formula::And(guards.to_vec()) };
    let mut conj = vec![assumption];
    match formula {
        Formula::And(inner) => conj.extend(inner),
        other => conj.push(other),
    }
    Formula::And(conj)
}

/// Reproduce `v2_formula_with_path_guards`: wrap `formula` once per guard path
/// (an `Or` across paths when there is more than one). For the clean if/else
/// envelope each predecessor block is reached by exactly ONE path, so this is the
/// single-path case (`And([guard, formula])`).
fn apply_path_guards(guard_paths: &[Vec<Formula>], formula: Formula) -> Formula {
    let mut terms: Vec<Formula> =
        guard_paths.iter().map(|guards| apply_guarded_formula(guards, formula.clone())).collect();
    match terms.len() {
        0 => formula,
        1 => terms.pop().unwrap_or(formula),
        _ => Formula::Or(terms),
    }
}

/// Reconstruct, BYTE-FOR-BYTE, the per-(Return-block × predecessor) `Postcondition`
/// VC formulas `generate_v2_contract_vcs_impl` emits for an ACYCLIC branching body.
///
/// Mirrors the live builder's assembly for each `(return_block, vc_block)` pair:
///   1. `Not(post)`;
///   2. `combine_relevant_block_defs(block_defs(return_block), …)`;
///   3. (if `vc_block != return_block`) `combine_relevant_block_defs(block_defs(vc_block), …)`;
///   4. RETURN-PIN loop over `[vc_block, return_block]` — prepend `Eq(_0, rvalue)`
///      for each directly-representable (non-CheckedBinaryOp) `_0 = <rvalue>`;
///   4b. TRANSITIVE RETURN-PIN (upstream 2026-07-04 branchy computed-return fix):
///      when the return path copies `_0 = _L` (whole-local, `L != 0`), prepend the
///      3-ary `And([Eq(_0, value), Eq(_{L}, value), …])` where `value` is `_L`'s
///      last per-path (arm-first) non-CheckedBinaryOp assignment;
///   5. PATH GUARDS for `vc_block` (the branch condition reaching it);
///   6. SEMANTIC GUARDS — from `return_block` then (if different) `vc_block`,
///      using the join-weakened semantic-guard map;
///   7. LIVE PRECONDITIONS (straight-through; no parameter is reassigned in the
///      branch fixtures, so `may_reassigned` kills nothing — see the fail-closed
///      note);
///   8. REFINED ENV (prepended iff non-Top, exactly as `augment_vc_with_abstract_state`).
///
/// Returns one candidate formula per `(return_block, vc_block)` pair, or an empty
/// vec (FAIL-CLOSED) for any function outside the acyclic reproducible envelope
/// (a loop / back-edge, a non-Use return pin, an unreproducible block-def, a
/// guard shape we cannot mirror, a reassigned precondition variable, a non-Int
/// return slot, ≠1 postcondition predicate).
fn reconstruct_acyclic_postcondition_formulas(func: &VerifiableFunction) -> Vec<Formula> {
    // FAIL CLOSED on loops: the semantic-guard widening for back-edges is out of
    // scope; never offer a candidate for a cyclic CFG.
    if cfg_has_back_edge(func) {
        return Vec::new();
    }

    // Exactly one ensures predicate (same envelope as the straight-line case).
    if func.postconditions.len() != 1 {
        return Vec::new();
    }
    let post = &func.postconditions[0];

    // The return slot must be the default Int (the postcond parser models `_0` as
    // Int; a non-Int return needs the `__ret`→`_0` rename, outside this envelope).
    let Some(ret_decl) = func.body.locals.iter().find(|d| d.index == 0) else {
        return Vec::new();
    };
    if ret_decl.ty.int_width().is_none() {
        return Vec::new();
    }
    // We only reproduce the case where the return-slot ALIAS is `_0` (no rename) —
    // i.e. the live builder's `ret_alias == "_0"` no-op path. Local 0 with no
    // declared name canonicalizes to `_0` in trust-vcgen's `place_to_var_name`;
    // a NAMED local 0 (or a canonicalization alias) is outside the envelope.
    if ret_decl.name.is_some() {
        return Vec::new();
    }

    // Build the join-weakened semantic-guard map + the path-guard map; either
    // failing closed aborts the whole reconstruction.
    let Some(semantic_guards) = reconstruct_semantic_guard_map(func) else {
        return Vec::new();
    };
    let Some(path_guard_map) = reconstruct_path_guard_map(func) else {
        return Vec::new();
    };

    // PRECONDITION reassignment guard: `conjoin_live_preconditions` DROPS a
    // precondition at a block that may have reassigned one of its free variables.
    // We model the straight-through case (no kill); if any block reassigns a
    // precondition free variable, the live formula would differ, so fail closed.
    if precondition_var_reassigned_anywhere(func) {
        return Vec::new();
    }

    let env = reconstruct_abstract_state_param_env(func);

    let mut out: Vec<Formula> = Vec::new();

    for ret_block in func.body.blocks.iter() {
        if !matches!(ret_block.terminator, Terminator::Return) {
            continue;
        }
        let predecessors: Vec<&TrustBlock> = func
            .body
            .blocks
            .iter()
            .filter(|pred| terminator_targets_block(&pred.terminator, ret_block.id))
            .collect();
        let vc_blocks: Vec<&TrustBlock> =
            if predecessors.is_empty() { vec![ret_block] } else { predecessors };

        for vc_block in &vc_blocks {
            // The locals read by a CROSS-BLOCK return-pin (`_0 = Use(Copy(local L))`
            // in the RETURN block, where `L` is assigned in the distinct `vc_block`).
            // Post-S2c: trust-vcgen versions the `vc_block` def `L = N` to `L#s{vc}_k`
            // but the return-block read of `L` carries the JOIN-re-versioned token
            // `L#s{vc}_k_s{ret}_j`, so the def DISCONNECTS from the body and
            // `combine_relevant_block_defs` PRUNES it. We reproduce that prune: a
            // `vc_block` block-def whose subject is the cross-block return-pin source
            // local is dropped (its value rides on the return-pin chain, which the
            // version disconnection severs). See the S2c versioning series
            // (`trust-vcgen` commits around `47060f15ba`).
            let cross_block_retpin_sources: std::collections::HashSet<String> =
                if vc_block.id != ret_block.id {
                    ret_block
                        .stmts
                        .iter()
                        .filter_map(|stmt| match stmt {
                            Statement::Assign {
                                place,
                                rvalue: Rvalue::Use(Operand::Copy(p) | Operand::Move(p)),
                                ..
                            } if place.local == 0 && place.projections.is_empty() => {
                                safety_place_var_name(&func.body.locals, p)
                            }
                            _ => None,
                        })
                        .collect()
                } else {
                    std::collections::HashSet::new()
                };

            // (1) Not(post).
            let mut formula = Formula::Not(Box::new(post.clone()));

            // (2) RETURN-PIN loop over `[vc_block, ret_block]`. Pin `Eq(_0, rvalue)`
            // for each directly-representable `_0 = <rvalue>` assignment (NOT a
            // CheckedBinaryOp, whose value rides on the semantic guard). The pin is
            // conjoined INNERMOST (adjacent to `Not(post)`), matching the live shape.
            for def_block in [*vc_block, ret_block] {
                for stmt in &def_block.stmts {
                    let Statement::Assign { place, rvalue, .. } = stmt else {
                        continue;
                    };
                    if place.local != 0 || !place.projections.is_empty() {
                        continue;
                    }
                    if matches!(rvalue, Rvalue::CheckedBinaryOp(..)) {
                        continue;
                    }
                    // Only the Use(integer) rvalue is in the reproducible envelope;
                    // any other return rvalue (BinaryOp/Cast/…) aborts (the live
                    // path would pin a formula we are not reproducing here).
                    let Rvalue::Use(operand) = rvalue else {
                        return Vec::new();
                    };
                    let Some(rhs) = block_def_operand_formula(&func.body.locals, operand) else {
                        return Vec::new();
                    };
                    let ret_def =
                        Formula::Eq(Box::new(Formula::var("_0", Sort::Int)), Box::new(rhs));
                    formula = Formula::And(vec![ret_def, formula]);
                }
            }

            // (3) return-block block-defs (relevance-filtered).
            let Some(ret_defs) = reconstruct_block_definitions(func, ret_block, false) else {
                return Vec::new();
            };
            formula = combine_relevant_block_defs(ret_defs, formula);

            // (4) vc_block block-defs (if distinct), MINUS the cross-block return-pin
            // source def the version flip prunes (see `cross_block_retpin_sources`).
            if vc_block.id != ret_block.id {
                let Some(pred_defs) = reconstruct_block_definitions(func, vc_block, false) else {
                    return Vec::new();
                };
                let pred_defs: Vec<Formula> = pred_defs
                    .into_iter()
                    .filter(|d| {
                        block_def_subject_name(d)
                            .map(|s| !cross_block_retpin_sources.contains(&s))
                            .unwrap_or(true)
                    })
                    .collect();
                formula = combine_relevant_block_defs(pred_defs, formula);
            }

            // (4b) TRANSITIVE RETURN-PIN — mirror of the live builder's branchy
            // computed-return fix (trust-vcgen `generate_v2_contract_vcs_impl`,
            // commits `f23871d348` + `88030f9360`, 2026-07-04): when the return
            // path routes the value through a shared return binding (`_0 = copy
            // _L`, whole-local, `L != 0` — found by scanning the arm FIRST, then
            // the return block, statements in REVERSE), the live builder conjoins
            // a 3-ary `And` OUTSIDE the pin/def chain:
            //   `And([_0 == <value>, _{L} == <value>, formula])`
            // where `<value>` is `_L`'s last non-CheckedBinaryOp assignment on
            // THIS path (same arm-first reverse scan) and the source pin spells
            // `_L` by its RAW index name (`_{L}`), NOT the `place_to_var_name`
            // alias (`__ret`) — that raw spelling is deliberate upstream (it is
            // what connects the aliased/multi-exit shape). Both pin sorts are the
            // return slot's sort, which is Int inside this envelope (checked
            // above). An `_L` def outside the `Use`(int local/const) envelope
            // fails the WHOLE reconstruction CLOSED: the live formula would then
            // carry a pin (e.g. a BinaryOp value) we are not reproducing here.
            let scan_blocks: [&TrustBlock; 2] = [*vc_block, ret_block];
            let return_src_local: Option<usize> =
                scan_blocks.iter().flat_map(|b| b.stmts.iter().rev()).find_map(|stmt| {
                    let Statement::Assign { place, rvalue, .. } = stmt else {
                        return None;
                    };
                    if place.local != 0 || !place.projections.is_empty() {
                        return None;
                    }
                    match rvalue {
                        Rvalue::Use(Operand::Copy(p) | Operand::Move(p))
                            if p.projections.is_empty() && p.local != 0 =>
                        {
                            Some(p.local)
                        }
                        _ => None,
                    }
                });
            if let Some(src) = return_src_local {
                let mut arm_def: Option<Formula> = None;
                'scan: for def_block in scan_blocks {
                    for stmt in def_block.stmts.iter().rev() {
                        let Statement::Assign { place, rvalue, .. } = stmt else {
                            continue;
                        };
                        if place.local != src || !place.projections.is_empty() {
                            continue;
                        }
                        if matches!(rvalue, Rvalue::CheckedBinaryOp(..)) {
                            continue;
                        }
                        // The live scan converts via `chc::rvalue_to_formula`; our
                        // reproducible envelope is `Use` of an int local/constant.
                        // Anything else aborts (fail-closed) rather than risking a
                        // near-miss candidate.
                        let Rvalue::Use(operand) = rvalue else {
                            return Vec::new();
                        };
                        let Some(rhs) = block_def_operand_formula(&func.body.locals, operand)
                        else {
                            return Vec::new();
                        };
                        arm_def = Some(rhs);
                        break 'scan;
                    }
                }
                if let Some(rhs) = arm_def {
                    let pin_ret =
                        Formula::Eq(Box::new(Formula::var("_0", Sort::Int)), Box::new(rhs.clone()));
                    let pin_src = Formula::Eq(
                        Box::new(Formula::var_owned(format!("_{src}"), Sort::Int)),
                        Box::new(rhs),
                    );
                    formula = Formula::And(vec![pin_ret, pin_src, formula]);
                }
            }

            // (5) LIVE PRECONDITIONS — conjoined adjacent to the return-pin + block-def
            // chain (INSIDE the path/semantic guards), matching the post-S2c threaded
            // placement (`build_semantic_guard_map` / `conjoin_preconditions_versioned`):
            // the precondition wraps the full `[ret_pin, block_defs, Not(post)]` body,
            // not the top-level VC.
            formula = conjoin_live_preconditions_full(func, formula);

            // (6) PATH GUARDS for vc_block (the branch condition reaching it).
            if let Some(paths) = path_guard_map.get(&vc_block.id) {
                formula = apply_path_guards(paths, formula);
            }

            // (7) SEMANTIC GUARDS: return-block then (if different) vc_block.
            let mut sem_conjuncts: Vec<Formula> = Vec::new();
            if let Some(g) = semantic_guards.get(&ret_block.id) {
                sem_conjuncts.extend(g.iter().cloned());
            }
            if vc_block.id != ret_block.id
                && let Some(g) = semantic_guards.get(&vc_block.id)
            {
                sem_conjuncts.extend(g.iter().cloned());
            }
            if !sem_conjuncts.is_empty() {
                sem_conjuncts.push(formula);
                formula = Formula::And(sem_conjuncts);
            }

            // (8) REFINED ENV (prepend iff non-Top).
            if let Some(env) = &env {
                formula = Formula::And(vec![env.clone(), formula]);
            }

            // Keep the version-distinct return pins. This reconstruction is
            // intentionally versionless and the flip compares modulo SSA tokens;
            // two equal-looking pins here may correspond to distinct live ASTs.
            out.push(formula);
        }
    }

    out
}

/// True if any block reassigns (assigns to a projection-free place named like) a
/// free variable of any precondition. Used to fail closed on the
/// `conjoin_live_preconditions` kill case we do not model.
fn precondition_var_reassigned_anywhere(func: &VerifiableFunction) -> bool {
    if func.preconditions.is_empty() {
        return false;
    }
    let mut pre_vars: FxHashSet<String> = FxHashSet::default();
    for pre in &func.preconditions {
        collect_formula_var_names(pre, &mut pre_vars);
    }
    func.body.blocks.iter().any(|b| {
        b.stmts.iter().any(|s| match s {
            Statement::Assign { place, .. } if place.projections.is_empty() => {
                let fallback = format!("_{}", place.local);
                let name = func
                    .body
                    .locals
                    .iter()
                    .find(|d| d.index == place.local)
                    .and_then(|d| d.name.as_deref())
                    .unwrap_or(&fallback);
                pre_vars.contains(name)
            }
            _ => false,
        })
    })
}

// =====================================================================
// LOOP (back-edge) POSTCONDITION RECONSTRUCTION
//
// The final CFG tier: a CYCLIC body (a `while`/`loop` with a back-edge). For such
// bodies the live `generate_v2_contract_vcs_impl` STILL emits one `Postcondition` VC per
// (Return block × predecessor) pair, and its formula's abstract-interp env conjunct
// is sourced from `fixpoint_configured`'s FIXPOINT WITH WIDENING over the back-edge.
//
// THE KEY EMPIRICAL FINDING (validated against the live dumped `count`):
// `interval_domain_to_formula` EMITS NOTHING for a loop variable whose widened
// interval is TOP (`[i128::MIN, i128::MAX]`), because it filters MIN/MAX bounds. A
// counter `c`/`i` that only increases widens its UPPER bound to `i128::MAX` (and its
// lower stays at its `0` init only until the join with the back-edge pushes it; for
// `count` BOTH widen fully to TOP). So the widened loop-variable intervals
// CONTRIBUTE NO ENV CONJUNCT — the env reduces to exactly the integer PARAMETERS'
// type ranges, which `reconstruct_abstract_state_param_env` already reproduces
// byte-for-byte WITHOUT running the fixpoint at all. We therefore do NOT reproduce
// the widening sequence; we reproduce its OBSERVABLE RESULT on the env (the loop
// vars drop out), which is byte-stable regardless of iteration order / widen delay /
// narrowing, because a TOP interval is TOP however the fixpoint reached it.
//
// The other loop-specific effect is the semantic-guard map's JOIN-WEAKENING on the
// back-edge: the loop header (and the return block reached through it) is revisited
// with different accumulated guards and weakens to `[Bool(true)]` — exactly the
// `build_semantic_guard_map` behavior the acyclic port already implements (the live
// algorithm has NO cycle guard other than this 2-visit-bounded weakening, so it
// terminates on loops natively). We faithfully port that algorithm here, extended to
// the loop CFG's block-def shapes (`BinaryOp` comparison) and `Call` terminators
// (`wrapping_add`), and gate the whole result on the flip's EXACT byte-equality, so
// any divergence fails closed (sound).
//
// SOUNDNESS: this is gated to the case where the env's loop-variable contribution is
// provably empty (every non-parameter integer local that the fixpoint touches widens
// to TOP, so it is filtered) — we VERIFY that by running the real
// `interval_domain_to_formula` would be wrong (that needs trust-vcgen private
// fixpoint state we do not call here); instead the exact-equality gate is the proof:
// the reconstructed candidate is accepted ONLY if it byte-equals the live VC, so a
// loop whose widened env DOES contribute a conjunct (a bounded loop var that does
// not reach TOP) simply does not byte-match and the flip keeps trust-vcgen's formula.
// We never emit a candidate carrying a fabricated widened interval.
// =====================================================================

/// Reproduce `extract_block_definitions` for the loop CFG's block-def shapes:
/// the `Use` shapes the acyclic port handles, PLUS integer `BinaryOp` comparison
/// rvalues (`_b = _x < _y`, the loop-condition def), reproduced via the same
/// `try_binop_to_formula` comparison encoding trust-vcgen uses (`Lt`/`Le`/`Gt`/
/// `Ge`/`Eq`/`Ne`). Fails closed (`None`) on any other rvalue shape (a non-comparison
/// `BinaryOp`, `Cast`, `UnaryOp`, non-empty `Aggregate`, …), so a block we cannot
/// mirror exactly aborts the whole reconstruction.
fn reconstruct_loop_block_definitions(
    func: &VerifiableFunction,
    block: &TrustBlock,
) -> Option<Vec<Formula>> {
    let locals = &func.body.locals;
    let mut defs: Vec<Formula> = Vec::new();
    let mut seen_dests: FxHashSet<String> = FxHashSet::default();

    for stmt in block.stmts.iter().rev() {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            match stmt {
                Statement::Assign { .. } => unreachable!(),
                Statement::Nop | Statement::StorageLive(_) | Statement::StorageDead(_) => continue,
                _ => return None,
            }
        };

        // Empty-operand Adt aggregate (the ensures/requires checker marker):
        // contributes no field defs (mirrors `extract_block_definitions`).
        if let Rvalue::Aggregate(AggregateKind::Adt { .. }, operands) = rvalue {
            if operands.is_empty() {
                continue;
            }
            return None;
        }

        let dest_name = field_or_local_var_name(locals, place)?;
        if !seen_dests.insert(dest_name.clone()) {
            continue;
        }

        // CheckedBinaryOp: its result def rides on the semantic guards (skip).
        if matches!(rvalue, Rvalue::CheckedBinaryOp(..)) {
            continue;
        }

        let dest_sort = local_place_sort(locals, place);
        let rhs = match rvalue {
            Rvalue::Use(operand) => block_def_operand_formula(locals, operand)?,
            // Integer COMPARISON binop (`_b = _x < _y`): reproduce trust-vcgen's
            // `try_binop_to_formula` comparison encoding. Only the six relational
            // ops are in the envelope (their RHS is a clean `Lt`/`Le`/`Gt`/`Ge`/`Eq`/
            // `Ne` of two integer operands); a non-comparison binop (Add/Sub/BitAnd/
            // shift/…) is OUTSIDE the envelope here (trust-vcgen routes those through
            // CHC widths / bool-logic / shift-range branches we do not mirror) and
            // fails the whole reconstruction closed.
            Rvalue::BinaryOp(op, lhs, rhs) => {
                let l = safety_operand_to_formula(locals, lhs)?;
                let r = safety_operand_to_formula(locals, rhs)?;
                reconstruct_comparison_binop(*op, l, r)?
            }
            _ => return None,
        };
        defs.push(Formula::Eq(Box::new(Formula::var(&dest_name, dest_sort)), Box::new(rhs)));
    }

    Some(defs)
}

/// The six integer relational binops, encoded exactly as
/// `trust_vcgen::chc::try_binop_to_formula` does. Returns `None` for any
/// non-comparison op (outside the loop block-def envelope → fail-closed).
fn reconstruct_comparison_binop(op: BinOp, lhs: Formula, rhs: Formula) -> Option<Formula> {
    let b = |f| Box::new(f);
    Some(match op {
        BinOp::Lt => Formula::Lt(b(lhs), b(rhs)),
        BinOp::Le => Formula::Le(b(lhs), b(rhs)),
        BinOp::Gt => Formula::Gt(b(lhs), b(rhs)),
        BinOp::Ge => Formula::Ge(b(lhs), b(rhs)),
        BinOp::Eq => Formula::Eq(b(lhs), b(rhs)),
        BinOp::Ne => Formula::Not(Box::new(Formula::Eq(b(lhs), b(rhs)))),
        _ => return None,
    })
}

/// The local names a `Call` terminator's destination invalidates — the spine
/// reproduction of `terminator_def_names` for the loop envelope. The live function
/// havocs the `Call` dest AND every mutably-borrowed / mutable-pointer local. We
/// FAIL CLOSED (return `None`) the instant the function carries ANY mutable
/// reference / raw pointer (a `&mut`/`*mut` anywhere in a local type), because the
/// live `mutably_borrowed_local_names` / `mutable_pointer_local_names` kill sets are
/// outside the envelope we mirror; for the pure-value loop body (`count`: all `u32`
/// by value) those sets are empty, so the kill set is exactly the projection-free
/// `Call` dest name.
fn reconstruct_terminator_def_names(
    func: &VerifiableFunction,
    block: &TrustBlock,
) -> Option<Vec<String>> {
    match &block.terminator {
        Terminator::Call { dest, .. } => {
            // Any mutable reference / raw pointer in the function is outside the
            // envelope (the live kill set would include borrowed/pointee names we do
            // not compute). Fail closed.
            if func.body.locals.iter().any(|d| ty_contains_mut_pointer_loop(&d.ty)) {
                return None;
            }
            // The projection-free dest name (the value the call writes).
            let name = field_or_local_var_name(&func.body.locals, dest)?;
            Some(vec![name])
        }
        _ => Some(Vec::new()),
    }
}

/// True if `ty` TRANSITIVELY contains a mutable reference / raw pointer — the spine
/// reproduction of `ty_contains_mut_pointer`. Used to fail closed on any function
/// whose `Call` kill set would include borrowed/pointee names (outside the loop
/// envelope). Conservative: a SHARED `&`/`*const` is not recursed (matching the live
/// gate), but ANY `&mut`/`*mut` (direct or nested) trips it.
fn ty_contains_mut_pointer_loop(ty: &Ty) -> bool {
    match ty {
        Ty::Ref { mutable: true, .. } | Ty::RawPtr { mutable: true, .. } => true,
        // Trust: piece #7a — descend into a const-generic array's element too;
        // SOUNDNESS-CRITICAL (drives the conservative loop-havoc kill set).
        Ty::Slice { elem } | Ty::Array { elem, .. } | Ty::SymArray { elem, .. } => {
            ty_contains_mut_pointer_loop(elem)
        }
        Ty::Tuple(elems) => elems.iter().any(ty_contains_mut_pointer_loop),
        Ty::Adt { fields, .. } => fields.iter().any(|(_, t)| ty_contains_mut_pointer_loop(t)),
        Ty::Closure { upvars, .. } | Ty::Coroutine { upvars, .. } => {
            upvars.iter().any(ty_contains_mut_pointer_loop)
        }
        _ => false,
    }
}

/// Faithful port of `trust_vcgen::generate::build_semantic_guard_map` for the LOOP
/// (cyclic) CFG. Unlike `reconstruct_semantic_guard_map` (which fails closed on a
/// `Call` terminator and a `BinaryOp` block-def), this handles the loop body's
/// `Call` (`wrapping_add`) terminators and comparison block-defs, AND threads the
/// `terminator_def_names` havoc of the `Call` dest into the forwarded facts — exactly
/// as the live algorithm does.
///
/// The live algorithm's loop termination relies SOLELY on the visited-state
/// weakening (`NOT_VISITED → VISITED_PRECISE → VISITED_WEAKENED`, then `continue`),
/// so each block is processed at most through two states regardless of the back-edge.
/// We reproduce that exactly, so a `count`-shaped loop terminates and the loop header
/// + return block both weaken to `[Bool(true)]`.
///
/// FAIL CLOSED (`None`) on: any block-def shape outside the loop envelope
/// (`reconstruct_loop_block_definitions`), any `Call` whose kill set is outside the
/// envelope (`reconstruct_terminator_def_names`), or a `Call` callee that the LIVE
/// algorithm would attach a result-bound fact to (`len`/`min`/`max`/`clamp`) — we do
/// NOT model those facts, so we decline the whole map rather than emit a divergent
/// one. `wrapping_add` attaches no such fact and is in the envelope.
fn reconstruct_loop_semantic_guard_map(
    func: &VerifiableFunction,
) -> Option<FxHashMap<BlockId, Vec<Formula>>> {
    use std::collections::VecDeque;

    const NOT_VISITED: u8 = 0;
    const VISITED_PRECISE: u8 = 1;
    const VISITED_WEAKENED: u8 = 2;

    let n = func.body.blocks.len();
    let mut result: FxHashMap<BlockId, Vec<Formula>> = FxHashMap::default();
    let mut visited = vec![NOT_VISITED; n];
    let index_of = |id: BlockId| func.body.blocks.iter().position(|b| b.id == id);

    let mut queue: VecDeque<(BlockId, Vec<Formula>)> = VecDeque::new();
    queue.push_back((BlockId(0), Vec::new()));

    while let Some((block_id, mut acc_guards)) = queue.pop_front() {
        let Some(idx) = index_of(block_id) else {
            continue;
        };
        let block = &func.body.blocks[idx];

        // A `Call` callee that the live map attaches a synthesized result-bound to
        // (`len`/`min`/`max`/`clamp`) is outside the envelope — decline the map.
        if let Terminator::Call { func: callee, .. } = &block.terminator {
            if callee_attaches_result_fact(callee) {
                return None;
            }
        }

        let block_defs = reconstruct_loop_block_definitions(func, block)?;
        let redefined: FxHashSet<String> =
            block_defs.iter().filter_map(formula_def_name).map(str::to_string).collect();
        if !redefined.is_empty() {
            acc_guards.retain(|f| formula_survives_redefs(f, &redefined));
        }

        match visited[idx] {
            VISITED_WEAKENED => continue,
            VISITED_PRECISE => {
                let existing = result.get(&block_id).cloned().unwrap_or_default();
                if existing == acc_guards {
                    continue;
                }
                acc_guards = vec![Formula::Bool(true)];
                result.insert(block_id, acc_guards.clone());
                visited[idx] = VISITED_WEAKENED;
            }
            NOT_VISITED => {
                visited[idx] = VISITED_PRECISE;
                if !acc_guards.is_empty() {
                    result.insert(block_id, acc_guards.clone());
                }
            }
            _ => unreachable!("loop semantic guard visitation state"),
        }

        let mut next_guards = acc_guards;
        for f in reconstruct_assert_passed_semantics(&func.body.locals, block).into_iter().flatten()
        {
            if formula_survives_redefs(&f, &redefined) {
                next_guards.push(f);
            }
        }
        next_guards.extend(block_defs);

        // Terminator-level kill (a `Call` dest written without an intermediate temp).
        let term_defs = reconstruct_terminator_def_names(func, block)?;
        if !term_defs.is_empty() {
            let term_set: FxHashSet<String> = term_defs.into_iter().collect();
            next_guards.retain(|f| formula_survives_redefs(f, &term_set));
        }

        match &block.terminator {
            Terminator::Assert { target, .. } | Terminator::Goto(target) => {
                queue.push_back((*target, next_guards));
            }
            Terminator::SwitchInt { targets, otherwise, .. } => {
                for (_, target) in targets {
                    queue.push_back((*target, next_guards.clone()));
                }
                queue.push_back((*otherwise, next_guards));
            }
            Terminator::Call { target: Some(target), .. } => {
                queue.push_back((*target, next_guards));
            }
            Terminator::Call { target: None, .. } => {}
            Terminator::Drop { target, .. } => {
                queue.push_back((*target, next_guards));
            }
            Terminator::Return | Terminator::Unreachable | Terminator::Resume => {}
            // Opaque (and any unknown variant) carries dataflow we do not model.
            _ => return None,
        }
    }

    Some(result)
}

/// True if the live `build_semantic_guard_map` would attach a synthesized
/// result-bound fact to a `Call` to this callee (`len`/`min`/`max`/`clamp`). We do
/// not model those facts, so the loop reconstruction declines any function carrying
/// such a call. `wrapping_add` (the `count` body call) attaches NOTHING and is fine.
fn callee_attaches_result_fact(callee: &str) -> bool {
    if trust_types::total_call_summaries::total_summary_len_bound(callee) {
        return true;
    }
    // Mirror `trust_vcgen::generate::ord_method`: the `min`/`max`/`clamp` Ord/cmp
    // stdlib calls (the result-bound facts the live `build_semantic_guard_map`
    // attaches). Matching the live gate exactly maximizes the firing envelope while
    // staying sound — declining the function the instant such a call appears (we do
    // not model the facts).
    let Some(last) = callee.rsplit("::").next() else {
        return false;
    };
    let method = last.split('<').next().unwrap_or(last).trim();
    if !matches!(method, "min" | "max" | "clamp") {
        return false;
    }
    callee.contains("core::cmp::") || callee.contains("std::cmp::") || callee.contains("as Ord>::")
}

/// Port of `trust_vcgen::generate::v2_build_path_guard_map` for the LOOP envelope,
/// storing the RAW `GuardCondition`s (NOT eagerly lowered to `Formula`). This matches
/// the live two-phase structure: the BFS records `GuardCondition` paths, and lowering
/// to a `Formula` happens LATER (only when a path guard is actually applied to a
/// block). Eager lowering — as the acyclic `reconstruct_path_guard_map` does — fails
/// closed on a DEFINED-Bool loop-condition discriminant (`_5 = _6 < n`) even when that
/// guard is never used (the vc_block's own paths are empty), so the loop needs the
/// lazy form. The `path_blocks.contains` cycle guard (mirroring the live one) makes
/// this terminate on the back-edge.
fn reconstruct_loop_path_guard_map(
    func: &VerifiableFunction,
) -> FxHashMap<BlockId, Vec<Vec<trust_types::GuardCondition>>> {
    use std::collections::VecDeque;
    let mut result: FxHashMap<BlockId, Vec<Vec<trust_types::GuardCondition>>> =
        FxHashMap::default();
    if func.body.blocks.is_empty() {
        return result;
    }
    let index_of = |id: BlockId| func.body.blocks.iter().position(|b| b.id == id);

    // Faithful to `v2_build_path_guard_map`: a per-block path cap and a global step
    // cap, so a pathological CFG saturates to the unguarded form deterministically
    // (the same RESULT the live builder produces) instead of running unbounded.
    const MAX_PATHS_PER_BLOCK: usize = 64;
    let n = func.body.blocks.len();
    let cap = n.saturating_mul(n).saturating_add(n).saturating_mul(16).saturating_add(4096);
    let mut steps = 0usize;
    let mut saturated_blocks: FxHashSet<BlockId> = FxHashSet::default();

    let mut queue: VecDeque<(BlockId, Vec<trust_types::GuardCondition>, Vec<BlockId>)> =
        VecDeque::from([(BlockId(0), Vec::new(), Vec::new())]);

    while let Some((block_id, path_guards, mut path_blocks)) = queue.pop_front() {
        steps += 1;
        if steps > cap {
            // Global saturation: every block collapses to a single unguarded path
            // (matches the live builder's `cap` escape hatch byte-for-byte).
            return func.body.blocks.iter().map(|block| (block.id, vec![Vec::new()])).collect();
        }
        let Some(idx) = index_of(block_id) else {
            continue;
        };
        if path_blocks.contains(&block_id) {
            continue;
        }
        path_blocks.push(block_id);

        let paths = result.entry(block_id).or_default();
        if saturated_blocks.contains(&block_id) {
            // Already weakened to a single unguarded path.
        } else if paths.len() < MAX_PATHS_PER_BLOCK {
            paths.push(path_guards.clone());
        } else {
            paths.clear();
            paths.push(Vec::new());
            saturated_blocks.insert(block_id);
        }

        let block = &func.body.blocks[idx];
        for guarded in block.terminator.discovered_clauses(block_id) {
            if let trust_types::ClauseTarget::Block(target) = guarded.target {
                let mut next = path_guards.clone();
                next.push(guarded.guard);
                queue.push_back((target, next, path_blocks.clone()));
            }
        }
        for target in block.terminator.unguarded_successors() {
            queue.push_back((target, path_guards.clone(), path_blocks.clone()));
        }
    }
    result
}

/// Apply the loop path-guard paths for a block to `formula`, lowering each
/// `GuardCondition` to a `Formula` LAZILY (only now). Returns `None` (fail-closed for
/// the whole reconstruction) if ANY guard on ANY non-trivial path is outside the
/// reproducible envelope — but an EMPTY guard list (the common vc_block case) lowers
/// trivially and never fails. Mirrors `v2_formula_with_path_guards` ∘ `guarded_formula`.
fn apply_loop_path_guards(
    func: &VerifiableFunction,
    guard_paths: &[Vec<trust_types::GuardCondition>],
    formula: Formula,
) -> Option<Formula> {
    let mut terms: Vec<Formula> = Vec::with_capacity(guard_paths.len());
    for guards in guard_paths {
        let mut lowered: Vec<Formula> = Vec::with_capacity(guards.len());
        for g in guards {
            lowered.push(reconstruct_guard_formula(func, g)?);
        }
        terms.push(apply_guarded_formula(&lowered, formula.clone()));
    }
    Some(match terms.len() {
        0 => formula,
        1 => terms.pop().unwrap_or(formula),
        _ => Formula::Or(terms),
    })
}

/// Reconstruct, BYTE-FOR-BYTE, the per-(Return-block × predecessor) `Postcondition`
/// VC formulas `generate_v2_contract_vcs_impl` emits for a LOOP (cyclic) body — the final
/// CFG tier. Mirrors the acyclic assembly, but (a) only activates on a CYCLIC CFG
/// (`cfg_has_back_edge`), (b) uses the loop-aware semantic-guard map + loop block
/// defs, and (c) ALLOWS a named local-0 return slot (`__ret`) via the live no-op
/// `ret_alias`→`_0` rename guard.
///
/// Returns one candidate per `(return_block, vc_block)` pair, or an empty vec
/// (FAIL-CLOSED) for any function outside the reproducible loop envelope. The flip
/// accepts a candidate ONLY on exact `Formula` byte-equality, so a loop whose widened
/// env contributes a non-empty loop-variable conjunct (a bounded counter that does
/// not reach TOP) does not byte-match and stays trust-vcgen-sourced.
fn reconstruct_loop_postcondition_formulas(func: &VerifiableFunction) -> Vec<Formula> {
    // ONLY a cyclic CFG (the acyclic path owns the acyclic case).
    if !cfg_has_back_edge(func) {
        return Vec::new();
    }

    // Exactly one ensures predicate (same envelope as the acyclic case).
    if func.postconditions.len() != 1 {
        return Vec::new();
    }
    let post = &func.postconditions[0];

    // The return slot must be the default Int (the postcond parser models `_0` as
    // Int). A named local 0 (`__ret`) is ALLOWED here — the live builder renames the
    // `place_to_var_name` alias `__ret`→`_0` over the final formula; we require that
    // rename to be a NO-OP (the formula never references `__ret`), which holds for the
    // simple loop shape (the return-pin uses `_0` directly).
    let Some(ret_decl) = func.body.locals.iter().find(|d| d.index == 0) else {
        return Vec::new();
    };
    if ret_decl.ty.int_width().is_none() {
        return Vec::new();
    }

    let Some(semantic_guards) = reconstruct_loop_semantic_guard_map(func) else {
        return Vec::new();
    };
    // Lazy (raw `GuardCondition`) path-guard map — lowered only when applied, so a
    // defined-Bool loop-condition guard that is never used does not fail closed.
    let path_guard_map = reconstruct_loop_path_guard_map(func);

    // Precondition reassignment guard (same fail-closed envelope as acyclic).
    if precondition_var_reassigned_anywhere(func) {
        return Vec::new();
    }

    // The refined abstract-interp env conjunct. KEY: this is the integer-parameter
    // type range ONLY — the loop variables widen to TOP and are filtered out by
    // `interval_domain_to_formula`, so they contribute nothing. We do NOT run the
    // fixpoint; we reproduce its OBSERVABLE env (params only). The exact-equality gate
    // is the proof: if a loop var did NOT widen to TOP (so the live env carries an
    // extra conjunct), the candidate would not byte-match and the flip fails closed.
    let env = reconstruct_abstract_state_param_env(func);

    // The block-def alias for local 0 (`place_to_var_name`): the declared name or
    // `_0`. The live rename `ret_alias`→`_0` over the FINAL formula must be a NO-OP,
    // i.e. the alias must not appear in the reconstructed formula. We enforce that by
    // construction (the return-pin and block-defs are built with `_0`/value names,
    // never the `__ret` alias) and additionally CHECK it below.
    let ret_alias = field_or_local_var_name(&func.body.locals, &Place::local(0));

    let mut out: Vec<Formula> = Vec::new();

    for ret_block in func.body.blocks.iter() {
        if !matches!(ret_block.terminator, Terminator::Return) {
            continue;
        }
        let predecessors: Vec<&TrustBlock> = func
            .body
            .blocks
            .iter()
            .filter(|pred| terminator_targets_block(&pred.terminator, ret_block.id))
            .collect();
        let vc_blocks: Vec<&TrustBlock> =
            if predecessors.is_empty() { vec![ret_block] } else { predecessors };

        for vc_block in &vc_blocks {
            // (1) Not(post).
            let mut formula = Formula::Not(Box::new(post.clone()));

            // (2) return-block block-defs (relevance-filtered).
            let Some(ret_defs) = reconstruct_loop_block_definitions(func, ret_block) else {
                return Vec::new();
            };
            formula = combine_relevant_block_defs(ret_defs, formula);

            // (3) vc_block block-defs (if distinct).
            if vc_block.id != ret_block.id {
                let Some(pred_defs) = reconstruct_loop_block_definitions(func, vc_block) else {
                    return Vec::new();
                };
                formula = combine_relevant_block_defs(pred_defs, formula);
            }

            // (4) RETURN-PIN loop over `[vc_block, ret_block]`. Pin `Eq(_0, rvalue)`
            // for each directly-representable `_0 = Use(operand)` assignment.
            for def_block in [*vc_block, ret_block] {
                for stmt in &def_block.stmts {
                    let Statement::Assign { place, rvalue, .. } = stmt else {
                        continue;
                    };
                    if place.local != 0 || !place.projections.is_empty() {
                        continue;
                    }
                    if matches!(rvalue, Rvalue::CheckedBinaryOp(..)) {
                        continue;
                    }
                    let Rvalue::Use(operand) = rvalue else {
                        return Vec::new();
                    };
                    let Some(rhs) = block_def_operand_formula(&func.body.locals, operand) else {
                        return Vec::new();
                    };
                    let ret_def =
                        Formula::Eq(Box::new(Formula::var("_0", Sort::Int)), Box::new(rhs));
                    formula = Formula::And(vec![ret_def, formula]);
                }
            }

            // (5) PATH GUARDS for vc_block (lowered lazily; fail closed if a USED
            // guard is outside the envelope).
            if let Some(paths) = path_guard_map.get(&vc_block.id) {
                let Some(guarded) = apply_loop_path_guards(func, paths, formula) else {
                    return Vec::new();
                };
                formula = guarded;
            }

            // (6) SEMANTIC GUARDS: return-block then (if different) vc_block.
            let mut sem_conjuncts: Vec<Formula> = Vec::new();
            if let Some(g) = semantic_guards.get(&ret_block.id) {
                sem_conjuncts.extend(g.iter().cloned());
            }
            if vc_block.id != ret_block.id
                && let Some(g) = semantic_guards.get(&vc_block.id)
            {
                sem_conjuncts.extend(g.iter().cloned());
            }
            if !sem_conjuncts.is_empty() {
                sem_conjuncts.push(formula);
                formula = Formula::And(sem_conjuncts);
            }

            // (7) LIVE PRECONDITIONS (straight-through).
            formula = conjoin_live_preconditions_full(func, formula);

            // (8) REFINED ENV (prepend iff non-Top).
            if let Some(env) = &env {
                formula = Formula::And(vec![env.clone(), formula]);
            }

            // The live `ret_alias`→`_0` rename must be a NO-OP: the reconstructed
            // formula must not mention the `__ret` alias (we built it with `_0`).
            // If it somehow does, the live rename would change it and our candidate
            // would diverge — fail closed for this whole reconstruction.
            if let Some(alias) = &ret_alias {
                if alias != "_0" {
                    let mut names: FxHashSet<String> = FxHashSet::default();
                    collect_formula_var_names(&formula, &mut names);
                    if names.contains(alias) {
                        return Vec::new();
                    }
                }
            }

            out.push(dedup_identical_return_slot_pin(formula));
        }
    }

    out
}

/// Reconstruct CANDIDATE byte-equal formulas for the function's `Postcondition`
/// VC(s). Returns the straight-line single-Return candidate (if in that scope)
/// PLUS the acyclic per-(Return×predecessor) candidates (if in THAT scope), PLUS the
/// loop per-(Return×predecessor) candidates (if the CFG is cyclic and in THAT scope),
/// or an empty vec (fail-closed). The flip matches each `Postcondition` VC's formula
/// against this candidate set by exact `Formula` byte-equality, so a wrong/partial
/// candidate can never flip a verdict.
pub(crate) fn reconstruct_postcondition_formula_candidates(
    func: &VerifiableFunction,
) -> Vec<Formula> {
    let mut cands: Vec<Formula> =
        reconstruct_simple_postcondition_formula(func).into_iter().collect();
    cands.extend(reconstruct_acyclic_postcondition_formulas(func));
    cands.extend(reconstruct_loop_postcondition_formulas(func));
    cands
}

/// True when an `AssertMessage` class corresponds to the trust-vcgen `VcKind`
/// class — the per-class guard for span-based matching.
fn assert_message_matches_vc_kind(msg: &AssertMessage, vc_kind: &VcKind) -> bool {
    match (msg, vc_kind) {
        (
            AssertMessage::Overflow(BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem),
            VcKind::ArithmeticOverflow { .. },
        ) => true,
        (AssertMessage::Overflow(BinOp::Shl | BinOp::Shr), VcKind::ShiftOverflow { .. }) => true,
        (AssertMessage::OverflowNeg, VcKind::NegationOverflow { .. }) => true,
        (AssertMessage::DivisionByZero, VcKind::DivisionByZero) => true,
        (AssertMessage::RemainderByZero, VcKind::RemainderByZero) => true,
        (AssertMessage::BoundsCheck, VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck) => true,
        _ => false,
    }
}

#[derive(Debug, Clone)]
struct ObligationSourceMetadata {
    source_id: String,
    assertion_id: String,
    native_assertion_id: u32,
    span: TrustSourceSpan,
    /// The machine-readable contract predicate, when this obligation came from a
    /// contract clause (requires/ensures/invariant/refinement). `None` for
    /// MIR-assert and function-aggregate obligations, which have no predicate.
    predicate: Option<ContractPredicate>,
    /// The reconstructed core L0 safety predicate, when this obligation came from
    /// a `Terminator::Assert` whose `AssertMessage` has a reconstructable
    /// arithmetic/bounds core (overflow / div-by-zero). `None` for contract,
    /// function-aggregate, and non-arithmetic safety obligations. Mutually
    /// exclusive with `predicate` in practice (an obligation is either a contract
    /// clause or a MIR-assert, never both).
    safety_predicate: Option<SafetyPredicate>,
}

impl ObligationSourceMetadata {
    fn to_proof_source_identity(&self, module: &mut Module) -> ProofObligationSourceIdentity {
        let identity =
            ProofObligationSourceIdentity::new(self.source_id.clone(), self.assertion_id.clone());
        if self.span.file.is_empty() {
            return identity;
        }
        identity.with_range(ProofObligationSourceRange {
            file: module.intern_file(self.span.file.clone()),
            start_line: self.span.line_start,
            start_col: self.span.col_start,
            end_line: self.span.line_end,
            end_col: self.span.col_end,
        })
    }

    fn for_contract(
        func: &VerifiableFunction,
        contract_index: usize,
        contract: &trust_types::Contract,
    ) -> Self {
        Self {
            source_id: contract.stable_source_id(&func.def_path, contract_index),
            assertion_id: contract.stable_assertion_id(&func.def_path, contract_index),
            native_assertion_id: contract
                .stable_native_assertion_index(&func.def_path, contract_index),
            span: contract.span.clone(),
            // Parse the contract predicate NOW (fail-closed) so the obligation
            // carries it machine-readably — this is the D2.1 enrichment.
            predicate: ContractPredicate::from_contract(contract.kind, &contract.body),
            // A contract obligation is never a MIR-assert safety check.
            safety_predicate: None,
        }
    }

    /// MIR-assert obligation metadata, enriched (trust-ir-spine Phase 2/3) with
    /// the reconstructed solvable L0 safety predicate when the assert's
    /// `AssertMessage` has a faithful arithmetic/bounds/shift core (overflow /
    /// div-by-zero / bounds / shift). `locals`/`all_blocks`/`target`/`cond` are the
    /// trust-types data [`reconstruct_assert_safety_predicate`] needs to recover
    /// the operands the predicate ranges over; they never affect the source ids.
    #[allow(clippy::too_many_arguments)]
    fn for_mir_assert(
        function_def_path: &str,
        block: BlockId,
        span: &TrustSourceSpan,
        message: &str,
        locals: &[LocalDecl],
        all_blocks: &[TrustBlock],
        target: BlockId,
        cond: &Operand,
        msg: &AssertMessage,
    ) -> Self {
        let source_id = format!("mir-assert:{function_def_path}:bb{}:terminator", block.0);
        let assertion_id = format!(
            "trust-assertion:{source_id}:{}",
            trust_types::stable_sha256_hex(message.as_bytes())
        );
        let native_assertion_id = trust_types::stable_u32_id(assertion_id.as_bytes());
        // MIR-assert obligations are panic-class safety, not contract predicates;
        // but they CAN carry a reconstructed solvable safety formula (the heart
        // of the spine-as-source-of-record requirement).
        let safety_predicate =
            reconstruct_assert_safety_predicate(locals, all_blocks, block, target, cond, msg);
        Self {
            source_id,
            assertion_id,
            native_assertion_id,
            span: span.clone(),
            predicate: None,
            safety_predicate,
        }
    }

    /// F8: source metadata for a CONDITIONAL panic-freedom obligation whose solvable
    /// core predicate is supplied DIRECTLY (not reconstructed from an `AssertMessage`).
    /// Used for the rewritten `Ratio::new` zero-denominator obligation, whose panic
    /// condition (`prim == 0` / `is_zero_result == true`) is derived by the F8 axioms
    /// at the call site rather than from a MIR-assert. `safety_formula` is the PANIC
    /// condition the verifier must refute UNSAT under the caller's guards; `None`
    /// records a fail-closed audit marker (the in-body `Inst::Assert` still carries
    /// the check for the CHC lane), never a fabricated formula.
    fn for_conditional_panic(
        function_def_path: &str,
        block: BlockId,
        span: &TrustSourceSpan,
        message: &str,
        safety_formula: Option<Formula>,
    ) -> Self {
        let source_id =
            format!("mir-conditional-panic:{function_def_path}:bb{}:terminator", block.0);
        let assertion_id = format!(
            "trust-assertion:{source_id}:{}",
            trust_types::stable_sha256_hex(message.as_bytes())
        );
        let native_assertion_id = trust_types::stable_u32_id(assertion_id.as_bytes());
        let safety_predicate = Some(match safety_formula {
            Some(formula) => SafetyPredicate::Reconstructed(formula),
            None => SafetyPredicate::NotReconstructed(
                "Ratio::new denom witness outside the faithful envelope (projected/symbolic \
                 source) — the in-body conditional Assert still carries the check"
                    .into(),
            ),
        });
        Self {
            source_id,
            assertion_id,
            native_assertion_id,
            span: span.clone(),
            predicate: None,
            safety_predicate,
        }
    }

    fn for_function_assertions(function_def_path: &str, span: &TrustSourceSpan) -> Self {
        let source_id = format!("mir-assertions:{function_def_path}:panic-freedom");
        let assertion_id = format!("trust-assertion:{source_id}");
        let native_assertion_id = trust_types::stable_u32_id(assertion_id.as_bytes());
        // The function-level panic-freedom aggregate has no contract predicate
        // and no per-site safety predicate (it is the whole-function aggregate).
        Self {
            source_id,
            assertion_id,
            native_assertion_id,
            span: span.clone(),
            predicate: None,
            safety_predicate: None,
        }
    }

    /// The structured source-metadata JSON (`source_id` / `assertion_id` /
    /// `native_assertion_id` / `span`) common to every obligation. This is the
    /// span-preserving record; it is the WHOLE payload for non-contract
    /// obligations and the nested `source` field of the predicate-bearing
    /// payload for contract obligations (so the span is never lost — task
    /// constraint).
    fn source_json(&self) -> serde_json::Value {
        serde_json::json!({
            "source_id": self.source_id,
            "assertion_id": self.assertion_id,
            "native_assertion_id": self.native_assertion_id,
            "span": {
                "file": self.span.file,
                "line_start": self.span.line_start,
                "col_start": self.span.col_start,
                "line_end": self.span.line_end,
                "col_end": self.span.col_end,
            },
        })
    }

    fn into_formula(self) -> ProofFormula {
        match &self.predicate {
            // CONTRACT obligation, predicate parsed: emit it machine-readably.
            // The payload is a `trust-types.Formula@1` JSON document carrying the
            // serialized `Formula` AST under `formula`, plus the source metadata
            // (span preserved) under `source`. `smtlib`/`sort` are populated so a
            // router can dispatch without re-parsing the description string.
            Some(ContractPredicate::Parsed(formula)) => {
                // serde_json::to_value on a trust_types::Formula is infallible in
                // practice (no map keys, no non-finite floats in the AST); on the
                // theoretical error we FAIL CLOSED to the source-metadata payload
                // rather than emit a wrong/empty formula.
                match serde_json::to_value(formula) {
                    Ok(formula_json) => ProofFormula {
                        schema: TRUST_CONTRACT_PREDICATE_SCHEMA.to_string(),
                        payload: serde_json::json!({
                            "formula": formula_json,
                            "source": self.source_json(),
                        })
                        .to_string(),
                        smtlib: Some(formula.to_smtlib()),
                        sort: Some(TRUST_CONTRACT_PREDICATE_SORT.to_string()),
                    },
                    Err(_) => self.fail_closed_source_formula(Some("formula-serialization-failed")),
                }
            }
            // CONTRACT obligation, predicate did NOT parse: FAIL CLOSED. Keep the
            // source-metadata schema, leave smtlib/sort None, and mark the
            // failure (with the attempted predicate) so no consumer mistakes the
            // absent formula for a successfully-rendered one.
            Some(ContractPredicate::Unparseable(expr)) => {
                self.fail_closed_source_formula_with_predicate(expr)
            }
            // NON-contract obligation: MIR-assert (may carry a reconstructed
            // solvable safety formula) or function-aggregate (no predicate).
            None => self.safety_into_formula(),
        }
    }

    /// `into_formula` for a MIR-assert obligation: emit the reconstructed
    /// solvable L0 safety predicate when one was reconstructed faithfully,
    /// otherwise the unchanged source-metadata-only payload (with a fail-closed
    /// audit marker when reconstruction was attempted but declined).
    ///
    /// The payload schema is the SAME `trust-types.Formula@1`
    /// ([`TRUST_CONTRACT_PREDICATE_SCHEMA`]) the contract-predicate path uses, so a
    /// router/backend indexes a safety formula and a contract formula identically;
    /// the `kind`/`description` on the surrounding `ProofObligation` distinguish
    /// them. SMT-LIB + a `Bool` sort are populated so the solvable formula is
    /// directly consumable. This is the byte-for-byte equivalence the spine needs
    /// so a future verdict flip cannot regress `proved → unknown`.
    fn safety_into_formula(&self) -> ProofFormula {
        match &self.safety_predicate {
            // Reconstructed core safety predicate: emit it machine-readably,
            // exactly like a parsed contract predicate.
            Some(SafetyPredicate::Reconstructed(formula)) => match serde_json::to_value(formula) {
                Ok(formula_json) => ProofFormula {
                    schema: TRUST_CONTRACT_PREDICATE_SCHEMA.to_string(),
                    payload: serde_json::json!({
                        "formula": formula_json,
                        "source": self.source_json(),
                    })
                    .to_string(),
                    smtlib: Some(formula.to_smtlib()),
                    sort: Some(TRUST_SAFETY_PREDICATE_SORT.to_string()),
                },
                // Theoretical serialization failure → fail closed to source-only.
                Err(_) => {
                    self.fail_closed_source_formula(Some("safety-formula-serialization-failed"))
                }
            },
            // Reconstruction was attempted (the message has an arithmetic/bounds
            // class) but the operands were outside the faithful envelope: FAIL
            // CLOSED with an audit marker recording why — never a guessed formula.
            Some(SafetyPredicate::NotReconstructed(reason)) => {
                let mut payload = self.source_json();
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "safety_formula_not_reconstructed".to_string(),
                        serde_json::Value::String(reason.clone()),
                    );
                }
                ProofFormula {
                    schema: TRUST_OBLIGATION_SOURCE_SCHEMA.to_string(),
                    payload: payload.to_string(),
                    smtlib: None,
                    sort: None,
                }
            }
            // Not a reconstructable safety class (function-aggregate, or a
            // non-arithmetic/non-bounds message): unchanged source-only payload.
            None => self.fail_closed_source_formula(None),
        }
    }

    /// The source-metadata `ProofFormula` (schema
    /// [`TRUST_OBLIGATION_SOURCE_SCHEMA`], no smtlib/sort). Used for non-contract
    /// obligations and as the fail-closed fallback. `parse_error`, when set,
    /// records WHY the predicate is absent from the payload.
    fn fail_closed_source_formula(&self, parse_error: Option<&str>) -> ProofFormula {
        let mut payload = self.source_json();
        if let Some(reason) = parse_error
            && let Some(obj) = payload.as_object_mut()
        {
            obj.insert(
                "predicate_parse_failed".to_string(),
                serde_json::Value::String(reason.to_string()),
            );
        }
        ProofFormula {
            schema: TRUST_OBLIGATION_SOURCE_SCHEMA.to_string(),
            payload: payload.to_string(),
            smtlib: None,
            sort: None,
        }
    }

    /// Fail-closed source-metadata `ProofFormula` for a contract whose predicate
    /// did not parse, recording the attempted predicate string. `smtlib`/`sort`
    /// stay `None` — we emit NO formula, never a wrong one.
    fn fail_closed_source_formula_with_predicate(&self, attempted: &str) -> ProofFormula {
        let mut payload = self.source_json();
        if let Some(obj) = payload.as_object_mut() {
            obj.insert(
                "predicate_parse_failed".to_string(),
                serde_json::Value::String("unparseable-contract-predicate".to_string()),
            );
            obj.insert(
                "attempted_predicate".to_string(),
                serde_json::Value::String(attempted.to_string()),
            );
        }
        ProofFormula {
            schema: TRUST_OBLIGATION_SOURCE_SCHEMA.to_string(),
            payload: payload.to_string(),
            smtlib: None,
            sort: None,
        }
    }
}

/// Get the type of a field in a tuple or ADT.
fn field_type(ty: &Ty, field_idx: usize) -> Result<Ty, BridgeError> {
    match ty {
        Ty::Tuple(elems) => elems.get(field_idx).cloned().ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "tuple field {field_idx} out of range (len {})",
                elems.len()
            ))
        }),
        Ty::Adt { fields, .. } => {
            fields.get(field_idx).map(|(_, fty): &(String, Ty)| fty.clone()).ok_or_else(|| {
                BridgeError::UnsupportedOp(format!(
                    "ADT field {field_idx} out of range (len {})",
                    fields.len()
                ))
            })
        }
        Ty::Closure { upvars, .. } => upvars.get(field_idx).cloned().ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "closure capture field {field_idx} out of range (len {})",
                upvars.len()
            ))
        }),
        // Trust: piece #13 step-2 (safe-async native lowering) — a coroutine
        // FRAME field. The captured-arg PREFIX fields are typed by `upvars` (a
        // zero-await resume body reads these back, e.g. `((*self).0: u8)` = the
        // saved arg). The frame VALUE is built as an opaque `Inst::Undef`
        // (aggregate lowering), so `resolve_place`'s `ExtractField` off it yields
        // a FRESH UNCONSTRAINED value — the type is precise, the value is havoc'd
        // (the sound over-approximation, never a stale across-suspend fact). A
        // field index BEYOND the upvars is an across-await saved local (only in a
        // body with an `.await`): fail CLOSED (Unknown, never a false proof) — the
        // single/multi-await frontier is a sound later increment.
        Ty::Coroutine { upvars, .. } => upvars.get(field_idx).cloned().ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "coroutine frame field {field_idx} is an across-await saved local (len {}); \
                 the single/multi-await native frontier is not yet modeled",
                upvars.len()
            ))
        }),
        _ => Err(BridgeError::UnsupportedOp(format!(
            "Field projection .{field_idx} on non-aggregate type {ty:?}"
        ))),
    }
}

/// Resolve a Downcast-qualified enum field to both its physical TrustIr lane
/// and its source-level type. Faithful enums use the active variant's compact
/// `[tag, fields...]` value, while legacy enums require the extractor's
/// `__v{variant}_` flattened-field prefix. Keeping both decisions here prevents
/// value lowering and type-only call/operator gates from drifting.
fn variant_field_projection(
    ty: &Ty,
    variant_idx: usize,
    field_idx: usize,
) -> Result<(u32, Ty), BridgeError> {
    let Ty::Adt { fields, variants, faithful_enum_repr, .. } = ty else {
        return Err(BridgeError::UnsupportedOp(format!(
            "Field projection on non-ADT with active variant {variant_idx}"
        )));
    };
    if faithful_enum_repr.is_some() {
        let variant = variants.get(variant_idx).ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "variant {variant_idx} out of range (len {}) on ADT {ty:?}",
                variants.len()
            ))
        })?;
        let field_ty =
            variant.fields.get(field_idx).map(|(_, field_ty)| field_ty.clone()).ok_or_else(
                || {
                    BridgeError::UnsupportedOp(format!(
                        "variant {variant_idx} field {field_idx} out of range on first-class enum"
                    ))
                },
            )?;
        let lane = field_idx.checked_add(1).and_then(|lane| u32::try_from(lane).ok()).ok_or_else(
            || {
                BridgeError::UnsupportedOp(format!(
                    "variant {variant_idx} field {field_idx} lane exceeds TrustIr limits"
                ))
            },
        )?;
        return Ok((lane, field_ty));
    }

    let variant_prefix = format!("__v{variant_idx}_");
    let (flat_idx, (_, field_ty)) = fields
        .iter()
        .enumerate()
        .filter(|(_, (name, _))| name.starts_with(&variant_prefix))
        .nth(field_idx)
        .ok_or_else(|| {
            BridgeError::UnsupportedOp(format!(
                "field {field_idx} not found in variant {variant_idx} of legacy ADT {ty:?}"
            ))
        })?;
    let flat_idx = u32::try_from(flat_idx).map_err(|_| {
        BridgeError::UnsupportedOp(format!(
            "legacy variant {variant_idx} field {field_idx} lane exceeds TrustIr limits"
        ))
    })?;
    Ok((flat_idx, field_ty.clone()))
}

/// Walk a source place's projections using Downcast-qualified variant fields.
/// This is the type-only twin of `resolve_place_expecting`: it must return the
/// same payload type that the value lane extracts, because its result controls
/// instruction types and trust-sensitive absent-callee summary gates.
fn projected_place_type(mut current_ty: Ty, projections: &[Projection]) -> Result<Ty, BridgeError> {
    let mut active_variant = None;

    for projection in projections {
        current_ty = match projection {
            Projection::Field(idx) => match active_variant.take() {
                Some(variant_idx) => variant_field_projection(&current_ty, variant_idx, *idx)?.1,
                None if matches!(
                    &current_ty,
                    Ty::Adt { faithful_enum_repr: Some(_), variants, .. }
                        if !variants.is_empty()
                ) =>
                {
                    return Err(BridgeError::UnsupportedOp(
                        "plain Field projection on a first-class enum (no Downcast)".to_string(),
                    ));
                }
                None => field_type(&current_ty, *idx)?,
            },
            Projection::Index(_) | Projection::ConstantIndex { .. } => {
                active_variant = None;
                indexed_element_type(&current_ty, "operand")?
            }
            Projection::Deref => {
                active_variant = None;
                current_ty.pointee_ty().cloned().ok_or_else(|| {
                    BridgeError::UnsupportedOp(format!(
                        "Deref projection on non-pointer type {current_ty:?}"
                    ))
                })?
            }
            Projection::Downcast(variant) => {
                active_variant = Some(*variant);
                current_ty
            }
            Projection::OpaqueCast(ty) | Projection::UnwrapUnsafeBinder(ty) => {
                active_variant = None;
                ty.clone()
            }
            Projection::Subslice { from, to, from_end } => {
                active_variant = None;
                subslice_result_type(&current_ty, *from, *to, *from_end)?
            }
            _ => {
                return Err(BridgeError::UnsupportedOp(format!(
                    "unknown projection variant: {projection:?}"
                )));
            }
        };
    }

    Ok(current_ty)
}

fn aggregate_operand_type(ty: &Ty, field_idx: usize) -> Result<Ty, BridgeError> {
    match ty {
        Ty::Array { elem, .. } => Ok((**elem).clone()),
        _ => field_type(ty, field_idx),
    }
}

fn indexed_element_type(ty: &Ty, projection: &str) -> Result<Ty, BridgeError> {
    match ty {
        // Trust: piece #7a — a const-generic array indexes to its element type
        // (the index load itself routes through the slice path — see
        // `slice_element_type` — producing a fresh symbolic element).
        Ty::Array { elem, .. } | Ty::Slice { elem } | Ty::SymArray { elem, .. } => {
            Ok((**elem).clone())
        }
        _ => Err(BridgeError::UnsupportedOp(format!(
            "{projection} projection on non-indexable type {ty:?}"
        ))),
    }
}

fn subslice_result_type(
    ty: &Ty,
    from: usize,
    to: usize,
    from_end: bool,
) -> Result<Ty, BridgeError> {
    match ty {
        Ty::Array { elem, len } => {
            let result_len = if from_end {
                len.checked_sub(from as u64)
                    .and_then(|remaining| remaining.checked_sub(to as u64))
                    .ok_or_else(|| {
                        BridgeError::UnsupportedOp(format!(
                            "Subslice range {from}..-{to} exceeds array length {len}"
                        ))
                    })?
            } else {
                if to < from || to as u64 > *len {
                    return Err(BridgeError::UnsupportedOp(format!(
                        "Subslice range {from}..{to} exceeds array length {len}"
                    )));
                }
                (to - from) as u64
            };
            Ok(Ty::Array { elem: elem.clone(), len: result_len })
        }
        Ty::Slice { elem } => Ok(Ty::Slice { elem: elem.clone() }),
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => match inner.as_ref() {
            Ty::Slice { elem } => Ok(Ty::Slice { elem: elem.clone() }),
            _ => Err(BridgeError::UnsupportedOp(format!(
                "Subslice projection on non-slice pointer type {ty:?}"
            ))),
        },
        _ => Err(BridgeError::UnsupportedOp(format!(
            "Subslice projection on non-slice/array type {ty:?}"
        ))),
    }
}

fn is_fieldless_adt(ty: &Ty) -> bool {
    matches!(ty, Ty::Adt { fields, .. } if fields.is_empty())
}

fn raw_ptr_pointee_support_error(pointee_ty: &Ty) -> Option<String> {
    match pointee_ty {
        Ty::Dynamic { .. } => {
            Some("trait-object pointers carry a vtable metadata lane".to_string())
        }
        Ty::Unsupported { kind, detail } => {
            Some(format!("pointee type {kind} is unsupported: {detail}"))
        }
        _ => None,
    }
}

fn place_ty_contains_provenance_sensitive_type(ty: &Ty) -> bool {
    match ty {
        Ty::RawPtr { .. } | Ty::Dynamic { .. } | Ty::Unsupported { .. } => true,
        Ty::Ref { inner, .. } => place_ty_contains_provenance_sensitive_type(inner),
        Ty::Slice { elem } | Ty::Array { elem, .. } => {
            place_ty_contains_provenance_sensitive_type(elem)
        }
        Ty::Tuple(fields) => fields.iter().any(place_ty_contains_provenance_sensitive_type),
        Ty::Adt { fields, .. } => {
            fields.iter().any(|(_, field_ty)| place_ty_contains_provenance_sensitive_type(field_ty))
        }
        Ty::Closure { upvars, .. } | Ty::Coroutine { upvars, .. } => {
            upvars.iter().any(place_ty_contains_provenance_sensitive_type)
        }
        _ => false,
    }
}

enum RawPtrAggregateOperands<'a> {
    Thin { data: &'a Operand },
    Slice { data: &'a Operand, metadata: &'a Operand },
}

fn ensure_raw_ptr_aggregate_data_operand(
    ctx: &LoweringCtx<'_>,
    operand: &Operand,
    expected_pointee: &Ty,
    mutable: bool,
) -> Result<(), BridgeError> {
    let expected_ty = Ty::RawPtr { mutable, pointee: Box::new(expected_pointee.clone()) };
    match operand_trust_type_with_context(operand, Some(&expected_ty), ctx)? {
        Ty::RawPtr { mutable: data_mutable, pointee } => {
            if data_mutable != mutable {
                return Err(BridgeError::UnsupportedOp(format!(
                    "raw pointer aggregate data pointer mutability {data_mutable} does not match aggregate mutability {mutable}"
                )));
            }
            if pointee.as_ref() != expected_pointee {
                return Err(BridgeError::UnsupportedOp(format!(
                    "raw pointer aggregate data pointer pointee {pointee:?} does not match expected thin pointee {expected_pointee:?}"
                )));
            }
            if let Some(reason) = raw_ptr_pointee_support_error(&pointee) {
                return Err(BridgeError::UnsupportedOp(format!(
                    "raw pointer aggregate data operand must be a thin raw pointer; got {pointee:?}: {reason}"
                )));
            }
            Ok(())
        }
        other => Err(BridgeError::UnsupportedOp(format!(
            "raw pointer aggregate first operand must be a raw pointer; got {other:?}"
        ))),
    }
}

fn ensure_slice_metadata_operand(
    ctx: &LoweringCtx<'_>,
    operand: &Operand,
) -> Result<(), BridgeError> {
    let expected_ty = Ty::usize();
    match operand_trust_type_with_context(operand, Some(&expected_ty), ctx)? {
        ty if is_trust_usize_ty(&ty) => Ok(()),
        other => Err(BridgeError::UnsupportedOp(format!(
            "slice raw pointer aggregate metadata operand must be a precise usize length lane; got {other:?}"
        ))),
    }
}

fn raw_ptr_aggregate_operands<'a>(
    ctx: &LoweringCtx<'_>,
    dest_ty: &Ty,
    pointee_ty: &Ty,
    mutable: bool,
    operands: &'a [Operand],
) -> Result<RawPtrAggregateOperands<'a>, BridgeError> {
    match dest_ty {
        Ty::RawPtr { mutable: dest_mutable, pointee }
            if *dest_mutable == mutable && pointee.as_ref() == pointee_ty => {}
        Ty::RawPtr { .. } => {
            return Err(BridgeError::UnsupportedOp(format!(
                "raw pointer aggregate kind does not match destination type: kind pointee={pointee_ty:?} mutable={mutable}, dest={dest_ty:?}"
            )));
        }
        other => {
            return Err(BridgeError::UnsupportedOp(format!(
                "raw pointer aggregate destination must be raw pointer; got {other:?}"
            )));
        }
    }

    if operands.len() != 2 {
        return Err(BridgeError::UnsupportedOp(format!(
            "raw pointer aggregate must have data pointer and metadata operands; got {} operands",
            operands.len()
        )));
    }

    if let Some(reason) = raw_ptr_pointee_support_error(pointee_ty) {
        return Err(BridgeError::UnsupportedOp(format!(
            "raw pointer aggregate for pointee {pointee_ty:?} requires fat-pointer metadata semantics: {reason}"
        )));
    }

    if let Ty::Slice { elem } = pointee_ty {
        ensure_raw_ptr_aggregate_data_operand(ctx, &operands[0], elem, mutable)?;
        ensure_slice_metadata_operand(ctx, &operands[1])?;
        return Ok(RawPtrAggregateOperands::Slice { data: &operands[0], metadata: &operands[1] });
    }

    ensure_raw_ptr_aggregate_data_operand(ctx, &operands[0], pointee_ty, mutable)?;
    match operand_trust_type(&operands[1], ctx)? {
        Ty::Unit => Ok(RawPtrAggregateOperands::Thin { data: &operands[0] }),
        other => Err(BridgeError::UnsupportedOp(format!(
            "thin raw pointer aggregate metadata must be unit; got {other:?}"
        ))),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ArrayToSlicePointerCast {
    len: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PointerCastKind {
    Ref,
    RawPtr,
}

fn array_to_slice_pointer_cast(
    source_ty: &Ty,
    target_ty: &Ty,
) -> Result<Option<ArrayToSlicePointerCast>, BridgeError> {
    let (source_kind, source_mutable, source_pointee) = match source_ty {
        Ty::Ref { mutable, inner } => (PointerCastKind::Ref, *mutable, inner),
        Ty::RawPtr { mutable, pointee } => (PointerCastKind::RawPtr, *mutable, pointee),
        _ => return Ok(None),
    };
    let (target_kind, target_mutable, target_pointee) = match target_ty {
        Ty::Ref { mutable, inner } => (PointerCastKind::Ref, *mutable, inner),
        Ty::RawPtr { mutable, pointee } => (PointerCastKind::RawPtr, *mutable, pointee),
        _ => return Ok(None),
    };

    let Ty::Array { elem: source_elem, len } = source_pointee.as_ref() else {
        return Ok(None);
    };
    let Ty::Slice { elem: target_elem } = target_pointee.as_ref() else {
        return Ok(None);
    };

    if source_kind != target_kind {
        return Err(BridgeError::UnsupportedOp(format!(
            "array-to-slice pointer cast changes pointer kind: source={source_ty:?}, target={target_ty:?}"
        )));
    }
    if source_mutable != target_mutable {
        return Err(BridgeError::UnsupportedOp(format!(
            "array-to-slice pointer cast changes mutability: source={source_ty:?}, target={target_ty:?}"
        )));
    }
    if !source_elem.eq_ignoring_disc_index_safe(target_elem) {
        return Err(BridgeError::UnsupportedOp(format!(
            "array-to-slice pointer cast changes element type: source={source_ty:?}, target={target_ty:?}"
        )));
    }

    Ok(Some(ArrayToSlicePointerCast { len: *len }))
}

fn collect_closure_env_types(
    funcs: &[&VerifiableFunction],
) -> Result<ClosureEnvTypes, BridgeError> {
    let mut registry = ClosureEnvTypes::default();
    let mut changed = true;

    while changed {
        changed = false;
        for func in funcs {
            let mut refinements =
                closure_refinements_from_registry(&func.body.locals, &func.def_path, &registry);

            for block in &func.body.blocks {
                for stmt in &block.stmts {
                    let Statement::Assign {
                        place,
                        rvalue: Rvalue::Aggregate(AggregateKind::Closure { name, .. }, operands),
                        ..
                    } = stmt
                    else {
                        continue;
                    };

                    let Some(env_ty) = try_closure_env_type_from_operands(
                        name,
                        operands,
                        &func.body.locals,
                        &refinements,
                        &func.def_path,
                        &registry,
                    )?
                    else {
                        continue;
                    };

                    if insert_closure_env_type(&mut registry, name, env_ty.clone())? {
                        changed = true;
                    }
                    if place_is_direct_local(place) {
                        refinements.insert(place.local, env_ty);
                    }
                }
            }
        }
    }

    Ok(registry)
}

fn closure_refinements_from_registry(
    locals: &[LocalDecl],
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> FxHashMap<usize, Ty> {
    let mut refinements = FxHashMap::default();
    for local in locals {
        if let Ty::Unsupported { kind, detail } = &local.ty
            && let Some(refined) = closure_env_type_for_unsupported_marker(
                kind,
                detail,
                function_def_path,
                closure_env_types,
            )
        {
            refinements.insert(local.index, refined);
        }
    }
    refinements
}

fn insert_closure_env_type(
    registry: &mut ClosureEnvTypes,
    name: &str,
    env_ty: Ty,
) -> Result<bool, BridgeError> {
    match registry.get(name) {
        Some(existing) if existing == &env_ty => Ok(false),
        Some(existing) => Err(BridgeError::UnsupportedType(format!(
            "closure aggregate `{name}` has inconsistent captured-environment types across module: {existing:?} vs {env_ty:?}"
        ))),
        None => {
            registry.insert(name.to_string(), env_ty);
            Ok(true)
        }
    }
}

fn try_closure_env_type_from_operands(
    name: &str,
    operands: &[Operand],
    locals: &[LocalDecl],
    refinements: &FxHashMap<usize, Ty>,
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> Result<Option<Ty>, BridgeError> {
    let mut upvars = Vec::with_capacity(operands.len());
    for operand in operands {
        let Some(ty) = try_operand_trust_type_from_decls(
            operand,
            locals,
            refinements,
            function_def_path,
            closure_env_types,
        )?
        else {
            return Ok(None);
        };
        upvars.push(ty);
    }
    Ok(Some(Ty::Closure { name: name.to_string(), upvars, call: None }))
}

fn try_operand_trust_type_from_decls(
    operand: &Operand,
    locals: &[LocalDecl],
    refinements: &FxHashMap<usize, Ty>,
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> Result<Option<Ty>, BridgeError> {
    match operand {
        Operand::Copy(place) | Operand::Move(place) => Ok(try_place_type_from_decls(
            place,
            locals,
            refinements,
            function_def_path,
            closure_env_types,
        )),
        Operand::Constant(ConstValue::Bool(_)) => Ok(Some(Ty::Bool)),
        Operand::Constant(ConstValue::Int(_)) => Ok(Some(Ty::i64())),
        Operand::Constant(ConstValue::Uint(_, width)) => {
            Ok(Some(Ty::Int { width: *width, signed: false }))
        }
        Operand::Constant(ConstValue::Float(_)) => Ok(Some(Ty::f64_ty())),
        Operand::Constant(ConstValue::FloatBits { width, .. }) => {
            Ok(Some(Ty::Float { width: *width }))
        }
        Operand::Constant(ConstValue::Unit | ConstValue::CallableItem { .. }) => Ok(Some(Ty::Unit)),
        Operand::Constant(ConstValue::Str { .. }) => Ok(Some(Ty::Ref {
            mutable: false,
            inner: Box::new(Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) }),
        })),
        // A typed opaque integer constant carries its declared integer type so
        // arithmetic/index uses stay well-typed (value is still a fresh symbol).
        Operand::Constant(ConstValue::OpaqueScalar { width, signed }) => {
            Ok(Some(Ty::Int { width: *width, signed: *signed }))
        }
        // Trust: piece #7a — a const-generic PARAM carries its declared int type.
        // A BOOL const-generic (in-band `width==1 && !signed`) types as Bool.
        Operand::Constant(ConstValue::ConstParam { width: 1, signed: false, .. }) => {
            Ok(Some(Ty::Bool))
        }
        Operand::Constant(ConstValue::ConstParam { width, signed, .. }) => {
            Ok(Some(Ty::Int { width: *width, signed: *signed }))
        }
        Operand::Symbolic(formula) => Ok(contextless_symbolic_trust_type(formula).ok()),
        Operand::Unsupported { .. } => Ok(None),
        _ => Ok(None),
    }
}

fn try_place_type_from_decls(
    place: &Place,
    locals: &[LocalDecl],
    refinements: &FxHashMap<usize, Ty>,
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> Option<Ty> {
    let current_ty = refinements.get(&place.local).cloned().or_else(|| {
        let local = locals.iter().find(|local| local.index == place.local)?;
        refine_declared_ty_from_closure_registry(&local.ty, function_def_path, closure_env_types)
            .or_else(|| Some(local.ty.clone()))
    })?;

    if matches!(current_ty, Ty::Unsupported { .. }) {
        return None;
    }

    let current_ty = projected_place_type(current_ty, &place.projections).ok()?;

    (!matches!(current_ty, Ty::Unsupported { .. })).then_some(current_ty)
}

fn refine_declared_ty_from_closure_registry(
    ty: &Ty,
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> Option<Ty> {
    match ty {
        Ty::Unsupported { kind, detail } => closure_env_type_for_unsupported_marker(
            kind,
            detail,
            function_def_path,
            closure_env_types,
        ),
        _ => None,
    }
}

fn closure_env_type_for_unsupported_marker(
    kind: &str,
    detail: &str,
    function_def_path: &str,
    closure_env_types: &ClosureEnvTypes,
) -> Option<Ty> {
    if !is_unsupported_rustc_closure_kind(kind) {
        return None;
    }

    if let Some(name) = closure_name_from_unsupported_detail(detail)
        && let Some(env_ty) = closure_env_types.get(name)
    {
        return Some(env_ty.clone());
    }

    if let Some(env_ty) = closure_env_types.get(function_def_path) {
        return Some(env_ty.clone());
    }

    let mut matches = closure_env_types
        .iter()
        .filter(|(name, _)| detail.contains(name.as_str()))
        .map(|(_, ty)| ty.clone());
    let first = matches.next()?;
    if matches.next().is_none() { Some(first) } else { None }
}

fn closure_name_from_unsupported_detail(detail: &str) -> Option<&str> {
    detail
        .strip_prefix("closure ")
        .and_then(|rest| rest.split_once(" needs captured-environment modeling"))
        .map(|(name, _)| name)
}

fn is_rust_callable_trait_call(callee: &str) -> bool {
    is_canonical_trait_method(
        callee,
        &["core::ops::FnOnce", "std::ops::FnOnce", "core::ops::function::FnOnce"],
        "::call_once",
    ) || is_canonical_trait_method(
        callee,
        &["core::ops::FnMut", "std::ops::FnMut", "core::ops::function::FnMut"],
        "::call_mut",
    ) || is_canonical_trait_method(
        callee,
        &["core::ops::Fn", "std::ops::Fn", "core::ops::function::Fn"],
        "::call",
    )
}

/// The signature of a fn-pointer RECEIVER of a `Fn`/`FnMut`/`FnOnce::call*` trait
/// shim — i.e. an INDIRECT call through a function pointer (`f(x)` where
/// `f: fn(..)->_`). Returns the `FnSig` recovered from the receiver's `Ty::FnPtr`
/// (thin or `&`-behind), or `None` for any other receiver so the caller FALLS
/// CLOSED:
///
/// * a `Ty::Closure` receiver -> `None`: closures resolve to a bundled body via
///   `resolve_call_target` / `try_resolve_hof_closure` (a REAL direct `Inst::Call`
///   into the closure body), which is strictly stronger than a havoc dispatch.
/// * a `Ty::Dynamic` (`dyn Fn`) receiver -> `None`: a trait-object virtual call
///   needs vtable modeling (the fat pointer's vtable slot Load), a separate larger
///   step; refusing it keeps the whole function fail-closed rather than fabricating
///   a callee we cannot type.
///
/// SOUNDNESS: only a concrete `Ty::FnPtr` — whose call is a genuine BLR through an
/// opaque code address the OPEN-havoc `CallIndirect` lowering models conservatively
/// — is admitted. Everything else declines, matching the fail-closed discipline of
/// the surrounding call arms.
fn fnptr_indirect_call_sig(receiver_ty: &Ty) -> Option<&trust_types::FnSig> {
    match receiver_ty {
        Ty::FnPtr { sig } => Some(sig),
        Ty::Ref { inner, .. } => match inner.as_ref() {
            Ty::FnPtr { sig } => Some(sig),
            _ => None,
        },
        _ => None,
    }
}

// Trust: a user-level `assert!`/`panic!` does not lower to a MIR `Assert`
// terminator (those are compiler-inserted bounds/overflow checks); it lowers to
// an explicit `if !cond { core::panicking::panic(..) }`, i.e. a diverging `Call`
// to a panic intrinsic. Those intrinsics are never part of the user crate's
// TrustIr module, so `resolve_call_target` would reject them. Recognize the
// panic family so the call site can be lowered as a panic-freedom obligation
// (prove the site is unreachable) instead of an unsupported-call error.
/// True iff `callee` is a SCALAR-index slice `get_unchecked` / `get_unchecked_mut`
/// call — the ONE unsafe shape whose COMPLETE undefined-behavior set is exactly
/// `index < len` (mirrors trust-vcgen's `is_unchecked_index_call` and
/// `unsafe_verify::detection::block_is_bounds_complete_unchecked_index`). A RANGE
/// index (`get_unchecked(a..b)`) is a struct, NOT `Ty::Int`, and `str::get_unchecked`
/// (extra char-boundary UB) has a non-slice receiver — both return `false` and fall
/// through to `resolve_call_target`, which FAILS CLOSED. So this recognizes ONLY
/// bounds-complete unchecked element indexing, whose safety is exactly `i < len`.
fn slice_get_unchecked_scalar_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let normalized = strip_generics(callee);
    if !has_trusted_std_root(&normalized)
        || !normalized.contains("::slice::")
        || !(normalized.ends_with("::get_unchecked") || normalized.ends_with("::get_unchecked_mut"))
    {
        return Ok(false);
    }
    let (Some(recv), Some(idx)) = (args.first(), args.get(1)) else {
        return Ok(false);
    };
    // Receiver must be a slice (`&[T]`): `slice_element_type` returns `None` for
    // `str`, arrays, and everything else → fail closed.
    if slice_element_type(&operand_trust_type(recv, ctx)?).is_none() {
        return Ok(false);
    }
    // Index must be exactly `usize`; a range index is a struct. Accept both the
    // legacy U64 carrier and the faithful PtrSizedInt spelling, but not an
    // arbitrary integer merely because it happens to be scalar.
    let expected_ty = Ty::usize();
    Ok(is_trust_usize_ty(&operand_trust_type_with_context(idx, Some(&expected_ty), ctx)?))
}

fn is_panic_call(callee: &str) -> bool {
    callee.contains("::panicking::")
        || callee.contains("begin_panic")
        || callee.ends_with("::panic")
        || callee.ends_with("::panic_fmt")
        || callee.ends_with("::panic_nounwind")
        || callee.contains("panic_bounds_check")
        || callee.contains("panic_misaligned_pointer_dereference")
        || callee.contains("panic_cannot_unwind")
}

// Trust Gap 3: core integer wrapping-arithmetic methods (e.g. `u32::wrapping_add`)
// arrive as a call to `core::num::<impl uN/iN>::wrapping_{add,..}`. Their bodies
// live in `core`, never in the user crate's TrustIr module, so
// `resolve_call_target` would reject them. Recognize the family so the call site
// lowers directly to a modular `BinOp` (tagged `Wrapping`) instead of an
// unsupported-call error. Returns the equivalent trust-types `BinOp`.
fn core_int_arith_intrinsic(
    callee: &str,
    args: &[Operand],
    dest: &Place,
    ctx: &LoweringCtx<'_>,
) -> Result<Option<BinOp>, BridgeError> {
    let normalized = strip_generics(callee);
    let method = normalized.rsplit("::").next().unwrap_or_default();
    if !is_exact_primitive_num_method(&normalized, method) || args.len() != 2 {
        return Ok(None);
    }
    let lhs_ty = operand_trust_type(&args[0], ctx)?;
    let rhs_ty = operand_trust_type(&args[1], ctx)?;
    let dest_ty = place_type(dest, ctx)?;
    if !matches!(lhs_ty, Ty::Int { .. }) || rhs_ty != lhs_ty || dest_ty != lhs_ty {
        return Ok(None);
    }
    // wrapping_{add,sub,mul} map exactly to a modular BinOp (tagged `Wrapping`).
    // checked_/overflowing_/saturating_ need Inst::Overflow (consumer support
    // pending) and are intentionally NOT matched here.
    let op = if method == "wrapping_add" {
        Some(BinOp::Add)
    } else if method == "wrapping_sub" {
        Some(BinOp::Sub)
    } else if method == "wrapping_mul" {
        Some(BinOp::Mul)
    } else {
        None
    };
    Ok(op)
}

fn is_exact_primitive_num_method(normalized: &str, method: &str) -> bool {
    normalized == format!("core::num::{method}") || normalized == format!("std::num::{method}")
}

// Trust Gap 3 (slice/array iterator): a `for &x in s {..}` loop — the dominant
// loop form in Rust — desugars to `IntoIterator::into_iter(recv)` followed by
// repeated `Iterator::next(&mut iter)`. For the CONCRETE slice/array iterator
// family these std methods are TOTAL: `into_iter` is a thin wrapper and
// `slice::Iter::next` is a bounds-guarded pointer bump — neither can panic and
// neither runs user code. Modeling each result as a fresh-symbolic value
// (`Undef`, like `total_no_panic_call_summary`) is therefore a SOUND
// over-approximation: the yielded element is left unconstrained, so any loop-body
// obligation that depends on it stays `unknown` (never falsely proved), while the
// (vacuous) panic obligation of these total calls is correctly omitted. This lets
// the dominant loop form lower into the native bundle without the stdlib iterator
// MIR — the standing `-full` usability blocker for everyday loops.
//
// STRICTLY gated on the receiver TYPE, never the generic callee alone, so a USER
// Trust (#48): recognize `Ord::min`/`max`/`clamp` only when the compiler-held
// MIR operands prove that the selected instance is a primitive integer Ord
// impl. A flat `core::cmp::Ord` path is not proof of the selected impl: a user
// `Ord` implementation may panic or violate the modeled ordering law.
fn bridge_ord_method(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<Option<&'static str>, BridgeError> {
    let Some(method) = native_ord_method(callee) else { return Ok(None) };
    // `Ord::clamp` panics when `min > max`.  The bridge has no authenticated
    // value-order witness for that precondition, so even a primitive receiver
    // must stay in the honest may-panic lane.  `min`/`max` are unconditional.
    if method == "clamp" {
        return Ok(None);
    }
    if args.len() != 2 {
        return Ok(None);
    }
    let mut arg_tys = args.iter().map(|arg| operand_trust_type(arg, ctx));
    let Some(first) = arg_tys.next().transpose()? else { return Ok(None) };
    if !matches!(first, Ty::Int { .. } | Ty::PtrSizedInt { .. })
        || !arg_tys.all(|ty| ty.is_ok_and(|ty| ty == first))
    {
        return Ok(None);
    }
    Ok(Some(method))
}

// RETIRED LANE (TRY-TOTAL MARKER) — record only, no implementation. A callee
// suffix is printable source, not compiler-authenticated dispatch identity, so it
// cannot carry proof authority; the design below is kept so a future attempt does
// not rediscover the same shape without the same objection.
//
// The `?` operator desugars to a `Try::branch(recv)` call followed (on the early-
// return arm) by a `FromResidual::from_residual(residual)` call. For the std
// `Result`/`Option`/`ControlFlow` `Try` impls these are TOTAL: `branch` is a pure
// discriminant split, and `from_residual` — WHEN no error `From` conversion runs — is
// the identity `Err`/`None` re-wrap. Their bodies live in `core`/`std` (never in the
// user crate's TrustIr module), so `resolve_call_target` rejects them, which fail-
// closes EVERY `?`-using function. The EXTRACTOR (trust-mir-extract `func_operand_name`
// / `trust_try_total_marker`) decides totality where the full monomorphized signature
// is available — the residual/target error types, which here are lost (a unit-error
// residual extracts as a type-erased opaque constant) — and tags a confirmed-total call
// with a `::<__trust_try_total>` suffix. The dispatch then models the result as a fresh
// `Undef` (sound over-approximation: the Continue payload is left UNCONSTRAINED, so
// `let x = r?; assert!(x==0)` stays refutable — never falsely proved; the vacuous panic
// obligation of a total call is correctly omitted). A CONVERTING `?` is NOT tagged and
// stays fail-closed.

// RETIRED / QUARANTINED (SPAWN-NAMESAFE V2). This string-marker discharge granted
// panic-freedom to a `Builder::spawn` on the strength of a source-VISIBLE
// `::<__trust_spawn_namesafe>` def-path suffix. A printable callee suffix is NOT
// compiler-authenticated dispatch identity, so it cannot be a proof-authority trust
// root — the reviewed "drop authority" tightening (`9557f585d62`) retired both this
// recognizer and the extractor stamp that fed it, and the extractor test
// `codegen_extraction_separates_verifier_abstractions_and_fails_closed` pins that the
// marker is NEVER emitted by production extraction. No implementation remains;
// what follows is the record. A genuinely-nul-free spawn must be discharged via a
// per-call-site compiler certificate (the PAIRED-CONDVAR discipline), never a
// forgeable string. Re-enabling it would let a forged suffix ride proof authority —
// exactly what `test_forged_spawn_namesafe_suffix_has_no_bridge_authority` forbids.
//
// Original V2 rationale (archived): Recognize a `std::thread::Builder::spawn`
// / `::spawn_unchecked` call the EXTRACTOR tagged with the trailing
// `::<__trust_spawn_namesafe>` marker — one whose thread name it PROVED nul-free (a
// unique-def'd, never-aliased, mention-accounted `String` holding exactly the bytes
// of a nul-free compile-time `&str` literal) or absent (`name: None`).
// `Builder::spawn`'s ENTIRE body is `unsafe { self.spawn_unchecked(f) }`
// (library/std/src/thread/builder.rs:185-192, no prelude), so both spellings share
// ONE panic surface; its only name-DEPENDENT panic is `CString::new(name).expect(
// "thread name may not contain interior null bytes")` (`ThreadNameString:
// From<String>`, thread.rs, reached via `Thread::new`'s `name.map(…)` only when a
// name was set) — exactly what the namesafe proof discharges, so the absent-callee
// arm may model the call panic-free (like `total_no_panic_call_summary`, but WITHOUT
// its closure gate — which would reject spawn's closure arg). The residual
// name-INDEPENDENT surface (ThreadId bitspace exhaustion after 2^64 spawns, the
// unstable `add_spawn_hook` user hooks, `assert_eq!(pthread_attr_*, 0)` OS-contract
// asserts) is the SAME trusted envelope the reviewed V1 accepted for `spawn` and is
// inherited unchanged by `spawn_unchecked`. The match demands the EXACT
// extractor-appended suffix after a `std::thread::Builder::spawn[_unchecked]` base
// (bare or with its own `::<F, T>` turbofish): a genuine def path never renders two
// consecutive turbofish groups (`>::<`), spawn's arity-2 instantiation always
// contains a comma so `::<__trust_spawn_namesafe>` can never be a genuine turbofish,
// and a crate impersonating `std` renders with the `__trust_crate@…::`
// disambiguation prefix and fails the base match. An UNMARKED / possibly-nul /
// mutated-name spawn keeps its fail-closed absent-callee panic obligation. The
// spawned CLOSURE runs on another thread (its panics are caught there and verified
// at the closure's own def_id), so discharging the caller-side spawn masks nothing.

// SOUNDNESS-CRITICAL (PAIRED-CONDVAR). Recognize a `std::sync::Condvar::wait`
// call only when the compiler supplied an exact, current call-site sidecar —
// one whose receiver is a shared borrow of a condvar field carrying the
// whole-crate `#[trust::paired]` PAIRING CERTIFICATE
// (`trust_vcgen::certify_paired_condvars` plus the rustc MIR receiver collector):
// every crate wait site on that field is guard-provenance VALIDATED by an
// instance-pinned gen/kill dataflow (the guard is provably the SAME dynamic
// instance's fixed sibling mutex's guard), the field is private, never escapes,
// and is freshly `Condvar::new()`-constructed in every constructor. `wait`'s
// only name-DEPENDENT panic is the pthread lane's two-mutex `verify()` panic
// (library/std/src/sys/sync/condvar/pthread.rs:39 — it compare_exchanges the
// pal-mutex ADDRESS; poison maps to `Err` at poison/condvar.rs:125-132; the pal
// return is only debug_assert'ed; futex/windows lanes have no verify), which
// pairing makes unreachable — so the absent-callee arm may model the call
// panic-free (blocking is out of model exactly as for the allowlisted
// `Mutex::lock`). This is a PER-CALL-SITE discharge, NEVER a flat allowlist or
// source-forgeable string marker: an unpaired `Condvar::wait`'s verify() panic
// is REACHABLE on macOS. The key must match the full function def-path, block,
// and exact callee bytes. Duplicate keys reject the context at intake;
// missing, stale, reordered, wrong-function, and wrong-callee keys do not match.
// A crate impersonating `std` is excluded by the collector's DefId identity.
// `wait_timeout`/`wait_while` are never collected and keep their fail-closed
// absent-callee panic obligation, as does every unlisted `wait`.
fn is_std_condvar_wait_callee(callee: &str) -> bool {
    const WAIT: &str = "std::sync::Condvar::wait";
    callee == WAIT || callee.strip_prefix(WAIT).is_some_and(|rest| rest.starts_with("::<"))
}

fn compiler_certifies_paired_condvar_wait(
    ctx: &LoweringCtx<'_>,
    block: BlockId,
    callee: &str,
) -> bool {
    is_std_condvar_wait_callee(callee)
        && ctx
            .certified_paired_condvar_wait_sites
            .iter()
            .any(|site| {
                site.authorizes(
                    &ctx.function_def_path,
                    &ctx.function_body_digest,
                    block,
                    callee,
                )
            })
}

/// SOUNDNESS (canonical-path sweep): true iff `callee` names trait method
/// `TRAIT::METHOD` AND the complete trait path is one of the closed, crate-rooted
/// paths below. Both def-path renderings a trait call reaches the bridge in are
/// accepted: the plain `…::TRAIT::METHOD` an unresolved/generic dispatch carries,
/// and the fully-qualified `<Self as …TRAIT>::METHOD` a resolved impl call carries.
/// A final-segment or immediate-module match is insufficient: a user crate can
/// define `mycrate::ops::Add` or `mycrate::fmt::Display` and implement it on a
/// trusted receiver with a panicking body. Ambiguous-crate spellings carrying
/// `__trust_crate@...` fail closed because this bridge has no authenticated
/// stable-crate-id registry with which to prove their origin.
fn callee_is_trait_method_in(
    callee: &str,
    ns_lasts: &[&str],
    trait_last: &str,
    method: &str,
) -> bool {
    let Some(path) = canonical_trait_path(callee, method) else {
        return false;
    };
    let Some(namespace) = path
        .strip_suffix(trait_last)
        .and_then(|prefix| prefix.strip_suffix("::"))
        .and_then(|prefix| prefix.rsplit("::").next())
    else {
        return false;
    };
    if !ns_lasts.contains(&namespace) {
        return false;
    }

    match trait_last {
        "Iterator" => matches!(
            path.as_str(),
            "core::iter::Iterator"
                | "std::iter::Iterator"
                | "core::iter::traits::iterator::Iterator"
                | "std::iter::traits::iterator::Iterator"
        ),
        "IntoIterator" => matches!(
            path.as_str(),
            "core::iter::IntoIterator"
                | "std::iter::IntoIterator"
                | "core::iter::traits::collect::IntoIterator"
                | "std::iter::traits::collect::IntoIterator"
        ),
        "DoubleEndedIterator" => matches!(
            path.as_str(),
            "core::iter::DoubleEndedIterator"
                | "std::iter::DoubleEndedIterator"
                | "core::iter::traits::double_ended::DoubleEndedIterator"
                | "std::iter::traits::double_ended::DoubleEndedIterator"
        ),
        "Deref" => matches!(
            path.as_str(),
            "core::ops::Deref"
                | "std::ops::Deref"
                | "core::ops::deref::Deref"
                | "std::ops::deref::Deref"
        ),
        "DerefMut" => matches!(
            path.as_str(),
            "core::ops::DerefMut"
                | "std::ops::DerefMut"
                | "core::ops::deref::DerefMut"
                | "std::ops::deref::DerefMut"
        ),
        "Add" | "Sub" | "Mul" | "Neg" | "AddAssign" | "SubAssign" | "MulAssign" => {
            path == format!("core::ops::{trait_last}")
                || path == format!("std::ops::{trait_last}")
                || path == format!("core::ops::arith::{trait_last}")
                || path == format!("std::ops::arith::{trait_last}")
        }
        "Try" | "FromResidual" => {
            path == format!("core::ops::{trait_last}")
                || path == format!("std::ops::{trait_last}")
                || path == format!("core::ops::try_trait::{trait_last}")
                || path == format!("std::ops::try_trait::{trait_last}")
        }
        "From" | "Into" | "TryFrom" | "TryInto" => {
            path == format!("core::convert::{trait_last}")
                || path == format!("std::convert::{trait_last}")
        }
        "PartialEq" | "Ord" | "PartialOrd" => {
            path == format!("core::cmp::{trait_last}")
                || path == format!("std::cmp::{trait_last}")
        }
        "Clone" => path == "core::clone::Clone" || path == "std::clone::Clone",
        "Default" => path == "core::default::Default" || path == "std::default::Default",
        "Display" => path == "core::fmt::Display" || path == "std::fmt::Display",
        "ToString" => {
            path == "alloc::string::ToString" || path == "std::string::ToString"
        }
        "ToOwned" => path == "alloc::borrow::ToOwned" || path == "std::borrow::ToOwned",
        "Error" => path == "core::error::Error" || path == "std::error::Error",
        "Zero" | "One" => {
            path == format!("num_traits::{trait_last}")
                || path == format!("num_traits::identities::{trait_last}")
        }
        "Signed" => path == "num_traits::Signed" || path == "num_traits::sign::Signed",
        "ToPrimitive" => {
            path == "num_traits::ToPrimitive" || path == "num_traits::cast::ToPrimitive"
        }
        _ => false,
    }
}

// Namespace tables for `callee_is_trait_method_in`: per trait, the last segment of
// its public RE-EXPORT module plus (where different) its TRUE defining module —
// both def-path renderings reach the bridge (`std::iter::Iterator::next` vs
// `core::iter::traits::iterator::Iterator::next`), so both anchors are required
// for production spellings; anything else (a user `mycrate::widget::Add`) fails.
const NS_ITERATOR: &[&str] = &["iter", "iterator"];
const NS_INTO_ITERATOR: &[&str] = &["iter", "collect"];
const NS_DOUBLE_ENDED_ITERATOR: &[&str] = &["iter", "double_ended"];
const NS_OPS_ARITH: &[&str] = &["ops", "arith"];
// `core::cmp::Ord` — the namespace's last segment in both renderings.
const NS_ORD: &[&str] = &["cmp"];
const NS_OPS_DEREF: &[&str] = &["ops", "deref"];
const NS_OPS_TRY: &[&str] = &["ops", "try_trait"];
const NS_CONVERT: &[&str] = &["convert"];
const NS_CMP: &[&str] = &["cmp"];
const NS_CLONE: &[&str] = &["clone"];
const NS_DEFAULT: &[&str] = &["default"];
const NS_FMT: &[&str] = &["fmt"];
const NS_STRING: &[&str] = &["string"];
const NS_BORROW: &[&str] = &["borrow"];
const NS_NUM_IDENTITIES: &[&str] = &["num_traits", "identities"];
const NS_NUM_SIGN: &[&str] = &["num_traits", "sign"];
const NS_NUM_CAST: &[&str] = &["num_traits", "cast"];

// `IntoIterator`/`Iterator` impl (whose `into_iter`/`next` may panic or run
// arbitrary code), or an adapter like `Map`/`Filter` (whose `next` drives a user
// closure), still falls through to `resolve_call_target` and is refused. Only the
// concrete slice/array iterators — which the compiler guarantees total — match.
fn total_slice_iterator_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let Some(receiver) = args.first() else { return Ok(false) };
    if callee_is_trait_method_in(callee, NS_INTO_ITERATOR, "IntoIterator", "into_iter") {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        // A slice/array receiver (the `for &x in s` form), OR an already-built
        // slice/array iterator (the `for x in s.iter_mut()` / `.iter()` form, where
        // `into_iter` on the iterator is the identity) — both are total. Bucket I —
        // ALSO a std CONTAINER (`&BTreeMap`/`&HashMap`/`Vec`/`&Vec`/…): iterating an
        // ALREADY-BUILT structure walks stored links and yields references / moves
        // owned elements, running NO user `Ord`/`Hash`/`Clone` (those ran at insert
        // time), so `into_iter` on it is total for ANY key/value type.
        return Ok(ty_is_slice_or_array_iterable(&recv_ty)
            || ty_is_slice_iterator_receiver(&recv_ty)
            || ty_is_integer_range_iter(&recv_ty)
            || ty_is_std_container_iterable(&recv_ty));
    }
    // `Iterator::next` AND `DoubleEndedIterator::next_back` — advancing a concrete
    // slice/array/map iterator from EITHER end is a bounds-guarded pointer bump that
    // runs NO user code and cannot panic (an empty iterator yields `None`, never a
    // panic). Both hops are total for the same receiver gate.
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next")
        || callee_is_trait_method_in(callee, NS_DOUBLE_ENDED_ITERATOR, "DoubleEndedIterator", "next_back")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next_back")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_slice_iterator_receiver(&recv_ty)
            || ty_is_integer_range_iter(&recv_ty));
    }
    // TOTAL iterator ADAPTERS that wrap a slice-backed iterator and run NO user
    // code on the elements — they only reorder/wrap/count references, so for a
    // total inner they are themselves total. `copied` is total (T: Copy, a bitwise
    // copy); `cloned`/`map`/`filter`/… are EXCLUDED — they run a user `Clone`/
    // closure that may panic. Gated on the receiver being slice-backed.
    const TOTAL_ADAPTER_CTORS: &[&str] = &[
        "copied", "rev", "take", "skip", "enumerate", "peekable", "by_ref",
    ];
    if TOTAL_ADAPTER_CTORS.iter().any(|m| callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", m)) {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_slice_iterator_receiver(&recv_ty));
    }
    // `take_while(pred)` / `skip_while(pred)` — CLOSURE-adapter CONSTRUCTORS. Unlike
    // the total adapters above, their `next` LATER drives the user predicate, so the
    // RESULT (`TakeWhile`/`SkipWhile`) is NOT a `ty_is_slice_iterator_receiver` and a
    // subsequent `next` on it correctly stays FAIL-CLOSED (its own obligation). But
    // the CONSTRUCTOR itself only builds the adapter struct (stores the closure) — it
    // runs NO user code and cannot panic — so discharging THIS call is sound; the
    // stored closure is a separately-bundled body with its own panic obligation
    // (exactly as for the lazy `Iterator::map` constructor). Gated on the receiver
    // being a concrete slice/array/map iterator, so a user iterator declines.
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "take_while")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "skip_while")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_slice_iterator_receiver(&recv_ty));
    }
    // Bucket A — the CLOSURE/CLONE-adapter CONSTRUCTORS `map(f)` / `filter(p)` /
    // `cloned()`. Like `take_while`/`skip_while` above, the CONSTRUCTOR only builds the
    // adapter struct (`Map{iter,f}` / `Filter{iter,p}` / `Cloned{it}`) — it stores the
    // closure/inner and returns, running NO user code and never panicking. The stored
    // closure's `Clone` runs LATER inside the adapter's `next` (a SEPARATE consume call
    // whose own bundled body carries the obligation), and the resulting
    // `Map`/`Filter`/`Cloned` is NOT a `ty_is_slice_iterator_receiver`, so that later
    // `next` correctly stays FAIL-CLOSED. Gated on the receiver being a concrete
    // slice/array/map iterator, so a user iterator declines. (`copied` rides
    // `TOTAL_ADAPTER_CTORS` above — `Copied`'s own `next` IS total.)
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "map")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "filter")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "cloned")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_slice_iterator_receiver(&recv_ty));
    }
    // `zip` is a BINARY adapter: `Zip<A, B>::next` pulls from BOTH inner iterators,
    // so it is total only when BOTH are slice-backed (total). Requiring BOTH (not
    // either) is the soundness gate — a non-slice inner could be a user iterator
    // whose `next` panics. The other operand may be an iterator, a slice/array, or a
    // std CONTAINER (`&Vec`/`Vec`/`&BTreeMap` — bucket I: `IntoIterator` yielding
    // references, no user code). Runs no user code on elements (just pairs references).
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "zip") {
        let Some(other) = args.get(1) else { return Ok(false) };
        let recv_ty = operand_trust_type(receiver, ctx)?;
        let other_ty = operand_trust_type(other, ctx)?;
        let total = |t: &Ty| {
            ty_is_slice_iterator_receiver(t)
                || ty_is_slice_or_array_iterable(t)
                || ty_is_std_container_iterable(t)
        };
        return Ok(total(&recv_ty) && total(&other_ty));
    }
    // `<[T]>::windows(size)` / `<[T]>::chunks(size)` CONSTRUCT a slice-backed
    // iterator (`Windows`/`Chunks`) yielding `&[T]` sub-slices. Their `next` runs
    // NO user code and never panics — the ONLY panic in the whole API is the
    // constructor's `assert!(size != 0)`. So the constructor is total iff the size
    // is provably non-zero. We recognize it as total ONLY when the size argument is
    // a LITERAL CONSTANT `>= 1` (the dominant idiom: a fixed window/chunk width).
    // A symbolic or zero size is NOT recognized → falls through to fail-closed, so a
    // real `windows(0)`/`chunks(0)` panic is never falsely certified (the
    // discriminating mutant). The receiver must be a real slice/array; the resulting
    // `Windows`/`Chunks` value flows into the loop's `into_iter`/`next`, which
    // `ty_is_slice_iterator_receiver` accepts (those are unconditionally total).
    // `callee_is_std_slice_inherent` accepts the generic `<impl [T]>` spelling AND
    // the monomorphized `core::slice::<impl [u32]>::chunks` spelling (anchored to
    // the core/std slice module) — the receiver + literal-size gates are unchanged.
    if callee_is_std_slice_inherent(callee, "windows")
        || callee_is_std_slice_inherent(callee, "chunks")
        || callee_is_std_slice_inherent(callee, "chunks_mut")
        || callee_is_std_slice_inherent(callee, "chunks_exact")
        || callee_is_std_slice_inherent(callee, "chunks_exact_mut")
        || callee_is_std_slice_inherent(callee, "rchunks")
        || callee_is_std_slice_inherent(callee, "rchunks_mut")
        || callee_is_std_slice_inherent(callee, "rchunks_exact")
        || callee_is_std_slice_inherent(callee, "rchunks_exact_mut")
    {
        // The `_mut`/`r`-prefixed twins have the SAME single panic — the constructor's
        // `assert!(size != 0)` — and their `next` yields `&mut [T]`/reversed sub-slices with
        // no user code, so they are total under the identical nonzero-literal-size gate.
        let recv_ty = operand_trust_type(receiver, ctx)?;
        if !ty_is_slice_or_array_iterable(&recv_ty) {
            return Ok(false);
        }
        return Ok(args.get(1).and_then(operand_const_nonneg).is_some_and(|n| n >= 1));
    }
    // `as_chunks::<N>` / `as_rchunks::<N>` panic for `N == 0`.  The generic
    // argument is not represented as a trustworthy value operand here, so this
    // bridge cannot prove the non-zero precondition and deliberately declines.
    // `ChunksExact::remainder()` returns the trailing `&[T]` (len < chunk size) left after the
    // exact chunks — TOTAL (no panic; runs no user code). Gated on the receiver being a slice
    // iterator (a `ChunksExact`), so a user `remainder` method on another type declines.
    if callee_is_std_slice_inherent(callee, "remainder") {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_slice_iterator_receiver(&recv_ty));
    }
    // `<P as Deref>::deref` / `DerefMut::deref_mut` for a std smart-pointer / container
    // (PathBuf->Path, Vec->[T], String->str, Box/Rc/Arc/Cow->T) is a TOTAL pointer cast — no
    // panic, runs no user code. Gated on the receiver being a std deref-able type; a user
    // `Deref` impl (which CAN panic) is not recognized -> fail-closed.
    if callee_is_trait_method_in(callee, NS_OPS_DEREF, "Deref", "deref")
        || callee_is_trait_method_in(callee, NS_OPS_DEREF, "DerefMut", "deref_mut")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_std_deref_receiver(&recv_ty));
    }
    Ok(false)
}

/// True when `ty` (a `Deref`/`DerefMut` receiver, possibly behind a `&`/`*`) is a std
/// smart-pointer / owning container whose `Deref` is a TOTAL pointer cast (no panic, no user
/// code). A user type's `Deref` can run arbitrary code and is NOT recognized (fail-closed).
fn ty_is_std_deref_receiver(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    // Build-2: `<&T as Deref>::deref` / `<&mut T as Deref>` — a reference's OWN Deref
    // just RE-BORROWS the referent (`fn deref(&self) -> &T { *self }`), running NO
    // user code and never panicking, for ANY `T`. After peeling the `&self` receiver
    // the value is itself a reference/pointer, so recognize it directly.
    if matches!(adt, Ty::Ref { .. } | Ty::RawPtr { .. }) {
        return true;
    }
    let Ty::Adt { name, .. } = adt else { return false };
    if !adt_path_is_std_anchored(name) {
        return false;
    }
    const DEREFABLE: &[&str] = &[
        "::vec::Vec",
        "::string::String",
        "::boxed::Box",
        "::path::PathBuf",
        "::rc::Rc",
        "::sync::Arc",
        "::ffi::OsString",
        "::ffi::CString",
        // Build-2 — RefCell borrow GUARDS (the rational-arena reads via the
        // `try_borrow{,_mut}` added in Build-1) plus the transparent std wrappers.
        // Each `deref`/`deref_mut` is a total pointer/field read that runs no user
        // code. `"::cell::Ref"` subsumes `Ref` and `RefMut` (both valid guards) and
        // the inert `RefCell` (never itself a Deref receiver). `ManuallyDrop<T>`
        // dereferences its stored value directly. `Pin<P>` and `Cow<B>` are
        // intentionally excluded: their Deref implementations dispatch through
        // user-selected `P::deref` / `Owned: Borrow<B>` implementations.
        "::cell::Ref",
        "::ManuallyDrop",
    ];
    DEREFABLE.iter().any(|p| name.contains(p))
}

fn total_str_iterator_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let Some(receiver) = args.first() else { return Ok(false) };
    if callee_is_trait_method_in(callee, NS_INTO_ITERATOR, "IntoIterator", "into_iter") {
        // `into_iter` on an already-built str iterator is the identity (the blanket
        // `impl<I: Iterator> IntoIterator for I`). Total iff the receiver is a
        // closure-free concrete str iterator.
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_str_iterator_receiver(&recv_ty));
    }
    // `Iterator::next` AND `DoubleEndedIterator::next_back` — advancing a concrete
    // closure-free str iterator (`Chars`/`Bytes`/…) from EITHER end walks the valid
    // `&str` and yields `None` at the end; it runs NO user code and cannot panic.
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next")
        || callee_is_trait_method_in(callee, NS_DOUBLE_ENDED_ITERATOR, "DoubleEndedIterator", "next_back")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next_back")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_str_iterator_receiver(&recv_ty));
    }
    // TOTAL adapter CONSTRUCTORS that wrap a str-backed iterator and run NO user
    // code (they only count/limit/wrap). `take`/`skip`/`enumerate`/`peekable`/
    // `rev`/`by_ref` are total; `map`/`filter`/`cloned`/… are EXCLUDED (run a user
    // closure/Clone that may panic). Gated on the receiver being a closure-free
    // str iterator. (`copied` is omitted: str iterators yield `char`/`&str`, not
    // `&T`, so `copied` never appears on them.) `take_while`/`skip_while` join as
    // CLOSURE-adapter constructors: the construction itself only stores the closure
    // (total, no user code — the closure is a separately-bundled body), and the
    // resulting `TakeWhile`/`SkipWhile` is NOT a `ty_is_str_iterator_receiver`, so a
    // later `next` on it stays fail-closed.
    const TOTAL_STR_ADAPTER_CTORS: &[&str] =
        &["rev", "take", "skip", "enumerate", "peekable", "by_ref", "take_while", "skip_while"];
    if TOTAL_STR_ADAPTER_CTORS.iter().any(|m| callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", m)) {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_str_iterator_receiver(&recv_ty));
    }
    // Bucket A — the CLOSURE/CLONE-adapter CONSTRUCTORS `map(f)` / `filter(p)` /
    // `cloned()` over a str iterator. Same soundness as the slice sibling: the
    // constructor only STORES the closure/inner (no user code, no panic); the closure
    // runs LATER in the adapter's `next`, which — the result being a
    // `Map`/`Filter`/`Cloned`, NOT a `ty_is_str_iterator_receiver` — stays fail-closed.
    if callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "map")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "filter")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "cloned")
    {
        let recv_ty = operand_trust_type(receiver, ctx)?;
        return Ok(ty_is_str_iterator_receiver(&recv_ty));
    }
    Ok(false)
}

// RETIRED LANE (SEQUENCE-COLLECT TOTALITY) — record only, no implementation. The
// gate read the destination out of a rendered turbofish SPELLING, which is not
// resolved type identity; the reasoning is kept so the next attempt starts from a
// real dest type rather than from its printed form.
//
// Build-1 F5-completeness: `Iterator::collect` into a std SEQUENCE collection
// (`Vec`/`VecDeque`/`String`) is TOTAL. `collect` itself only pushes the already-
// yielded elements into a freshly-allocated buffer — it runs NO user `Ord`/`Hash`
// (unlike a keyed/hashed `collect` into `BTreeMap`/`HashMap`/`BTreeSet`, whose key
// comparison IS user code) and its only failure mode is allocation abort, which —
// like all allocation in the trusted std TCB — is out of the modeled panic set
// (matching `total_no_panic_call_summary`). So the absent-callee `may panic`
// obligation for such a collect is spurious and is discharged.
//
// SOUNDNESS. Gated on the DESTINATION collection type (the `collect` turbofish
// target), which — unlike the erased element `K` of a keyed collection — IS
// carried by the dest ADT's `def_path_str` `name`. Keyed/hashed collects have a
// `BTreeMap`/`HashMap`/… dest name and fail the SEQUENCE gate; a later round added
// a separate KEY-GATED arm for `BTreeMap` (and `Result`-wrapped) dests, while
// `HashMap`/`BTreeSet`/user dests still fell through to the fail-closed arms
// (keeping their obligation). The
// element type of a sequence collect is irrelevant: a `Vec<K>`/`String` push runs
// no user code regardless of `K` (the element was produced by the upstream
// iterator, whose own body is analyzed separately). The `std::`/`alloc::`/`core::`
// origin gate keeps a like-named user collection out.

// A CONCRETE str-backed iterator: a `str::Chars`/`CharIndices`/`Bytes`/`Lines`/
// `Split`/`SplitN`/`RSplit`/`RSplitN`/`SplitTerminator`/`SplitWhitespace`/
// `SplitAsciiWhitespace`/`SplitInclusive`/`Matches`/`RMatches`/`MatchIndices`/
// `RMatchIndices` base, or a chain of TOTAL adapters (`Rev`/`Take`/`Skip`/
// `Enumerate`/`Peekable`) over such a base. Its `next` runs no user code and
// cannot panic — UNLESS a `Split`-family receiver was built from a CLOSURE
// pattern (`s.split(|c| ..)`), whose `next` runs the user predicate; that case is
// rejected by `ty_carries_closure_pattern`. Matched by the ADT's FINAL TWO path
// segments under a `str` gate (def_path_str spells these as `core::str::iter::<T>`
// — last2 `("iter", T)` — or the re-exported `core::str::<T>` — last2 `("str",
// T)`; both forms are accepted, mirroring trust-mc's `is_str_chars_path`). The two
// alternatives plus the `str` substring gate keep a user type whose module merely
// ends in `iter`/`str` from false-matching. Closure/code-carrying receivers are
// rejected wholesale (the soundness gate).
fn ty_is_str_iterator_receiver(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    let Ty::Adt { name, fields, .. } = adt else { return false };
    // Round-14: crate-origin anchor before the name heuristic (see
    // `adt_path_is_std_anchored`) — a `dep::str::Chars` must not match.
    if !adt_path_is_std_anchored(name) {
        return false;
    }
    let base = strip_generics(name);
    let base = strip_trust_crate_disambiguator(&base);
    // Soundness gate: a str iterator that carries a closure/fn pattern
    // (`Split`/`SplitN`/… built from `|c| ..`) runs user code in `next` and may
    // panic — refuse it so the call falls through to resolve_call_target.
    if ty_carries_closure_pattern(adt) || ty_carries_untrusted_str_pattern_state(adt) {
        return false;
    }
    let segs: Vec<&str> = base.split("::").collect();
    let n = segs.len();
    if n < 2 {
        return false;
    }
    // The path must be a STR iterator (`core::str::iter::*` / `core::str::*`),
    // never a like-named user/other-module type.
    let is_str_path = base.starts_with("core::str::") || base.starts_with("std::str::");
    let last = segs[n - 1];
    // Str-iterator BASE types (their `next` is total over a valid `&str`).
    const STR_ITER_BASES: &[&str] = &[
        "Chars",
        "CharIndices",
        "Bytes",
        "Lines",
        "Split",
        "SplitN",
        "RSplit",
        "RSplitN",
        "SplitTerminator",
        "RSplitTerminator",
        "SplitWhitespace",
        "SplitAsciiWhitespace",
        "SplitInclusive",
        "Matches",
        "RMatches",
        "MatchIndices",
        "RMatchIndices",
    ];
    if is_str_path && STR_ITER_BASES.contains(&last) {
        return true;
    }
    // Total adapter (`std::iter::Rev`/`Take`/`Skip`/`Enumerate`/`Peekable`) —
    // recurse into its inner iterator field. Only adapters that run NO user code
    // are listed; `Map`/`Filter`/`Cloned`/… are excluded. The adapter itself lives
    // in `core::iter::*`, so it has its OWN two-segment shape; recurse to find the
    // str-backed inner.
    let last2 = (segs[n - 2], last);
    let total_adapter = matches!(
        last2,
        ("iter", "Rev")
            | ("iter", "Take")
            | ("iter", "Skip")
            | ("iter", "Enumerate")
            | ("iter", "Peekable")
    );
    if total_adapter {
        return fields.iter().any(|(_, fty)| ty_is_str_iterator_receiver(fty));
    }
    false
}

// True if `ty` transitively carries a closure / fn-item / fn-ptr / coroutine type
// in any field, element, or pointee. Used as the str-iterator soundness gate: a
// `Split`-family iterator built from a CLOSURE pattern (`s.split(|c| ..)`) holds
// the closure in its pattern field, and its `next` runs that user predicate (which
// may panic), so such a receiver must NOT be treated as a total iterator.
fn ty_carries_closure_pattern(ty: &Ty) -> bool {
    match ty {
        Ty::Closure { .. } | Ty::FnDef { .. } | Ty::FnPtr { .. } | Ty::Coroutine { .. } => true,
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => {
            ty_carries_closure_pattern(inner)
        }
        Ty::Slice { elem } | Ty::Array { elem, .. } => ty_carries_closure_pattern(elem),
        Ty::Tuple(elems) => elems.iter().any(ty_carries_closure_pattern),
        Ty::Adt { fields, .. } => fields.iter().any(|(_, fty)| ty_carries_closure_pattern(fty)),
        _ => false,
    }
}

// A pattern-driven str iterator may carry an extracted searcher/pattern state.
// Built-in char/str pattern state is rooted in core/std (or is scalar/slice
// state), but a synthetic or compatibility IR can carry an arbitrary user ADT.
// Such a value has no authenticated totality authority, so reject it even when
// it is not represented as an explicit `Ty::Closure`.
fn ty_carries_untrusted_str_pattern_state(ty: &Ty) -> bool {
    match ty {
        Ty::Adt { name, fields, .. } => {
            !adt_path_is_std_anchored(name)
                || fields.iter().any(|(_, fty)| ty_carries_untrusted_str_pattern_state(fty))
        }
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => {
            ty_carries_untrusted_str_pattern_state(inner)
        }
        Ty::Slice { elem } | Ty::Array { elem, .. } => ty_carries_untrusted_str_pattern_state(elem),
        Ty::Tuple(elems) => elems.iter().any(ty_carries_untrusted_str_pattern_state),
        Ty::Closure { .. } | Ty::FnDef { .. } | Ty::FnPtr { .. } | Ty::Coroutine { .. } => true,
        _ => false,
    }
}

// SOUNDNESS (HOLE-6B): true if ANY argument operand carries a closure/fn — i.e. the
// call is higher-order and its panic-freedom depends on user closure code, so it
// must NOT be summarized as a total (cannot-panic) call. An operand whose type
// cannot be resolved is conservatively treated as non-closure (these are simple
// scalar/total-call args; the higher-order callees pass a concrete `Ty::Closure`).
/// The std INTEGER→INTEGER `TryFrom::try_from` / `TryInto::try_into` blanket
/// impls, identified by name PLUS the call's actual types. Name alone cannot
/// justify totality: the trait-method spelling (`std::convert::TryFrom::
/// try_from`) is type-ERASED and a user `TryFrom` impl can panic. The three
/// typed gates pin it to exactly the std int→int family — total by
/// construction (unrepresentable values return `Err(TryFromIntError)`, never
/// panic; no user code runs):
///   1. callee is the core/std `convert` trait method (`try_from`/`try_into`);
///   2. the single argument is an integer scalar;
///   3. the DESTINATION is the flattened `Result` ADT whose Err payload is
///      `num::TryFromIntError` — the marker type ONLY the std int→int (and
///      NonZero, equally total) impls produce. `char::try_from(u32)`'s
///      `CharTryFromError` and every user impl fail this gate → fall through
///      to the absent-callee may-panic encoding (fail-closed).
fn int_try_from_total_call(
    callee: &str,
    args: &[Operand],
    dest: &Place,
    ctx: &LoweringCtx<'_>,
) -> bool {
    let normalized = strip_generics(callee);
    // The unresolved generic-dispatch spelling `…::convert::TryFrom::try_from`, PLUS the
    // RESOLVED qualified spelling `<usize as std::convert::TryFrom<i128>>::try_from`
    // (which `strip_generics` collapses to a bare `try_from`, losing the trait — so the
    // suffix match misses it). `callee_is_trait_method_in` recovers the qualified form
    // (peeling the trait-level `<i128>` generic + any method turbofish); the typed
    // `Result<_, TryFromIntError>` dest gate below is unchanged and remains the whole
    // soundness argument (excludes `char::try_from` and every user `TryFrom`).
    let is_try_conv = ((normalized.starts_with("core::") || normalized.starts_with("std::"))
        && (normalized.ends_with("::convert::TryFrom::try_from")
            || normalized.ends_with("::convert::TryInto::try_into")))
        || callee_is_trait_method_in(callee, NS_CONVERT, "TryFrom", "try_from")
        || callee_is_trait_method_in(callee, NS_CONVERT, "TryInto", "try_into");
    if !is_try_conv || args.len() != 1 {
        return false;
    }
    if !operand_trust_type(&args[0], ctx)
        .map(|ty| matches!(ty, Ty::Int { .. } | Ty::PtrSizedInt { .. }))
        .unwrap_or(false)
    {
        return false;
    }
    let Ok(dest_ty) = place_type(dest, ctx) else {
        return false;
    };
    let Ty::Adt { name, fields, .. } = &dest_ty else {
        return false;
    };
    if !matches!(name.as_str(), "core::result::Result" | "std::result::Result") {
        return false;
    }
    let Some(ok_ty) = fields.iter().find(|(field, _)| field == "__v0_0").map(|(_, ty)| ty) else {
        return false;
    };
    let Some(err_ty) = fields.iter().find(|(field, _)| field == "__v1_0").map(|(_, ty)| ty) else {
        return false;
    };
    let ok_is_builtin = matches!(ok_ty, Ty::Int { .. } | Ty::PtrSizedInt { .. })
        || matches!(ok_ty, Ty::Adt { name, .. } if is_builtin_nonzero_int_name(name));
    let err_is_exact = matches!(err_ty, Ty::Adt { name, .. }
        if matches!(name.as_str(),
            "core::num::TryFromIntError"
                | "core::num::error::TryFromIntError"
                | "std::num::TryFromIntError"));
    ok_is_builtin && err_is_exact
}

fn is_builtin_nonzero_int_name(name: &str) -> bool {
    matches!(
        name,
        "core::num::NonZero"
            | "core::num::nonzero::NonZero"
            | "core::num::NonZeroU8"
            | "core::num::NonZeroU16"
            | "core::num::NonZeroU32"
            | "core::num::NonZeroU64"
            | "core::num::NonZeroU128"
            | "core::num::NonZeroUsize"
            | "core::num::NonZeroI8"
            | "core::num::NonZeroI16"
            | "core::num::NonZeroI32"
            | "core::num::NonZeroI64"
            | "core::num::NonZeroI128"
            | "core::num::NonZeroIsize"
            | "std::num::NonZeroU8"
            | "std::num::NonZeroU16"
            | "std::num::NonZeroU32"
            | "std::num::NonZeroU64"
            | "std::num::NonZeroU128"
            | "std::num::NonZeroUsize"
            | "std::num::NonZeroI8"
            | "std::num::NonZeroI16"
            | "std::num::NonZeroI32"
            | "std::num::NonZeroI64"
            | "std::num::NonZeroI128"
            | "std::num::NonZeroIsize"
    )
}

fn call_has_closure_pattern_arg(args: &[Operand], ctx: &LoweringCtx<'_>) -> bool {
    args.iter().any(|a| {
        operand_trust_type(a, ctx).map(|ty| ty_carries_closure_pattern(&ty)).unwrap_or(true)
    })
}

/// Trust: strip every `<…>` generic span from a def-path and drop the empty path
/// components the strip leaves behind, normalizing a monomorphized callee spelling
/// (`core::str::<impl str>::len`, `std::vec::Vec::<T>::new`) to a stable `a::b::c`
/// form. Shared by `total_no_panic_call_summary`, `closure_driving_consumer_call`,
/// `fmt_value_packing_call`, and `extern_fmt_dispatch_call` so their path matching
/// cannot drift apart (previously each open-coded the same strip loop).
fn strip_generics(callee: &str) -> String {
    let mut without_generics = String::with_capacity(callee.len());
    let mut depth = 0usize;
    for c in callee.chars() {
        match c {
            '<' => depth += 1,
            '>' => depth = depth.saturating_sub(1),
            _ if depth == 0 => without_generics.push(c),
            _ => {}
        }
    }
    without_generics.split("::").filter(|seg| !seg.is_empty()).collect::<Vec<_>>().join("::")
}

fn has_trusted_std_root(path: &str) -> bool {
    path.starts_with("core::") || path.starts_with("alloc::") || path.starts_with("std::")
}

/// Authenticate a compiler-rendered standard trait method before consulting a
/// receiver type. A receiver gate alone is insufficient: a user function can
/// accept the same std receiver and choose the same `Trait::method` tail.
fn canonical_trait_path(callee: &str, method: &str) -> Option<String> {
    let method = method.trim_start_matches("::");
    if let Some((trait_path, rendered_method)) = qualified_callee_trait_method(callee) {
        return (rendered_method == method && !trait_path.starts_with("__trust_crate@"))
            .then_some(trait_path);
    }
    let suffix = format!("::{method}");
    let normalized = strip_generics(callee);
    (!normalized.starts_with("__trust_crate@"))
        .then(|| normalized.strip_suffix(&suffix).map(str::to_owned))
        .flatten()
}

/// Exact trait-path authority for a canonical std trait method.
///
/// PATH-SPELLING ROBUSTNESS (the definition-path renderer, same class as the
/// iterator receiver-gate fix): callers pass the PUBLIC re-export spelling
/// (`core::ops::Index`), but the renderer now emits the DEFINITION path
/// (`core::ops::index::Index`) in the qualified impl form
/// `<alloc::vec::Vec<i32> as core::ops::index::Index<usize>>::index`. An exact
/// string comparison therefore silently stopped matching, and every recognizer
/// built on it fell through to the fail-closed absent-callee arm — measured on
/// `vec_scalar_index_lenchecked`, whose bounds VC the formula lane had already
/// PROVED while the unmatched call minted a duplicate, undischargeable
/// may-panic row.
///
/// Accept a candidate whose segments are the expected path's segments with at
/// most ONE extra module segment inserted before the final trait name — the
/// exact shape of a re-export (`core::ops::Index` is `core::ops::index::Index`
/// re-exported from `core::ops`). Crate root and trait name must still match
/// exactly, so this widens spelling only WITHIN the same authenticated std
/// trait; a foreign `my::ops::Index` still fails on its root.
fn is_canonical_trait_method(callee: &str, trait_paths: &[&str], method: &str) -> bool {
    canonical_trait_path(callee, method).is_some_and(|path| {
        trait_paths.iter().any(|expected| {
            if path == *expected {
                return true;
            }
            let actual: Vec<&str> = path.split("::").collect();
            let want: Vec<&str> = expected.split("::").collect();
            // Exactly one extra module segment, same root, same trait name, and
            // every leading segment of the expectation preserved in order.
            actual.len() == want.len() + 1
                && actual.first() == want.first()
                && actual.last() == want.last()
                && want[..want.len() - 1]
                    .iter()
                    .zip(actual[..actual.len() - 1].iter())
                    .all(|(w, a)| w == a)
        })
    })
}

fn is_canonical_iterator_method(callee: &str, trait_name: &str, method: &str) -> bool {
    callee_is_std_iter_method(callee, trait_name, method.trim_start_matches("::"))
}

/// Preserve only unambiguous crate-rooted paths for authority checks.
///
/// The extractor adds `__trust_crate@<stable-id>::` precisely when two crates
/// share a rendered crate name. This bridge does not receive the authenticated
/// stable id of `core`/`alloc`/`std` (or third-party semantic dependencies), so
/// removing that prefix would erase the collision evidence and could bless an
/// attacker crate with the same name. Return an impossible empty path instead;
/// every caller consequently fails closed.
fn strip_trust_crate_disambiguator(path: &str) -> &str {
    if path.starts_with("__trust_crate@") { "" } else { path }
}

/// Split a QUALIFIED trait-impl callee spelling `<Self as Trait>::method` into its
/// generic-stripped trait path and its method segment — `None` for any other shape
/// (no leading `<…>` header, no top-level ` as ` inside it, no `::method` tail). A
/// trailing turbofish after the method (`…>::zip::<std::slice::Iter<'_, u32>>`) is
/// ignored. The extractor renders resolved trait-method callees in this form (via
/// `safe_def_path_str_with_args`), e.g.
/// `<std::ops::Range<usize> as std::iter::IntoIterator>::into_iter`, while the
/// historical name gates in this file only knew the GENERIC trait-fn spelling
/// (`std::iter::IntoIterator::into_iter`) — parsing the header restores a stable
/// `Trait::method` identity for both.
fn qualified_callee_trait_method(callee: &str) -> Option<(String, &str)> {
    let inner = callee.strip_prefix('<')?;
    // The matching `>` of the leading `<…>` header, by depth count (the Self/Trait
    // spellings carry their own nested `<…>` generic groups).
    let mut depth = 1usize;
    let mut header_end = None;
    for (i, c) in inner.char_indices() {
        match c {
            '<' => depth += 1,
            '>' => {
                depth -= 1;
                if depth == 0 {
                    header_end = Some(i);
                    break;
                }
            }
            _ => {}
        }
    }
    let header_end = header_end?;
    let header = &inner[..header_end];
    let tail = &inner[header_end + 1..];
    // `Self as Trait` — split on the LAST depth-0 ` as ` (a nested qualified Self
    // like `<<A as B>::C as Trait>` keeps its inner ` as ` at depth > 0).
    let mut trait_start = None;
    let mut d = 0usize;
    for (i, b) in header.bytes().enumerate() {
        match b {
            b'<' => d += 1,
            b'>' => d = d.saturating_sub(1),
            b' ' if d == 0 && header[i..].starts_with(" as ") => {
                trait_start = Some(i + " as ".len());
            }
            _ => {}
        }
    }
    let trait_spelling = &header[trait_start?..];
    // The method is the first path segment after the header's `::`; any further
    // `::<turbofish>` segment is ignored. A non-identifier segment declines.
    let after = tail.strip_prefix("::")?;
    let method = after.split("::").next().unwrap_or(after);
    if method.is_empty() || method.contains('<') {
        return None;
    }
    Some((strip_generics(trait_spelling), method))
}

/// Callee-NAME gate shared by the std ITERATOR-PROTOCOL totality recognizers
/// (`total_slice_iterator_call` / `total_str_iterator_call` /
/// `total_range_iterator_call` / `total_rev_range_iterator_call` /
/// `total_step_by_ctor_call`): does `callee` spell the std trait method
/// `{trait_last}::{method}` in either def-path rendering the extractor produces?
///
///  * the GENERIC trait-fn spelling `…::{trait_last}::{method}`
///    (`std::iter::Iterator::enumerate`,
///    `core::iter::traits::collect::IntoIterator::into_iter`) — the historical
///    with the trait path crate-anchored to `std::iter::` / `core::iter::`;
///  * the QUALIFIED impl spelling `<Self as Trait>::{method}` (with an optional
///    turbofish after the method), where the trait path must be CRATE-ANCHORED:
///    generic-stripped it starts with `std::iter::` / `core::iter::` and its last
///    segment is `{trait_last}`. This is the same crate-origin discipline as
///    trust-vcgen's `f64_std_method_name`: a user trait spelled
///    `<T as my_crate::Iterator>::enumerate` has arbitrary semantics and must
///    NEVER match — only the real std/core iterator traits can (`starts_with`,
///    so a `my_crate::std::iter::Iterator` embedding cannot sneak in either).
///
/// NAME-ONLY — deliberately NOT a totality decision. Every caller keeps its own
/// receiver/argument TYPE gate, which is the load-bearing soundness check:
/// `<my_crate::MyIter as std::iter::Iterator>::next` IS user code (a required
/// trait method), passes this name gate, and is then rejected by the caller's
/// `ty_is_*_receiver` gate (fail-closed).
fn callee_is_std_iter_method(callee: &str, trait_last: &str, method: &str) -> bool {
    let normalized = strip_generics(callee);
    let suffix = format!("::{method}");
    if let Some(trait_path) = normalized.strip_suffix(&suffix) {
        let trait_path = strip_trust_crate_disambiguator(trait_path);
        if (trait_path.starts_with("std::iter::") || trait_path.starts_with("core::iter::"))
            && trait_path.rsplit("::").next() == Some(trait_last)
        {
            return true;
        }
    }
    let Some((trait_path, m)) = qualified_callee_trait_method(callee) else { return false };
    let trait_path = strip_trust_crate_disambiguator(&trait_path);
    m == method
        && (trait_path.starts_with("std::iter::") || trait_path.starts_with("core::iter::"))
        && trait_path.rsplit("::").next() == Some(trait_last)
}

/// Callee-NAME gate for the INHERENT slice methods (`<[T]>::windows` /
/// `::chunks` / `::chunks_exact`): either the generic `[T]` impl spelling
/// (`core::slice::<impl [T]>::chunks` — the historical `contains("[T]")` match,
/// kept as-is) or a MONOMORPHIZED element spelling
/// (`core::slice::<impl [u32]>::chunks`), which generic-strips to
/// `core::slice::chunks` — anchored to the `core::slice::` / `std::slice::`
/// module root, so a user `my_crate::slice::<impl …>::chunks` (which strips to
/// `my_crate::slice::chunks`) never matches. NAME-ONLY: the caller keeps its
/// receiver-type AND nonzero-literal-size gates, which carry the soundness
/// (the constructors' only panic is `assert!(size != 0)`).
fn callee_is_std_slice_inherent(callee: &str, method: &str) -> bool {
    let suffix = format!("::{method}");
    let stripped = strip_generics(callee);
    let stripped = strip_trust_crate_disambiguator(&stripped);
    (stripped.starts_with("core::slice::") || stripped.starts_with("std::slice::"))
        && stripped.ends_with(&suffix)
}

// A closure-DRIVING consumer of an iterator/`Option`/`Result` (or `to_string`)
// whose panic-freedom depends on a USER closure / `Display` impl we cannot
// summarize as total: `Iterator::{collect,fold,all,any,find,find_map,for_each,
// position,rposition,rfind,try_fold,try_for_each,reduce,partition,max_by,min_by,
// max_by_key,min_by_key,sum,product,count}`, `Option/Result::{map,and_then,
// map_or,map_or_else,filter,is_some_and,unwrap_or_else,or_else,ok_or_else,
// get_or_insert_with}`, and `ToString::to_string` (dispatches to `Display::fmt`).
// These cannot be allowlisted as total (they may panic through the user code) but
// they need not POISON the whole function: we model the call as an opaque result
// PLUS one honest `PanicFreedom` obligation that stays UNKNOWN (sound — the call
// genuinely can panic, so an unknown verdict is conservative and never a false
// prove), then continue lowering so the function's OTHER obligations get real
// verdicts instead of all collapsing to `Unsupported`. (Verifying code after the
// call under "the call returned" is sound: on a panic the continuation is
// unreachable, so its obligations are vacuously satisfied.)
fn closure_driving_consumer_call(callee: &str) -> bool {
    // Derive `(trait_last, method)` robustly across BOTH def-path renderings.
    //   * GENERIC trait-fn spelling `…::Iterator::fold` — the last two segments
    //     of the generic-stripped path;
    //   * QUALIFIED impl spelling `<Copied<…> as core::iter::traits::iterator::
    //     Iterator>::fold::<u8, {closure}>` — here `strip_generics` collapses
    //     the whole `<Self as Trait>` header to nothing, leaving just `fold`
    //     (one segment), so the segment approach fails. Parse the qualified
    //     header instead (`qualified_callee_trait_method`) and take the trait
    //     path's LAST segment as the receiver. This was the sixth site of the
    //     definition-path spelling skew: without it `<Copied<slice::Iter> as
    //     Iterator>::fold` fell through to the FATAL absent-callee arm instead
    //     of the closure-consumer / HOF-resolve arms (measured on
    //     slice_range_index).
    if let Some((trait_path, method)) = qualified_callee_trait_method(callee) {
        let receiver = trait_path.rsplit("::").next().unwrap_or(&trait_path);
        return closure_consumer_receiver_method(receiver, method);
    }
    let normalized = strip_generics(callee);
    let segs: Vec<&str> = normalized.split("::").collect();
    let n = segs.len();
    if n < 2 {
        return false;
    }
    closure_consumer_receiver_method(segs[n - 2], segs[n - 1])
}

/// The (receiver-trait, method) membership table for
/// [`closure_driving_consumer_call`], factored so both the generic and
/// qualified spellings share one decision.
fn closure_consumer_receiver_method(receiver: &str, method: &str) -> bool {
    match receiver {
        "Iterator" => matches!(
            method,
            "collect"
                | "fold"
                | "try_fold"
                | "all"
                | "any"
                | "find"
                | "find_map"
                | "for_each"
                | "try_for_each"
                | "position"
                | "rposition"
                | "rfind"
                | "reduce"
                | "partition"
                | "max_by"
                | "min_by"
                | "max_by_key"
                | "min_by_key"
                | "sum"
                | "product"
                | "count"
        ),
        "Option" | "Result" => matches!(
            method,
            "map"
                | "map_err"
                | "and_then"
                | "map_or"
                | "map_or_else"
                | "filter"
                | "is_some_and"
                | "is_ok_and"
                | "unwrap_or_else"
                | "or_else"
                | "ok_or_else"
                | "get_or_insert_with"
                | "unwrap_or_default"
        ),
        "slice" => matches!(method, "binary_search_by_key" | "binary_search_by"),
        "ToString" => method == "to_string",
        _ => false,
    }
}

// SOUNDNESS (W3.3, HOLE-6B pairing): EXACT-name recognition of the core/alloc/std
// `fmt` VALUE-PACKING constructors — `Argument::new_display`/`new_debug`/… — which
// only PACKAGE a data pointer plus a (transmuted) formatter fn-pointer into an
// `Argument` struct. They are genuinely TOTAL: no formatter runs AT CONSTRUCTION,
// nothing allocates, and NO user code executes here (the user `Display`/`Debug::fmt`
// dispatch happens LATER, inside the print/format/write DISPATCH calls modeled by
// `extern_fmt_dispatch_call`). Because the packed formatter fn-pointer arg trips
// `call_has_closure_pattern_arg`, the HOLE-6B gate would otherwise reject these
// legitimate total packers; this predicate lets ONLY them bypass that rejection.
//
// SOUNDNESS anchors: (1) crate-origin — core/alloc/std only (a user
// `mycrate::Argument::new_display` fails closed); (2) EXACT trailing
// `::Argument::new_*` names. `::Argument::from_usize` is DELIBERATELY NOT listed —
// it `panic!`s on `> u16::MAX`, so it is NOT total and must keep bailing. This never
// matches a print/format DISPATCH call (`_print`/`write_fmt`/`fmt::format`), only
// the pure packers.
fn fmt_value_packing_call(callee: &str) -> bool {
    let normalized = strip_generics(callee);
    if !(normalized.starts_with("core::")
        || normalized.starts_with("alloc::")
        || normalized.starts_with("std::"))
    {
        return false;
    }
    // Keep in lockstep with the `::Argument::new_*` entries in the `TOTAL` list of
    // `total_no_panic_call_summary` (those make the call `total`; this lets it clear
    // the HOLE-6B closure-pattern gate). `from_usize` is intentionally absent.
    const FMT_VALUE_PACKING: &[&str] = &[
        "::Argument::new_display",
        "::Argument::new_debug",
        "::Argument::new_debug_noop",
        "::Argument::new_octal",
        "::Argument::new_lower_hex",
        "::Argument::new_upper_hex",
        "::Argument::new_pointer",
        "::Argument::new_binary",
        "::Argument::new_lower_exp",
        "::Argument::new_upper_exp",
        // The `Arguments` container constructors — same pure-packaging semantics
        // (see the `total_no_panic_call_summary` TOTAL list). Also let them clear
        // the HOLE-6B closure-pattern gate (the stored `Argument` slice carries
        // transmuted fn-pointers that would otherwise trip the closure check).
        "::Arguments::new_v1",
        "::Arguments::new_const",
        "::Arguments::new_v1_formatted",
        "::Arguments::new",
    ];
    FMT_VALUE_PACKING.iter().any(|name| normalized.ends_with(name))
}

// SOUNDNESS (W3.4): the core/alloc/std print/format/write DISPATCH entry points.
// EACH drives a user `Display`/`Debug::fmt` impl — arbitrary user code that CAN
// panic — and the stdout legs (`_print`/`_eprint`) can additionally hit a broken
// pipe / SIGPIPE. So NONE may EVER be summarized total/no-panic. Instead the caller
// models them like `closure_driving_consumer_call`: an opaque result + one honest
// `PanicFreedom` obligation (marked with `EXTERN_CALL_ASSUMPTION_PREFIX`) that stays
// UNKNOWN — conservative, never a false PROVE — then continues lowering so the
// function's OTHER obligations get real verdicts instead of collapsing to
// `Unsupported`. The explicit memory-safe policy may later demote that UNKNOWN
// row to a recorded `assumption:extern-call` ledger entry (never a proof), but
// only after the compiler establishes that the function contains no source or
// inlined unsafe code. Strict and broad advisory policies keep it UNKNOWN.
//
// Crate-origin anchored (a user method named `format`/`write_fmt` fails closed).
// Exact trailing names so this never over-matches an accessor.
fn extern_fmt_dispatch_call(callee: &str) -> bool {
    let normalized = strip_generics(callee);
    if !(normalized.starts_with("core::")
        || normalized.starts_with("alloc::")
        || normalized.starts_with("std::"))
    {
        return false;
    }
    normalized.ends_with("::io::_print")            // std println!/print! backend
        || normalized.ends_with("::io::_eprint")    // std eprintln!/eprint! backend
        || normalized.ends_with("::fmt::format")    // alloc::fmt::format — format!() backend
        || normalized.ends_with("::fmt::write")     // core::fmt::write — the formatting driver
        || normalized.ends_with("::write_fmt") // io::Write / fmt::Write::write_fmt — write!()
}

// `(a..b).contains(&x)` / `(a..=b).contains(&x)` / `(..n)`/`(n..)` over a PRIMITIVE
// `Idx` — TOTAL (runs only the primitive's builtin `PartialOrd`, no panic, no user
// code). Triple-gated for soundness: the callee def-path AND the receiver ADT
// def-path must both be a std/core `Range…`, AND every receiver field must be a
// primitive `Copy` scalar (so a user type merely named `Range`, or a
// `Range<UserType>` whose `contains` runs user `PartialOrd`, is excluded — as is
// `slice::contains`/`HashSet::contains`, which are under different paths and run
// user `Eq`/`Hash`).
fn total_range_contains_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let normalized = strip_generics(callee);
    if !has_trusted_std_root(&normalized) || !normalized.ends_with("::contains") {
        return Ok(false);
    }
    const RANGE_PATHS: &[&str] =
        &["std::ops::Range", "core::ops::range::Range", "core::ops::Range"];
    if !RANGE_PATHS.iter().any(|p| normalized.starts_with(p)) {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    let adt = match &recv_ty {
        Ty::Ref { inner, .. } => inner.as_ref(),
        Ty::RawPtr { pointee, .. } => pointee.as_ref(),
        other => other,
    };
    let Ty::Adt { name, fields, .. } = adt else { return Ok(false) };
    if !RANGE_PATHS.iter().any(|p| name.starts_with(p)) {
        return Ok(false);
    }
    Ok(!fields.is_empty() && fields.iter().all(|(_, fty)| field_is_primitive_copy(fty)))
}

// A primitive `Copy` scalar (`bool`/integer/`char`-as-`Int`/float) or a ref/raw-ptr
// to one — used to gate `total_range_contains_call` to ranges over a primitive Idx.
fn field_is_primitive_copy(ty: &Ty) -> bool {
    match ty {
        Ty::Bool | Ty::Int { .. } | Ty::Float { .. } => true,
        Ty::Ref { inner, .. } => field_is_primitive_copy(inner),
        Ty::RawPtr { pointee, .. } => field_is_primitive_copy(pointee),
        _ => false,
    }
}

// `for i in a..b` desugars to `IntoIterator::into_iter(a..b)` (identity on a
// `Range`) then `Iterator::next(&mut range)`. For an EXCLUSIVE `Range<P>` over a
// primitive integer `P` BOTH are TOTAL: `into_iter` returns `self`, and `next` is
// `if start < end { let n = start; start = n + 1; Some(n) } else { None }`, whose
// `n + 1` cannot overflow (`start < end <= P::MAX`, so `n = start <= P::MAX - 1`).
// Triple-gated like `total_range_contains_call`: the callee is the std iterator
// protocol method AND the receiver ADT is the std/core EXCLUSIVE `Range` (NOT
// `RangeInclusive`/`From`/`To` — their `next`/overflow profile differs) AND every
// field is a primitive `Copy` scalar (so a `Range<UserType>` whose `Step`/
// `PartialOrd` runs user code that could panic is excluded). The caller models the
// result as `Undef`, leaving the yielded index UNCONSTRAINED — sound: a loop-body
// obligation that depends on the index fails closed (Unknown), never falsely
// proved. Unblocks `for i in 0..n { .. }` under strict verification, which
// previously fail-closed the WHOLE function because `IntoIterator::into_iter` is
// not present in the TrustIr module.
fn total_range_iterator_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    // `into_iter` (identity), `next`, AND `next_back` on a bare `Range` — `Range` is
    // its own `DoubleEndedIterator`. `next_back` is `if start < end { end -= 1;
    // Some(end) }`, whose `end - 1` cannot underflow under `start < end` (so `end >
    // start >= MIN`) — total for the exclusive PRIMITIVE Range gated below, exactly
    // the argument `total_rev_range_iterator_call` already makes for `Range::next_back`
    // reached via `Rev`.
    if !(callee_is_trait_method_in(callee, NS_INTO_ITERATOR, "IntoIterator", "into_iter")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next")
        || callee_is_trait_method_in(callee, NS_DOUBLE_ENDED_ITERATOR, "DoubleEndedIterator", "next_back")
        || callee_is_trait_method_in(callee, NS_ITERATOR, "Iterator", "next_back"))
    {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    let adt = match &recv_ty {
        Ty::Ref { inner, .. } => inner.as_ref(),
        Ty::RawPtr { pointee, .. } => pointee.as_ref(),
        other => other,
    };
    Ok(ty_is_exclusive_primitive_range_adt(adt))
}

// The EXCLUSIVE std/core `Range<P>` over a primitive `Copy` scalar `P` — the
// receiver gate `total_range_iterator_call` uses, factored so the `Rev<Range>`
// arm below can re-validate the WRAPPED iterator with the identical discipline.
// Exact `…::Range`, or `…::Range<..>` — the trailing `<` rules out the longer
// names (`RangeInclusive`/`RangeFrom`/`RangeTo`) that share the prefix; the
// all-primitive-fields gate rules out a `Range<UserType>` whose `Step`/
// `PartialOrd` runs user code that could panic.
fn ty_is_exclusive_primitive_range_adt(adt: &Ty) -> bool {
    let Ty::Adt { name, fields, .. } = adt else { return false };
    const EXCL_RANGE: &[&str] = &["std::ops::Range", "core::ops::range::Range", "core::ops::Range"];
    let normalized = strip_generics(name);
    let normalized = strip_trust_crate_disambiguator(&normalized);
    let is_excl_range = EXCL_RANGE.contains(&normalized);
    is_excl_range
        && !fields.is_empty()
        && fields.iter().all(|(_, fty)| field_is_primitive_copy(fty))
}

// `for i in (a..b).rev()` — the for-loop desugar's `IntoIterator::into_iter`
// (blanket identity on any `Iterator`) and `Iterator::next` calls on a
// `Rev<Range<P>>` adapter over an EXCLUSIVE primitive Range. BOTH are TOTAL:
// `into_iter` returns `self` unchanged (runs NO user code), and
// `Rev<Range<P>>::next` is `Range::next_back` — `if start < end { end -= 1;
// Some(end) } else { None }` — whose `end - 1` cannot underflow (`start < end`
// implies `end > start >= P::MIN`, so `end >= P::MIN + 1`). The `.rev()` CTOR
// hop is already modeled by the lazy-adapter-constructor totality list; these
// two are the remaining chain links that previously ABORTED whole-function
// lowering ("Call target `std::iter::IntoIterator::into_iter` is not present
// in the TrustIr module") and hard-errored the provably-safe superiority
// fixture `rev_range_index_bound` under the strict native-evidence default.
//
// Triple-gated for soundness, mirroring `total_range_iterator_call` +
// `ty_is_step_by_iterator_receiver`:
//   * callee is the std iterator-protocol method (`into_iter` / `next`);
//   * the receiver ADT path is the std/core `Rev` adapter — last-two segments
//     `("rev"|"iter", "Rev")` AND a `core::`/`std::` crate root, so a
//     like-named USER type (whose `next` could run panicking code) never
//     matches;
//   * the single wrapped field is itself the EXCLUSIVE primitive `Range`
//     (`ty_is_exclusive_primitive_range_adt`) — a `Rev` over any OTHER
//     iterator (user iterator, `RangeInclusive`, slice `Iter`, …) declines and
//     falls through (slice/str-backed `Rev` chains keep their own arms).
// The caller models the result as `Undef`, leaving the yielded index
// UNCONSTRAINED — sound: a loop-body obligation that depends on the index
// fails closed, never falsely proved — and exactly matching the forward
// `for i in a..b` treatment (whose bounds proof lives in the formula lane's
// range-yield invariant; vcgen treats `.rev()` as value-set-transparent).
fn total_rev_range_iterator_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    // Generic AND qualified impl spellings (see `callee_is_std_iter_method`);
    // the Rev<Range<primitive>> receiver gate below is the soundness decision.
    if !(callee_is_std_iter_method(callee, "IntoIterator", "into_iter")
        || callee_is_std_iter_method(callee, "Iterator", "next"))
    {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    let adt = match &recv_ty {
        Ty::Ref { inner, .. } => inner.as_ref(),
        Ty::RawPtr { pointee, .. } => pointee.as_ref(),
        other => other,
    };
    let Ty::Adt { name, fields, .. } = adt else { return Ok(false) };
    // Strip any `<..>` generic-args suffix BEFORE splitting on `::` (the args
    // contain their own `::` separators) — same discipline as the StepBy gate.
    let path = strip_generics(name);
    let path = strip_trust_crate_disambiguator(&path);
    if !(path.starts_with("core::") || path.starts_with("std::")) {
        return Ok(false);
    }
    let segs: Vec<&str> = path.split("::").collect();
    let n = segs.len();
    if n < 2 || segs[n - 1] != "Rev" || !(segs[n - 2] == "rev" || segs[n - 2] == "iter") {
        return Ok(false);
    }
    Ok(fields.len() == 1 && ty_is_exclusive_primitive_range_adt(&fields[0].1))
}

// `(LO..HI).step_by(K)` — the `StepBy` ADAPTER CONSTRUCTOR call
// `<Range as Iterator>::step_by(range_iter, k)`. Its body lives in `core` (so
// `resolve_call_target` rejects it, aborting whole-function lowering), but for a
// LITERAL NONZERO step the constructor is TOTAL: it wraps the inner iterator in a
// `StepBy` value and returns it, running NO user code. The constructor's ONE
// panic path is the step itself — std documents `Iterator::step_by` as "Panics if
// the given step is 0" (the `assert!(step != 0)` lives in `StepBy::new`, i.e. AT
// CONSTRUCTION, not in `next`) — so totality is CONDITIONAL on the step argument:
// this recognizer requires a literal constant `>= 1`, and a symbolic or zero step
// FAILS CLOSED (falls through to the absent-callee may-panic arm and KEEPS its
// obligation — a real `step_by(0)` panic is never falsely certified). Recognizing
// the const-step call lets the caller model the RESULT (a `StepBy` value) as a
// fresh OPAQUE `Undef` and continue lowering, INSTEAD of failing closed.
// SOUNDNESS: this asserts NOTHING about the `StepBy` — the `[start, end)` yield
// bound is emitted SEPARATELY, by the (verified-sound)
// `total_iterator_step_by_next` recognizer when `next()` is later called on the
// `StepBy` (whose own gate (d) re-requires the const step). Gated on the receiver
// (arg 0) being an EXCLUSIVE-`Range` iterator (a bare `Range` ADT, or its
// `into_iter`/`rev` identity result), so a user `step_by` on another type
// declines and falls through to fail-closed. Sibling of
// `total_range_iterator_call` (the `into_iter`/`next` arm) — the constructor hop
// that `total_range_iterator_call` does not cover.
fn total_step_by_ctor_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    if !step_by_callee_is_step_by(callee) || args.len() != 2 {
        return Ok(false);
    }
    // `Iterator::step_by` takes a `usize`.  The authenticated trait path and a
    // positive-looking constant are not enough for synthetic/compatibility MIR:
    // a forged signed operand must not inherit the constructor's no-panic
    // summary.  Accept both compatibility spellings of the pinned-target usize.
    let step_ty = operand_trust_type(&args[1], ctx)?;
    if !is_trust_usize_ty(&step_ty) {
        return Ok(false);
    }
    if !args.get(1).and_then(operand_const_nonneg).is_some_and(|step| step >= 1) {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    let adt = match &recv_ty {
        Ty::Ref { inner, .. } => inner.as_ref(),
        Ty::RawPtr { pointee, .. } => pointee.as_ref(),
        other => other,
    };
    Ok(ty_is_exclusive_primitive_range_adt(adt))
}

// `IntoIterator::into_iter(StepBy<..>)` — the for-loop desugar's `into_iter` hop on a
// `StepBy` adapter receiver. The blanket `impl<I: Iterator> IntoIterator for I` makes
// this the IDENTITY (it returns the receiver iterator unchanged), so it is TOTAL — it
// runs NO user code and cannot fail. Its body lives in `core` (so `resolve_call_target`
// would abort the whole function here, in the chain BETWEEN the `step_by` constructor
// — now modeled by `total_step_by_ctor_call` — and the `StepBy::next` yield-bound arm),
// so it must be recognized to let lowering reach `next()`. SOUNDNESS: this asserts
// NOTHING about the `StepBy` — the `[start, end)` yield bound is emitted SEPARATELY by
// `total_iterator_step_by_next` when `next()` is later called; modeling the `into_iter`
// result opaque (a fresh `StepBy` value, no facts) introduces no bound. The `next()`
// receiver-trace (`step_by_trace_local_to_range_aggregate`) hops this `into_iter` Call
// independently of how its VALUE is modeled, so the trace still reaches the Range
// aggregate. Sibling of `total_range_iterator_call` / `total_slice_iterator_call`'s
// `into_iter` arms (which cover Range / slice receivers, NOT a `StepBy` adapter). Gated
// on the receiver typing as a concrete `StepBy` ADT, so a user `into_iter` declines.
fn total_step_by_into_iter_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    if !acc_callee_is_into_iter(callee) {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    Ok(ty_is_step_by_iterator_receiver(&recv_ty))
}

// Extract a non-negative integer constant from a literal operand, if it is one.
// Used to gate `windows`/`chunks` recognition on a provably-non-zero size (the
// only panic in their constructors is `size == 0`); a non-literal size is not
// recognized and the call fails closed.
fn operand_const_nonneg(op: &Operand) -> Option<u128> {
    match op {
        Operand::Constant(ConstValue::Uint(v, _)) => Some(*v),
        Operand::Constant(ConstValue::Int(v)) if *v >= 0 => Some(*v as u128),
        _ => None,
    }
}

// Trust Gap 3 (str/slice RANGE slicing): recognize `&s[a..b]` / `&s[..n]` /
// `&s[n..]` / `&s[..]` (and the `&mut` form), which MIR lowers to a call to
// `<[T] as Index<Range…>>::index` / `<str as Index<Range…>>::index` (callee path
// `core::ops::Index::index` / `…IndexMut::index_mut`, with NO `Self`/`Idx` type
// in the def-path string). Gated STRICTLY on the operand TYPES, never the generic
// callee alone:
//   * receiver (arg 0) is `&[T]` / `&mut [T]` / `&str` — i.e. `Ty::Ref` (or
//     `RawPtr`) to a `Ty::Slice` (`str` is modeled as `Slice<u8>`). This EXCLUDES
//     `Vec`/`HashMap`/`BTreeMap`/user-ADT indexing (those receivers are
//     `Ty::Ref{Adt}`, and `HashMap`/`BTreeMap` `index` runs user `Hash`+`Eq`/`Ord`
//     and must stay refused).
//   * index (arg 1) is a `Range`-family ADT (`Range`/`RangeTo`/`RangeFrom`/
//     `RangeInclusive`/`RangeFull`). This EXCLUDES the single-element
//     `<[T] as Index<usize>>::index` form (its index is a bare `usize`), which the
//     `Projection::Index` + compiler-inserted bounds `Assert` path already covers.
// Recognizing it lets the caller model the RESULT as a fresh opaque slice (`Undef`
// of the slice fat pointer, exactly like the `Windows`/`Chunks` sub-slice results
// in `total_slice_iterator_call`) and continue lowering, INSTEAD of aborting the
// whole-function lowering in `resolve_call_target`. SOUNDNESS: this is NOT a
// totality claim. A str/slice range slice can panic (byte index out of bounds, or
// — for `str` — a non-char-boundary split), and that panic IS an obligation in the
// FORMULA lane: trust-vcgen's `slice_method_panic_body` RangeIndex arm emits a
// `SliceBoundsCheck` VC at this call site — the byte-bounds violation for `[T]`
// slices, and for a MARKED `str` receiver additionally the char-boundary
// fail-close (`Bool(true)` unless every explicit endpoint is boundary-safe: a
// traced `char_indices()` yield or the constant 0). Modeling the result opaque
// therefore neither over-claims (it asserts nothing about the slice's contents,
// length, or safety — the fresh fat pointer's `__slice_len` is unconstrained, so
// no false length fact) NOR drops the panic (the formula-lane VC carries it).
// The function's REAL obligations (this bounds VC, the `a`/`b`/`n` index
// arithmetic overflow, the reachability/unreachable-block checks, etc.) —
// previously POISONED to `Unsupported` because lowering aborted at this call —
// now lower and receive native verdicts.
fn str_slice_range_index_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    // Trust (str char-boundary marker, 3f93cbb5bd): mir-extract's
    // `apply_str_index_marker` appends the trailing turbofish
    // `::<__trust_str_index>` to a `str` `Index::index`/`IndexMut::index_mut`
    // callee — the Self identity that survives str→[u8] erasure, consumed by
    // trust-vcgen's RangeIndex char-boundary fail-close. Strip it before the
    // trait-path match so a marked str range-slice keeps THIS recognition (its
    // panic is the formula lane's `SliceBoundsCheck`, see the banner above)
    // instead of regressing to the fail-soft absent-callee arm, whose blanket
    // `Assert(false)` may-panic marker pins the whole-function panic-freedom
    // obligation UNPROVABLE for the provably-safe `char_indices()` idiom. The
    // operand TYPE gates below still decide recognition — fail-closed.
    let callee = callee.strip_suffix("::<__trust_str_index>").unwrap_or(callee);
    if !(is_canonical_trait_method(callee, &["core::ops::Index", "std::ops::Index"], "::index")
        || is_canonical_trait_method(
            callee,
            &["core::ops::IndexMut", "std::ops::IndexMut"],
            "::index_mut",
        ))
    {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let Some(index) = args.get(1) else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    if !ty_is_ref_to_slice(&recv_ty) {
        return Ok(false);
    }
    let index_ty = operand_trust_type(index, ctx)?;
    Ok(ty_is_range_family(&index_ty))
}

// Trust (#7c owned-Vec SCALAR index): recognize `v[i]` on an owned `Vec` — MIR
// lowers it to `<Vec<T> as Index<usize>>::index(&v, i)` (callee `core::ops::
// index::Index::index`, no Self/Idx in the def-path). This is the SCALAR sibling
// of `str_slice_range_index_call`:
//   * receiver (arg 0) is `&Vec` / `&mut Vec` / owned `Vec` — a `Ty::Adt` whose
//     name tail is `Vec` (or a ref/raw-ptr to one). This EXCLUDES `&[T]` (handled
//     by the compiler-inserted `Projection::Index` bounds-`Assert` path) and
//     `HashMap`/`BTreeMap`/user-ADT `index` (whose panic semantics differ — a
//     `HashMap` "key not present" is not a length OOB, and its `index` runs user
//     `Hash`+`Eq`/`Ord`, so it must stay refused / fail-closed).
//   * index (arg 1) is a SCALAR unsigned integer (`usize`), NOT a range ADT.
// Recognizing it lets the caller model the RESULT opaque (a fresh `Undef` element
// pointer) and continue, INSTEAD of aborting the whole-function lowering in
// `resolve_call_target` (which poisons EVERY obligation in the function to
// Unsupported — the pre-#7c behavior for any `Vec`-scalar-indexing function).
//
// SOUNDNESS: this is NOT a totality claim and it does NOT drop the OOB obligation.
// The bounds check IS emitted — by the FORMULA lane (trust-vcgen `slice_method_
// panic_body`'s `RangeIndex` arm now emits a `SliceBoundsCheck` VC `Ge(i,
// coll_len)` for exactly this scalar-Vec-index shape). Under `-full` that VC flows
// through the native bundle at the index site: with this opaque model leaving it
// WITHOUT a native certificate it resolves to `Unknown`, and the location-matched
// formula VC is then re-solved (interval + in-process ay) — a SAT `Ge(i, len)`
// REFUTES an unguarded `v[2]` (fatal), a dominating `if i < v.len()` guard
// DISCHARGES it. So modeling the result opaque here neither over-claims nor drops
// a hole — it un-poisons the function so its REAL obligations (this bounds VC, the
// index arithmetic, reachability) get native verdicts. Mirror of the range arm.
fn vec_scalar_index_call(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    if !(is_canonical_trait_method(callee, &["core::ops::Index", "std::ops::Index"], "::index")
        || is_canonical_trait_method(
            callee,
            &["core::ops::IndexMut", "std::ops::IndexMut"],
            "::index_mut",
        ))
    {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    let Some(index) = args.get(1) else { return Ok(false) };
    let recv_ty = operand_trust_type(receiver, ctx)?;
    if !ty_is_owned_vec_container(&recv_ty) {
        return Ok(false);
    }
    let index_ty = operand_trust_type(index, ctx)?;
    Ok(matches!(index_ty, Ty::Int { signed: false, .. }))
}

// `Vec<T>` / `&Vec<T>` / `&mut Vec<T>` / `*Vec<T>` — an owned deref-to-slice
// container (or a reference/raw pointer to one) whose ADT name tail is `Vec`.
// EXACT-monomorphized on the receiver ADT name (byte-faithful to trust-vcgen's
// `is_owned_slice_container_name`), so a user `struct MyVec` (name tail `MyVec`)
// does NOT match — it never inherits `Vec` index semantics. `String`/`VecDeque`
// are deliberately excluded (deferred: `String` carries an unmodeled char-boundary
// panic on RANGE index; scalar `String` indexing does not exist — `String: !Index
// <usize>` — and `VecDeque`'s scalar index needs a separate model).
fn ty_is_owned_vec_container(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    let Ty::Adt { name, .. } = adt else { return false };
    let base = name.split('<').next().unwrap_or(name);
    matches!(base, "alloc::vec::Vec" | "std::vec::Vec")
}

// `&[T]` / `&mut [T]` / `*[T]` / `&str` (modeled `&Slice<u8>`) — a reference (or raw
// pointer) whose pointee is a `Ty::Slice`. A bare unsized `Ty::Slice` is also
// accepted (the receiver place can carry the slice type directly). Used to gate
// `str_slice_range_index_call` to genuine slice/str receivers, excluding `Vec`/
// `HashMap`/user-ADT `Index` receivers (`Ty::Ref{Adt}`).
fn ty_is_ref_to_slice(ty: &Ty) -> bool {
    match ty {
        Ty::Slice { .. } => true,
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => {
            matches!(inner.as_ref(), Ty::Slice { .. })
        }
        _ => false,
    }
}

// A `core::ops::range::{Range,RangeTo,RangeFrom,RangeInclusive,RangeFull}` ADT —
// the index argument of a RANGE slice. Matched on the final path segment so the
// `core::`/`std::` and `::range::` spelling variants all hit; the single-element
// `usize` index (a non-ADT) is correctly excluded.
fn ty_is_range_family(ty: &Ty) -> bool {
    let Ty::Adt { name, .. } = ty else { return false };
    let base = strip_generics(name);
    let base = strip_trust_crate_disambiguator(&base);
    if !adt_path_is_std_anchored(name)
        || !(base.starts_with("core::ops::") || base.starts_with("std::ops::"))
    {
        return false;
    }
    let last = base.rsplit("::").next().unwrap_or(base);
    let last = last.split('<').next().unwrap_or(last).trim();
    matches!(last, "Range" | "RangeTo" | "RangeFrom" | "RangeInclusive" | "RangeFull")
}

// `[T]` / `&[T]` / `&mut [T]` / `[T; N]` / `&[T; N]` — the receivers whose
// `IntoIterator` impl is the std slice/array iterator (total, runs no user code).
fn ty_is_slice_or_array_iterable(ty: &Ty) -> bool {
    match ty {
        Ty::Slice { .. } | Ty::Array { .. } => true,
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => {
            matches!(inner.as_ref(), Ty::Slice { .. } | Ty::Array { .. })
        }
        _ => false,
    }
}

/// Bucket I — a std sequence/map CONTAINER whose `IntoIterator::into_iter` walks the
/// ALREADY-BUILT structure and runs NO user `Ord`/`Hash`/`Clone`: `Vec`/`VecDeque`
/// (yield `&T`/owned `T`), `BTreeMap`/`HashMap` (yield `(&K,&V)`/owned `(K,V)`), and
/// their set twins. The tree/table was built by earlier inserts; `into_iter` only
/// produces a cursor — the `K::cmp`/`K::hash` ran at insert time, so iteration is
/// panic-free for ANY element type. Gated on a std/alloc/core origin (a like-named
/// user container declines) AND the concrete container path, so a user `IntoIterator`
/// impl (whose `into_iter` can run arbitrary code) is NOT recognized. Matched behind
/// an optional `&`/`&mut` (the `for (k,v) in &map` borrow form). Also a sound `zip`
/// operand for the same reason.
fn ty_is_std_container_iterable(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    let Ty::Adt { name, .. } = adt else { return false };
    if !(name.starts_with("std::") || name.starts_with("alloc::") || name.starts_with("core::")) {
        return false;
    }
    const CONTAINERS: &[&str] = &[
        "::vec::Vec",
        "::collections::VecDeque",
        "::collections::BTreeMap",
        "::collections::HashMap",
        "::collections::BTreeSet",
        "::collections::HashSet",
    ];
    CONTAINERS.iter().any(|p| name.contains(p))
}

// A TOTAL std-iterator receiver: a `slice::Iter` / `slice::IterMut` /
// `array::IntoIter` base, a std MAP iterator (`btree_map`/`hash_map`
// `Iter`/`IterMut`/`Keys`/`Values`/`ValuesMut`), or a chain of TOTAL adapters
// (`Rev`/`Copied`/`Take`/`Skip`/`Enumerate`/`Peekable`) over such a base. Its `next`
// runs no user code and cannot panic, so it is the receiver of a total
// `Iterator::next` (and a valid `into_iter` identity receiver). Matched by the ADT's
// final two path segments — NOT the generic callee — so user iterators and
// CLOSURE/CLONE adapters (`Map`/`Filter`/`TakeWhile`/`Cloned`/…, whose `next` runs
// arbitrary code that may panic) are excluded. The two-segment match avoids a false
// hit on an unrelated type whose module merely ends in `slice`/`btree_map`/`hash_map`.
// Total adapters are recursive: their inner iterator field must itself be a total std
// iterator, so `Rev<Copied<slice::Iter>>` / `Rev<btree_map::Iter>` are accepted but
// `Rev<Map<…>>` is not.
//
// Build-3 — the std MAP iterators are new. `BTreeMap`/`HashMap`
// `iter`/`keys`/`values` (and `&map` `into_iter`) build a cursor over the ALREADY-BUILT
// tree/table; their `next` walks stored links and YIELDS references (or `(&K, &V)`
// pairs) — it runs NO `K::cmp`/`K::hash` (those ran at INSERT time) and NO user code,
// so it is unconditionally panic-free for ANY key/value type. ny-cert reaches these via
// `for (var, coeff) in &self.coeffs` / `m.iter().map(..)` / `.keys()` over
// `BTreeMap<String, Rat>` (selfcheck.rs / schema.rs). CLOSURE adapters (`Filter`/
// `TakeWhile`) are STILL excluded even over a std map base: their `next` drives a user
// predicate that can panic (kept fail-closed, matching the existing `Map`/`Filter`
// stance — the predicate is a separately bundled body with its own obligation).
/// Whether an unambiguous ADT def-path names a standard-library type
/// (`core::`/`alloc::`/`std::`), tolerating generic-argument tails but rejecting
/// cross-crate disambiguation prefixes. THE load-bearing soundness anchor for the iterator
/// receiver-type gates: without it, a dependency crate's `dep::slice::Iter`
/// (whose body is ABSENT from the per-crate verify bundle, so its `next`'s panics
/// are verified nowhere) matches on its last-two path segments `("slice","Iter")`
/// and gets its call modeled TOTAL — a false proof of panic-freedom (round-14
/// review). A genuine std iterator's ADT path always starts with a std crate
/// after the optional disambiguation prefix; a user/dependency type never does.
fn adt_path_is_std_anchored(name: &str) -> bool {
    let stripped = strip_generics(name);
    !stripped.starts_with("__trust_crate@")
        && (stripped.starts_with("core::")
            || stripped.starts_with("alloc::")
            || stripped.starts_with("std::"))
}

/// A `Range`/`RangeInclusive` whose element is a std INTEGER — its `next`/`into_iter`
/// drives std's integer `Step`, which is TOTAL for the BOUNDED ranges: each increment is
/// guarded by the range's own `start < end` invariant (`RangeInclusive` by its
/// `exhausted` flag), so `start + 1` cannot overflow past the element max, and
/// exhaustion returns `None`. No user code, no panic. A non-integer / user-`Step`
/// element (a `char` range is fine but excluded here for simplicity; a user newtype
/// with a hand-written `Step` could panic) fails the gate and keeps its obligation.
/// Fields are `{start, end[, exhausted: bool]}`, all int except the `RangeInclusive`
/// exhausted flag. `RangeFrom` is DELIBERATELY EXCLUDED (fail-closed): it has no `end`
/// bound, so its `next` runs an UNGUARDED `Step::forward(start, 1)` whose overflow is a
/// real debug-profile panic (`0u8..` reaching 255) — the same overflow-profile reason
/// `total_range_iterator_call` restricts to the exclusive `Range`.
fn ty_is_integer_range_iter(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    let Ty::Adt { name, fields, .. } = adt else { return false };
    // Round-14 discipline (matches every other receiver-type gate): the last-segment
    // match below is a NAME HEURISTIC — anchor it to std origin or a dependency
    // `dep::ops::Range` with a hand-written panicking `Iterator` impl is falsely
    // certified total (see the `adt_path_is_std_anchored` doc + tests).
    if !adt_path_is_std_anchored(name) {
        return false;
    }
    let last = name.rsplit("::").next().unwrap_or(name);
    if !matches!(last, "Range" | "RangeInclusive") {
        return false;
    }
    !fields.is_empty()
        && fields.iter().any(|(_, fty)| matches!(fty, Ty::Int { .. }))
        && fields.iter().all(|(_, fty)| matches!(fty, Ty::Int { .. } | Ty::Bool))
}

fn ty_is_slice_iterator_receiver(ty: &Ty) -> bool {
    let adt = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    let Ty::Adt { name, fields, .. } = adt else { return false };
    // Round-14: the last-2-segment match below is a NAME HEURISTIC; anchor it to
    // std origin or a dependency `dep::slice::Iter` is falsely certified total.
    if !adt_path_is_std_anchored(name) {
        return false;
    }
    let base = strip_generics(name);
    let base = strip_trust_crate_disambiguator(&base);
    let segs: Vec<&str> = base.split("::").collect();
    let n = segs.len();
    if n < 2 {
        return false;
    }
    // PATH-SPELLING ROBUSTNESS (the old `last2` heuristic is not enough on its own).
    //
    // These gates were written when `def_path_str` rendered std iterators at their
    // PUBLIC re-export path (`core::slice::Iter`, `core::iter::Rev`), so the last
    // two segments were `("slice","Iter")` / `("iter","Rev")`. The renderer now
    // produces the PRIVATE DEFINITION path:
    //     core::slice::iter::Iter            -> last2 ("iter","Iter")
    //     core::iter::adapters::rev::Rev     -> last2 ("rev","Rev")
    // so EVERY arm below silently stopped matching and the whole slice/array/range
    // iterator family fell through to the fail-closed absent-callee arm. Measured
    // casualty: `<core::slice::iter::Iter<'_, i32> as Iterator>::next` minting a
    // `[trust-absent-callee-assumption]` row for the canonical `for &x in s` loop.
    //
    // `names_any` matches the TYPE on the last segment and requires the anchoring
    // MODULE to appear anywhere earlier in the path, so both spellings match.
    //
    // SOUNDNESS is unchanged: `adt_path_is_std_anchored` has ALREADY pinned the
    // path to a `core::`/`alloc::`/`std::` origin, so a dependency's
    // `dep::slice::Iter` is rejected before reaching here (the round-14 false
    // proof). Widening WITHIN an authenticated std path only makes the module
    // anchor position-independent; it never admits a foreign type.
    let names_any = |pairs: &[(&str, &str)]| -> bool {
        pairs.iter().any(|(module, ty_name)| {
            segs[n - 1] == *ty_name && segs[..n - 1].contains(module)
        })
    };
    // Slice/array iterator base — incl. the sub-slice iterators `Windows`/`Chunks`
    // (`<[T]>::windows`/`::chunks`). Their `next` is unconditionally total (runs no
    // user code; the only panic is the constructor's `size != 0` assert, gated in
    // `total_slice_iterator_call`). They yield `&[T]` sub-slices.
    if names_any(&[
        ("slice", "Iter"),
        ("slice", "IterMut"),
        ("array", "IntoIter"),
        ("slice", "Windows"),
        ("slice", "Chunks"),
        ("slice", "ChunksMut"),
        ("slice", "ChunksExact"),
        ("slice", "ChunksExactMut"),
        ("slice", "RChunks"),
        ("slice", "RChunksMut"),
        ("slice", "RChunksExact"),
        ("slice", "RChunksExactMut"),
            // Build-2 — `Vec<T>::into_iter()` (`for x in vec {..}`) yields the owning
            // `IntoIter`. Its `next` MOVES an element out (`ptr::read`) — no user code,
            // no panic — so it is total regardless of `T`, exactly like the already-
            // listed `array::IntoIter`. This fork spells re-exported iterators at their
            // public path (`std::array::IntoIter`, so `std::vec::IntoIter`); the
            // `("into_iter", …)` twin covers the private-module spelling.
        ("vec", "IntoIter"),
        ("into_iter", "IntoIter"),
            // Build-3 — std MAP iterators (keyless traversal; `next` runs no user
            // code, panic-free for any K/V). `def_path_str` spells them at the
            // re-exported `std::collections::{btree_map,hash_map}::<T>` path — last2
            // `("btree_map", T)` / `("hash_map", T)`. The `btree_map`/`hash_map`
            // segment keeps a like-named user type out.
        ("btree_map", "Iter"),
        ("btree_map", "IterMut"),
        ("btree_map", "Keys"),
        ("btree_map", "Values"),
        ("btree_map", "ValuesMut"),
        ("btree_map", "Range"),
        ("hash_map", "Iter"),
        ("hash_map", "IterMut"),
        ("hash_map", "Keys"),
        ("hash_map", "Values"),
        ("hash_map", "ValuesMut"),
    ]) {
        return true;
    }
    // Build-5 — a CONCRETE std iterator whose `next` runs NO USER code and is panic-free,
    // though (unlike the slice/array/map bases above) it is NOT slice-backed:
    // `std::fs::ReadDir` (`for entry in std::fs::read_dir(..)?`, cite_check.rs). Its `next`
    // performs a directory-read syscall and yields `Option<io::Result<DirEntry>>` — an I/O
    // failure becomes `Some(Err(..))`, NEVER a panic — and it drives no user closure/`Ord`/
    // `Clone`. Gated on the EXACT `("fs", "ReadDir")` std path (the `fs` segment keeps a
    // like-named user iterator out), so any other receiver declines and falls through to
    // the fail-closed refusal. Same trusted-std-body TCB tier as the sort/HashMap-accessor/
    // serde entries elsewhere in this file; the modeled result is an opaque `Undef`, so
    // nothing downstream is provable from the yielded entry.
    if names_any(&[("fs", "ReadDir")]) {
        return true;
    }
    // Round-3 — `Range<int>` as a TOTAL iterator base (`std::ops::Range`, fields
    // `start`/`end`, both primitive ints after lowering — `char` lowers to `Int`).
    // Its `next` is `if start < end { start.forward_unchecked(1) }` — the
    // in-bounds guard makes the step non-overflowing, no user code runs, no panic
    // path exists; `next_back` is the mirror, so the `Rev<Range<usize>>` of a
    // reversed elimination loop (`for c in (0..n).rev()`, batch-44's
    // `exact::solve_system`) recurses through the `("iter", "Rev")` adapter arm
    // into this base. `Range<UserStep>` has ADT fields and FAILS CLOSED; the
    // `ops` segment keeps a like-named user type out. (`RangeInclusive` carries
    // an extra `exhausted` bool — covered by its own Round-5 arm just below.)
    if names_any(&[("ops", "Range")])
        && !fields.is_empty()
        && fields.iter().all(|(_, fty)| matches!(fty, Ty::Int { .. }))
    {
        return true;
    }
    // Round-5 — `RangeInclusive<int>` joins its exclusive twin above (batch-49's
    // residual: `exact::solve_system`'s `for c in col..=n` elimination loops).
    // The extracted ADT carries `start`/`end` primitive ints PLUS the `exhausted`
    // Bool (the reason the all-`Int` Range gate above cannot cover it). Its `next`
    // is `if exhausted { None } else if start < end { forward step — in-bounds, so
    // non-overflowing } else { exhausted = true; yield start }`: for the primitive
    // `Step` impls no user code runs and no panic path exists, same as `Range`.
    // The field gate (every field `Int`/`Bool`, at least one `Int`) keeps
    // `RangeInclusive<UserStep>` — whose ADT-typed bounds drive a user `Step` that
    // may panic — FAIL-CLOSED, exactly like `Range<UserStep>`; the `ops` segment
    // keeps a like-named user type out.
    if names_any(&[("ops", "RangeInclusive")])
        && fields.iter().any(|(_, fty)| matches!(fty, Ty::Int { .. }))
        && fields.iter().all(|(_, fty)| matches!(fty, Ty::Int { .. } | Ty::Bool))
    {
        return true;
    }
    // Total adapter — recurse into its inner iterator field. Only adapters that run
    // NO user code on elements are listed; `Cloned`/`Map`/`Filter`/… are excluded.
    let total_adapter = names_any(&[
        ("iter", "Rev"),
        ("iter", "Copied"),
        ("iter", "Take"),
        ("iter", "Skip"),
        ("iter", "Enumerate"),
        ("iter", "Peekable"),
    ]);
    if total_adapter {
        // Unary adapters have ONE inner-iterator field (plus possibly a non-iterator
        // field like Enumerate's count) — `any` finds the slice-backed inner.
        return fields.iter().any(|(_, fty)| ty_is_slice_iterator_receiver(fty));
    }
    // `Zip<A, B>` is the BINARY adapter: `next` pulls from BOTH inner iterators, so
    // it is total only when EVERY inner ITERATOR is slice-backed. `Zip` also carries
    // SCALAR state (`index`/`len`/`a_len` for the TrustedRandomAccess specialization),
    // so check every ITERATOR-SHAPED field (an ADT, or a ref to one) is slice-backed
    // and ignore the scalar state — using `all` (not `any`) on the iterator fields is
    // the soundness gate: a single non-slice inner could panic.
    if names_any(&[("iter", "Zip")]) {
        let has_slice_inner = fields.iter().any(|(_, fty)| ty_is_slice_iterator_receiver(fty));
        let no_unmodeled_inner = fields
            .iter()
            .all(|(_, fty)| !ty_is_iterator_shaped(fty) || ty_is_slice_iterator_receiver(fty));
        return has_slice_inner && no_unmodeled_inner;
    }
    false
}

// An ITERATOR-SHAPED field type — an ADT (or a ref/ptr to one). Used to tell a
// `Zip`'s two inner iterators (ADTs) from its scalar state fields (`usize`), so the
// slice-backed soundness gate applies only to the iterators.
fn ty_is_iterator_shaped(ty: &Ty) -> bool {
    let inner = match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        other => other,
    };
    matches!(inner, Ty::Adt { .. })
}

// RETIRED LANE (BROAD TOTAL-SUMMARY SURFACE) — record only, no implementation.
// The heuristic below was fitted to a corpus, not derived from resolved callee
// identity, so it could not be production proof authority. The closed structural
// list that replaced it is `total_no_panic_call_summary`, further down.
//
// Trust Gap 3: a curated allowlist of **total** (cannot-panic) core/std functions
// whose bodies live outside the TrustIr module. Modeling the call result as a
// fresh unconstrained value (`Inst::Undef` → a fresh symbolic var in the trust-mc
// consumer) is a sound over-approximation: nothing is assumed about the result,
// so any obligation that *depends* on the result stays `unknown` (never falsely
// proved), and omitting the call's panic obligation is sound *only* because these
// functions cannot panic. This lets a caller function lower (and its own
// arithmetic/bounds obligations verify) without the callee's MIR.
//
// DELIBERATELY EXCLUDED (not unconditionally total): closure/pattern-taking
// (`Option::map`, `str::find`/`split`/`strip_*` — the pattern may be a panicking
// closure), `to_string` (dispatches to a user `Display::fmt`),
// hand-implementable traits (`Default::default`, `PartialEq::eq` — a user impl
// may panic), and control-flow desugars (`Try::branch`). Those need
// closure-aware / postcondition modeling later. NOTE: pure allocation is NOT a
// disqualifier — OOM is excluded from the panic model — so `Box::new_uninit`
// (raw uninit alloc, no user code) IS total; `to_lowercase`/`replace`
// (allocating but otherwise total) are likewise total.

/// Closed string-only summary surface. Every entry names a concrete inherent or
/// free library operation whose implementation cannot dispatch a user trait,
/// callback, clone, drop, hasher, ordering implementation, formatter, or generic
/// conversion. Broad method families and trait names are deliberately absent —
/// they belong to the retired heuristic above; type-dependent cases use dedicated
/// typed gates.
pub(crate) fn total_no_panic_call_summary(callee: &str) -> bool {
    // Compiler-authenticated primitive comparisons use a synthetic, exact wire
    // identity that cannot be a Rust def path. The extractor mints it only after
    // authenticating the resolved core impl, diagnostic trait, method, and
    // primitive Self type. Prefix/suffix lookalikes still fail the std-root gate.
    if callee == trust_types::total_call_summaries::TRUST_TOTAL_CLONE_SENTINEL {
        return true;
    }
    let normalized = strip_generics(callee);
    if !has_trusted_std_root(&normalized) {
        return false;
    }
    const EXACT_TOTAL: &[&str] = &[
        // Pure language/library structure.
        "core::mem::size_of",
        "core::mem::align_of",
        "core::mem::size_of_val",
        "core::mem::align_of_val",
        "core::mem::swap",
        "core::mem::replace",
        "core::mem::forget",
        "core::any::type_name",
        "core::hint::must_use",
        // Concrete sequence/string operations; no element Clone/Drop/callback.
        "alloc::vec::Vec::new",
        "alloc::vec::Vec::len",
        "alloc::vec::Vec::is_empty",
        "alloc::vec::Vec::capacity",
        "alloc::vec::Vec::pop",
        "alloc::vec::Vec::as_slice",
        "alloc::vec::Vec::as_mut_slice",
        "alloc::string::String::new",
        "alloc::string::String::len",
        "alloc::string::String::is_empty",
        "alloc::string::String::as_bytes",
        "alloc::string::String::as_str",
        "alloc::string::String::clear",
        "alloc::string::String::pop",
        "alloc::string::String::from_utf8_unchecked",
        // Concrete str/slice structural operations with no Pattern callback.
        "core::str::len",
        "core::str::is_empty",
        "core::str::as_bytes",
        "core::str::chars",
        "core::str::char_indices",
        "core::str::bytes",
        "core::str::encode_utf16",
        "core::str::lines",
        "core::str::split_whitespace",
        "core::slice::len",
        "core::slice::is_empty",
        "core::slice::iter",
        "core::slice::iter_mut",
        "core::slice::first",
        "core::slice::last",
        "core::slice::first_mut",
        "core::slice::last_mut",
        "core::slice::get",
        "core::slice::get_mut",
        // Structural enum/container accessors. The consumed value is returned or
        // bit-copied; no hidden payload is dropped by these calls.
        "core::option::Option::is_none",
        "core::option::Option::is_some",
        "core::option::Option::as_ref",
        "core::option::Option::as_mut",
        "core::option::Option::copied",
        "core::option::Option::take",
        "core::option::Option::replace",
        "core::result::Result::is_ok",
        "core::result::Result::is_err",
        "core::result::Result::as_ref",
        // Exact no-user-code constructors/accessors.
        "core::mem::maybe_uninit::MaybeUninit::new",
        "core::ops::range::RangeInclusive::new",
        "alloc::boxed::Box::new",
        "alloc::boxed::Box::new_uninit",
        "alloc::boxed::box_new_uninit",
        "alloc::slice::into_vec",
        "std::process::id",
        "std::collections::BTreeMap::new",
        "std::collections::BTreeMap::len",
        "std::collections::BTreeMap::is_empty",
        "std::collections::BTreeMap::iter",
        "std::collections::BTreeMap::keys",
        "std::collections::BTreeMap::values",
        "std::collections::BTreeMap::values_mut",
        "std::collections::HashMap::new",
        "std::collections::HashMap::len",
        "std::collections::HashMap::is_empty",
        "std::collections::HashMap::iter",
        "std::collections::HashMap::keys",
        "std::collections::HashMap::values",
        "std::collections::HashMap::values_mut",
        "core::cell::RefCell::new",
        "core::cell::RefCell::try_borrow",
        "core::cell::RefCell::try_borrow_mut",
        "std::sync::Mutex::new",
        "std::sync::RwLock::new",
        "std::path::Path::as_os_str",
        "std::path::Path::file_name",
        "std::path::Path::file_stem",
        "std::path::Path::extension",
        "std::path::Path::parent",
        "std::path::Path::display",
        "std::ffi::OsStr::to_str",
    ];
    if EXACT_TOTAL.contains(&normalized.as_str()) {
        return true;
    }

    // Compiler-only formatting value packers merely store pointers/slices; they
    // do not invoke the formatter pointer. Direct Formatter/Debug/Display calls
    // are intentionally absent.
    normalized.starts_with("core::fmt::")
        && matches!(
            normalized.rsplit("::").next(),
            Some(
                "new_display"
                    | "new_debug"
                    | "new_debug_noop"
                    | "new_octal"
                    | "new_lower_hex"
                    | "new_upper_hex"
                    | "new_pointer"
                    | "new_binary"
                    | "new_lower_exp"
                    | "new_upper_exp"
                    | "new_v1"
                    | "new_const"
                    | "new_v1_formatted"
            )
        )
        && (normalized.contains("::Argument::") || normalized.contains("::Arguments::"))
}

// RETIRED LANE (F5 ABSENT-CALLEE ALLOWLIST) — record only, no implementation.
// It mixed true inherent-library facts with overridable trait/callback/Clone/
// Hash/Ord/serde assumptions, so it could not be a production trust boundary.
// The strict subset that replaced it follows.
//
// F5 (task #41): a CLOSED, EXPLICIT allowlist of std / well-known-crate callees
// that are UNCONDITIONALLY panic-free by their documented contract, consulted at
// the absent-callee emission site (the `Terminator::Call` FAIL-SOFT arm). When a
// call's target body is NOT in the lowered bundle, the bridge conservatively
// assumes it MAY panic and raises a `trust-absent-callee-assumption`
// `PanicFreedom` obligation that stays UNKNOWN in the strict lane. For a callee on
// THIS list that assumption is spurious: these are standard-library / trusted-crate
// functions whose bodies live outside the verification bundle but are part of the
// TRUSTED COMPUTING BASE — the exact same boundary under which the verifier already
// hard-skips `core`/`alloc`/`std` ("all proofs are conditional on its
// correctness"). So the caller models such a call like a TOTAL summary (fresh
// `Undef` result, NO in-body may-panic marker, NO obligation) instead of the
// may-panic encoding, discharging the spurious obligation.
//
// SOUNDNESS. The list is CLOSED and membership is REQUIRED: a callee we cannot
// positively identify keeps its panic obligation (fail-closed — never a false
// discharge). Every entry is unconditionally panic-free by contract; any panic it
// could SURFACE is either separately modeled or deliberately excluded:
//   * Comparisons (`PartialOrd::{le,lt,ge,gt}`, `Ord::cmp`, `PartialEq::{eq,ne}`):
//     total for the primitive/derived impls that reach here as absent callees.
//   * Iterator ADAPTERS (`map`/`filter`/`take_while`/`cloned`/`copied`,
//     `IntoIterator::into_iter`, `DoubleEndedIterator::next_back`): the adapter
//     itself only builds/advances the adapter struct and CANNOT panic; any closure
//     or `Clone` it stores runs LATER inside a SEPARATE consume call whose own MIR
//     body is analyzed independently.
//   * Non-panicking `Option`/`Result` combinators + `bool::{then,then_some}` +
//     `FromResidual::from_residual` (the `?` desugar): pure control-flow / value
//     re-wrapping; any user closure they run is a separately-verified body.
//   * `ToOwned::to_owned` / slice `to_vec`: allocation may ABORT, but OOM is NOT
//     the modeled panic (the codebase excludes alloc-abort from the panic model,
//     see `total_no_panic_call_summary`).
//   * `thiserror` glue, `BTreeMap::{new,keys}`, `LocalKey::with` (non-reentrant
//     thread-local arena access), `num_traits::Zero::is_zero`,
//     `num_rational::Ratio::{denom,numer}`: trusted-crate accessors, panic-free.
//
// DELIBERATELY EXCLUDED (fail-closed — keep the obligation): ANY arithmetic op
// (`ops::{Add,Sub,Mul,Neg,Shl,Shr,Div,Rem}::*` — overflow-panic is SEPARATELY
// modeled by arithmetic obligations; allowlisting them could MASK a real overflow
// panic), `Ratio::new` (panics on a zero denominator — CONDITIONAL),
// `Result::{unwrap,expect}`, `Option::{unwrap,expect}`, `[]` `Index`,
// `RefCell::{borrow,borrow_mut}` (double-borrow panic — CONDITIONAL; the TOTAL
// `RefCell::{try_borrow,try_borrow_mut}` which return `Result` ARE allowlisted),
// slicing, and everything the list did not name.
//
// Entries were stored ALREADY generic-normalized (matched against
// `strip_generics(callee)`), so a monomorphized spelling
// (`std::cmp::PartialOrd::<i32>::le`, `std::slice::<impl [T]>::to_vec`) matched the
// same stable `a::b::c` form.

/// Closed string-only subset whose totality is independent of generic trait
/// implementations, callbacks, `Clone`, `Drop`, hashing, ordering, and corpus
/// assumptions. Anything requiring receiver/argument identity belongs behind
/// a typed gate at the call site and fails closed here.
/// Primitive-int TOTAL arithmetic method (`checked_/saturating_/overflowing_
/// {add,sub,mul}` + `checked_neg`/`checked_abs`/`saturating_neg`/
/// `saturating_abs`) — the non-division subset whose std contract has NO panic
/// path (overflow is reported in the return VALUE). Type-gated: the normalized
/// path must be the `core::num::{method}`/`std::num::{method}` primitive-impl
/// spelling (the same discipline as `is_exact_primitive_num_method`) and EVERY
/// argument must be a primitive int — a user method that merely shares the
/// name declines on the path gate, and an exotic receiver declines on the
/// type gate. Fail-closed on every other shape.
fn is_primitive_int_total_arith_absent_callee(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let normalized = strip_generics(callee);
    let Some(method) = normalized.rsplit("::").next() else { return Ok(false) };
    if !matches!(
        method,
        "checked_add"
            | "checked_sub"
            | "checked_mul"
            | "checked_neg"
            | "checked_abs"
            | "saturating_add"
            | "saturating_sub"
            | "saturating_mul"
            | "saturating_neg"
            | "saturating_abs"
            | "overflowing_add"
            | "overflowing_sub"
            | "overflowing_mul"
            // `wrapping_{add,sub,mul}` are ALSO total (defined modular
            // semantics, no panic path). Where the precise
            // `core_int_arith_intrinsic` BinOp model fires, the call never
            // reaches the absent-callee arm and keeps its exact semantics;
            // this fallback covers the call SHAPES that model misses (the
            // measured casualty: `*x = x.wrapping_add(1)` through a slice
            // iterator's `&mut` yield). Result stays opaque — sound, any
            // dependent obligation fails closed.
            | "wrapping_add"
            | "wrapping_sub"
            | "wrapping_mul"
            | "wrapping_neg"
    ) {
        return Ok(false);
    }
    if !is_exact_primitive_num_method(&normalized, method) {
        return Ok(false);
    }
    if args.is_empty() {
        return Ok(false);
    }
    for arg in args {
        if !matches!(operand_trust_type(arg, ctx)?, Ty::Int { .. }) {
            return Ok(false);
        }
    }
    Ok(true)
}

/// `rem_euclid`/`checked_rem_euclid`-family PRIMITIVE call whose RHS is a
/// NONZERO integer literal: std documents the panic as `rhs == 0` (plus the
/// `MIN % -1` overflow case for `rem_euclid` on signed — EXCLUDED by requiring
/// rhs to also not be `-1`; `checked_*` returns None instead and has no panic
/// at all, but is gated identically for uniformity). A symbolic or zero/-1
/// literal RHS declines and keeps the honest may-panic row.
fn is_const_nonzero_rem_euclid_absent_callee(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let normalized = strip_generics(callee);
    let Some(method) = normalized.rsplit("::").next() else { return Ok(false) };
    if !matches!(method, "rem_euclid" | "checked_rem_euclid" | "div_euclid" | "checked_div_euclid")
    {
        return Ok(false);
    }
    if !is_exact_primitive_num_method(&normalized, method) {
        return Ok(false);
    }
    let [lhs, rhs] = args else { return Ok(false) };
    if !matches!(operand_trust_type(lhs, ctx)?, Ty::Int { .. }) {
        return Ok(false);
    }
    let Some(rhs) = acc_operand_const_int(rhs) else { return Ok(false) };
    Ok(rhs != 0 && rhs != -1)
}

/// `Ord::clamp` whose BOTH bounds are integer CONSTANTS with `lo <= hi` — the
/// one shape where std's documented panic (`min > max`) is refuted at the call
/// site. The callee must be the std `Ord::clamp` (crate-anchored via
/// `native_ord_method`'s own gate is caller-side; here the qualified/generic
/// std spelling is required through `callee_is_trait_method_in`), the receiver
/// a primitive int, and both bound operands integer literals in order.
fn is_const_bounded_ord_clamp_absent_callee(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    if !callee_is_trait_method_in(callee, NS_ORD, "Ord", "clamp") {
        return Ok(false);
    }
    let [recv, lo, hi] = args else { return Ok(false) };
    if !matches!(operand_trust_type(recv, ctx)?, Ty::Int { .. }) {
        return Ok(false);
    }
    let (Some(lo), Some(hi)) = (acc_operand_const_int(lo), acc_operand_const_int(hi)) else {
        return Ok(false);
    };
    Ok(lo <= hi)
}

pub(crate) fn is_trusted_panic_free_absent_callee(callee: &str) -> bool {
    // Native thread-local LAZY-INIT machinery — the INNER half of the TLS access
    // performed by the OUTER `LocalKey::with` call. The `thread_local!` macro
    // expands its `LocalKey`'s init closure (for `ARENA`, the proof units
    // `rational::ARENA::{constant#0}::{closure#0,1}`) to a SINGLE absent call
    // `__RUST_STD_INTERNAL_VAL.get_or_init(__rust_std_internal_init,
    // __rust_std_internal_init_fn)` (std `sys/thread_local/native/mod.rs`), so that
    // closure's ONLY absent call is this `get_or_init`. Its body (std
    // `native/lazy.rs`) is a pure `Cell`/`UnsafeCell`/`ptr`/`MaybeUninit` state
    // machine — NO `unwrap`/`expect`/`panic!`/index/alloc — and its one
    // `unreachable!()` (the recursive-`State::Destroyed` arm, reachable only after
    // the earlier `match` already `return`ed on `Destroyed`) is genuinely dead. It
    // DRIVES the initializer `f`, but — UNLIKE the DELIBERATELY-EXCLUDED
    // `OnceLock::get_or_init` (see `total_no_panic_call_summary`) — it is SOUND to
    // trust for two independent reasons: (1) it has NO panic path INDEPENDENT of `f`
    // (`OnceLock::get_or_init` panics on reentrant init; the native TLS instead
    // handles reentrancy by dropping the stale value, the `State::Alive` arm in
    // `lazy.rs`), and (2) `f` is ALWAYS the compiler-synthesized named fn
    // `__rust_std_internal_init_fn`, itself a SEPARATE proof unit carrying its OWN
    // panic-freedom obligation — so a panicking `thread_local!` initializer is
    // REFUTED there, never masked here (the "the driven body carries its own
    // obligation" discipline). This does NOT violate the closed-subset charter
    // above: the "callback" is never user-choosable — `std::thread::local_impl` is
    // a `#[doc(hidden)]` std-internal path namable ONLY by the `thread_local!`
    // expansion, so no user call site supplying an arbitrary closure can ride this.
    //
    // Matched on the RAW `callee` (not `normalized`): the init-fn turbofish
    // `::<fn() -> T {…_init_fn}>` carries a `->` whose `>` desyncs `strip_generics`'
    // bracket counter and mangles the normalized form — but the stable
    // `std::thread::local_impl::LazyStorage::<…>::get_or_init` HEAD (before the
    // turbofish) is intact, so the anchored structural check below is exact.
    if callee.starts_with("std::thread::local_impl::LazyStorage::")
        && callee.contains("::get_or_init")
    {
        // Env-gated decision-point trace, so the sound discharge of the ARENA
        // closures' spurious panic-freedom obligation is observable without a
        // rebuild-diff. Set `TRUST_TLS_DISCHARGE_DEBUG=1`.
        if std::env::var_os("TRUST_TLS_DISCHARGE_DEBUG").is_some() {
            eprintln!(
                "TRUST_TLS_DISCHARGE_DEBUG: discharged trusted-panic-free native-TLS \
                 lazy-init call `{callee}` — panic-freedom obligation dropped (init fn \
                 `__rust_std_internal_init_fn` carries its own)"
            );
        }
        return true;
    }
    let normalized = strip_generics(callee);
    const UNCONDITIONALLY_TOTAL: &[&str] = &[
        // Structural Option operations: borrowing or a `Copy` bit-copy only.
        "std::option::Option::as_ref",
        "std::option::Option::copied",
        // Keyless collection construction/iteration never invokes K/V code.
        "std::collections::BTreeMap::new",
        "std::collections::BTreeMap::keys",
        "std::collections::BTreeMap::values",
        "std::collections::BTreeMap::values_mut",
        "std::collections::BTreeMap::len",
        "std::collections::BTreeMap::is_empty",
        "std::collections::BTreeMap::iter",
        "std::collections::HashMap::keys",
        "std::collections::HashMap::values",
        "std::collections::HashMap::values_mut",
        "std::collections::HashMap::len",
        "std::collections::HashMap::is_empty",
        "std::collections::HashMap::iter",
        // Concrete constructors/accessors with no user-code dispatch.
        "std::thread::Builder::new",
        "std::thread::Builder::name",
        "std::cell::RefCell::try_borrow",
        "std::cell::RefCell::try_borrow_mut",
        "core::cell::RefCell::try_borrow",
        "core::cell::RefCell::try_borrow_mut",
        "std::cell::RefCell::new",
        "core::cell::RefCell::new",
        "std::sync::Mutex::new",
        "std::sync::RwLock::new",
        "std::path::Path::as_os_str",
        "std::path::Path::file_name",
        "std::path::Path::file_stem",
        "std::path::Path::extension",
        "std::path::Path::parent",
        "std::path::Path::display",
        "std::ffi::OsStr::to_str",
        "std::process::id",
        // Exact inherent primitive method; no overridable trait surface.
        "core::num::unsigned_abs",
    ];
    UNCONDITIONALLY_TOTAL.contains(&normalized.as_str())
}

// F6 (task #43): ARBITRARY-PRECISION arithmetic is unconditionally panic-free.
//
// F5 (above) deliberately EXCLUDES every arithmetic op from the string-only
// allowlist because for PRIMITIVE integers `Add`/`Sub`/`Mul`/`Neg` can
// overflow-panic (a real failure, separately modeled). But ny-cert's exact
// arithmetic is over `num_rational::Ratio<num_bigint::BigInt>` (`BigRational`)
// and `num_bigint::BigInt`/`BigUint` — ARBITRARY-PRECISION types that allocate as
// needed and CANNOT overflow. For those operand types `Add`/`Sub`/`Mul`/`Neg` are
// unconditionally panic-free, and their bodies live in the num crates (outside
// the bundle) — exactly the trusted-TCB, body-absent situation F5/#27 handle for
// other std/num callees. So the absent-callee `may panic` obligation for such a
// call is spurious and is DISCHARGED.
//
// Unlike F5, a callee-PATH match is INSUFFICIENT: the obligation spells the
// GENERIC trait path (`std::ops::Mul::mul`, no operand type), so we must recover
// the concrete Self/receiver TYPE at the call site and gate STRICTLY on it. The
// type is read from the FIRST argument's local type via `operand_trust_type`
// (`place_type` → the declared, monomorphized local type), the same recovery
// `trait_method_governing_ty` uses for Clone/PartialEq.
//
// SOUNDNESS RATIONALE. `num_bigint::BigInt`/`BigUint` and `num_rational::Ratio`
// over such an element are arbitrary-precision: `Add`/`Sub`/`Mul`/`Neg` grow the
// representation instead of overflowing, so they never panic (their only failure
// mode is allocation abort, which — like all allocation in the trusted std/num
// TCB — is out of the modeled panic set, matching `total_no_panic_call_summary`
// and the hard-skip of `core`). Gated on the RECEIVER being POSITIVELY one of
// those types; every other operand (primitive int, unknown ADT, `Ratio` over a
// primitive) FAILS CLOSED and KEEPS its obligation — a primitive `Add::add`'s
// overflow obligation is never masked. `Div`/`Rem` are EXCLUDED even for bignums
// (division by a zero divisor panics — CONDITIONAL); `Shl`/`Shr` are out of the
// op set; `Ratio::new` (zero-denominator panic) is a constructor, not on the arm.

/// Fuel for the `Ratio<…>`-element recursion in [`is_arbitrary_precision_ty`].
/// A handful of levels is ample (real nesting is one: `Ratio<BigInt>`); the bound
/// only guards against a pathological cyclic field type.
pub(crate) const ARBITRARY_PRECISION_TY_FUEL: u32 = 8;

/// The def-path name carried by an `Adt` OR a compacted by-name `Datatype`
/// reference (an oversized `num_bigint::BigInt` field can lower to the latter —
/// see `compact_oversized_field`, which PRESERVES the name). `None` for any other
/// `Ty`, so the type gate fails closed on it.
fn adt_or_datatype_name(ty: &Ty) -> Option<&str> {
    match ty {
        Ty::Adt { name, .. } | Ty::Datatype { name, .. } => Some(name.as_str()),
        _ => None,
    }
}

/// True iff `ty` is one of the ARBITRARY-PRECISION number types whose
/// `Add`/`Sub`/`Mul`/`Neg` cannot overflow-panic:
///   * `num_bigint::BigInt` / `num_bigint::BigUint` — matched by exact def-path
///     `name`. That is the `def_path_str` VISIBLE re-export spelling: the structs
///     are defined in the PRIVATE `num_bigint::{bigint,biguint}` submodules but
///     the only public path is the crate-root re-export, so they render at the
///     root — the same spelling F5 relies on for `num_rational::Ratio::denom`.
///   * `num_rational::Ratio<T>` ONLY WHEN its element `T` (the `numer` field) is
///     itself arbitrary-precision. This is the SOUNDNESS KEYSTONE: `BigRational =
///     Ratio<BigInt>` discharges, but `Rational64 = Ratio<i64>` (the SAME ADT
///     `name`, `numer: i64`) does NOT — its inner primitive multiply/add can
///     overflow-panic, so it keeps its obligation. The element is erased from the
///     ADT `name` (`def_path_str` drops generic args) but present as the field
///     type (`Ratio { numer: T, denom: T }`), lowered as a full `Ty::Adt`
///     (top-level operand) or, if oversized, a name-preserving `Ty::Datatype`.
///
/// FAIL-CLOSED: any type not positively matched here returns `false` — primitive
/// ints, unknown ADTs, `Ratio` over a primitive, an empty-field `Ratio`. The
/// caller peels references before calling.
pub(crate) fn is_arbitrary_precision_ty(ty: &Ty, fuel: u32) -> bool {
    // The compatibility type carries only a printable path, not the defining
    // crate's stable identity/version. A dependency can therefore export a
    // same-named type with panicking arithmetic/Clone/Display/Drop code. Until
    // rustc-authenticated provenance reaches this layer, no third-party numeric
    // path may grant proof authority.
    let _ = (ty, fuel);
    false
}

/// Arbitrary-precision values whose subtraction/negation is closed over the
/// represented domain. `BigUint` (and `Ratio<BigUint>`) is deliberately absent:
/// subtracting a larger value from a smaller `BigUint` panics, and it has no
/// signed negation.
fn is_signed_arbitrary_precision_ty(ty: &Ty, fuel: u32) -> bool {
    let _ = (ty, fuel);
    false
}

/// The trailing `ops::Trait::method` of an arithmetic op whose absent-callee
/// obligation F6 may discharge: `{Add,Sub,Mul,Neg}` and their in-place `*Assign`
/// forms. Matched on the generic-stripped path's last THREE segments, so both
/// the `std::ops::…` and `core::ops::…` spellings (and any monomorphized impl
/// segments) resolve identically, while the required `ops` segment keeps a
/// stray user `some::mod::Add::add` from matching.
/// `Div`/`Rem`/`DivAssign`/`RemAssign` stay DELIBERATELY ABSENT (a zero-divisor
/// panic is CONDITIONAL).
///
/// `Shl`/`Shr` are ALSO deliberately absent — this set has NO shift-amount
/// gate, and a bignum shift is total ONLY for an unsigned ≤64-bit amount
/// (num-bigint's signed-rhs impls PANIC on a negative amount, biguint/
/// shift.rs:14; a u128 amount can trip `.to_usize().expect("capacity
/// overflow")`, shift.rs:20). The amount-gated discharge lives in
/// `is_bignum_unsigned_shl_absent_callee` (pinned by the round-3 matrix:
/// `<< u32`/`<< usize` discharge, `<< i64`/`<< u128` fail closed).
pub(crate) fn is_arbitrary_precision_candidate_arith_method(callee: &str) -> bool {
    // Authenticate the COMPLETE canonical core/std trait path for both plain
    // and qualified spellings. A final `ops::Trait::method` suffix is not
    // authority: a user crate can define `mycrate::ops::Add` on the same receiver.
    callee_is_trait_method_in(callee, NS_OPS_ARITH, "Add", "add")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "Sub", "sub")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "Mul", "mul")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "Neg", "neg")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "AddAssign", "add_assign")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "SubAssign", "sub_assign")
        || callee_is_trait_method_in(callee, NS_OPS_ARITH, "MulAssign", "mul_assign")
}

/// F6: DISCHARGE the absent-callee may-panic obligation for an arbitrary-precision
/// arithmetic op. `true` IFF `callee` is one of `ops::{Add,Sub,Mul,Neg}(::*Assign)`
/// AND the receiver/Self operand (the FIRST arg, references peeled) is POSITIVELY
/// an arbitrary-precision number type. Anything else — a primitive-int receiver,
/// `Div`/`Rem`, an unresolvable type — returns `false` and KEEPS the obligation.
///
/// Gating on the RECEIVER (the LHS/`self` — arg 0 for `add(self, rhs)`,
/// `neg(self)`, and `add_assign(&mut self, rhs)`) is sound: a bignum-LHS
/// `Add`/`Mul` is panic-free on the supported arbitrary-precision domains;
/// `Sub`/`Neg` additionally require a signed `BigInt`-based domain. `BigUint`
/// subtraction can underflow-panic and therefore fails closed.
fn is_arbitrary_precision_arith_absent_callee(
    callee: &str,
    args: &[Operand],
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    if !is_arbitrary_precision_candidate_arith_method(callee) {
        return Ok(false);
    }
    let is_neg = is_canonical_trait_method(callee, &["core::ops::Neg", "std::ops::Neg"], "::neg");
    if args.len() != if is_neg { 1 } else { 2 } {
        return Ok(false);
    }
    let Some(receiver) = args.first() else { return Ok(false) };
    // Peel all reference/pointer levels to the underlying value type — a
    // `&BigInt + &BigInt` receiver lowers as `&BigInt` (the `impl Add for &BigInt`
    // forwarding impl) — exactly as `trait_method_governing_ty` does.
    let governing = {
        let mut g = operand_trust_type(receiver, ctx)?;
        loop {
            match g {
                Ty::Ref { inner, .. } => g = *inner,
                Ty::RawPtr { pointee, .. } => g = *pointee,
                other => break other,
            }
        }
    };
    let requires_signed_domain = [
        ("core::ops::Sub", "sub"),
        ("std::ops::Sub", "sub"),
        ("core::ops::SubAssign", "sub_assign"),
        ("std::ops::SubAssign", "sub_assign"),
        ("core::ops::Neg", "neg"),
        ("std::ops::Neg", "neg"),
    ]
    .iter()
    .any(|(trait_path, method)| is_canonical_trait_method(callee, &[*trait_path], method));
    Ok(if requires_signed_domain {
        is_signed_arbitrary_precision_ty(&governing, ARBITRARY_PRECISION_TY_FUEL)
    } else {
        is_arbitrary_precision_ty(&governing, ARBITRARY_PRECISION_TY_FUEL)
    })
}

/// Build-4 / Part A — DISCHARGE the `ArithmeticSafety` integer-overflow obligation
/// for an `Overflow(Add|Sub|Mul)` assert whose underlying binary op operates on
/// ARBITRARY-PRECISION operands. `true` IFF `msg` is one of those three overflow
/// messages AND the recovered binop's LHS operand type (references peeled) is
/// POSITIVELY `num_bigint::BigInt`/`BigUint` or a `num_rational::Ratio<Big…>`
/// (the `is_arbitrary_precision_ty` gate F6 relies on). Anything else — a
/// primitive-int operand, `Div`/`Rem`/`Shl`/`Shr`/`Neg`, an unrecoverable
/// binop/type — returns `false` and KEEPS the real obligation.
///
/// WHY THIS OBLIGATION IS SPURIOUS. A signed bignum `Add`/`Sub`/`Mul` GROWS its
/// representation rather than overflowing (its only failure mode is allocation
/// abort, out of the modeled panic set — the same rationale F6 documents). rustc's
/// overflow-check assert on such a `CheckedBinaryOp` is therefore vacuous. But the
/// assert lowering below stamps an `ArithmeticSafety` obligation for EVERY overflow
/// assert regardless of operand width, and the SMT lane
/// (`trust_vcgen::v2_build_overflow_vc_for_operands`) DECLINES to give it a
/// solvable formula — `int_op_type` returns `None` for a bignum operand (no fixed
/// integer width) — so the obligation reaches the native lane unsolved, is stamped
/// `UnsupportedMir{FullVerification::ArithmeticSafety: "arithmetic overflow (…)"}`,
/// and (under the strict default) reclassifies to a FAILED
/// refutation. Discharging it here — emitting NEITHER the refutable `Inst::Assert`
/// NOR the obligation, only the success branch — is the typed-overflow twin of F6's
/// absent-callee discharge.
///
/// SOUNDNESS. Both operands of a real `Add`/`Sub`/`Mul` `Rvalue::BinaryOp` share a
/// type, so gating on the LHS (as F6 gates on the receiver) is exact; a genuine
/// PRIMITIVE-int overflow has a primitive LHS, fails `is_arbitrary_precision_ty`,
/// and keeps its real obligation — this NEVER blanket-discharges arithmetic
/// overflow. `BigUint` subtraction is also excluded because unsigned underflow
/// panics. `Div`/`Rem` remain excluded for zero-divisor panic.
fn is_arbitrary_precision_overflow_assert(
    msg: &AssertMessage,
    source_block: BlockId,
    target: BlockId,
    ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    let op = match msg {
        AssertMessage::Overflow(op @ (BinOp::Add | BinOp::Sub | BinOp::Mul)) => *op,
        _ => return Ok(false),
    };
    // Recover the binop operands from the assert's SOURCE block (the canonical
    // `_t = CheckedOp(a, b); assert(!_t.1)` shape) then its TARGET block — the two
    // places `reconstruct_assert_safety_predicate` searches.
    let block_by_id = |id: BlockId| ctx.all_blocks.iter().find(|b| b.id == id);
    let Some((lhs, _rhs)) = block_by_id(source_block)
        .and_then(|b| find_block_binary_operands(b, op))
        .or_else(|| block_by_id(target).and_then(|b| find_block_binary_operands(b, op)))
    else {
        return Ok(false);
    };
    // Peel all reference/pointer levels to the underlying value type — a
    // `&BigInt - &BigInt` binop lowers with `&BigInt` operands — exactly as
    // `is_arbitrary_precision_arith_absent_callee` does.
    let governing = {
        let mut g = operand_trust_type(lhs, ctx)?;
        loop {
            match g {
                Ty::Ref { inner, .. } => g = *inner,
                Ty::RawPtr { pointee, .. } => g = *pointee,
                other => break other,
            }
        }
    };
    Ok(if op == BinOp::Sub {
        is_signed_arbitrary_precision_ty(&governing, ARBITRARY_PRECISION_TY_FUEL)
    } else {
        is_arbitrary_precision_ty(&governing, ARBITRARY_PRECISION_TY_FUEL)
    })
}

/// Round-4 / Part 2 — DISCHARGE gate for the shift-overflow obligation of an
/// `Overflow(Shl|Shr)` assert whose shift AMOUNT is a compile-time integer LITERAL
/// strictly below the shiftee's bit width. A shift `x << k` / `x >> k` panics IFF
/// `k >= bits(x)` (rustc's shift-overflow assert ranges over the AMOUNT alone —
/// never the shifted value), so a literal `k < bits(x)` makes the assert VACUOUSLY
/// TRUE: a total, machine-checkable fact needing no solver. Stamping the
/// obligation anyway strands it in the native lane as `UnsupportedMir{
/// FullVerification::ArithmeticSafety: shift overflow (Shl|Shr)}` plus a
/// `mir_assert::Overflow(Shl|Shr)` panic-boundary row (the ny-cert
/// `from_f32_exact`/`from_f64_exact`/`isqrt` sites: `bits >> 31` / `bits >> 23`
/// on u32, `s >> 31`/`state >> 33` on u64, `1i128 << 23`, `1 << 20` on usize).
/// Discharging — the caller emits NEITHER the refutable assert NOR the
/// obligation, only the success branch — is exactly the Part-A discipline.
///
/// OBLIGATION-GATING ONLY: this READS the MIR; the `Shl`/`Shr` RVALUE lowering is
/// untouched (the f32-FloatBits native lowering pattern-matches raw `Shr`
/// rvalues — those stay byte-identical).
///
/// FAIL-CLOSED, point by point (each `false` KEEPS the real obligation):
///   * no `Shl`/`Shr` assignment found in the assert's source/target block;
///   * SYMBOLIC amount — a local/param, or an unknown-valued constant
///     (`ConstParam`/`OpaqueScalar`): a dominating range guard is deliberately
///     NOT consulted this round;
///   * NEGATIVE literal amount (a real panic);
///   * shiftee width not POSITIVELY recoverable from the operand TYPE — the
///     declared type of a (possibly projected) place, the carried width of a
///     `Uint` constant, or, for a width-less `Int` constant, the assignment
///     DESTINATION's declared type (the shift result type IS the shiftee type —
///     the same recovery trust-vcgen uses); never an assumed width;
///   * literal amount >= width (`u32 << 32` — a real panic).
fn is_literal_shift_in_range_overflow_assert(
    msg: &AssertMessage,
    source_block: BlockId,
    target: BlockId,
    ctx: &LoweringCtx<'_>,
) -> bool {
    let op = match msg {
        AssertMessage::Overflow(op @ (BinOp::Shl | BinOp::Shr)) => *op,
        _ => return false,
    };
    // Recover the shift assignment from the assert's SOURCE block then its TARGET
    // block — the two places `reconstruct_shift_violation` searches.
    let block_by_id = |id: BlockId| ctx.all_blocks.iter().find(|b| b.id == id);
    let Some((dest, checked, value, amount)) = block_by_id(source_block)
        .and_then(|b| find_block_shift_assign(b, op))
        .or_else(|| block_by_id(target).and_then(|b| find_block_shift_assign(b, op)))
    else {
        return false;
    };
    // The amount must be an integer LITERAL with a known compile-time value:
    // `Uint` (width-carrying) or a non-negative width-less `Int`. Everything else
    // — locals, `ConstParam`, `OpaqueScalar`, negative literals — fails closed.
    let amount_val: u128 = match amount {
        Operand::Constant(ConstValue::Uint(v, _)) => *v,
        Operand::Constant(ConstValue::Int(v)) if *v >= 0 => *v as u128,
        _ => return false,
    };
    // The shiftee's bit width, from its TYPE (never assumed). A `place_type`
    // error fails closed rather than propagating (this gate must never turn a
    // previously-lowering assert into a lowering failure).
    let value_width: u32 = match value {
        Operand::Copy(place) | Operand::Move(place) => match place_type(place, ctx) {
            Ok(Ty::Int { width, .. }) => width,
            _ => return false,
        },
        Operand::Constant(ConstValue::Uint(_, width)) => *width,
        Operand::Constant(ConstValue::Int(_)) => {
            // Width-less integer literal: recover the width from the assignment
            // destination's declared type (trust-vcgen's recovery — the shift
            // result type is the shiftee type; for a checked shift it is tuple
            // field 0).
            let dest_ty = match place_type(dest, ctx) {
                Ok(ty) => ty,
                Err(_) => return false,
            };
            let value_ty = if checked {
                match dest_ty {
                    Ty::Tuple(fields) if fields.len() == 2 => fields[0].clone(),
                    _ => return false,
                }
            } else {
                dest_ty
            };
            match value_ty {
                Ty::Int { width, .. } => width,
                _ => return false,
            }
        }
        _ => return false,
    };
    amount_val < u128::from(value_width)
}

/// Fail-closed placeholder for `BTreeMap` mutation. The compatibility type erases
/// allocator `A`, so even a primitive/std-total key does not prove that mutation
/// cannot invoke user allocation code. `remove(&Q)` additionally erases the
/// selected `K: Borrow<Q>` implementation. No map mutation receives authority.
fn is_std_ord_key_map_mutate_absent_callee(
    _callee: &str,
    _args: &[Operand],
    _ctx: &LoweringCtx<'_>,
) -> Result<bool, BridgeError> {
    // `BTreeMap<K, V, A>` erases `A` from this bridge type. Even with a
    // primitive/std-total `K`, mutation can invoke a user allocator. Until the
    // selected allocator is carried as compiler-authenticated evidence, every
    // mutation stays in the honest absent-callee lane.
    Ok(false)
}

/// Fail-closed placeholder for `HashMap` mutation. The compatibility type erases
/// `S: BuildHasher`, so the visible key type cannot exclude a panicking custom
