    #[test]
    fn slice_index_projected_store_uses_data_lane() {
        let slice_ty =
            Ty::Ref { mutable: true, inner: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }) };
        let func = unit_function(
            "trust_ir_slice_index_store",
            vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: slice_ty, name: Some("slice".into()) },
                LocalDecl { index: 2, ty: Ty::usize(), name: Some("idx".into()) },
                LocalDecl { index: 3, ty: Ty::u8(), name: Some("value".into()) },
            ],
            vec![Statement::Assign {
                place: Place {
                    local: 1,
                    projections: vec![Projection::Deref, Projection::Index(2)],
                },
                rvalue: Rvalue::Use(Operand::Copy(Place::local(3))),
                span: SourceSpan::default(),
            }],
        );

        let module = lower_to_trust_ir(&func).expect("slice index projected store should lower");
        let bb0 = &module.functions[0].blocks[0];
        // Trust (B2-1b): the data lane is the FORMAT's own PtrData on the
        // first-class slice fat spelling (the anonymous ExtractField{Ptr, field:0}
        // tuple projection retired).
        let fat_ty = slice_fat_ty(&module, &TrustIrTy::U8);
        assert!(
            bb0.body.iter().any(|node| matches!(
                &node.inst,
                Inst::PtrData { ptr_ty, .. } if *ptr_ty == fat_ty
            )),
            "slice store should extract the data pointer lane"
        );
        assert!(
            bb0.body.iter().any(|node| matches!(node.inst, Inst::GEP { .. })),
            "slice store should address the selected element"
        );
        assert!(
            bb0.body.iter().any(|node| matches!(node.inst, Inst::Store { ty: TrustIrTy::U8, .. })),
            "slice store should write the element type"
        );
    }

