    #[test]
    fn fat_raw_ptr_aggregate_lowers_slice_length_metadata() {
        let data_ptr_ty = Ty::RawPtr { pointee: Box::new(Ty::u8()), mutable: false };
        let slice_ptr_ty = Ty::RawPtr {
            pointee: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }),
            mutable: false,
        };
        let func = unit_function(
            "trust_ir_fat_raw_ptr_aggregate",
            vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: data_ptr_ty, name: Some("data".into()) },
                LocalDecl { index: 2, ty: Ty::usize(), name: Some("len".into()) },
                LocalDecl { index: 3, ty: slice_ptr_ty, name: Some("out".into()) },
            ],
            vec![Statement::Assign {
                place: Place::local(3),
                rvalue: Rvalue::Aggregate(
                    AggregateKind::RawPtr {
                        pointee_ty: Ty::Slice { elem: Box::new(Ty::u8()) },
                        mutable: false,
                    },
                    vec![Operand::Copy(Place::local(1)), Operand::Copy(Place::local(2))],
                ),
                span: SourceSpan::default(),
            }],
        );

        let module = lower_to_trust_ir(&func).expect("fat raw pointer aggregate should lower");
        let bb0 = &module.functions[0].blocks[0];
        // Trust (B2-1b): the aggregate assembles the FORMAT's first-class fat
        // pointer via PtrFromParts at FatPtr(Slice(elem TyId)) — the data lane and
        // the canonical U64 length metadata lane in ONE op (the anonymous
        // Undef+InsertField tuple lanes retired).
        let fat_ty = slice_fat_ty(&module, &TrustIrTy::U8);
        assert!(
            bb0.body.iter().any(|node| matches!(
                &node.inst,
                Inst::PtrFromParts { ptr_ty, metadata_ty: TrustIrTy::U64, .. } if *ptr_ty == fat_ty
            )),
            "fat raw pointer aggregate should assemble the data + length metadata lanes \
             via PtrFromParts at the first-class slice fat type"
        );
        assert!(
            !bb0.body.iter().any(|node| matches!(
                &node.inst,
                Inst::InsertField { .. } | Inst::Undef { ty: TrustIrTy::Tuple(_) }
            )),
            "the legacy anonymous tuple spelling (Undef + InsertField lanes) is retired"
        );
    }

    #[test]
    fn faithful_raw_slice_metadata_crosses_usize_to_u64_exactly() {
        let data_ptr_ty = Ty::RawPtr { pointee: Box::new(Ty::u8()), mutable: false };
        let slice_ptr_ty = Ty::RawPtr {
            pointee: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }),
            mutable: false,
        };
        let func = VerifiableFunction {
            name: "faithful_raw_slice_parts".into(),
            def_path: "test::faithful_raw_slice_parts".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Unit, name: None },
                    LocalDecl { index: 1, ty: data_ptr_ty, name: Some("data".into()) },
                    LocalDecl { index: 2, ty: faithful_usize_ty(), name: Some("len".into()) },
                    LocalDecl { index: 3, ty: slice_ptr_ty, name: Some("out".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Aggregate(
                            AggregateKind::RawPtr {
                                pointee_ty: Ty::Slice { elem: Box::new(Ty::u8()) },
                                mutable: false,
                            },
                            vec![Operand::Copy(Place::local(1)), Operand::Copy(Place::local(2))],
                        ),
                        span: SourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 2,
                return_ty: Ty::Unit,
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
        };

        let module = lower_to_trust_ir(&func).expect("faithful raw slice parts should lower");
        assert_valid_module(&module);
        let body = &module.functions[0].blocks[0].body;
        assert!(body.iter().any(|node| matches!(
            node.inst,
            Inst::Cast {
                op: CastOp::Bitcast,
                src_ty: TrustIrTy::Usize,
                dst_ty: TrustIrTy::U64,
                ..
            }
        )));
        assert!(body.iter().any(|node| matches!(
            node.inst,
            Inst::PtrFromParts { metadata_ty: TrustIrTy::U64, .. }
        )));
    }

