    #[test]
    fn slice_iterator_accepts_qualified_next_and_next_back() {
        // The ny-cert RESOLVED spellings: `<slice::Iter as Iterator>::next` and the
        // DoubleEndedIterator `next_back` twin — previously MISSED by the plain
        // `ends_with("::Iterator::next")`, so they stayed runtime_checked.
        assert!(slice_iter_recognized(
            "<core::slice::Iter<u8> as std::iter::Iterator>::next",
            Ty::Ref { mutable: true, inner: Box::new(slice_iter_u8()) },
        ));
        assert!(slice_iter_recognized(
            "<core::slice::Iter<u8> as std::iter::DoubleEndedIterator>::next_back",
            Ty::Ref { mutable: true, inner: Box::new(slice_iter_u8()) },
        ));
    }

    #[test]
    fn slice_iterator_accepts_qualified_vec_deref() {
        // `<std::vec::Vec<Rat> as std::ops::Deref>::deref` (×30 in ny-cert): the
        // std-container Deref is a total pointer cast, gated on `ty_is_std_deref_receiver`.
        assert!(slice_iter_recognized(
            "<std::vec::Vec<rational::Rat> as std::ops::Deref>::deref",
            Ty::Ref { mutable: false, inner: Box::new(std_vec()) },
        ));
    }

    #[test]
    fn slice_iterator_declines_user_iterator_next() {
        // SOUNDNESS: a USER iterator's `next` (whose body runs arbitrary code that
        // may panic) is NOT recognized as total — even in the qualified spelling —
        // because the receiver fails `ty_is_slice_iterator_receiver`.
        let user_iter = Ty::Adt { adt_kind: None, layout: None, 
            variants: Vec::new(),
            name: "my_crate::MyIter".into(),
            fields: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, };
        assert!(!slice_iter_recognized(
            "<my_crate::MyIter as std::iter::Iterator>::next",
            Ty::Ref { mutable: true, inner: Box::new(user_iter) },
        ));
        // And a USER Deref (which can run panicking code) is declined.
        let user_smart = Ty::Adt { adt_kind: None, layout: None, 
            variants: Vec::new(),
            name: "my_crate::MySmartPtr".into(),
            fields: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, };
        assert!(!slice_iter_recognized(
            "<my_crate::MySmartPtr as std::ops::Deref>::deref",
            Ty::Ref { mutable: false, inner: Box::new(user_smart) },
        ));
    }

